INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DwmosvL5ofD', 1, '{"title":"梓行《本草疏》题辞","description":"<p>      药性之道，具在本草。虽代有哲匠，演其奥义，然去古弥远，寖失其旨。予以绵质，性复疏戆，本不堪尘俗。年方弱冠，直门户衰冷，世累纠缠。以是多见愤激，碍膺之事，十常八九。自兹数婴疾病，於是检讨《图经》，求其本意。积累既久，恍焉有会心处，辄札记之。历三十馀年，遂成此《疏》。学士大夫见而奇之，欲予付诸梓人，予未之许也。予以昔人尝云：“切忌说破，恐塞断后学悟门”，将兹是咎。外孙毛凤苞文学曰：“不然，世间上根人少，中下人多。设使上根人出，自得无师智获，睹此书当不言而喻，默默相契；下根人读之，如盲人谭五色，总不能别；惟中人已上之资，得窥其概，则所得多矣。其为利济，宁有量耶！请亟登梓，以拯夭枉。”予曰：“善”。且曰：“舅祖许可，凤苞愿力任其役。”乃悉检《疏》稿付之。即集予同里门人李枝，通家子云间康元浤，松陵顾澄先二文学，并其舅氏隐沦戈汕辈董督校雠，早夜孜孜，惟恐或后，其用意可谓勤矣！志存及物，有君子之嗜尚焉，良足多也。予年已髦，倘书成而得早行於世，亦足以副海内求明斯道者之企望也。　</p>\n<p>　</p>\n<p>            时天启乙丑暮春海虞遗民缪希雍题于吴江舟次　　</p>\n<p></p>\n<p>      吴兴晚学姚凝之书　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001001,"no":1}}', '2024-12-20T01:23:58.000Z', '2024-12-20T01:23:58.000Z', '2024-12-20T01:23:58.000Z', '药性之道，具在本草。虽代有哲匠，演其奥义，然去古弥远，寖失其旨。予以绵质，性复疏戆，本不堪尘俗。年方弱冠，直门户衰冷，世累纠缠。以是多见愤激，碍膺之事，十常八九。自兹数婴疾病，於是检讨《图经》，求其本意。积累既久，恍焉有会心处，辄札记之。历三十馀年，遂成此《疏》。学士大夫见而奇之，欲予付诸梓人，予未之许也。予以昔人尝云：“切忌说破，恐塞断后学悟门”，将兹是咎。外孙毛凤苞文学曰：“不然，世间上根人少，中下人多。设使上根人出，自得无师智获，睹此书当不言而喻，默默相契；下根人读之，如盲人谭五色，总不能别；惟中人已上之资，得窥其概，则所得多矣。其为利济，宁有量耶！请亟登梓，以拯夭枉。”予曰：“善”。且曰：“舅祖许可，凤苞愿力任其役。”乃悉检《疏》稿付之。即集予同里门人李枝，通家子云间康元浤，松陵顾澄先二文学，并其舅氏隐沦戈汕辈董督校雠，早夜孜孜，惟恐或后，其用意可谓勤矣！志存及物，有君子之嗜尚焉，良足多也。予年已髦，倘书成而得早行於世，亦足以副海内求明斯道者之企望也。 时天启乙丑暮春海虞遗民缪希雍题于吴江舟次 吴兴晚学姚凝之书', '2024-12-20T01:23:58.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gYfrTaT6HUn', 1, '{"title":"自序","description":"<p>       《神农本草经》者，古“三坟”之一也。其成於黄帝之世乎？观其尝药别味，对病主治，施之百世，无可逾越。其为开天大圣，悯生民疾苦，於饮食衣服之外，复设针石药物，用拯夭札，俾得尽其天年。是已原夫药之生也，气禀乎天，味成乎地，性在其间。气为阳，味为阴，五味四气，各归其类，斯亲上、亲下之义也。既述之以本性，又制之以君臣，合之以佐使，以成其攻邪已疾之能。遂使无情之用，同诸有识，自非生而神灵、冥契万物者，其孰能与於斯乎！去古滋远，民性滋漓，心识粗浮，莫能研精殚思，深入玄要，而不察乎即象即理，物物昭然，弭疾延年，功力自著。正以“三坟”之书，言大道也，言其然而不言其所以然。言亦象也。予因据经以疏义，缘义以致用，参互以尽其长，简误以防其失；而复详列病忌药忌；以别其微；条析诸药，应病分门，以究其用；刊定七方十剂，以定其法；阐发五藏苦欲补泻，以畅其神。著论三十馀首，以通古今之变。始悉一经之趣，命之曰《神农本草经疏》。读之者宜因疏以通经，因经以契往，俾炎黄之旨，晦而复明，药物之生，利而罔害，乃余述疏意也。余生也晚，亲年已衰，得于禀者固薄，故少善病。长嗜方伎，僻耽药妙，顾念自昔仙人道士，靡不悉由药道以济群生。加之友生协赞，后先不一。驯届耳顺，良友凋丧，百念灰冷。惟兹一事，尚用婴怀，手所论著，裒然成帙。倘典则可师，幽隐可显，试用于世，有广来学，固所愿也，不敢必也。采真同好，其相证诸？</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001002,"no":2}}', '2024-12-20T01:27:39.000Z', '2024-12-20T01:27:39.000Z', '2024-12-20T01:27:39.000Z', '《神农本草经》者，古“三坟”之一也。其成於黄帝之世乎？观其尝药别味，对病主治，施之百世，无可逾越。其为开天大圣，悯生民疾苦，於饮食衣服之外，复设针石药物，用拯夭札，俾得尽其天年。是已原夫药之生也，气禀乎天，味成乎地，性在其间。气为阳，味为阴，五味四气，各归其类，斯亲上、亲下之义也。既述之以本性，又制之以君臣，合之以佐使，以成其攻邪已疾之能。遂使无情之用，同诸有识，自非生而神灵、冥契万物者，其孰能与於斯乎！去古滋远，民性滋漓，心识粗浮，莫能研精殚思，深入玄要，而不察乎即象即理，物物昭然，弭疾延年，功力自著。正以“三坟”之书，言大道也，言其然而不言其所以然。言亦象也。予因据经以疏义，缘义以致用，参互以尽其长，简误以防其失；而复详列病忌药忌；以别其微；条析诸药，应病分门，以究其用；刊定七方十剂，以定其法；阐发五藏苦欲补泻，以畅其神。著论三十馀首，以通古今之变。始悉一经之趣，命之曰《神农本草经疏》。读之者宜因疏以通经，因经以契往，俾炎黄之旨，晦而复明，药物之生，利而罔害，乃余述疏意也。余生也晚，亲年已衰，得于禀者固薄，故少善病。长嗜方伎，僻耽药妙，顾念自昔仙人道士，靡不悉由药道以济群生。加之友生协赞，后先不一。驯届耳顺，良友凋丧，百念灰冷。惟兹一事，尚用婴怀，手所论著，裒然成帙。倘典则可师，幽隐可显，试用于世，有广来学，固所愿也，不敢必也。采真同好，其相证诸？', '2024-12-20T01:27:39.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oi4Khfzdv9I', 1, '{"title":"凡例","description":"<p>一、《本经》为“三坟”之书，后增入《名医别录》，有朱字、墨字之分，总言药之主治，从未有发其所以然者。兹《疏》直接神圣立言之旨，故总题之曰《神农本草经疏》。　　</p><p>一、药物治疗，《本经》、《别录》业已备悉。间有未尽者，参之以各名家主治，故小字附列於经文之下，或即于疏内叙述，俾采用易稽。</p><p>一、药类一千二百馀种，品类浩繁，今简治疗之必不可缺，暨近地所产，得於睹记者，备为具疏。馀非必用之药，及罕识难致者，存而不论。</p><p>一、种类随土异形，甚且称名未核。矧近来市肆，饰伪似真。若令误服，遗害非浅。故详辩种类，以正其讹。</p><p>一、畏忌制使，物性自然，非可以意求者，俱照本经，列之条下。至其制用之宜，古法倶在。兹复采入，俾得遵守。</p><p>一、《证类本草》所载诸方，倶录入 “【主治参与】”，有未当於用者，已为删去。其外诸书所录良方甚多，必详纪述，以便采取。</p><p>一 “简误” 以防误用之失，故有证同而药不宜同者，每条后详书其害。至於性淳功良，有益无损，一药只堪治一病者，悉不复著。</p><p>一、目录次序，悉从《证类本草》，有部分混杂，如木部之藿香，菜部之假苏，今为移正。</p><p>一、本文悉遵《证类》善本。但是书流传已久，字画谬讹颇多，兹逐条参订。有一二意义难通者，稍为厘正，如 “伤” 作 “疡”，“动” 作 “痛” 之类。</p><p>一、《证类本草》第三十卷，倶载有名未用之药。今有常用之物，而本经未载；有《拾遗》载之而未详者，兹列为三十卷 “补遗”。</p><p>一、本文顶行立款。其附入之条，有正文者仍从顶行；原系附入者，低字加圈，以别正文。</p><p>一、“续序例” 下卷，倶系病药忌宜。今总列应忌诸药於前，以见必不可轻用。</p><p>       先生殚一生精力，发千古神圣之奥，以利万世。门人李季虬氏，几经参录，悉以付新安吴康虞氏刻之金陵，未竟而遗焉。流传於知交者，西吴朱氏集而刻之，不及其半，然且序次弗伦，考核未审也。先生以医为司命，一字有讹，遗祸无极。遂命澄先检其存稿若干卷，按部选类，汇得全帙；细复检阅，以为定本。</p>\n<p></p>\n<p>      凡 “续序例” 二卷，药四百九十味，用识年月，书此凡例云。</p>\n<p></p>\n<p>      时天启五年岁在乙丑六月十有一日松陵通家子顾澄先谨识。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001003,"no":3}}', '2024-12-20T01:28:46.000Z', '2024-12-20T01:28:46.000Z', '2024-12-20T01:28:46.000Z', '一、《本经》为“三坟”之书，后增入《名医别录》，有朱字、墨字之分，总言药之主治，从未有发其所以然者。兹《疏》直接神圣立言之旨，故总题之曰《神农本草经疏》。 一、药物治疗，《本经》、《别录》业已备悉。间有未尽者，参之以各名家主治，故小字附列於经文之下，或即于疏内叙述，俾采用易稽。 一、药类一千二百馀种，品类浩繁，今简治疗之必不可缺，暨近地所产，得於睹记者，备为具疏。馀非必用之药，及罕识难致者，存而不论。 一、种类随土异形，甚且称名未核。矧近来市肆，饰伪似真。若令误服，遗害非浅。故详辩种类，以正其讹。 一、畏忌制使，物性自然，非可以意求者，俱照本经，列之条下。至其制用之宜，古法倶在。兹复采入，俾得遵守。 一、《证类本草》所载诸方，倶录入 “【主治参与】”，有未当於用者，已为删去。其外诸书所录良方甚多，必详纪述，以便采取。 一 “简误” 以防误用之失，故有证同而药不宜同者，每条后详书其害。至於性淳功良，有益无损，一药只堪治一病者，悉不复著。 一、目录次序，悉从《证类本草》，有部分混杂，如木部之藿香，菜部之假苏，今为移正。 一、本文悉遵《证类》善本。但是书流传已久，字画谬讹颇多，兹逐条参订。有一二意义难通者，稍为厘正，如 “伤” 作 “疡”，“动” 作 “痛” 之类。 一、《证类本草》第三十卷，倶载有名未用之药。今有常用之物，而本经未载；有《拾遗》载之而未详者，兹列为三十卷 “补遗”。 一、本文顶行立款。其附入之条，有正文者仍从顶行；原系附入者，低字加圈，以别正文。 一、“续序例” 下卷，倶系病药忌宜。今总列应忌诸药於前，以见必不可轻用。 先生殚一生精力，发千古神圣之奥，以利万世。门人李季虬氏，几经参录，悉以付新安吴康虞氏刻之金陵，未竟而遗焉。流传於知交者，西吴朱氏集而刻之，不及其半，然且序次弗伦，考核未审也。先生以医为司命，一字有讹，遗祸无极。遂命澄先检其存稿若干卷，按部选类，汇得全帙；细复检阅，以为定本。 凡 “续序例” 二卷，药四百九十味，用识年月，书此凡例云。 时天启五年岁在乙丑六月十有一日松陵通家子顾澄先谨识。', '2024-12-20T01:28:46.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9KHprCHE7rd', 1, '{"title":"卷之一_读《经疏》引","description":"<p>         予之作是《疏》也，赅括经文，义难概述；求其宗趣，宜有裁节。是以或先经而阐义，或随文而畅旨，或断章以相比，或因源以导流，或从末而会本，或根性以知非。凡兹数者，期在发明经旨，适当於用。然惧偏见多遗，难为准的，必欲使纤悉洞了，小大靡遗。开扩来学，臻乎无惑，尚有望于明哲之助焉。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001004,"no":4}}', '2024-12-21T01:27:47.000Z', '2024-12-21T01:27:47.000Z', '2024-12-21T01:27:47.000Z', '予之作是《疏》也，赅括经文，义难概述；求其宗趣，宜有裁节。是以或先经而阐义，或随文而畅旨，或断章以相比，或因源以导流，或从末而会本，或根性以知非。凡兹数者，期在发明经旨，适当於用。然惧偏见多遗，难为准的，必欲使纤悉洞了，小大靡遗。开扩来学，臻乎无惑，尚有望于明哲之助焉。', '2024-12-21T01:27:47.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GmpduHksm9v', 1, '{"title":"卷之一_续序例上_原本药性气味生成指归","description":"<p>        夫物之生也，必禀乎天。其成也，必资乎地。</p>\n<p></p>\n<p>       天布令，主发生，$m{寒、热、温、凉}，四时之气行焉，阳也；地凝质，主成物，$n{酸、苦、辛、咸、甘、淡}，五行之味滋焉，阴也。</p>\n<p></p>\n<p>       故知微寒微温者，春之气也；大温热者，夏之气也；大热者，长夏之气也；凉者，秋之气也；大寒者，冬之气也。</p>\n<p></p>\n<p>      凡言微寒者，禀春之气以生，春气升而生；言$m{温热}者，盛夏之气以生，夏气散而长；言$m{大热}者，感长夏之气以生，长夏之气软而化；言$m{平}者，感秋之气以生，$m{平}即$m{凉}也，秋气降而收；言$m{大寒}者，感冬之气以生，冬气沉而$m{藏}。此物之气得乎天者也。</p>\n<p> </p>\n<p>      天一生水，地六成之。地二生火，天七成之。天三生木，地八成之。地四生金，天九成之。天五生土，地十成之。</p>\n<p></p>\n<p>      水曰润下，润下作$n{咸}。火曰炎上，炎上作$n{苦}。 木曰曲直，曲直作$n{酸}。金曰从革，从革作$n{辛}。  土爰稼穑，稼穑作$n{甘}。本乎天者亲上，本乎地者亲下。气味多少，各从其类也。</p>\n<p></p>\n<p>      凡言$n{酸}者，得木之气；言$n{辛}者，得金之气；言$n{咸}者，得水之气；言$n{苦}者，得火之气；言$n{甘}者，得土之气。</p>\n<p></p>\n<p>      惟土也，寄旺於四季。生成之数皆五，故其气平，其味甘而淡，其性和而无毒。土德冲和，感而类之，莫或不然。固万物之所出，亦万物之所入乎？此物之味，资乎地者也。　　</p>\n<p></p>\n<p>      气之毒者必$m{热}，味之毒者必$n{辛}。炎黄言味而不加气性者何也？盖古文尚简，故只言味。物有味，必有气，有气斯有性，自然之道也。气味生成，原本乎是。知其所自，则思过半矣。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001005,"no":5}}', '2024-12-21T01:29:57.000Z', '2024-12-21T01:29:57.000Z', '2024-12-21T01:29:57.000Z', '夫物之生也，必禀乎天。其成也，必资乎地。 天布令，主发生，$m{寒、热、温、凉}，四时之气行焉，阳也；地凝质，主成物，$n{酸、苦、辛、咸、甘、淡}，五行之味滋焉，阴也。 故知微寒微温者，春之气也；大温热者，夏之气也；大热者，长夏之气也；凉者，秋之气也；大寒者，冬之气也。 凡言微寒者，禀春之气以生，春气升而生；言$m{温热}者，盛夏之气以生，夏气散而长；言$m{大热}者，感长夏之气以生，长夏之气软而化；言$m{平}者，感秋之气以生，$m{平}即$m{凉}也，秋气降而收；言$m{大寒}者，感冬之气以生，冬气沉而$m{藏}。此物之气得乎天者也。 天一生水，地六成之。地二生火，天七成之。天三生木，地八成之。地四生金，天九成之。天五生土，地十成之。 水曰润下，润下作$n{咸}。火曰炎上，炎上作$n{苦}。 木曰曲直，曲直作$n{酸}。金曰从革，从革作$n{辛}。 土爰稼穑，稼穑作$n{甘}。本乎天者亲上，本乎地者亲下。气味多少，各从其类也。 凡言$n{酸}者，得木之气；言$n{辛}者，得金之气；言$n{咸}者，得水之气；言$n{苦}者，得火之气；言$n{甘}者，得土之气。 惟土也，寄旺於四季。生成之数皆五，故其气平，其味甘而淡，其性和而无毒。土德冲和，感而类之，莫或不然。固万物之所出，亦万物之所入乎？此物之味，资乎地者也。 气之毒者必$m{热}，味之毒者必$n{辛}。炎黄言味而不加气性者何也？盖古文尚简，故只言味。物有味，必有气，有气斯有性，自然之道也。气味生成，原本乎是。知其所自，则思过半矣。', '2024-12-21T01:29:57.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qY6eqI3CHpg', 1, '{"title":"卷之一_续序例上_药性【主治参与】指归","description":"<p>         今夫病，譬诸兵焉。料敌出奇者，将之谋也；破军杀贼者，士之力也。</p>\n<p></p>\n<p>        审度病机者，医之智也；攻邪伐病者，药之能也。非士无以破敌，非药无以攻邪。故良将养士，上医蓄药。然不知士，何以养？不知药，何以蓄？夫士犹有情实可考，才略可试，尚曰难知。</p>\n<p></p>\n<p>        以孔明之明，一马谡用违其才，卒致败衄，悔不可追，况乎药石无情，才性莫测，既非言论之可考，又非拟议之可及，而欲知其的然不谬，非神圣之智，其孰能与於斯？ 假令尝试漫为，则下咽不返，死生立判，顾不大可惧耶！</p>\n<p> </p>\n<p>      上古之人，病生於$n{六淫者多}，发于$m{七情者寡}。故其主治，尝以一药治一病，或一药治数病。今时则不然：$n{七情弥厚，五欲弥深，精气既亏，六淫易入}。$m{内外胶固，病情殊古}：则$n{须合众药之所长，而又善护其所短，乃能苏凋瘵而起沉疴，其在良医善知药性}，剂量无差，庶得参互旁通，彼此兼济，以尽其才，而无乖刺败坏之弊矣。故作“【主治参与】”，俾后之医师循而求之，共收平定之功，期无夭枉之患，斯作《疏》意也。昔人云：“用医如用兵。”旨哉言乎！旨哉言乎！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001006,"no":6}}', '2024-12-21T01:32:51.000Z', '2024-12-21T01:32:51.000Z', '2024-12-21T01:32:51.000Z', '今夫病，譬诸兵焉。料敌出奇者，将之谋也；破军杀贼者，士之力也。 审度病机者，医之智也；攻邪伐病者，药之能也。非士无以破敌，非药无以攻邪。故良将养士，上医蓄药。然不知士，何以养？不知药，何以蓄？夫士犹有情实可考，才略可试，尚曰难知。 以孔明之明，一马谡用违其才，卒致败衄，悔不可追，况乎药石无情，才性莫测，既非言论之可考，又非拟议之可及，而欲知其的然不谬，非神圣之智，其孰能与於斯？ 假令尝试漫为，则下咽不返，死生立判，顾不大可惧耶！ 上古之人，病生於$n{六淫者多}，发于$m{七情者寡}。故其主治，尝以一药治一病，或一药治数病。今时则不然：$n{七情弥厚，五欲弥深，精气既亏，六淫易入}。$m{内外胶固，病情殊古}：则$n{须合众药之所长，而又善护其所短，乃能苏凋瘵而起沉疴，其在良医善知药性}，剂量无差，庶得参互旁通，彼此兼济，以尽其才，而无乖刺败坏之弊矣。故作“【主治参与】”，俾后之医师循而求之，共收平定之功，期无夭枉之患，斯作《疏》意也。昔人云：“用医如用兵。”旨哉言乎！旨哉言乎！', '2024-12-21T01:32:51.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J5d0Ry9lo9l', 1, '{"title":"卷之一_续序例上_药性简误指归","description":"<p>       夫$x{药石}禀$m{天地偏至之气者也}。$n{虽醇和浓懿}，号称$m{上药}，然所禀既$x{偏}，所至必$x{独}。脱也用违其性之宜，则偏重之害，势所必至。</p>\n<p></p>\n<p>       故凡有益于$x{阳虚者}，必$x{不利乎阴}；有益于$x{阴虚者}，必$x{不利乎阳}。</p>\n<p></p>\n<p>       能治$x{燥者}，必不宜于$x{湿}；</p>\n<p></p>\n<p>       能治$x{湿者}，必不宜于$x{燥}。</p>\n<p></p>\n<p>      能破$x{散者}，不可以$x{治虚}；</p>\n<p></p>\n<p>      能收$x{敛者}，不可以治实。</p>\n<p></p>\n<p>      $x{升}，不可以$x{止升}；</p>\n<p>   </p>\n<p>      $x{降}，不可以$x{疗降}。</p>\n<p></p>\n<p>     $x{寒}有时而不宜于$x{热}，$x{热}有时而不宜于$x{寒}。</p>\n<p></p>\n<p>     古人$u{半夏}有三禁，谓渴家、汗家、血家。</p>\n<p></p>\n<p>     仲景呕家忌$x{甘}，酒家亦忌$x{甘}。王好古论$x{肺热}忌$u{人参}之属。</p>\n<p></p>\n<p>     诸如此类，莫可胜数。苟昧斯旨，吉凶贸焉。人命至重，冥报难逃，医为司命，其可不深思详察也哉！此与“十剂”互证。“十剂”对治，$x{反}则为$m{误}，故作“简误”以防其失。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001007,"no":7}}', '2024-12-21T01:33:42.000Z', '2024-12-21T01:33:42.000Z', '2024-12-21T01:33:42.000Z', '夫$x{药石}禀$m{天地偏至之气者也}。$n{虽醇和浓懿}，号称$m{上药}，然所禀既$x{偏}，所至必$x{独}。脱也用违其性之宜，则偏重之害，势所必至。 故凡有益于$x{阳虚者}，必$x{不利乎阴}；有益于$x{阴虚者}，必$x{不利乎阳}。 能治$x{燥者}，必不宜于$x{湿}； 能治$x{湿者}，必不宜于$x{燥}。 能破$x{散者}，不可以$x{治虚}； 能收$x{敛者}，不可以治实。 $x{升}，不可以$x{止升}； $x{降}，不可以$x{疗降}。 $x{寒}有时而不宜于$x{热}，$x{热}有时而不宜于$x{寒}。 古人$u{半夏}有三禁，谓渴家、汗家、血家。 仲景呕家忌$x{甘}，酒家亦忌$x{甘}。王好古论$x{肺热}忌$u{人参}之属。 诸如此类，莫可胜数。苟昧斯旨，吉凶贸焉。人命至重，冥报难逃，医为司命，其可不深思详察也哉！此与“十剂”互证。“十剂”对治，$x{反}则为$m{误}，故作“简误”以防其失。', '2024-12-21T01:33:42.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eOvHKJDNetK', 1, '{"title":"卷之一_续序例上_论七方本义","description":"<p>         夫方者，法也。法乃所以制物者也。故$x{大}、$x{小}、$x{缓}、$x{急}、$x{奇}、$x{偶}、$x{复}七者，为法制之变且尽也。</p>\n<p></p>\n<p>       七方不同，同归已疾。其制各异，异以从宜。</p>\n<p></p>\n<p>       岐伯言之已详，后人演之弥悉，凡制方者必本乎是。</p>\n<p></p>\n<p>      $y{苟悖其制，则非法矣}。非法则不能所施合辙，而反致$m{乖刺}，恶在其能攻邪已疾耶！　</p><p>附录：七方　　</p>\n<p></p>\n<p>       岐伯曰：气有多少，形有盛衰。治有缓急，方有大小。又曰：病有远近，证有中外，治有轻重。近者偶之，远者奇之。汗不以奇，下不以偶。补上治上制以缓，补下治下制以急。近而偶奇，制小其服；远而奇偶，制大其服。大则数小，小则数多。多则九之，少则一之。奇之不去则偶之，偶之不去则反佐以取之。所谓寒热温凉，反从其病也。　　</p>\n<p></p>\n<p>       王冰曰：脏位有高下，腑气有远近。病证有表里，药用有轻重。单方为奇，复方为偶。心肺为近，肝肾为远，脾胃居中。肠、膀、胞、胆，亦有远近。识见高远，权以合宜。方奇而分两偶，方偶而分两奇。近而偶制，多数服之；远而奇制，少数服之。则肺服九，心服七，脾服五，肝服三，肾服一，为常制也，方与其重也宁轻，与其毒也宁良，与其大也宁小。是以奇方不去，偶方主之；偶方不去，则反佐以同病之气而取之。夫微小之热，折之以寒；微小之冷，消之以热。其大寒热，则必能与异气相格，声不同不相应，气不同不相合。是以反其佐，以同其气，夏令寒热参合，使其始同终异也。　</p>\n<p>　</p>\n<p>       逆者正治，从者反治。反佐，即从治也。谓热在下而上有寒邪拒格，则寒药中入热药为佐。下膈之后，热气既散，寒性随发也。寒在下而上有浮火拒格，则热药中入寒药为佐。下膈之后，寒气既消，热性随发也。此寒因热用，热因寒用之妙也。温冷仿此。　</p>\n<p>　</p>\n<p>      完素曰：流变在乎病，主病在乎方，制方在乎人。方有七：大、小、缓、急、奇、偶、复也。制方之体，本於气味。寒、热、温、凉，四气生於天；酸、苦、辛、咸、甘、淡，六味成於地。是以有形为味，无形为气。气为阳，味为阴。辛甘发散为阳，酸苦涌泄为阴。咸味涌泄为阴，淡味渗泄为阳。或收或散，或缓或急，或燥或润，或软或坚，各随脏腑之证。而施药之品味，乃分七方之制也。故奇、偶、复，三方也，大、小、缓、急，四制之法也。故曰：治有缓急，方有大小。　　</p><p>$m{大方}　　</p>\n<p>       岐伯曰：君一、臣三、佐九，制之大也；君一、臣三、佐五，制之中也；君一、臣二，制之小也。又曰：远而奇偶，制大其服；近而偶奇，制小其服。大则数少，小则数多。多则九之，小则二之。完素曰：身表为远，身里为近。大小者，制奇偶之法也。假如小承气汤、调胃承气汤，奇之小方也；大承气汤、抵当汤，奇之大方也，所谓因其攻里而用之也。桂枝、麻黄，偶之小方也；葛根、青龙，偶之大方也，所谓因其发表而用之也。故曰：汗不以奇，下不以偶。张从正曰：大方有二：有君一、臣三、佐九之大方，病有兼证而邪不一，不可以一二味治者宜之；有分两大而顿服之大方，肝肾及下部之病道远者宜之。王太仆以心肺为近，肾肝为远，脾胃为中。刘河间以身表为远，身里为近。以予观之，身半以上其气三，天之分也。身半以下其气三，地之分也。中脘，人之分也。　　</p><p>$m{小方}　　</p>\n<p>          从正曰：小方有二：有君一、臣二之小方，病无兼证，邪气专一，可一二味治者宜之；有分两少而频服之小方，心肺及在上之病者宜之，徐徐细呷是也。完素曰：肝肾位远，数多则其气缓，不能速达于下，必大剂而数少，取其迅急下走也。心肺位近，数少则其气急下走，不能升发于上，必小剂而数多，取其易散而上行也。王氏所谓肺服九，心服七，脾服五，肝服三，肾服一，乃五脏生成之数也。　</p><p>$m{缓方}　　</p>\n<p>        岐伯曰：补上治上制以缓，补下治下制以急。急则气味厚，缓则气味薄，适其至所，此之谓也。病所远而中道气味之者，食而过之，无越其制度也。王冰曰：假如病在肾而心气不足，服药宜急过之，不以气味饲心，肾药凌心，心复益散矣。馀上下远近例同。完素曰：圣人治上不犯下，治下不犯上，治中上下俱无犯。故曰：诛伐无过，命曰大惑。好古曰：治上必妨下，治表必违里。用黄芩以治肺必妨脾，用苁蓉以治肾必妨心，用干姜以治中必僭上，服附子以补火必涸水。从正曰：缓方有五：有甘以缓之之方，甘草、糖、蜜之属是也，病在胸膈，取其留恋也；有丸以缓之之方，比之汤散，其行迟慢也；有品件众多之缓方，药众则递相拘制，不得各骋其性也；有无毒治病之缓方，无毒则性纯功缓也；有气味俱薄之缓方，气味薄则长于补上治上，比至其下，药力已衰矣。　　</p>\n<p></p><p>$m{急方}　　</p>\n<p>        完素曰：味厚者为阴，味薄者为阴中之阳，故味厚则下泄，味薄则通气；气厚者为阳，气薄者为阳中之阴，故气厚则发热，气薄则发汗是也。好古曰：治主宜缓，缓则治其本也；治客宜急，急则治其标也。表里汗下，皆有所当缓、所当急。从正曰：急方有四：有急病急攻之急方，中风、关格之病是也。有汤散荡涤之急方，下咽易散而行速也。有毒药之急方，毒性能上涌下泄以夺病势也。有气味俱厚之急方，气味俱厚，直趋于下而力不衰也。　</p><p>$m{奇方}　　</p>\n<p>        王冰曰：单方也。从正曰：奇方有二：有独用一物之奇方，病在下而近者宜之。有药合阳数一、三、五、七、九之奇方，宜下不宜汗。完素曰：假如小承气，奇之小方也；大承气、抵当汤，奇之大方也，所谓因其攻下而为之也。桂枝、麻黄、偶之小方也；葛根、青龙，偶之大方也，所谓因其发散而用之也。故曰：汗不以奇，下不以偶。　　</p><p>$m{偶方}　　</p>\n<p>        从正曰：偶方有三：有两味相配之偶方，有古之二方相合之偶方，古谓之复方，皆病在下而远者宜之。有药合阴数二、四、六、八、十之偶方，宜汗不宜下。王太仆言汗药不以偶，则气不足以外发；下药不以奇，则药毒攻而致过。意者下本迅利，故单行则力专，专则直下、不旁及而速；汗或难出，故并行则物众而力微乎？乃仲景制方，桂枝汗药，反以三味为奇；大承气下药，反以四味为偶，何也？岂汗下缓急，在力之大小，而不以数之奇偶为重乎？　</p><p>$m{复方}　　</p>\n<p>        岐伯曰：奇之不去则偶之，是谓重方。好古曰：奇之不去复以偶，偶之不去复以奇，故曰复。复者，再也，重也。所谓十补一泄，数泄一补也。又伤寒见风脉，伤风得寒脉，为脉证不相应，宜以复方主之。从正曰：复方有三。有二方、三方及数方相合之复方，如桂枝二越婢一汤、五积散之属是也。有本方之外、别加馀药，如调胃承气加连翘、薄荷、黄芩、栀子为凉膈散之属是也。有分两均齐之复方，如胃风汤各等分之属是也。王太仆以偶为复方，今七方有偶又有复，岂非偶乃二方相合，复乃数方相合之谓乎？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001008,"no":8}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '夫方者，法也。法乃所以制物者也。故$x{大}、$x{小}、$x{缓}、$x{急}、$x{奇}、$x{偶}、$x{复}七者，为法制之变且尽也。 七方不同，同归已疾。其制各异，异以从宜。 岐伯言之已详，后人演之弥悉，凡制方者必本乎是。 $y{苟悖其制，则非法矣}。非法则不能所施合辙，而反致$m{乖刺}，恶在其能攻邪已疾耶！ 附录：七方 岐伯曰：气有多少，形有盛衰。治有缓急，方有大小。又曰：病有远近，证有中外，治有轻重。近者偶之，远者奇之。汗不以奇，下不以偶。补上治上制以缓，补下治下制以急。近而偶奇，制小其服；远而奇偶，制大其服。大则数小，小则数多。多则九之，少则一之。奇之不去则偶之，偶之不去则反佐以取之。所谓寒热温凉，反从其病也。 王冰曰：脏位有高下，腑气有远近。病证有表里，药用有轻重。单方为奇，复方为偶。心肺为近，肝肾为远，脾胃居中。肠、膀、胞、胆，亦有远近。识见高远，权以合宜。方奇而分两偶，方偶而分两奇。近而偶制，多数服之；远而奇制，少数服之。则肺服九，心服七，脾服五，肝服三，肾服一，为常制也，方与其重也宁轻，与其毒也宁良，与其大也宁小。是以奇方不去，偶方主之；偶方不去，则反佐以同病之气而取之。夫微小之热，折之以寒；微小之冷，消之以热。其大寒热，则必能与异气相格，声不同不相应，气不同不相合。是以反其佐，以同其气，夏令寒热参合，使其始同终异也。 逆者正治，从者反治。反佐，即从治也。谓热在下而上有寒邪拒格，则寒药中入热药为佐。下膈之后，热气既散，寒性随发也。寒在下而上有浮火拒格，则热药中入寒药为佐。下膈之后，寒气既消，热性随发也。此寒因热用，热因寒用之妙也。温冷仿此。 完素曰：流变在乎病，主病在乎方，制方在乎人。方有七：大、小、缓、急、奇、偶、复也。制方之体，本於气味。寒、热、温、凉，四气生於天；酸、苦、辛、咸、甘、淡，六味成於地。是以有形为味，无形为气。气为阳，味为阴。辛甘发散为阳，酸苦涌泄为阴。咸味涌泄为阴，淡味渗泄为阳。或收或散，或缓或急，或燥或润，或软或坚，各随脏腑之证。而施药之品味，乃分七方之制也。故奇、偶、复，三方也，大、小、缓、急，四制之法也。故曰：治有缓急，方有大小。 $m{大方} 岐伯曰：君一、臣三、佐九，制之大也；君一、臣三、佐五，制之中也；君一、臣二，制之小也。又曰：远而奇偶，制大其服；近而偶奇，制小其服。大则数少，小则数多。多则九之，小则二之。完素曰：身表为远，身里为近。大小者，制奇偶之法也。假如小承气汤、调胃承气汤，奇之小方也；大承气汤、抵当汤，奇之大方也，所谓因其攻里而用之也。桂枝、麻黄，偶之小方也；葛根、青龙，偶之大方也，所谓因其发表而用之也。故曰：汗不以奇，下不以偶。张从正曰：大方有二：有君一、臣三、佐九之大方，病有兼证而邪不一，不可以一二味治者宜之；有分两大而顿服之大方，肝肾及下部之病道远者宜之。王太仆以心肺为近，肾肝为远，脾胃为中。刘河间以身表为远，身里为近。以予观之，身半以上其气三，天之分也。身半以下其气三，地之分也。中脘，人之分也。 $m{小方} 从正曰：小方有二：有君一、臣二之小方，病无兼证，邪气专一，可一二味治者宜之；有分两少而频服之小方，心肺及在上之病者宜之，徐徐细呷是也。完素曰：肝肾位远，数多则其气缓，不能速达于下，必大剂而数少，取其迅急下走也。心肺位近，数少则其气急下走，不能升发于上，必小剂而数多，取其易散而上行也。王氏所谓肺服九，心服七，脾服五，肝服三，肾服一，乃五脏生成之数也。 $m{缓方} 岐伯曰：补上治上制以缓，补下治下制以急。急则气味厚，缓则气味薄，适其至所，此之谓也。病所远而中道气味之者，食而过之，无越其制度也。王冰曰：假如病在肾而心气不足，服药宜急过之，不以气味饲心，肾药凌心，心复益散矣。馀上下远近例同。完素曰：圣人治上不犯下，治下不犯上，治中上下俱无犯。故曰：诛伐无过，命曰大惑。好古曰：治上必妨下，治表必违里。用黄芩以治肺必妨脾，用苁蓉以治肾必妨心，用干姜以治中必僭上，服附子以补火必涸水。从正曰：缓方有五：有甘以缓之之方，甘草、糖、蜜之属是也，病在胸膈，取其留恋也；有丸以缓之之方，比之汤散，其行迟慢也；有品件众多之缓方，药众则递相拘制，不得各骋其性也；有无毒治病之缓方，无毒则性纯功缓也；有气味俱薄之缓方，气味薄则长于补上治上，比至其下，药力已衰矣。 $m{急方} 完素曰：味厚者为阴，味薄者为阴中之阳，故味厚则下泄，味薄则通气；气厚者为阳，气薄者为阳中之阴，故气厚则发热，气薄则发汗是也。好古曰：治主宜缓，缓则治其本也；治客宜急，急则治其标也。表里汗下，皆有所当缓、所当急。从正曰：急方有四：有急病急攻之急方，中风、关格之病是也。有汤散荡涤之急方，下咽易散而行速也。有毒药之急方，毒性能上涌下泄以夺病势也。有气味俱厚之急方，气味俱厚，直趋于下而力不衰也。 $m{奇方} 王冰曰：单方也。从正曰：奇方有二：有独用一物之奇方，病在下而近者宜之。有药合阳数一、三、五、七、九之奇方，宜下不宜汗。完素曰：假如小承气，奇之小方也；大承气、抵当汤，奇之大方也，所谓因其攻下而为之也。桂枝、麻黄、偶之小方也；葛根、青龙，偶之大方也，所谓因其发散而用之也。故曰：汗不以奇，下不以偶。 $m{偶方} 从正曰：偶方有三：有两味相配之偶方，有古之二方相合之偶方，古谓之复方，皆病在下而远者宜之。有药合阴数二、四、六、八、十之偶方，宜汗不宜下。王太仆言汗药不以偶，则气不足以外发；下药不以奇，则药毒攻而致过。意者下本迅利，故单行则力专，专则直下、不旁及而速；汗或难出，故并行则物众而力微乎？乃仲景制方，桂枝汗药，反以三味为奇；大承气下药，反以四味为偶，何也？岂汗下缓急，在力之大小，而不以数之奇偶为重乎？ $m{复方} 岐伯曰：奇之不去则偶之，是谓重方。好古曰：奇之不去复以偶，偶之不去复以奇，故曰复。复者，再也，重也。所谓十补一泄，数泄一补也。又伤寒见风脉，伤风得寒脉，为脉证不相应，宜以复方主之。从正曰：复方有三。有二方、三方及数方相合之复方，如桂枝二越婢一汤、五积散之属是也。有本方之外、别加馀药，如调胃承气加连翘、薄荷、黄芩、栀子为凉膈散之属是也。有分两均齐之复方，如胃风汤各等分之属是也。王太仆以偶为复方，今七方有偶又有复，岂非偶乃二方相合，复乃数方相合之谓乎？', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A4FcCLrJj0V', 1, '{"title":"卷之一_续序例上_论十剂本义","description":"<p>        剂者，从齐从刀，用以齐其不齐，而成其所以齐也。</p>\n<p></p>\n<p>       夫独用之谓药，合用之谓剂，而其才有长短、大小、良毒之难齐，故用有$x{相益}、$x{相济}、$x{相畏}、$x{相恶}、$x{相忌}、$x{相制}之不同，则剂有$x{宣}、$x{通}、$x{补}、$x{泻}、$x{轻}、$x{重}、$x{滑}、$x{涩}、$x{燥}、$x{湿}十者对治之各异。</p>\n<p></p>\n<p>       譬夫良相剂量群才，以成治世之功，类良医剂量群药，以成治病之功，其义一也。岐伯论之详矣！凡和剂者必本乎是。苟昧其旨而违其道，即失对治之义，求疾之瘳，其可得乎！　　</p><p>附录：十剂　　</p>\n<p>           刘完素曰：制方之体，欲成七方、十剂之用者，必本于气味也。寒、热、温、凉，四气生于天；酸、苦、辛、咸、甘、淡，六味成于地。是以有形为味，无形为气。气为阳，味为阴。阳气出上窍，阴味出下窍。气化则精生，味化则形长。故地产养形，形不足者，温之以气；天产养精，精不足者，补之以味。辛甘发散为阳，酸苦涌泄为阴；咸味涌泄为阴，淡味渗泄为阳。辛散、酸收、甘缓、苦坚、咸软，各随五脏之病，而制药性之品味。故方有七，剂有十。方不七，不足以尽方之变；剂不十，不足以尽剂之用。方不对证，非方也；剂不蠲疾，非剂也。此乃太古先师，设绳墨而取曲直；叔世方士，乃出规矩以为方圆。夫物各有性，制而用之，变而通之，施于品剂，其功用岂有穷哉！如是有因其性而为用者，有因其用而为使者，有因其所胜而为制者，有气相同则相求者，有气相克则相制者，有气有馀而补不足者，有气相感则以意使者，有质同而性异者，有名异而实同者。故蛇之性上窜而引药，蝉之性外脱而退翳，虻饮血而用以治血，鼠善穿而用以治漏，所谓因其性而为用者如此。弩牙速产，以机发而不括也；杵糠下咽，以杵筑下也，所谓因其用而为使者如此。浮萍不沉水，可以胜湿；独活不摇风，可以治风，所谓因其所胜而为制者如此。麻，木谷而治风；豆，水谷而治水，所谓气相同则相求者如此。牛，土畜，乳可以止渴疾；豕，水畜，心可以镇恍忽，所谓因其气相克则相制也如此。熊肉振羸，兔肝明视，所谓因其气有余补不足也如此。鲤之治水，鹜之利水，所谓因其气相感则以意使者如此。蜜成于蜂，蜜温而蜂寒；油生于麻，麻温而油寒，兹同质而异性者也。靡芜生于芎，蓬蘽并于覆盆，兹名异而实同者也。如斯之类，不可胜举。故天地赋形，不离阴阳，形色自然，皆有法象。毛羽之类，生于阳而属于阴；鳞甲之类，生于阴而属于阳。空青法木，色青而主肝；丹砂法火，色赤而主心；云母法金，色白而主肺；磁石法水，色黑而主肾；黄石脂法土，色黄而主脾。故触类而长之，莫不有自然之理也。欲为医者，上知天文，下知地理，中知人事，三者俱明，然后可以语人之疾病。不然，则如无目夜游，无足登陟，动致颠殒，而欲愈疾者，未之有也。　　</p>\n<p>       徐之才曰：药有宣、通、补、泻、轻、重、滑、涩、燥、湿十种，是药之大体，而《本经》不言，后人未述。凡用药者，审而详之，则靡所遗失矣。</p><p>宣剂　　</p>\n<p>        之才曰：宣可去壅，生姜、橘皮之属是也。杲曰：外感六淫之邪，欲传入里，三阴实而不受，逆于胸中，天分气分窒塞不通，而或哕或呕，所谓壅也。三阴者，脾也。故必破气，药如姜、橘、藿香、半夏之类，泻其壅塞。从正曰：俚人以宣为泻，又以宣为通，不知十剂之中，已有泻矣。仲景曰：春病在头，大法宜吐，是宣剂即涌剂也。经曰：高者因而越之，木郁则达之。宣者，升而上也，以君召臣曰宣是矣。凡风痫、中风、胸中诸实，痰饮寒结，胸中热郁，上而不下，久则喘嗽满胀，水肿之病生焉，非宣剂莫能愈也。吐中有汗，如引涎、追泪、嚏鼻，凡上行者，皆吐法也。完素曰：郁而不散为壅，必宣以散之，如痞满不通之类是矣。攻其里，则宣者上也，泄者下也。涌剂则瓜蒂、栀子之属是矣。发汗解表亦同。好古曰：《经》有五郁，木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之。皆宣也。教曰：宣，扬制曰宣朗，君召臣曰宣唤，臣奉君命，宣布上意，皆宣之意也。　　</p><p>通剂　　</p>\n<p>         之才曰：通可去滞，通草、防己之属是也。完素曰：留而不行，必通以行之。如水病为痰澼之类，以木通、防己之属攻其内，则留者行也。滑石、茯苓、芫花、甘遂、大戟、牵牛之类是也。从正曰：通者，流通也。前后不得溲便，宜木通、海金沙、琥珀、大黄之属通之。痹病郁滞，经隧不利，亦宜通之。　　</p><p>补剂　　</p>\n<p>         之才曰：补可去弱，人参、羊肉之属是也。杲曰：人参甘温，能补气虚；羊肉甘热，能补血虚。羊肉补形，人参补气。凡气味与二药同者皆是也。从正曰：五脏各有补泻，五味各补其脏，有表虚、里虚、上虚、下虚、阴虚、阳虚、气虚、血虚。《经》曰：精不足者补之以味，形不足者温之以气。五谷、五菜、五果、五肉，皆补养之物也。　</p><p>泻剂　　</p>\n<p>            之才曰：泄可去闭，葶苈、大黄之属是也。杲曰：葶苈苦寒，气味俱厚，不减大黄，能泄肺中之闭，又泄大肠。大黄走而不守，能泄血闭、肠胃渣秽之物。一泄气闭利小便，一泄血闭利大便。凡与二药同者皆然。从正曰：实则泄之。诸痛为实，痛随利减。芒硝、大黄、牵牛、甘遂、巴豆之属，皆泻剂也。其催生下乳，磨积逐水，破经泄气，凡下行者，皆下法也。</p><p>轻剂　　</p>\n<p>         之才曰：轻可去实，麻黄、葛根之属是也。从正曰：风寒之邪，始客皮肤，头痛身热，宜解其表，《内经》所谓轻而扬之也。痈疮疥痤，俱宜解表。汗以泄之，毒以熏之，皆轻剂也。凡熏、洗、蒸、灸、熨、烙、刺、砭、导引、按摩，皆汗法也。　　</p><p>重剂　　</p>\n<p>           之才曰：重可去怯，磁石、铁粉之属是也。从正曰：重者，镇坠之谓也。怯则气浮，如丧神失守，而惊悸气上。朱砂、水银、沉香、黄丹、寒水石之伦，皆镇重也。久病咳嗽，涎潮于上，形羸不可攻者，以此坠之。《经》曰：重者因而减之，贵其渐也。</p><p>滑剂　　</p>\n<p>         之才曰：滑可去着，冬葵子、榆白皮之属是也。完素曰：涩则气着，必滑剂以利之。滑能养窍，故润利也。从正曰：大便燥结，宜麻仁、郁李之类；小便癃闭，宜葵子、滑石之类。前后不通，两阴俱闭也，名曰三焦约。约者，束也。宜先以滑剂润养其燥，然后攻之。</p><p>涩剂　　</p>\n<p>         之才曰：涩可去脱，牡蛎、龙骨之属是也。完素曰：滑则气脱，如开肠洞泄，便溺遗失之类，必涩剂以收敛之。从正曰：寝汗不禁，涩以牡蛎、五味、五倍之属。滑泄不已，涩以肉豆蔻、诃黎勒、没食子、亚芙蓉、龙骨之属。凡酸味同乎涩者，收敛之义也。然此种皆宜先攻其本，而后收之可也。　　</p><p>燥剂　　</p>\n<p>         之才曰：燥可去湿，桑白皮、赤小豆之属是也。完素曰：湿气淫胜，肿满脾湿，必燥剂以除之，桑皮之属。湿胜于上，以苦吐之，以淡渗之是也。从正曰：积寒久冷，吐利腥秽，上下所出水液澄彻清冷，此大寒之病，宜姜、附、胡椒辈以燥之。若病湿气，则陈皮、白术、木香、苍术之属除之，亦燥剂也。而黄连、黄檗、栀子、大黄，其味皆苦，苦属火化，皆能燥湿，此《内经》之本旨也，岂独二术之类为燥剂乎？好古曰：湿有在上、在中、在下、在经、在皮、在里。　　</p><p>湿剂　　</p>\n<p>            之才曰：湿可去枯，白石英、紫石英之属是也。从正曰：湿者，润湿也。虽与滑类，少有不同。《经》云：辛以润之。辛能走气、能化液故也。盐、硝味虽咸，属真阴之水，诚濡枯之上药也。人有枯涸皴揭之病，非独金化，盖有火以乘之，故非湿剂不能愈。完素曰：津耗为枯，五脏痿弱，荣卫涸涩，必湿剂以润之。好古曰：有减气而枯，有减血而枯。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001009,"no":9}}', '2024-12-21T01:40:24.000Z', '2024-12-21T01:40:24.000Z', '2024-12-21T01:40:24.000Z', '剂者，从齐从刀，用以齐其不齐，而成其所以齐也。 夫独用之谓药，合用之谓剂，而其才有长短、大小、良毒之难齐，故用有$x{相益}、$x{相济}、$x{相畏}、$x{相恶}、$x{相忌}、$x{相制}之不同，则剂有$x{宣}、$x{通}、$x{补}、$x{泻}、$x{轻}、$x{重}、$x{滑}、$x{涩}、$x{燥}、$x{湿}十者对治之各异。 譬夫良相剂量群才，以成治世之功，类良医剂量群药，以成治病之功，其义一也。岐伯论之详矣！凡和剂者必本乎是。苟昧其旨而违其道，即失对治之义，求疾之瘳，其可得乎！ 附录：十剂 刘完素曰：制方之体，欲成七方、十剂之用者，必本于气味也。寒、热、温、凉，四气生于天；酸、苦、辛、咸、甘、淡，六味成于地。是以有形为味，无形为气。气为阳，味为阴。阳气出上窍，阴味出下窍。气化则精生，味化则形长。故地产养形，形不足者，温之以气；天产养精，精不足者，补之以味。辛甘发散为阳，酸苦涌泄为阴；咸味涌泄为阴，淡味渗泄为阳。辛散、酸收、甘缓、苦坚、咸软，各随五脏之病，而制药性之品味。故方有七，剂有十。方不七，不足以尽方之变；剂不十，不足以尽剂之用。方不对证，非方也；剂不蠲疾，非剂也。此乃太古先师，设绳墨而取曲直；叔世方士，乃出规矩以为方圆。夫物各有性，制而用之，变而通之，施于品剂，其功用岂有穷哉！如是有因其性而为用者，有因其用而为使者，有因其所胜而为制者，有气相同则相求者，有气相克则相制者，有气有馀而补不足者，有气相感则以意使者，有质同而性异者，有名异而实同者。故蛇之性上窜而引药，蝉之性外脱而退翳，虻饮血而用以治血，鼠善穿而用以治漏，所谓因其性而为用者如此。弩牙速产，以机发而不括也；杵糠下咽，以杵筑下也，所谓因其用而为使者如此。浮萍不沉水，可以胜湿；独活不摇风，可以治风，所谓因其所胜而为制者如此。麻，木谷而治风；豆，水谷而治水，所谓气相同则相求者如此。牛，土畜，乳可以止渴疾；豕，水畜，心可以镇恍忽，所谓因其气相克则相制也如此。熊肉振羸，兔肝明视，所谓因其气有余补不足也如此。鲤之治水，鹜之利水，所谓因其气相感则以意使者如此。蜜成于蜂，蜜温而蜂寒；油生于麻，麻温而油寒，兹同质而异性者也。靡芜生于芎，蓬蘽并于覆盆，兹名异而实同者也。如斯之类，不可胜举。故天地赋形，不离阴阳，形色自然，皆有法象。毛羽之类，生于阳而属于阴；鳞甲之类，生于阴而属于阳。空青法木，色青而主肝；丹砂法火，色赤而主心；云母法金，色白而主肺；磁石法水，色黑而主肾；黄石脂法土，色黄而主脾。故触类而长之，莫不有自然之理也。欲为医者，上知天文，下知地理，中知人事，三者俱明，然后可以语人之疾病。不然，则如无目夜游，无足登陟，动致颠殒，而欲愈疾者，未之有也。 徐之才曰：药有宣、通、补、泻、轻、重、滑、涩、燥、湿十种，是药之大体，而《本经》不言，后人未述。凡用药者，审而详之，则靡所遗失矣。 宣剂 之才曰：宣可去壅，生姜、橘皮之属是也。杲曰：外感六淫之邪，欲传入里，三阴实而不受，逆于胸中，天分气分窒塞不通，而或哕或呕，所谓壅也。三阴者，脾也。故必破气，药如姜、橘、藿香、半夏之类，泻其壅塞。从正曰：俚人以宣为泻，又以宣为通，不知十剂之中，已有泻矣。仲景曰：春病在头，大法宜吐，是宣剂即涌剂也。经曰：高者因而越之，木郁则达之。宣者，升而上也，以君召臣曰宣是矣。凡风痫、中风、胸中诸实，痰饮寒结，胸中热郁，上而不下，久则喘嗽满胀，水肿之病生焉，非宣剂莫能愈也。吐中有汗，如引涎、追泪、嚏鼻，凡上行者，皆吐法也。完素曰：郁而不散为壅，必宣以散之，如痞满不通之类是矣。攻其里，则宣者上也，泄者下也。涌剂则瓜蒂、栀子之属是矣。发汗解表亦同。好古曰：《经》有五郁，木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之。皆宣也。教曰：宣，扬制曰宣朗，君召臣曰宣唤，臣奉君命，宣布上意，皆宣之意也。 通剂 之才曰：通可去滞，通草、防己之属是也。完素曰：留而不行，必通以行之。如水病为痰澼之类，以木通、防己之属攻其内，则留者行也。滑石、茯苓、芫花、甘遂、大戟、牵牛之类是也。从正曰：通者，流通也。前后不得溲便，宜木通、海金沙、琥珀、大黄之属通之。痹病郁滞，经隧不利，亦宜通之。 补剂 之才曰：补可去弱，人参、羊肉之属是也。杲曰：人参甘温，能补气虚；羊肉甘热，能补血虚。羊肉补形，人参补气。凡气味与二药同者皆是也。从正曰：五脏各有补泻，五味各补其脏，有表虚、里虚、上虚、下虚、阴虚、阳虚、气虚、血虚。《经》曰：精不足者补之以味，形不足者温之以气。五谷、五菜、五果、五肉，皆补养之物也。 泻剂 之才曰：泄可去闭，葶苈、大黄之属是也。杲曰：葶苈苦寒，气味俱厚，不减大黄，能泄肺中之闭，又泄大肠。大黄走而不守，能泄血闭、肠胃渣秽之物。一泄气闭利小便，一泄血闭利大便。凡与二药同者皆然。从正曰：实则泄之。诸痛为实，痛随利减。芒硝、大黄、牵牛、甘遂、巴豆之属，皆泻剂也。其催生下乳，磨积逐水，破经泄气，凡下行者，皆下法也。 轻剂 之才曰：轻可去实，麻黄、葛根之属是也。从正曰：风寒之邪，始客皮肤，头痛身热，宜解其表，《内经》所谓轻而扬之也。痈疮疥痤，俱宜解表。汗以泄之，毒以熏之，皆轻剂也。凡熏、洗、蒸、灸、熨、烙、刺、砭、导引、按摩，皆汗法也。 重剂 之才曰：重可去怯，磁石、铁粉之属是也。从正曰：重者，镇坠之谓也。怯则气浮，如丧神失守，而惊悸气上。朱砂、水银、沉香、黄丹、寒水石之伦，皆镇重也。久病咳嗽，涎潮于上，形羸不可攻者，以此坠之。《经》曰：重者因而减之，贵其渐也。 滑剂 之才曰：滑可去着，冬葵子、榆白皮之属是也。完素曰：涩则气着，必滑剂以利之。滑能养窍，故润利也。从正曰：大便燥结，宜麻仁、郁李之类；小便癃闭，宜葵子、滑石之类。前后不通，两阴俱闭也，名曰三焦约。约者，束也。宜先以滑剂润养其燥，然后攻之。 涩剂 之才曰：涩可去脱，牡蛎、龙骨之属是也。完素曰：滑则气脱，如开肠洞泄，便溺遗失之类，必涩剂以收敛之。从正曰：寝汗不禁，涩以牡蛎、五味、五倍之属。滑泄不已，涩以肉豆蔻、诃黎勒、没食子、亚芙蓉、龙骨之属。凡酸味同乎涩者，收敛之义也。然此种皆宜先攻其本，而后收之可也。 燥剂 之才曰：燥可去湿，桑白皮、赤小豆之属是也。完素曰：湿气淫胜，肿满脾湿，必燥剂以除之，桑皮之属。湿胜于上，以苦吐之，以淡渗之是也。从正曰：积寒久冷，吐利腥秽，上下所出水液澄彻清冷，此大寒之病，宜姜、附、胡椒辈以燥之。若病湿气，则陈皮、白术、木香、苍术之属除之，亦燥剂也。而黄连、黄檗、栀子、大黄，其味皆苦，苦属火化，皆能燥湿，此《内经》之本旨也，岂独二术之类为燥剂乎？好古曰：湿有在上、在中、在下、在经、在皮、在里。 湿剂 之才曰：湿可去枯，白石英、紫石英之属是也。从正曰：湿者，润湿也。虽与滑类，少有不同。《经》云：辛以润之。辛能走气、能化液故也。盐、硝味虽咸，属真阴之水，诚濡枯之上药也。人有枯涸皴揭之病，非独金化，盖有火以乘之，故非湿剂不能愈。完素曰：津耗为枯，五脏痿弱，荣卫涸涩，必湿剂以润之。好古曰：有减气而枯，有减血而枯。', '2024-12-21T01:40:24.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Sv2jfePztQ', 1, '{"title":"卷之一_续序例上_十剂补遗","description":"<p>       十剂之后，陶隐居续入寒热二剂。岂知寒有时而不可以治热，热有时而不可以治寒，何者？阴虚内热，当用甘寒滋肾家之阴，是益水以制火也。设用芩、连、栀子苦寒之剂以攻热，则徒败胃气。苦寒损胃而伤血，血愈不足而热愈炽。胃气伤则后天之元气愈无所养，而病转增剧也。阳虚中外俱寒，当以人参、黄耆以益表里之阳气，而少佐桂、附以回阳，则其寒自解，是益火以祛寒也。设专用辛热，如吴茱萸、干姜、麻黄、葫芦巴、荜茇、胡椒之属以散寒，则辛能走散，真气愈虚，其寒愈甚。王安道所谓辛热愈投而沉寒愈滋也。二者非徒无益，而又害之，顾不悖欤！况寒热二剂，摄在补泻，义不重出。今当增入升降二剂。升降者，治法之大机也。《经》曰：高者抑之，即降之义也。下者举之，即升之义也。是以病升者用降剂，病降者用升剂。火空则发，降气则火自下矣，火下是阳交于阴也，此法所宜降者也。劳伤则阳气下陷，入于阴分，东垣所谓阴实阳虚。阳虚则内外皆寒，间有表热类外感者，但不头疼口渴、及热有时而间为异耳，法当升阳益气，用参、耆、炙甘草益元气以除虚寒虚热，佐以升麻、柴胡引阳气上行，则表里之寒热自解，即甘温除大热之谓，此法所宜升者也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001010,"no":10}}', '2024-12-21T01:45:04.000Z', '2024-12-21T01:45:04.000Z', '2024-12-21T01:45:04.000Z', '十剂之后，陶隐居续入寒热二剂。岂知寒有时而不可以治热，热有时而不可以治寒，何者？阴虚内热，当用甘寒滋肾家之阴，是益水以制火也。设用芩、连、栀子苦寒之剂以攻热，则徒败胃气。苦寒损胃而伤血，血愈不足而热愈炽。胃气伤则后天之元气愈无所养，而病转增剧也。阳虚中外俱寒，当以人参、黄耆以益表里之阳气，而少佐桂、附以回阳，则其寒自解，是益火以祛寒也。设专用辛热，如吴茱萸、干姜、麻黄、葫芦巴、荜茇、胡椒之属以散寒，则辛能走散，真气愈虚，其寒愈甚。王安道所谓辛热愈投而沉寒愈滋也。二者非徒无益，而又害之，顾不悖欤！况寒热二剂，摄在补泻，义不重出。今当增入升降二剂。升降者，治法之大机也。《经》曰：高者抑之，即降之义也。下者举之，即升之义也。是以病升者用降剂，病降者用升剂。火空则发，降气则火自下矣，火下是阳交于阴也，此法所宜降者也。劳伤则阳气下陷，入于阴分，东垣所谓阴实阳虚。阳虚则内外皆寒，间有表热类外感者，但不头疼口渴、及热有时而间为异耳，法当升阳益气，用参、耆、炙甘草益元气以除虚寒虚热，佐以升麻、柴胡引阳气上行，则表里之寒热自解，即甘温除大热之谓，此法所宜升者也。', '2024-12-21T01:45:04.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cz5fyMpaEiV', 1, '{"title":"卷之一_续序例上_五脏苦欲补泻论","description":"<p>       五脏苦欲补泻，乃用药第一义。好古为东垣高足，东垣得之洁古，洁古实宗仲景。仲景远师伊尹，伊尹原本炎黄。圣哲授受，百世一源，靡或少异。不明乎此，不足以言医矣。何则？五脏之内，各有其神。神各有性，性复各殊。故《素问》命十二官之名，厥有旨焉。盖形而上者，神也，有知而无质；形而下者，块然者也，五脏之体也，有质而无知。各各分断者也。肝藏魂，肺藏魄，心藏神，脾藏意与智，肾藏精与志，皆指有知之性而言，即神也。神也者，阴阳不测之谓也。是形而上者，脏之性也。惟其无形，故能主乎有形。故知苦欲者，犹言好恶也。违其性故苦，遂其性故欲。欲者，是本脏之神之所好也，即补也。苦者，是本脏之神之所恶也，即泻也。补泻系乎苦欲，苦欲因乎脏性。不属五行，未落阴阳，其神用之谓与！自“虚则补其母”已下，乃言脏体之虚实，始有补母泻子之法，斯则五行之性也。明乎此，斯可以言药道矣。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001011,"no":11}}', '2024-12-21T01:47:15.000Z', '2024-12-21T01:47:15.000Z', '2024-12-21T01:47:15.000Z', '五脏苦欲补泻，乃用药第一义。好古为东垣高足，东垣得之洁古，洁古实宗仲景。仲景远师伊尹，伊尹原本炎黄。圣哲授受，百世一源，靡或少异。不明乎此，不足以言医矣。何则？五脏之内，各有其神。神各有性，性复各殊。故《素问》命十二官之名，厥有旨焉。盖形而上者，神也，有知而无质；形而下者，块然者也，五脏之体也，有质而无知。各各分断者也。肝藏魂，肺藏魄，心藏神，脾藏意与智，肾藏精与志，皆指有知之性而言，即神也。神也者，阴阳不测之谓也。是形而上者，脏之性也。惟其无形，故能主乎有形。故知苦欲者，犹言好恶也。违其性故苦，遂其性故欲。欲者，是本脏之神之所好也，即补也。苦者，是本脏之神之所恶也，即泻也。补泻系乎苦欲，苦欲因乎脏性。不属五行，未落阴阳，其神用之谓与！自“虚则补其母”已下，乃言脏体之虚实，始有补母泻子之法，斯则五行之性也。明乎此，斯可以言药道矣。', '2024-12-21T01:47:15.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oh0ftU5iL63', 1, '{"title":"卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>        肝苦急，急食甘以缓之，（甘草。）欲散，急食辛以散之，（川芎。）以辛补之，（细辛。）以酸泻之，（芍药。）虚以生姜、陈皮之类补之。《经》曰：虚则补其母，水能生木，肾乃肝之母。肾，水也。苦以补肾，熟地黄、黄檗是矣。如无他证，钱氏地黄丸主之。实则白芍药泻之，如无他证，钱氏泻青丸主之。实则泻其子，心乃肝之子，以甘草泻心。　</p><p>         肝为将军之官，言不受制者也，急则有摧折之意焉，故苦而恶之。缓之，是使遂其性也。甘可以缓，甘草之属是已。扶苏条达，木之象也；升发开展，魂之用也。故其性欲散，辛以散之，解其束缚也，是散即补也。辛可以散，川芎之属是已。若其太过，则屈制之，毋使逾分。酸可以收，芍药之属是已。急也，敛也，肝性之所苦也。违其性而苦之，肝斯虚矣。补之以辛，是明以散为补也，细辛、生姜、陈皮之属是已。　</p><p>        心苦缓，急食酸以收之，（五味子。）欲软，急食咸以软之，（芒硝。）以咸补之，（泽泻。）以甘泻之，（人参、黄耆、甘草。）虚以炒盐补之，虚则补其母。木能生火，肝乃心之母。肝，木也，以生姜补肝。如无他证，钱氏安神丸主之。实则甘草泻之。如无他证，钱氏方中重则泻心汤，轻则导赤散。　</p><p>          心为形君，神明之性，恶散缓而喜收敛。散缓则违其性，敛则宁静清明，故宜酸以收其缓也。软者，和调之义也。心君本自和调，邪热乘之则躁急，故复须芒硝之咸寒，除其邪热，以软其躁急坚劲之气，使复其平也。以咸补之，泽泻导心气以入肾也。烦劳则虚而生热，故须人参、黄芪、甘草之甘温，以益元气而虚热自退，故谓之泻也。心以下交于肾为补，炒盐之咸以润下，即得心与肾交也。火空则发，盐为水味，得之俾心气下降，是既济之道也，有补之义焉，故软即补也。　　</p><p>       脾苦湿，急食苦以燥之，（白术。）欲缓，急食甘以缓之，（甘草。）以甘补之，（人参。）以苦泻之，（黄连。）虚以甘草、大枣之类补之，如无他证，钱氏益黄散主之。心乃脾之母，以炒盐补心。实则以枳实泻之，如无他证，以泻黄散泻之。肺乃脾之子，以桑白皮泻肺。</p><p>         脾为仓廪之官，主运动磨物之脏。燥，其性也，宜健而不宜滞。湿，斯滞矣。违其性，故苦而恶之。急食苦以燥之，使复其性之所喜，脾斯健矣。白术之苦温是已。过燥则复欲缓之以甘，甘草之属是已。稼穑之化，故甘先入脾。性欲健运，气旺则行。补之以甘，人参是已。长夏之令，湿热主之。脾气斯困，故当急食苦以泻之，黄连之苦寒是已。虚则宜补，炙甘草之甘以益血，大枣之甘温以益气，乃所以补其不足也。　　</p><p>      肺苦气上逆，急食苦以泄之，（诃子皮，一作黄芩。）欲收，急食酸以收之，（白芍药。）以辛泻之，（桑白皮。）以酸补之，（五味子。）虚则五味子补之，如无他证，钱氏阿胶散补之。脾乃肺之母，以甘草补脾。实则桑白皮泻之，如无他证，以泻白散泻之。肾乃肺之子。以泽泻泻肾。　</p><p>       肺为华盖之脏，相傅之官，藏魄而主气者也。气常则顺，气变则逆，逆则违其性矣，故宜急食苦以泄之，黄芩之属是已。肺主上焦，其政敛肃，故其性喜收，宜急食酸以收之，白芍药之属是已。贼肺者，热也，肺受热邪，急食辛以泻之，桑白皮之属是已，不敛，则气无所管束，是肺失其职也，故宜补之以酸，使遂其收敛之性，以清肃乎上焦，是即补也。五味子之属是已。　</p><p>      肾苦燥，急食辛以润之，（知母。）欲坚，急食苦以坚之，（黄檗。）以苦补之，（地黄。）以咸泻之，（泽泻。）虚则熟地黄、黄檗补之。肾本无实，不可泻，钱氏止有补肾地黄丸，无泻肾之药。肺乃肾之母，以五味子补肺。　</p><p>        肾为作强之官，藏精与志，主五液，属真阴，水脏也。其性本润，故恶涸燥，宜急食辛以润之，知母之属是已。欲坚，急食苦以坚之。盖肾非坚，则无以称作强之职。四气以遇湿热即软，遇寒冷即坚。五味以得咸即软，得苦即坚，故宜急食苦以坚之。黄檗味苦气寒，可以坚肾，故宜急食，以遂其欲坚之性也。以苦补之，是坚即补也，地黄、黄檗之属是已。咸能软坚，软即泻也，泽泻之属是已。虚者，精气夺也。藏精之脏，苦固能坚，然非益精，无以为补，故宜熟地黄、黄檗之属以补之是已。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001012,"no":12}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肝苦急，急食甘以缓之，（甘草。）欲散，急食辛以散之，（川芎。）以辛补之，（细辛。）以酸泻之，（芍药。）虚以生姜、陈皮之类补之。《经》曰：虚则补其母，水能生木，肾乃肝之母。肾，水也。苦以补肾，熟地黄、黄檗是矣。如无他证，钱氏地黄丸主之。实则白芍药泻之，如无他证，钱氏泻青丸主之。实则泻其子，心乃肝之子，以甘草泻心。 肝为将军之官，言不受制者也，急则有摧折之意焉，故苦而恶之。缓之，是使遂其性也。甘可以缓，甘草之属是已。扶苏条达，木之象也；升发开展，魂之用也。故其性欲散，辛以散之，解其束缚也，是散即补也。辛可以散，川芎之属是已。若其太过，则屈制之，毋使逾分。酸可以收，芍药之属是已。急也，敛也，肝性之所苦也。违其性而苦之，肝斯虚矣。补之以辛，是明以散为补也，细辛、生姜、陈皮之属是已。 心苦缓，急食酸以收之，（五味子。）欲软，急食咸以软之，（芒硝。）以咸补之，（泽泻。）以甘泻之，（人参、黄耆、甘草。）虚以炒盐补之，虚则补其母。木能生火，肝乃心之母。肝，木也，以生姜补肝。如无他证，钱氏安神丸主之。实则甘草泻之。如无他证，钱氏方中重则泻心汤，轻则导赤散。 心为形君，神明之性，恶散缓而喜收敛。散缓则违其性，敛则宁静清明，故宜酸以收其缓也。软者，和调之义也。心君本自和调，邪热乘之则躁急，故复须芒硝之咸寒，除其邪热，以软其躁急坚劲之气，使复其平也。以咸补之，泽泻导心气以入肾也。烦劳则虚而生热，故须人参、黄芪、甘草之甘温，以益元气而虚热自退，故谓之泻也。心以下交于肾为补，炒盐之咸以润下，即得心与肾交也。火空则发，盐为水味，得之俾心气下降，是既济之道也，有补之义焉，故软即补也。 脾苦湿，急食苦以燥之，（白术。）欲缓，急食甘以缓之，（甘草。）以甘补之，（人参。）以苦泻之，（黄连。）虚以甘草、大枣之类补之，如无他证，钱氏益黄散主之。心乃脾之母，以炒盐补心。实则以枳实泻之，如无他证，以泻黄散泻之。肺乃脾之子，以桑白皮泻肺。 脾为仓廪之官，主运动磨物之脏。燥，其性也，宜健而不宜滞。湿，斯滞矣。违其性，故苦而恶之。急食苦以燥之，使复其性之所喜，脾斯健矣。白术之苦温是已。过燥则复欲缓之以甘，甘草之属是已。稼穑之化，故甘先入脾。性欲健运，气旺则行。补之以甘，人参是已。长夏之令，湿热主之。脾气斯困，故当急食苦以泻之，黄连之苦寒是已。虚则宜补，炙甘草之甘以益血，大枣之甘温以益气，乃所以补其不足也。 肺苦气上逆，急食苦以泄之，（诃子皮，一作黄芩。）欲收，急食酸以收之，（白芍药。）以辛泻之，（桑白皮。）以酸补之，（五味子。）虚则五味子补之，如无他证，钱氏阿胶散补之。脾乃肺之母，以甘草补脾。实则桑白皮泻之，如无他证，以泻白散泻之。肾乃肺之子。以泽泻泻肾。 肺为华盖之脏，相傅之官，藏魄而主气者也。气常则顺，气变则逆，逆则违其性矣，故宜急食苦以泄之，黄芩之属是已。肺主上焦，其政敛肃，故其性喜收，宜急食酸以收之，白芍药之属是已。贼肺者，热也，肺受热邪，急食辛以泻之，桑白皮之属是已，不敛，则气无所管束，是肺失其职也，故宜补之以酸，使遂其收敛之性，以清肃乎上焦，是即补也。五味子之属是已。 肾苦燥，急食辛以润之，（知母。）欲坚，急食苦以坚之，（黄檗。）以苦补之，（地黄。）以咸泻之，（泽泻。）虚则熟地黄、黄檗补之。肾本无实，不可泻，钱氏止有补肾地黄丸，无泻肾之药。肺乃肾之母，以五味子补肺。 肾为作强之官，藏精与志，主五液，属真阴，水脏也。其性本润，故恶涸燥，宜急食辛以润之，知母之属是已。欲坚，急食苦以坚之。盖肾非坚，则无以称作强之职。四气以遇湿热即软，遇寒冷即坚。五味以得咸即软，得苦即坚，故宜急食苦以坚之。黄檗味苦气寒，可以坚肾，故宜急食，以遂其欲坚之性也。以苦补之，是坚即补也，地黄、黄檗之属是已。咸能软坚，软即泻也，泽泻之属是已。虚者，精气夺也。藏精之脏，苦固能坚，然非益精，无以为补，故宜熟地黄、黄檗之属以补之是已。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HFHOzS2lI5c', 1, '{"title":"卷之一_续序例上_治法提纲","description":"<p>1、（阴阳、寒热、脏腑、经络、气血、表里、标本先后、虚实缓急）</p><p>2、病在于阴，毋犯其阳；病在于阳，毋犯其阴。犯之者，是谓诛伐无过。</p><p>3、病之热也，当察其源：火苟实也，苦寒咸寒以折之；若其虚也，甘寒酸寒以摄之。病之寒也，亦察其源：寒从外也，辛热辛温以散之；动于内也，甘温以益之，辛热辛温以佐之。</p><p>4、《经》曰：五脏者，藏精气而不泻者也，故曰满而不能实。是有补而无泻者，其常也。脏偶受邪，则泻其邪，邪尽即止。是泻其邪，非泻脏也。脏不受邪，毋轻犯也。世谓肝无补法，知其谬也。六腑者，传导化物糟粕者也，故曰实而不能满。邪客之而为病，乃可攻也。中病乃已，毋尽剂也。</p><p>5、病在于经，则治其经；病流于络，则及其络。经直络横，相维辅也。</p><p>6、病从气分，则治其气：虚者温之，实者调之。病从血分，则治其血：虚则补肝、补脾、补心，实则为热、为瘀，热者清之，瘀者行之。因气病而及血者，先治其气；因血病而及气者，先治其血。因证互异，宜精别之。</p><p>7、病在于表，毋攻其里；病在于里，毋虚其表。邪之所在，攻必从之。</p><p>8、受邪为本，现证为标；五虚为本，五邪为标。譬夫腹胀由于湿者，其来必速，当利水除湿，则胀自止，是标急于本也，当先治其标。若因脾虚，渐成胀满，夜剧昼静，病属于阴，当补脾阴；夜静昼剧，病属于阳，当益脾气。是病从本生，本急于标也，当先治其本。举一为例，馀可类推矣。</p><p>9、病属于虚，宜治以缓。虚者精气夺也。若属沉痼，亦必从缓。治虚无速法，亦无巧法。盖病已沉痼，凡欲施治，宜有次第，故亦无速法。病属于实，宜治以急。实者，邪气胜也。邪不速逐，则为害滋蔓，故治实无迟法，亦无巧法。此病缓急一定之法也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001013,"no":13}}', '2024-12-21T02:35:55.000Z', '2024-12-21T02:35:55.000Z', '2024-12-21T02:35:55.000Z', '1、（阴阳、寒热、脏腑、经络、气血、表里、标本先后、虚实缓急） 2、病在于阴，毋犯其阳；病在于阳，毋犯其阴。犯之者，是谓诛伐无过。 3、病之热也，当察其源：火苟实也，苦寒咸寒以折之；若其虚也，甘寒酸寒以摄之。病之寒也，亦察其源：寒从外也，辛热辛温以散之；动于内也，甘温以益之，辛热辛温以佐之。 4、《经》曰：五脏者，藏精气而不泻者也，故曰满而不能实。是有补而无泻者，其常也。脏偶受邪，则泻其邪，邪尽即止。是泻其邪，非泻脏也。脏不受邪，毋轻犯也。世谓肝无补法，知其谬也。六腑者，传导化物糟粕者也，故曰实而不能满。邪客之而为病，乃可攻也。中病乃已，毋尽剂也。 5、病在于经，则治其经；病流于络，则及其络。经直络横，相维辅也。 6、病从气分，则治其气：虚者温之，实者调之。病从血分，则治其血：虚则补肝、补脾、补心，实则为热、为瘀，热者清之，瘀者行之。因气病而及血者，先治其气；因血病而及气者，先治其血。因证互异，宜精别之。 7、病在于表，毋攻其里；病在于里，毋虚其表。邪之所在，攻必从之。 8、受邪为本，现证为标；五虚为本，五邪为标。譬夫腹胀由于湿者，其来必速，当利水除湿，则胀自止，是标急于本也，当先治其标。若因脾虚，渐成胀满，夜剧昼静，病属于阴，当补脾阴；夜静昼剧，病属于阳，当益脾气。是病从本生，本急于标也，当先治其本。举一为例，馀可类推矣。 9、病属于虚，宜治以缓。虚者精气夺也。若属沉痼，亦必从缓。治虚无速法，亦无巧法。盖病已沉痼，凡欲施治，宜有次第，故亦无速法。病属于实，宜治以急。实者，邪气胜也。邪不速逐，则为害滋蔓，故治实无迟法，亦无巧法。此病缓急一定之法也。', '2024-12-21T02:35:55.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6LBaBNLqD3L', 1, '{"title":"卷之一_续序例上_药性差别论","description":"<p>1、药有五味，中涵四气，因气味而成性。合气与味及性而论，其为差别，本自多途。其间厚薄多少，单用互兼，各各不同，良难究竟。是故《经》曰：五味之变，不可胜穷。此方剂之本也。阴阳二象，实为之纲纪焉。咸味本水，苦味本火，酸味本木，甘味本土，辛味本金，此五味之常也。及其变也，有神明之用焉。今姑陈其略以明之：　　</p><p>2、第准经文，同一苦寒也，黄芩则燥，天冬则润，芦会能消，黄檗能补，黄连止泻，大黄下通，柴胡苦寒而升，龙胆苦寒而降。同一咸也，泽泻则泻，苁容则补，海藻、昆布则消而软坚，马茎、鹿茸则补而生齿。同一酸也，硫黄味酸而热，空青味酸而寒。甘合辛而发散为阳，甘合酸而收敛为阴。人参、黄耆，阳也，甘温以除大热；地黄、五味，阴也，甘酸以敛阴精。聊采数端，引以为例。如斯之类，难可枚举。良由气味互兼，性质各异，参合多少，制用全殊。所以穷五味之变，明药物之能，厥有旨哉！顾其用纷错，其道渊微，可以意知，难以言尽。非由妙悟，则物不从心。固将拯烝民于夭枉，宜寤寐乎兹篇。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001014,"no":14}}', '2024-12-21T02:38:57.000Z', '2024-12-21T02:38:57.000Z', '2024-12-21T02:38:57.000Z', '1、药有五味，中涵四气，因气味而成性。合气与味及性而论，其为差别，本自多途。其间厚薄多少，单用互兼，各各不同，良难究竟。是故《经》曰：五味之变，不可胜穷。此方剂之本也。阴阳二象，实为之纲纪焉。咸味本水，苦味本火，酸味本木，甘味本土，辛味本金，此五味之常也。及其变也，有神明之用焉。今姑陈其略以明之： 2、第准经文，同一苦寒也，黄芩则燥，天冬则润，芦会能消，黄檗能补，黄连止泻，大黄下通，柴胡苦寒而升，龙胆苦寒而降。同一咸也，泽泻则泻，苁容则补，海藻、昆布则消而软坚，马茎、鹿茸则补而生齿。同一酸也，硫黄味酸而热，空青味酸而寒。甘合辛而发散为阳，甘合酸而收敛为阴。人参、黄耆，阳也，甘温以除大热；地黄、五味，阴也，甘酸以敛阴精。聊采数端，引以为例。如斯之类，难可枚举。良由气味互兼，性质各异，参合多少，制用全殊。所以穷五味之变，明药物之能，厥有旨哉！顾其用纷错，其道渊微，可以意知，难以言尽。非由妙悟，则物不从心。固将拯烝民于夭枉，宜寤寐乎兹篇。', '2024-12-21T02:38:57.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vMftSu8mf12', 1, '{"title":" 卷之一_续序例上_脏气法时并四气所伤药随所感论","description":"<p>1、夫四时之气，行乎天地之间。人处气交之中，亦必因之而感者，其常也。春气生而升，夏气长而散，长夏之气化而软，秋气收而敛，冬气藏而沉。人身之气，自然相通。是故生者顺之，长者敷之，化者坚之，收者肃之，藏者固之。此药之顺乎天者也。春温夏热，元气外泄，阴精不足，药宜养阴；秋凉冬寒，阳气潜藏，勿轻开通，药宜养阳。此药之因时制用，补不足以和其气者也。</p><p>2、然而一气之中，初、中、末异；一日之内，寒燠或殊。假令大热之候，人多感暑，忽发冰雹，亦复感寒。由先而感则为暑病，由后而感则为寒病。病暑者投以暑药，病寒者投以寒药。此药之因时制宜，以合乎权，乃变中之常也。此时令不齐之所宜审也。假令阴虚之人，虽当隆冬，阴精亏竭，水既不足，不能制火，则阳无所依，外泄为热，或反汗出，药宜益阴，地黄、五味、鳖甲、枸杞之属是已。设从时令，误用辛温，势必立毙。假令阳虚之人，虽当盛夏，阳气不足，不能外卫其表，表虚不任风寒，洒淅战栗，思得热食，及御重裘，是虽天令之热，亦不足以敌其真阳之虚。病属虚寒，药宜温补，参、耆、桂、附之属是已。设从时令，误用苦寒，亦必立毙。此药之舍时从证者也。假令素病血虚之人，不利苦寒，恐其损胃伤血。一旦中暑，暴注霍乱，须用黄连、滑石以泄之；本不利升，须用葛根以散之。此药之舍证从时者也。从违之际，权其轻重耳。</p><p>3、至于四气所伤。因而致病，则各从所由。是故《经》曰：春伤于风，夏生飧泄。药宜升之、燥之，升麻、柴胡、羌活、防风之属是已。夏伤于暑，秋必痎疟。药宜清暑益气，以除寒热，石膏、知母、干葛、麦门冬、橘皮、参、苓、术之属是已。邪若内陷，必便脓血，药宜祛暑消滞，专保胃气，黄连、滑石、芍药、升麻、莲实、人参、扁豆、甘草之属是已。秋伤于湿，冬生咳嗽。药宜燥湿清热，和表降气保肺，桑白皮、石膏、薄荷、杏仁、甘草、桔梗、苏子、枇杷叶之属是已。冬伤于寒，春必病温。邪初在表，药宜辛寒、苦温、甘寒、苦寒，以解表邪，兼除内热，羌活、石膏、葛根、前胡、知母、竹叶、柴胡、麦门冬、荆芥、甘草之属是已。至夏变为热病，六经传变，药亦同前。散之贵早，治若后时，邪结于里，上则陷胸，中下承气，中病乃已，慎毋尽剂。勿僭勿忒，能事必矣。</p><p>4、以上皆四时六气所伤致病，并证重舍时，时重舍证，用药主治之大法，万世遵守之常经，圣哲复起，不可改已。所云六气者，即风寒暑湿燥火是也。过则为淫，故曰六淫。淫则为邪，以其为天之气，从外而入，故曰外邪。邪之所中，各有其地：在表治表，在里治里，表里之间，则从和解。病有是证，证有是药，各有司存，不相越也。此古人之定法，今人之轨则也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001015,"no":15}}', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '1、夫四时之气，行乎天地之间。人处气交之中，亦必因之而感者，其常也。春气生而升，夏气长而散，长夏之气化而软，秋气收而敛，冬气藏而沉。人身之气，自然相通。是故生者顺之，长者敷之，化者坚之，收者肃之，藏者固之。此药之顺乎天者也。春温夏热，元气外泄，阴精不足，药宜养阴；秋凉冬寒，阳气潜藏，勿轻开通，药宜养阳。此药之因时制用，补不足以和其气者也。 2、然而一气之中，初、中、末异；一日之内，寒燠或殊。假令大热之候，人多感暑，忽发冰雹，亦复感寒。由先而感则为暑病，由后而感则为寒病。病暑者投以暑药，病寒者投以寒药。此药之因时制宜，以合乎权，乃变中之常也。此时令不齐之所宜审也。假令阴虚之人，虽当隆冬，阴精亏竭，水既不足，不能制火，则阳无所依，外泄为热，或反汗出，药宜益阴，地黄、五味、鳖甲、枸杞之属是已。设从时令，误用辛温，势必立毙。假令阳虚之人，虽当盛夏，阳气不足，不能外卫其表，表虚不任风寒，洒淅战栗，思得热食，及御重裘，是虽天令之热，亦不足以敌其真阳之虚。病属虚寒，药宜温补，参、耆、桂、附之属是已。设从时令，误用苦寒，亦必立毙。此药之舍时从证者也。假令素病血虚之人，不利苦寒，恐其损胃伤血。一旦中暑，暴注霍乱，须用黄连、滑石以泄之；本不利升，须用葛根以散之。此药之舍证从时者也。从违之际，权其轻重耳。 3、至于四气所伤。因而致病，则各从所由。是故《经》曰：春伤于风，夏生飧泄。药宜升之、燥之，升麻、柴胡、羌活、防风之属是已。夏伤于暑，秋必痎疟。药宜清暑益气，以除寒热，石膏、知母、干葛、麦门冬、橘皮、参、苓、术之属是已。邪若内陷，必便脓血，药宜祛暑消滞，专保胃气，黄连、滑石、芍药、升麻、莲实、人参、扁豆、甘草之属是已。秋伤于湿，冬生咳嗽。药宜燥湿清热，和表降气保肺，桑白皮、石膏、薄荷、杏仁、甘草、桔梗、苏子、枇杷叶之属是已。冬伤于寒，春必病温。邪初在表，药宜辛寒、苦温、甘寒、苦寒，以解表邪，兼除内热，羌活、石膏、葛根、前胡、知母、竹叶、柴胡、麦门冬、荆芥、甘草之属是已。至夏变为热病，六经传变，药亦同前。散之贵早，治若后时，邪结于里，上则陷胸，中下承气，中病乃已，慎毋尽剂。勿僭勿忒，能事必矣。 4、以上皆四时六气所伤致病，并证重舍时，时重舍证，用药主治之大法，万世遵守之常经，圣哲复起，不可改已。所云六气者，即风寒暑湿燥火是也。过则为淫，故曰六淫。淫则为邪，以其为天之气，从外而入，故曰外邪。邪之所中，各有其地：在表治表，在里治里，表里之间，则从和解。病有是证，证有是药，各有司存，不相越也。此古人之定法，今人之轨则也。', '2024-12-21T02:41:16.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DvRbae0MoD5', 1, '{"title":"卷之一_续序例上_论制方和剂治疗大法","description":"<p>1、夫虚实者，诸病之根本也；补泻者，治疗之纲纪也。何谓虚？五脏六腑虚所生病也。何谓实？五脏六腑实所生病也。《经》曰：真气夺则虚，邪气胜则实。虚则补之，实则泻之。此万世之常经也。以补为泻，是补中有泻也；以泻为补，是泻中有补也。譬夫参、耆、炙甘草之退劳倦气虚发热；地黄、黄檗之滋水坚肾，以除阴虚潮热，是补中之泻也。桑根白皮之泻肺火，车前子之利小便除湿，是泻中之补也。举斯为例，馀可类推矣。　</p><p>2、升降者，病机之要最也。升为春气，为风化，为木象。故升有散之之义；降为秋气，为燥化，为金象，故降有敛之之义。饮食劳倦，则阳气下陷，宜升阳益气。泻利不止，宜升阳益胃。郁火内伏，宜升阳散火。滞下不休，宜升阳解毒，开胃除热。因湿洞泄，宜升阳除湿。肝木郁于地中，以致少腹作胀、作痛，宜升阳调气。此病宜升之类也。阴虚则水不足以制火，火空则发而炎上。其为证也，为咳嗽，为多痰，为吐血，为鼻衄，为齿衄，为头痛，为齿痛，为眼痛，为头眩，为晕，为眼花，为恶心，为呕吐，为口苦舌干，为不眠，为寒热，为骨蒸，是为上盛下虚之候。宜用苏子、枇杷叶、麦门冬、白芍药、五味子之属以降气，气降则火自降，而气自归元。而又益之以滋水添精之药，以救其本，则诸证自瘳。此病宜降之类也。设宜降而妄升，当升而反降，将使轻变为重，重必毙矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001016,"no":16}}', '2024-12-21T02:44:51.000Z', '2024-12-21T02:44:51.000Z', '2024-12-21T02:44:51.000Z', '1、夫虚实者，诸病之根本也；补泻者，治疗之纲纪也。何谓虚？五脏六腑虚所生病也。何谓实？五脏六腑实所生病也。《经》曰：真气夺则虚，邪气胜则实。虚则补之，实则泻之。此万世之常经也。以补为泻，是补中有泻也；以泻为补，是泻中有补也。譬夫参、耆、炙甘草之退劳倦气虚发热；地黄、黄檗之滋水坚肾，以除阴虚潮热，是补中之泻也。桑根白皮之泻肺火，车前子之利小便除湿，是泻中之补也。举斯为例，馀可类推矣。 2、升降者，病机之要最也。升为春气，为风化，为木象。故升有散之之义；降为秋气，为燥化，为金象，故降有敛之之义。饮食劳倦，则阳气下陷，宜升阳益气。泻利不止，宜升阳益胃。郁火内伏，宜升阳散火。滞下不休，宜升阳解毒，开胃除热。因湿洞泄，宜升阳除湿。肝木郁于地中，以致少腹作胀、作痛，宜升阳调气。此病宜升之类也。阴虚则水不足以制火，火空则发而炎上。其为证也，为咳嗽，为多痰，为吐血，为鼻衄，为齿衄，为头痛，为齿痛，为眼痛，为头眩，为晕，为眼花，为恶心，为呕吐，为口苦舌干，为不眠，为寒热，为骨蒸，是为上盛下虚之候。宜用苏子、枇杷叶、麦门冬、白芍药、五味子之属以降气，气降则火自降，而气自归元。而又益之以滋水添精之药，以救其本，则诸证自瘳。此病宜降之类也。设宜降而妄升，当升而反降，将使轻变为重，重必毙矣。', '2024-12-21T02:44:51.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n6QwgzoTFFC', 1, '{"title":"卷之一_续序例上_论塞因塞用、通因通用、寒因热用、热因寒用、用热远热、用寒远寒","description":"<p>1、《经》曰：塞因塞用者，譬夫脾虚中焦作胀，肾虚气不归元，致上焦逆满，用人参之甘以补元气，五味子之酸以收虚气，则脾得补而胀自消，肾得补而气自归元，上焦清泰，而逆满自平矣。　　</p><p>2、通因通用者，譬夫伤寒挟热下利，或中有燥粪，必用调胃承气汤，下之乃安。滞下不休，得六一散清热除积而愈，皆其义也。　　</p><p>3、寒因热用，是药本寒也，而反佐之以热。热因寒用，是药本热也，而反佐之以寒，则无拒格之患。故曰：必先其所主，而伏其所因也。　　</p><p>4、用热远热者，是病本于寒，法应热治，所投热剂，仅使中病，毋令过焉。过则反生热病矣。用寒远寒，义亦同此。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001017,"no":17}}', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '1、《经》曰：塞因塞用者，譬夫脾虚中焦作胀，肾虚气不归元，致上焦逆满，用人参之甘以补元气，五味子之酸以收虚气，则脾得补而胀自消，肾得补而气自归元，上焦清泰，而逆满自平矣。 2、通因通用者，譬夫伤寒挟热下利，或中有燥粪，必用调胃承气汤，下之乃安。滞下不休，得六一散清热除积而愈，皆其义也。 3、寒因热用，是药本寒也，而反佐之以热。热因寒用，是药本热也，而反佐之以寒，则无拒格之患。故曰：必先其所主，而伏其所因也。 4、用热远热者，是病本于寒，法应热治，所投热剂，仅使中病，毋令过焉。过则反生热病矣。用寒远寒，义亦同此。', '2024-12-21T02:46:52.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gMWHoxz98T3', 1, '{"title":"卷之一_续序例上_论天地风气渐薄，人亦因之渐弱，用药消息亦必因之而变，不可执泥古法，轻用峻利","description":"<p>1、夫人在气交之中，其强其弱，卒莫逃乎天地之气明甚。是以上古之人，度百岁乃去，今则七十称古稀矣。身形长大，常过七尺，今则世鲜六尺之躯矣。其寿数精神，既已渐减，则血气脏腑，亦应因之渐薄，乃天地之风气使然，有非人力所能挽回者。又况时丁末造，众生识昏见陋，五欲炽然，难解难遏，斫丧戕贼，日惟不足，于是疾病丛生，虚多实少。临证施治，多事调养，专防克伐，此今日治法之急务也。设使病宜用热，亦当先之以温；病宜用寒，亦当先之以清。纵有积滞宜消，必须先养胃气：纵有邪气宜祛，必须随时逐散，不得过剂，以损伤气血。气血者，人之所赖以生者也。气血一亏，则诸邪辐辏，百病横生。世人之病，十有九虚。医师之药，百无一补。宁知用药之误，则实者虚，虚者死，是死于医药，而非死于疾病也。其慎其难，属诸司命。临证之顷，宜加战兢。勉之哉！毋执己见而轻人命也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001018,"no":18}}', '2024-12-21T02:48:08.000Z', '2024-12-21T02:48:08.000Z', '2024-12-21T02:48:08.000Z', '1、夫人在气交之中，其强其弱，卒莫逃乎天地之气明甚。是以上古之人，度百岁乃去，今则七十称古稀矣。身形长大，常过七尺，今则世鲜六尺之躯矣。其寿数精神，既已渐减，则血气脏腑，亦应因之渐薄，乃天地之风气使然，有非人力所能挽回者。又况时丁末造，众生识昏见陋，五欲炽然，难解难遏，斫丧戕贼，日惟不足，于是疾病丛生，虚多实少。临证施治，多事调养，专防克伐，此今日治法之急务也。设使病宜用热，亦当先之以温；病宜用寒，亦当先之以清。纵有积滞宜消，必须先养胃气：纵有邪气宜祛，必须随时逐散，不得过剂，以损伤气血。气血者，人之所赖以生者也。气血一亏，则诸邪辐辏，百病横生。世人之病，十有九虚。医师之药，百无一补。宁知用药之误，则实者虚，虚者死，是死于医药，而非死于疾病也。其慎其难，属诸司命。临证之顷，宜加战兢。勉之哉！毋执己见而轻人命也。', '2024-12-21T02:48:08.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bxotugUgfvB', 1, '{"title":"卷之一_续序例上_通评虚实论","description":"<p>1、《经》曰：邪气盛则实，精气夺则虚。又曰：邪之所凑，其气必虚。凡言虚者，精气夺也；凡言实者，邪气胜也。是故虚则受邪，邪客为实，法先攻邪，邪尽治本。邪犹未尽，勿轻补益。犯之者，是谓实实。精者，阴也；气者，阳也。设被削夺，是五脏六腑之阴精、阳气皆虚也。宜从其类以补之。阴精虚者，补阴精；阳气虚者，益阳气。一切克伐攻击之药，概勿施用。犯之者，是为虚虚。《经》曰：实实虚虚，损不足而益有余，如是者，医杀之耳！戒之哉！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001019,"no":19}}', '2024-12-21T02:49:21.000Z', '2024-12-21T02:49:21.000Z', '2024-12-21T02:49:21.000Z', '1、《经》曰：邪气盛则实，精气夺则虚。又曰：邪之所凑，其气必虚。凡言虚者，精气夺也；凡言实者，邪气胜也。是故虚则受邪，邪客为实，法先攻邪，邪尽治本。邪犹未尽，勿轻补益。犯之者，是谓实实。精者，阴也；气者，阳也。设被削夺，是五脏六腑之阴精、阳气皆虚也。宜从其类以补之。阴精虚者，补阴精；阳气虚者，益阳气。一切克伐攻击之药，概勿施用。犯之者，是为虚虚。《经》曰：实实虚虚，损不足而益有余，如是者，医杀之耳！戒之哉！', '2024-12-21T02:49:21.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T6Aix9bimrr', 1, '{"title":"卷之一_续序例上_论治阴阳诸虚病皆当以保护胃气为急","description":"<p>夫胃气者，即后天元气也，以谷气为本。是故《经》曰：脉有胃气曰生，无胃气曰死。又曰：安谷则昌，绝谷则亡。可见先天之气，纵犹未尽，而他脏不至尽伤。独胃气偶有伤败，以至于绝，则速死矣。谷气者，譬国家之饷道也。饷道一绝，则万众立散；胃气一败，则百药难施。若阴虚，若阳虚，或中风，或中暑，乃至泻利滞下，胎前产后，丁肿痈疽，痘疮痧疹惊疳，靡不以保护胃气、补养脾气为先务，本所当急也。故益阴宜远苦寒，益阳宜防泄气，祛风勿过燥散，消暑毋轻下通，泻利勿加消导。滞下之忌芒硝、巴豆、牵牛，胎前泄泻之忌当归，产后寒热之忌芩、连、栀子，丁肿痈疽未溃之忌当归，痘疹之不可妄下。其他内外诸病，应设药之中，凡与胃气相违者，概勿施用。投药之顷，宜加三思。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001020,"no":20}}', '2024-12-21T02:50:29.000Z', '2024-12-21T02:50:29.000Z', '2024-12-21T02:50:29.000Z', '夫胃气者，即后天元气也，以谷气为本。是故《经》曰：脉有胃气曰生，无胃气曰死。又曰：安谷则昌，绝谷则亡。可见先天之气，纵犹未尽，而他脏不至尽伤。独胃气偶有伤败，以至于绝，则速死矣。谷气者，譬国家之饷道也。饷道一绝，则万众立散；胃气一败，则百药难施。若阴虚，若阳虚，或中风，或中暑，乃至泻利滞下，胎前产后，丁肿痈疽，痘疮痧疹惊疳，靡不以保护胃气、补养脾气为先务，本所当急也。故益阴宜远苦寒，益阳宜防泄气，祛风勿过燥散，消暑毋轻下通，泻利勿加消导。滞下之忌芒硝、巴豆、牵牛，胎前泄泻之忌当归，产后寒热之忌芩、连、栀子，丁肿痈疽未溃之忌当归，痘疹之不可妄下。其他内外诸病，应设药之中，凡与胃气相违者，概勿施用。投药之顷，宜加三思。', '2024-12-21T02:50:29.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0JMjE4vPboJ', 1, '{"title":"卷之一_续序例上_论诸病惟虚与火为难治","description":"<p>1、《经》曰：精气夺则虚。又曰：邪之所凑，其气必虚。虚者，空也，无也。</p>\n<p> </p>\n<p>        譬诸国内空虚，人民离散，则百祸易起，镇抚为难。非委任贤智，安靖休养以生息之，未可保其无事也。</p>\n<p></p>\n<p>         病之虚者，亦犹是已。医非明哲，孰能镇之以静？久而弗摇，卒成收合散亡，克复故物之功哉！</p>\n<p></p>\n<p>         是故《经》曰：不能治其虚，安问其余？盖言虚为百病之本，宜其首举以冠诸证也。　</p><p>2、夫火者，阳也，气也，与水为对待者也。</p>\n<p></p>\n<p>      水为阴精，火为阳气，二物匹配，名曰阴阳和平，亦名少火生气，如是则诸病不作矣。</p>\n<p> </p>\n<p>      设不善摄养，以致阴亏水涸，则火偏胜。$m{阴不足，则阳必凑}之，是谓$m{阳盛阴虚}，亦曰壮火食气。是知火即气，气即火也。故仙经谓：药即火，火即药，一而二，二而一者也。</p>\n<p></p>\n<p>      东垣亦曰：火与元气不两立。亦指此也。譬诸$m{水性本流、本寒}，$m{过极则凝而不流}，为层冰矣。解则复常，非二物也。盖平则为水火既济，当斯时也，火即真阳之气矣。及其偏也，则即阳气而为火也，始与元气不两立，而成乖否之象矣。</p>\n<p></p>\n<p>     故戴人亦曰：莫治风，莫治燥，治得火时风燥了。言苟能解此，则已达阴阳水火之原，曲畅旁通，何施不可？正指火之变态多端，其为病也非一，了此则馀皆可办。然学者非心领神会，讵足喻于斯乎？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001021,"no":21}}', '2024-12-21T02:51:41.000Z', '2024-12-21T02:51:41.000Z', '2024-12-21T02:51:41.000Z', '1、《经》曰：精气夺则虚。又曰：邪之所凑，其气必虚。虚者，空也，无也。 譬诸国内空虚，人民离散，则百祸易起，镇抚为难。非委任贤智，安靖休养以生息之，未可保其无事也。 病之虚者，亦犹是已。医非明哲，孰能镇之以静？久而弗摇，卒成收合散亡，克复故物之功哉！ 是故《经》曰：不能治其虚，安问其余？盖言虚为百病之本，宜其首举以冠诸证也。 2、夫火者，阳也，气也，与水为对待者也。 水为阴精，火为阳气，二物匹配，名曰阴阳和平，亦名少火生气，如是则诸病不作矣。 设不善摄养，以致阴亏水涸，则火偏胜。$m{阴不足，则阳必凑}之，是谓$m{阳盛阴虚}，亦曰壮火食气。是知火即气，气即火也。故仙经谓：药即火，火即药，一而二，二而一者也。 东垣亦曰：火与元气不两立。亦指此也。譬诸$m{水性本流、本寒}，$m{过极则凝而不流}，为层冰矣。解则复常，非二物也。盖平则为水火既济，当斯时也，火即真阳之气矣。及其偏也，则即阳气而为火也，始与元气不两立，而成乖否之象矣。 故戴人亦曰：莫治风，莫治燥，治得火时风燥了。言苟能解此，则已达阴阳水火之原，曲畅旁通，何施不可？正指火之变态多端，其为病也非一，了此则馀皆可办。然学者非心领神会，讵足喻于斯乎？', '2024-12-21T02:51:41.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SDlfV2M0h46', 1, '{"title":"卷之一_续序例上_论阳常有余，阴常不足，药必因之以为损益，误则杀人","description":"<p>1、人身之有阴阳也，水一而已，火则二焉。是秉受之始。阳常有余，阴常不足，天地且然，况于人乎？故自少至老，所生疾病，靡不由于真阴不足者，其恒也。若夫真阳不足之病，千百而一二矣。阳者气也，火也，神也：阴者血也，水也，精也。阴阳和平，气血均调，是为平人气象之常候。苟失所养，或纵恣房室，或肆情喜怒，或轻犯阴阳，或嗜好辛热，以致肾水真阴不足，不能匹配阳火，遂使阳气有余。气有余，即是火，故火愈盛而水愈涸，于是发为吐血、咳嗽、吐痰、内热、骨蒸、盗汗，种种阴虚等病。医师不察，不揆其本，凡见前证，不分阴阳，类施温补。参、耆、二术，视同食物；佐以姜、桂，若啖五辛。倘遇惫剧，辄投附子。于是轻者重，重者毙，累累相踵，死而不悟。良可悯也！然使其术得售者，不独医师之罪，亦病家不明，有以致之耳！何则？难成易亏者，阴也。益阴之药，纵医师选用无差，亦必无旦夕之效。助阳之药，能使胃气一时暂壮，饮食加增；或阳道兴举，有似神王。医师藉以要功，病者利其速效，彼此固执，莫辨厥由。故知阴虚真水不足之病，十人而九；阳虚真火不足之病，百不得一。医师之药，补助阳火者，往往概施；滋益阴精者，未尝少见。宜乎服药者之多毙，无药者之反存也。予见世医以此伤人者甚众，兹特著其误，以为世戒。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001022,"no":22}}', '2024-12-21T02:52:32.000Z', '2024-12-21T02:52:32.000Z', '2024-12-21T02:52:32.000Z', '1、人身之有阴阳也，水一而已，火则二焉。是秉受之始。阳常有余，阴常不足，天地且然，况于人乎？故自少至老，所生疾病，靡不由于真阴不足者，其恒也。若夫真阳不足之病，千百而一二矣。阳者气也，火也，神也：阴者血也，水也，精也。阴阳和平，气血均调，是为平人气象之常候。苟失所养，或纵恣房室，或肆情喜怒，或轻犯阴阳，或嗜好辛热，以致肾水真阴不足，不能匹配阳火，遂使阳气有余。气有余，即是火，故火愈盛而水愈涸，于是发为吐血、咳嗽、吐痰、内热、骨蒸、盗汗，种种阴虚等病。医师不察，不揆其本，凡见前证，不分阴阳，类施温补。参、耆、二术，视同食物；佐以姜、桂，若啖五辛。倘遇惫剧，辄投附子。于是轻者重，重者毙，累累相踵，死而不悟。良可悯也！然使其术得售者，不独医师之罪，亦病家不明，有以致之耳！何则？难成易亏者，阴也。益阴之药，纵医师选用无差，亦必无旦夕之效。助阳之药，能使胃气一时暂壮，饮食加增；或阳道兴举，有似神王。医师藉以要功，病者利其速效，彼此固执，莫辨厥由。故知阴虚真水不足之病，十人而九；阳虚真火不足之病，百不得一。医师之药，补助阳火者，往往概施；滋益阴精者，未尝少见。宜乎服药者之多毙，无药者之反存也。予见世医以此伤人者甚众，兹特著其误，以为世戒。', '2024-12-21T02:52:32.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aKMN48VXI8B', 1, '{"title":"卷之一_续序例上_论上盛下虚本于肾水真阴不足","description":"<p>1、人身以阴阳两称为平，偏胜则病，此大较也。水不足则火有余，阴既亏则阳独盛。盖阴阳之精，互藏其宅，是阴中有阳，阳中有阴也。故心，火也，而含赤液；肾，水也，而藏白气。赤液为阴，白气为阳。循环往复，昼夜不息，此常度也。苟不知摄养，纵恣情欲，亏损真阴，阳无所附，因而发越上升，此火空则发之义，是周身之气，并于阳也。并于阳则阳盛，故上焦热而咳嗽生痰，迫血上行而为吐衄，为烦躁，为头痛，为不得眠，为胸前骨痛，为口干舌苦，此其候也。阳愈盛则阴愈虚，阴愈虚则为五心烦热，为潮热骨蒸，为遗精，为骨乏无力，为小水短赤，丹田不暖，则饮食不化，为泄泻，为卒僵仆，此其候也。治之之要，当亟降气，当益阴精。气降即阳交于阴，是火下降也。精血生即肾阴复，是水上升也。此既济之象，为坎离交也。坎离交，即是小周天。至此则阴阳二气复得其平矣，病何自而生哉？　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001023,"no":23}}', '2024-12-21T02:54:41.000Z', '2024-12-21T02:54:41.000Z', '2024-12-21T02:54:41.000Z', '1、人身以阴阳两称为平，偏胜则病，此大较也。水不足则火有余，阴既亏则阳独盛。盖阴阳之精，互藏其宅，是阴中有阳，阳中有阴也。故心，火也，而含赤液；肾，水也，而藏白气。赤液为阴，白气为阳。循环往复，昼夜不息，此常度也。苟不知摄养，纵恣情欲，亏损真阴，阳无所附，因而发越上升，此火空则发之义，是周身之气，并于阳也。并于阳则阳盛，故上焦热而咳嗽生痰，迫血上行而为吐衄，为烦躁，为头痛，为不得眠，为胸前骨痛，为口干舌苦，此其候也。阳愈盛则阴愈虚，阴愈虚则为五心烦热，为潮热骨蒸，为遗精，为骨乏无力，为小水短赤，丹田不暖，则饮食不化，为泄泻，为卒僵仆，此其候也。治之之要，当亟降气，当益阴精。气降即阳交于阴，是火下降也。精血生即肾阴复，是水上升也。此既济之象，为坎离交也。坎离交，即是小周天。至此则阴阳二气复得其平矣，病何自而生哉？', '2024-12-21T02:54:41.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xWotcwQYHmY', 1, '{"title":"卷之一_续序例上_论阴精阳气补益不同","description":"<p>1、《经》曰：形不足，温之以气。人参、羊肉、黄耆、人胞、红铅之属是已。益阳气也，乃可以却沉寒。经曰：精不足，补之以味。人乳、鳖甲、地黄、黄檗、枸杞、牛膝、天门冬之属是已。补阴精也，乃可以除伏热。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001024,"no":24}}', '2024-12-21T02:55:15.000Z', '2024-12-21T02:55:15.000Z', '2024-12-21T02:55:15.000Z', '1、《经》曰：形不足，温之以气。人参、羊肉、黄耆、人胞、红铅之属是已。益阳气也，乃可以却沉寒。经曰：精不足，补之以味。人乳、鳖甲、地黄、黄檗、枸杞、牛膝、天门冬之属是已。补阴精也，乃可以除伏热。', '2024-12-21T02:55:15.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cbU6PXzATyw', 1, '{"title":" 卷之一_续序例上_论治气三法药各不同","description":"<p>1、一、补气：气虚宜补之，如人参、黄耆、羊肉、小麦、糯米之属是也。　</p><p>2、二、降气、调气：降气者，即下气也。虚则气升，故法宜降。其药之轻者，如紫苏子、橘皮、麦门冬、枇杷叶、芦根汁、甘蔗；其重者，如番降香、郁金、槟榔之属。调者，和也。逆则宜和，和则调也。其药如木香、沉水香、白豆蔻、缩砂蜜、香附、橘皮、乌药之属。　</p><p>3、三、破气：破者，损也。实则宜破，如少壮人暴怒气壅之类。然亦可暂不可久。其药如枳实、青皮、枳壳、牵牛之属。　　</p><p>4、盖气分之病，不出三端。治之之法，及所主之药，皆不可混滥也。误则使病转剧。世多不察，故表而出之。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001025,"no":25}}', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '1、一、补气：气虚宜补之，如人参、黄耆、羊肉、小麦、糯米之属是也。 2、二、降气、调气：降气者，即下气也。虚则气升，故法宜降。其药之轻者，如紫苏子、橘皮、麦门冬、枇杷叶、芦根汁、甘蔗；其重者，如番降香、郁金、槟榔之属。调者，和也。逆则宜和，和则调也。其药如木香、沉水香、白豆蔻、缩砂蜜、香附、橘皮、乌药之属。 3、三、破气：破者，损也。实则宜破，如少壮人暴怒气壅之类。然亦可暂不可久。其药如枳实、青皮、枳壳、牵牛之属。 4、盖气分之病，不出三端。治之之法，及所主之药，皆不可混滥也。误则使病转剧。世多不察，故表而出之。', '2024-12-21T02:57:15.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uFQeZW1wNlH', 1, '{"title":"卷之一_续序例上_论治血三法药各不同","description":"<p>1、血虚宜补之。虚则发热。内热，法宜甘寒、甘平、酸寒、酸温，以益荣血。其药为熟地黄、白芍药、牛膝、炙甘草、酸枣仁、龙眼肉、鹿角胶、肉苁蓉、甘枸杞子、甘菊花、人乳之属。</p><p>2、血热宜清之凉之。热则为痈肿疮疖，为鼻衄，为齿衄，为牙龈肿，为舌上出血，为舌肿，为血崩，为赤淋，为月事先期，为热入血室，为赤游丹，为眼暴赤痛。法宜酸寒、苦寒、咸寒、辛凉，以除实热。其药为童便、牡丹皮、赤芍药、生地黄、黄芩、犀角、地榆、大小蓟、茜草、黄连、山栀、大黄、青黛、天门冬、玄参、荆芥之属。　　</p><p>3、血瘀宜通之。瘀必发热发黄，作痛作肿，及作结块癖积。法宜辛温、辛热、辛平、辛寒、甘温，以入血通行。佐以咸寒，乃可软坚。其药为当归、红花、桃仁、苏木、桂、五灵脂、蒲黄、姜黄、郁金、京三棱、延胡索、花蕊石、没药、䗪虫、干漆、自然铜、韭汁、童便、牡蛎、芒硝之属。　</p><p>4、盖血为荣，阴也，有形可见，有色可察，有证可审者也。病既不同，药亦各异。治之之法，要在合宜。倘失其宜，为厉不浅，差剧之门，可不谨乎？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001026,"no":26}}', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '1、血虚宜补之。虚则发热。内热，法宜甘寒、甘平、酸寒、酸温，以益荣血。其药为熟地黄、白芍药、牛膝、炙甘草、酸枣仁、龙眼肉、鹿角胶、肉苁蓉、甘枸杞子、甘菊花、人乳之属。 2、血热宜清之凉之。热则为痈肿疮疖，为鼻衄，为齿衄，为牙龈肿，为舌上出血，为舌肿，为血崩，为赤淋，为月事先期，为热入血室，为赤游丹，为眼暴赤痛。法宜酸寒、苦寒、咸寒、辛凉，以除实热。其药为童便、牡丹皮、赤芍药、生地黄、黄芩、犀角、地榆、大小蓟、茜草、黄连、山栀、大黄、青黛、天门冬、玄参、荆芥之属。 3、血瘀宜通之。瘀必发热发黄，作痛作肿，及作结块癖积。法宜辛温、辛热、辛平、辛寒、甘温，以入血通行。佐以咸寒，乃可软坚。其药为当归、红花、桃仁、苏木、桂、五灵脂、蒲黄、姜黄、郁金、京三棱、延胡索、花蕊石、没药、䗪虫、干漆、自然铜、韭汁、童便、牡蛎、芒硝之属。 4、盖血为荣，阴也，有形可见，有色可察，有证可审者也。病既不同，药亦各异。治之之法，要在合宜。倘失其宜，为厉不浅，差剧之门，可不谨乎？', '2024-12-21T02:58:58.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xsyGodY30hk', 1, '{"title":" 卷之一_续序例上_论治吐血三要","description":"<p>1、【宜】降气，不宜降火。　　</p><p>2、气有余，即是火。气降则火降，火降则气不上升，血随气行，无溢出上窍之患矣。降火必用寒凉之剂，反伤胃气。胃气伤，则脾不能统血，血愈不能归经矣。　　</p><p>3、今之疗吐血者，大患有二：一则专用寒凉之味，如芩、连、山栀、青黛、柿饼灰、四物汤、黄檗、知母之类，往往伤脾作泄，以致不救。一则专用人参，肺热还伤肺，咳逆愈甚。亦有用参而愈者，此是气虚喘嗽。气属阳，不由阴虚火炽所致，然亦百不一二也。宜以白芍药、炙甘草制肝；枇杷叶、麦门冬、薄荷、橘红、贝母清肺；薏苡仁、怀山药养脾；韭菜、番降香、真苏子下气；青蒿、鳖甲、银柴胡、牡丹皮、地骨皮补阴清热；酸枣仁、白茯神养心；山茱萸、枸杞子、牛膝补肾。此累试辄验之方。然阴无骤补之法，非多服药不效。病家欲速其功，医者张皇无主。百药杂试，以致殒命，覆辙相寻而不悟，悲夫！　　</p><p>4、【宜】行血，不宜止血。　　</p><p>5、血不循经络者，气逆上壅也。夫血得热则行，得寒则凝，故降气行血，则血循经络，不求其止而自止矣。止之则血凝，血凝必发热、恶食，及胸胁痛，病日沉痼矣。　　</p><p>6、【宜】补肝，不宜伐肝。　</p><p>7、《经》曰：五脏者，藏精气而不泻者也。肝为将军之官，主藏血。吐血者，肝失其职也。养肝则肝气平，而血有所归；伐之则肝不能藏血，血愈不止矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001027,"no":27}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '1、【宜】降气，不宜降火。 2、气有余，即是火。气降则火降，火降则气不上升，血随气行，无溢出上窍之患矣。降火必用寒凉之剂，反伤胃气。胃气伤，则脾不能统血，血愈不能归经矣。 3、今之疗吐血者，大患有二：一则专用寒凉之味，如芩、连、山栀、青黛、柿饼灰、四物汤、黄檗、知母之类，往往伤脾作泄，以致不救。一则专用人参，肺热还伤肺，咳逆愈甚。亦有用参而愈者，此是气虚喘嗽。气属阳，不由阴虚火炽所致，然亦百不一二也。宜以白芍药、炙甘草制肝；枇杷叶、麦门冬、薄荷、橘红、贝母清肺；薏苡仁、怀山药养脾；韭菜、番降香、真苏子下气；青蒿、鳖甲、银柴胡、牡丹皮、地骨皮补阴清热；酸枣仁、白茯神养心；山茱萸、枸杞子、牛膝补肾。此累试辄验之方。然阴无骤补之法，非多服药不效。病家欲速其功，医者张皇无主。百药杂试，以致殒命，覆辙相寻而不悟，悲夫！ 4、【宜】行血，不宜止血。 5、血不循经络者，气逆上壅也。夫血得热则行，得寒则凝，故降气行血，则血循经络，不求其止而自止矣。止之则血凝，血凝必发热、恶食，及胸胁痛，病日沉痼矣。 6、【宜】补肝，不宜伐肝。 7、《经》曰：五脏者，藏精气而不泻者也。肝为将军之官，主藏血。吐血者，肝失其职也。养肝则肝气平，而血有所归；伐之则肝不能藏血，血愈不止矣。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iyuPry1EgI7', 1, '{"title":"卷之一_续序例上_论肾泄多在黎明所由","description":"<p>1、凡人之生，二五妙合之顷，识神依托是中，即揽父精母血，以为立命之基，遂成左右两肾。肾间动气，即道家所谓先天祖气是也。藏乎两肾之中，以肾属水，故称坎宫。以平人气象言之，此气至子后一阳生，生即渐渐上升，历丑、寅、卯、辰、巳，而六阳已极，则入离宫。午后一阴生，即白气变为赤液，渐渐降下至坎宫，复为白气，昼夜循环，升降不息，此即医家所谓真阳之火，道家所谓君火，即先天祖气，医家谓为相火者是也。方此火之自下而上也，行过中焦，必经脾胃，则能腐熟水谷，蒸糟粕而化精微。脾气散精，上归于肺。通调水道，下输膀胱，气化而出，是谓清升浊降，即既济之象也。苟不慎摄生之道，不明正性之理，则必务快其心，逆于生乐，忧患以伤心，寒热以伤肺，饥饱以伤脾，多怒以伤肝，多欲以伤肾，则真气渐衰，精神日损。驯至子后，一阳不以时生，不能上升腐熟水谷，则糟粕无由而化。寅为三阳之候，阳气微则不能应候而化物，故天黎明而泄。其泄亦溏，俗名鸭溏，是为肾泄，亦名大瘕泄。昔人以四神丸治之，予加人参、莲肉，辄获奇效。盖人参补五脏之阳气故也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001028,"no":28}}', '2024-12-21T03:02:23.000Z', '2024-12-21T03:02:23.000Z', '2024-12-21T03:02:23.000Z', '1、凡人之生，二五妙合之顷，识神依托是中，即揽父精母血，以为立命之基，遂成左右两肾。肾间动气，即道家所谓先天祖气是也。藏乎两肾之中，以肾属水，故称坎宫。以平人气象言之，此气至子后一阳生，生即渐渐上升，历丑、寅、卯、辰、巳，而六阳已极，则入离宫。午后一阴生，即白气变为赤液，渐渐降下至坎宫，复为白气，昼夜循环，升降不息，此即医家所谓真阳之火，道家所谓君火，即先天祖气，医家谓为相火者是也。方此火之自下而上也，行过中焦，必经脾胃，则能腐熟水谷，蒸糟粕而化精微。脾气散精，上归于肺。通调水道，下输膀胱，气化而出，是谓清升浊降，即既济之象也。苟不慎摄生之道，不明正性之理，则必务快其心，逆于生乐，忧患以伤心，寒热以伤肺，饥饱以伤脾，多怒以伤肝，多欲以伤肾，则真气渐衰，精神日损。驯至子后，一阳不以时生，不能上升腐熟水谷，则糟粕无由而化。寅为三阳之候，阳气微则不能应候而化物，故天黎明而泄。其泄亦溏，俗名鸭溏，是为肾泄，亦名大瘕泄。昔人以四神丸治之，予加人参、莲肉，辄获奇效。盖人参补五脏之阳气故也。', '2024-12-21T03:02:23.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xTBDXrouGLl', 1, '{"title":" 卷之一_续序例上_论少年人阳痿因于失志，不宜补阳","description":"<p>1、《经》曰：肾为作强之官，技巧出焉，藏精与志者也。夫志从士从心，志主决定，心主思维。思维则或迁或改，决定则一立不移，此作强之验也。苟志意不遂，则阳气不舒。阳气者，即真火也。譬夫极盛之火，置之密器之中，闭闷其气，使不得发越，则火立死而寒矣。此非真火衰也，乃闷郁之故也。宣其抑郁，通其志意，则阳气立舒，而其痿立起矣。若误谓阳精不足，过投补火之剂，多致痈疽而殁，可不戒哉！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001029,"no":29}}', '2024-12-21T03:03:44.000Z', '2024-12-21T03:03:44.000Z', '2024-12-21T03:03:44.000Z', '1、《经》曰：肾为作强之官，技巧出焉，藏精与志者也。夫志从士从心，志主决定，心主思维。思维则或迁或改，决定则一立不移，此作强之验也。苟志意不遂，则阳气不舒。阳气者，即真火也。譬夫极盛之火，置之密器之中，闭闷其气，使不得发越，则火立死而寒矣。此非真火衰也，乃闷郁之故也。宣其抑郁，通其志意，则阳气立舒，而其痿立起矣。若误谓阳精不足，过投补火之剂，多致痈疽而殁，可不戒哉！', '2024-12-21T03:03:44.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DlBjpy8umLi', 1, '{"title":" 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>1、凡言中风，有真假内外之别。差之毫厘，谬以千里。何者？西北土地高寒，风气刚烈。真气空虚之人，猝为所中，中脏者死，中腑者成废人，中经络者，可调理而瘳。治之之道，先以解散风邪为急，次则补养气血，此治真中外来风邪之法也。其药以小续命汤，桂枝、麻黄、生熟附子、羌独活、防风、白芷、南星、甘草之属为本。　</p><p>2、若夫大江已南之东西两浙、七闽、百粤、两川、滇南、鬼方、荆、扬、梁三州之域，天地之风气既殊，人之所禀亦异。其地绝无刚猛之风，而多湿热之气，质多柔脆，往往多热多痰。真阴既亏，内热弥甚，煎熬津液，凝结为痰，壅塞气道，不得通利。热极生风，亦致猝然僵仆，类中风证。或不省人事，或语言謇涩，或口眼歪斜，或半身不遂。其将发也，外必先显内热之候，或口干舌苦，或大便秘涩，小便短赤，此其验也。刘河间所谓此证全是将息失宜，水不制火。丹溪所谓湿热相火，中痰、中气是也。此即内虚暗风，确系阴阳两虚，而阴虚者为多，与外来风邪迥别。法当清热、顺气、开痰，以救其标，次当治本。阴虚则益血，阳虚则补气，气血两虚则气血兼补，久之自瘳。设若误用治真中风药，如前辛热风燥之剂，则轻变为重，重则必死。祸福反掌，不可不察也。　　</p><p>3、初清热则天门冬、麦门冬、甘菊花、白芍药、白茯苓、栝楼根、童便；　　</p><p>4、顺气则紫苏子、枇杷叶、橘红、郁金；　　</p><p>5、开痰则贝母、白芥子、竹沥、荆沥、栝楼仁、霞天膏。　　</p><p>6、次治本，益阴则天门冬、甘菊花、怀生地、当归身、白芍药、枸杞子、麦门冬、五味子、牛膝、人乳、白胶、黄檗、白蒺藜之属；　　</p><p>7、补阳则人参、黄耆、鹿茸、大枣、巴戟天之属。与时消息，则因乎证。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001030,"no":30}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '1、凡言中风，有真假内外之别。差之毫厘，谬以千里。何者？西北土地高寒，风气刚烈。真气空虚之人，猝为所中，中脏者死，中腑者成废人，中经络者，可调理而瘳。治之之道，先以解散风邪为急，次则补养气血，此治真中外来风邪之法也。其药以小续命汤，桂枝、麻黄、生熟附子、羌独活、防风、白芷、南星、甘草之属为本。 2、若夫大江已南之东西两浙、七闽、百粤、两川、滇南、鬼方、荆、扬、梁三州之域，天地之风气既殊，人之所禀亦异。其地绝无刚猛之风，而多湿热之气，质多柔脆，往往多热多痰。真阴既亏，内热弥甚，煎熬津液，凝结为痰，壅塞气道，不得通利。热极生风，亦致猝然僵仆，类中风证。或不省人事，或语言謇涩，或口眼歪斜，或半身不遂。其将发也，外必先显内热之候，或口干舌苦，或大便秘涩，小便短赤，此其验也。刘河间所谓此证全是将息失宜，水不制火。丹溪所谓湿热相火，中痰、中气是也。此即内虚暗风，确系阴阳两虚，而阴虚者为多，与外来风邪迥别。法当清热、顺气、开痰，以救其标，次当治本。阴虚则益血，阳虚则补气，气血两虚则气血兼补，久之自瘳。设若误用治真中风药，如前辛热风燥之剂，则轻变为重，重则必死。祸福反掌，不可不察也。 3、初清热则天门冬、麦门冬、甘菊花、白芍药、白茯苓、栝楼根、童便； 4、顺气则紫苏子、枇杷叶、橘红、郁金； 5、开痰则贝母、白芥子、竹沥、荆沥、栝楼仁、霞天膏。 6、次治本，益阴则天门冬、甘菊花、怀生地、当归身、白芍药、枸杞子、麦门冬、五味子、牛膝、人乳、白胶、黄檗、白蒺藜之属； 7、补阳则人参、黄耆、鹿茸、大枣、巴戟天之属。与时消息，则因乎证。', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CfP0L52yWOa', 1, '{"title":"卷之一_续序例上_似中风问答","description":"<p>1、或问：有患似中风证，眠不竟夕而易惺，心脉弦而不洪，多怒，肝脉弦而不长，语言謇涩不利，多痰声重，小便疾速不能忍，且有余沥，大便燥结，左尺脉浮洪，饮食少，不易消，此何以故？　　</p><p>2、答曰：眠不竟夕而易惺者，心血不足也，故其脉弦而不洪。东垣云：胃虚者多怒，多怒者肝气必不和。《经》曰：怒则气上逆。加以久病多郁，故益易怒，故肝脉亦弦而不长。弦为血少。此非以智慧观察，以慈忍静定之力和之，未可以药石瘳也。肾属水，冬脉沉，故曰：诸浮者，肾不足也。肾主五液，又主二便，肾家有火，则真阴日亏，津液日少，不能荣养于舌络，舌络劲急，故语言不利；火性急速，故小便疾出而不能忍，且有余沥，而大便亦多燥结也。故其脉应沉实而反浮洪，失常候也。肺者，五脏之华盖，位乎上，象天而属金，喜清肃而恶烦热，热则津液干枯，无以下滴而通水道，或煎熬浓稠而成痰矣。肺热则人参反助邪热而伤肺，故往往声重多痰，壅塞气道，而升降不利也。脾为土脏，胃为之腑，乃后天元气之所自出。胃主纳，脾主消，脾阴亏则不能消，胃气弱则不能纳，饮食少则后天元气无自而生，精血坐是日益不足也。《经》曰：损其脾者，调其饮食，节其起居，适其寒温。此至论也。不如是则不足以复脾阴。然其要又在戒暴怒，使肝无不平之气，肝和则不贼脾土矣。命门者，火脏也，乃先天真阳之气之所寄，即道家所谓先天祖气，医家所谓真火是也。其壮也有三：一者元禀过厚，二者保啬精气，不妄施泄，三者志气无所怫郁，则年虽迈而犹壮也。不尔则子后一阳不生，不能上升熏蒸糟粕而化精微，以滋后天之元气，是火不生土，而脾胃因之日弱也。法当降气和肝滋肾，气降是阳交于阴也。肝和则脾胃不被贼邪所干，故能纳而能消也。脾胃无恙，则后天元气日益生长矣。肾足则真阴自生，津液自足，舌络有所荣养，则舌之伸缩自如而言语自利矣。且世无不阴虚而中风者，第须拨去烦恼，一切放下，使心火不炎，则肾亦因之而不燥，此又治之之本也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001031,"no":31}}', '2024-12-21T03:07:28.000Z', '2024-12-21T03:07:28.000Z', '2024-12-21T03:07:28.000Z', '1、或问：有患似中风证，眠不竟夕而易惺，心脉弦而不洪，多怒，肝脉弦而不长，语言謇涩不利，多痰声重，小便疾速不能忍，且有余沥，大便燥结，左尺脉浮洪，饮食少，不易消，此何以故？ 2、答曰：眠不竟夕而易惺者，心血不足也，故其脉弦而不洪。东垣云：胃虚者多怒，多怒者肝气必不和。《经》曰：怒则气上逆。加以久病多郁，故益易怒，故肝脉亦弦而不长。弦为血少。此非以智慧观察，以慈忍静定之力和之，未可以药石瘳也。肾属水，冬脉沉，故曰：诸浮者，肾不足也。肾主五液，又主二便，肾家有火，则真阴日亏，津液日少，不能荣养于舌络，舌络劲急，故语言不利；火性急速，故小便疾出而不能忍，且有余沥，而大便亦多燥结也。故其脉应沉实而反浮洪，失常候也。肺者，五脏之华盖，位乎上，象天而属金，喜清肃而恶烦热，热则津液干枯，无以下滴而通水道，或煎熬浓稠而成痰矣。肺热则人参反助邪热而伤肺，故往往声重多痰，壅塞气道，而升降不利也。脾为土脏，胃为之腑，乃后天元气之所自出。胃主纳，脾主消，脾阴亏则不能消，胃气弱则不能纳，饮食少则后天元气无自而生，精血坐是日益不足也。《经》曰：损其脾者，调其饮食，节其起居，适其寒温。此至论也。不如是则不足以复脾阴。然其要又在戒暴怒，使肝无不平之气，肝和则不贼脾土矣。命门者，火脏也，乃先天真阳之气之所寄，即道家所谓先天祖气，医家所谓真火是也。其壮也有三：一者元禀过厚，二者保啬精气，不妄施泄，三者志气无所怫郁，则年虽迈而犹壮也。不尔则子后一阳不生，不能上升熏蒸糟粕而化精微，以滋后天之元气，是火不生土，而脾胃因之日弱也。法当降气和肝滋肾，气降是阳交于阴也。肝和则脾胃不被贼邪所干，故能纳而能消也。脾胃无恙，则后天元气日益生长矣。肾足则真阴自生，津液自足，舌络有所荣养，则舌之伸缩自如而言语自利矣。且世无不阴虚而中风者，第须拨去烦恼，一切放下，使心火不炎，则肾亦因之而不燥，此又治之之本也。', '2024-12-21T03:07:28.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('420lnw4jgqn', 1, '{"title":"卷之一_续序例上_论痰饮药宜分治","description":"<p>1、夫痰之生也，其由非一；其为治也，药亦不同。由于阴虚火炎，上迫乎肺，肺气热则煎熬津液，凝结为痰，是为阴虚痰火。痰在乎肺而本乎肾，治宜降气清热，益阴滋水。法忌辛温燥热补气等药。由于脾胃寒湿生痰，或兼饮啖过度，好食油面猪脂，以致脾气不利，壅滞为痰，浓厚胶固，甚至流于经络，及皮里膜外，或结为大块，或不思食，或彻夜不眠，或卒尔眩仆，不省人事，或发癫痫，或昔肥今瘦，或叫呼异常，或身重腹胀，不便行走，或泄泻不止，及成瘫痪。种种怪证，皆痰所为。故昔人云：怪病多属痰，暴病多属火。有以夫！此病在脾胃，无关肺肾，治宜燥脾行气，散结软坚。法忌滞泥、苦寒、湿润等药，及诸厚味。由于风寒郁闭，热气在肺，而成痰嗽齁喘，病亦在肺，治宜豁痰除肺热药中，加辛热、辛温，如麻黄、生干姜之属，以散外寒，则药无格拒之患。法忌温补、酸收等药。病因不齐，药亦宜异。利润利燥，及利发散，各有攸当，非可混施也。　</p><p>2、世以痰饮混称，药亦混投。殊不知痰之与饮，其由自别，其状亦殊。痰质稠粘，饮惟清水，特其色有异，或青或黄，或绿或黑，或如酸浆，或伏于肠胃，或上支胸胁，刺痛难忍，或流于经络四肢，则关节不利。支饮上攻为心痛，为中脘痛，甚则汗出，为呕吐酸水、苦黄水等，种种各异。或发寒热，不思饮食，及不得眠，皆其候也。此证皆因酒后过饮茶汤，则水浆与肠胃饮食湿热之气，凝而为饮；或因情抱抑郁，饮食停滞，不得以时消散，亦能成饮。总之必由脾胃有湿，或脾胃本虚，又感饮食之湿，则停而不消，此饮之大略也。治宜燥湿利水，行气健脾，乃为得也。其药大都以半夏、茯苓、参、术为君，佐以猪苓、泽泻以渗泄之，白豆蔻、橘皮以开散之，苏梗、旋覆花以通畅之。东垣五饮丸中有人参，其旨概可见矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001032,"no":32}}', '2024-12-21T03:08:28.000Z', '2024-12-21T03:08:28.000Z', '2024-12-21T03:08:28.000Z', '1、夫痰之生也，其由非一；其为治也，药亦不同。由于阴虚火炎，上迫乎肺，肺气热则煎熬津液，凝结为痰，是为阴虚痰火。痰在乎肺而本乎肾，治宜降气清热，益阴滋水。法忌辛温燥热补气等药。由于脾胃寒湿生痰，或兼饮啖过度，好食油面猪脂，以致脾气不利，壅滞为痰，浓厚胶固，甚至流于经络，及皮里膜外，或结为大块，或不思食，或彻夜不眠，或卒尔眩仆，不省人事，或发癫痫，或昔肥今瘦，或叫呼异常，或身重腹胀，不便行走，或泄泻不止，及成瘫痪。种种怪证，皆痰所为。故昔人云：怪病多属痰，暴病多属火。有以夫！此病在脾胃，无关肺肾，治宜燥脾行气，散结软坚。法忌滞泥、苦寒、湿润等药，及诸厚味。由于风寒郁闭，热气在肺，而成痰嗽齁喘，病亦在肺，治宜豁痰除肺热药中，加辛热、辛温，如麻黄、生干姜之属，以散外寒，则药无格拒之患。法忌温补、酸收等药。病因不齐，药亦宜异。利润利燥，及利发散，各有攸当，非可混施也。 2、世以痰饮混称，药亦混投。殊不知痰之与饮，其由自别，其状亦殊。痰质稠粘，饮惟清水，特其色有异，或青或黄，或绿或黑，或如酸浆，或伏于肠胃，或上支胸胁，刺痛难忍，或流于经络四肢，则关节不利。支饮上攻为心痛，为中脘痛，甚则汗出，为呕吐酸水、苦黄水等，种种各异。或发寒热，不思饮食，及不得眠，皆其候也。此证皆因酒后过饮茶汤，则水浆与肠胃饮食湿热之气，凝而为饮；或因情抱抑郁，饮食停滞，不得以时消散，亦能成饮。总之必由脾胃有湿，或脾胃本虚，又感饮食之湿，则停而不消，此饮之大略也。治宜燥湿利水，行气健脾，乃为得也。其药大都以半夏、茯苓、参、术为君，佐以猪苓、泽泻以渗泄之，白豆蔻、橘皮以开散之，苏梗、旋覆花以通畅之。东垣五饮丸中有人参，其旨概可见矣。', '2024-12-21T03:08:28.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Adq9tM3QdXE', 1, '{"title":"卷之一_续序例上_疟痢宜从六淫例治","description":"<p>1、风寒暑湿燥火，此天之六淫。其邪自外而入，感之而病，宜随其邪之所在以攻治之。《经》曰：夏伤于暑，秋必痎疟。是疟乃暑邪为病也。虽有山岚瘴气发疟一证，治稍不同，然其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，头疼骨疼，大渴引饮，口苦舌干，呕吐不思食，或烦躁不得眠，必用白虎汤二三剂，随证增损，解表以祛暑邪。而后随经消息，以除其苦可也。　　</p><p>2、滞下者，俗呼为痢疾，皆缘暑湿与饮食之积滞胶固而成。其证类多里急后重，数登圊而不便，或发热，或口渴，或恶心，不思食何，莫非暑之标证也。必用六一散、黄连、芍药为主，而后随其所苦，为之增损。伤气分则调气益气；伤血分则行血和血，然未有不先治暑而可获效者矣。治病必求其本，其斯之谓欤？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001033,"no":33}}', '2024-12-21T03:10:38.000Z', '2024-12-21T03:10:38.000Z', '2024-12-21T03:10:38.000Z', '1、风寒暑湿燥火，此天之六淫。其邪自外而入，感之而病，宜随其邪之所在以攻治之。《经》曰：夏伤于暑，秋必痎疟。是疟乃暑邪为病也。虽有山岚瘴气发疟一证，治稍不同，然其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，头疼骨疼，大渴引饮，口苦舌干，呕吐不思食，或烦躁不得眠，必用白虎汤二三剂，随证增损，解表以祛暑邪。而后随经消息，以除其苦可也。 2、滞下者，俗呼为痢疾，皆缘暑湿与饮食之积滞胶固而成。其证类多里急后重，数登圊而不便，或发热，或口渴，或恶心，不思食何，莫非暑之标证也。必用六一散、黄连、芍药为主，而后随其所苦，为之增损。伤气分则调气益气；伤血分则行血和血，然未有不先治暑而可获效者矣。治病必求其本，其斯之谓欤？', '2024-12-21T03:10:38.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('17Zc7PMslmG', 1, '{"title":"卷之一_续序例上_论病由七情生者，只应养性怡神、发舒志气以解之，不宜全仗药石攻治","description":"<p>1、夫喜怒忧思悲恐惊七者，皆发于情者也。情即神识，有知不定，无迹可寻，触境乃发，滞而难通。药石无知，焉能消其妄执？纵通其已滞之气，活其已伤之血，其默默绵绵之意，物而不化者，能保无将来复结之病乎？只宜以识遣识，以理遣情，此即“心病还将心药医”之谓也。如是庶可使滞者通，结者化，情与境离，不为所转，当处寂然，心君泰定，其何七情之为累哉？</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001034,"no":34}}', '2024-12-21T03:37:52.000Z', '2024-12-21T03:37:52.000Z', '2024-12-21T03:37:52.000Z', '1、夫喜怒忧思悲恐惊七者，皆发于情者也。情即神识，有知不定，无迹可寻，触境乃发，滞而难通。药石无知，焉能消其妄执？纵通其已滞之气，活其已伤之血，其默默绵绵之意，物而不化者，能保无将来复结之病乎？只宜以识遣识，以理遣情，此即“心病还将心药医”之谓也。如是庶可使滞者通，结者化，情与境离，不为所转，当处寂然，心君泰定，其何七情之为累哉？', '2024-12-21T03:37:52.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EDWZU6URWOV', 1, '{"title":"卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>1、伤寒、温疫初发，邪在于表，必头疼身热，病属三阳，即于此时急表散之。冬月即病，宜用辛温、辛热以汗之；春温夏热，宜用辛凉、辛寒、甘寒以汗之。汗后身凉脉静，无所伤犯，病不复作而愈。如投药濡滞，或病重药轻，不散之于表，致邪热内结，病属三阴，须下乃愈。内虚之人，不胜下药，多致危殆。又有少阴咽痛等证，则又不宜于下，或成狐惑，虫蚀肛门，种种难治之条，皆失于不早散故也。</p><p>2、痈疽皆由荣家实热气逆所结，急宜凉血活血，散结解毒，大剂连进，内外夹攻，务使消散。即势大毒盛，一时不能散尽，亦必十消七八。纵使溃脓，保无大害。若失于救治，使热毒内攻，其膜必坏。膜坏则神人不能救矣。</p><p>3、痘疮之害，多在血热，解于一二日内者十全八九，若迟则热毒内攻，陷入于里。肠胃当之，必致大便作泄，乳食不化，或神昏闷乱，便秘腹胀，则十不救一。除是禀受虚寒，方堪补托，济以温热，可救危急。</p><p>4、若夫疹家，便须速用辛寒、甘寒、苦寒之剂，清凉发散，十不失一。假令病重药轻，或治疗后期，或误投温热，则邪热内攻，烦躁闷乱，不可救药矣。</p><p>5、疟本暑邪，法当解肌。若元气先虚之人，脾胃薄弱，误投破气消食克伐之药，则中气愈虚，邪反内陷，必便脓血。治或失宜，多成腹胀，驯至不救，往往而是。</p><p>6、此之四证，皆须急治。要以自里达表者吉，自表陷里者凶。故药宜解散通利，最忌收涩破气，及诸温补。其关乎死生者最大，故特表而出之，俾世人知所先务也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001035,"no":35}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '1、伤寒、温疫初发，邪在于表，必头疼身热，病属三阳，即于此时急表散之。冬月即病，宜用辛温、辛热以汗之；春温夏热，宜用辛凉、辛寒、甘寒以汗之。汗后身凉脉静，无所伤犯，病不复作而愈。如投药濡滞，或病重药轻，不散之于表，致邪热内结，病属三阴，须下乃愈。内虚之人，不胜下药，多致危殆。又有少阴咽痛等证，则又不宜于下，或成狐惑，虫蚀肛门，种种难治之条，皆失于不早散故也。 2、痈疽皆由荣家实热气逆所结，急宜凉血活血，散结解毒，大剂连进，内外夹攻，务使消散。即势大毒盛，一时不能散尽，亦必十消七八。纵使溃脓，保无大害。若失于救治，使热毒内攻，其膜必坏。膜坏则神人不能救矣。 3、痘疮之害，多在血热，解于一二日内者十全八九，若迟则热毒内攻，陷入于里。肠胃当之，必致大便作泄，乳食不化，或神昏闷乱，便秘腹胀，则十不救一。除是禀受虚寒，方堪补托，济以温热，可救危急。 4、若夫疹家，便须速用辛寒、甘寒、苦寒之剂，清凉发散，十不失一。假令病重药轻，或治疗后期，或误投温热，则邪热内攻，烦躁闷乱，不可救药矣。 5、疟本暑邪，法当解肌。若元气先虚之人，脾胃薄弱，误投破气消食克伐之药，则中气愈虚，邪反内陷，必便脓血。治或失宜，多成腹胀，驯至不救，往往而是。 6、此之四证，皆须急治。要以自里达表者吉，自表陷里者凶。故药宜解散通利，最忌收涩破气，及诸温补。其关乎死生者最大，故特表而出之，俾世人知所先务也。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xF3B5wJTy3y', 1, '{"title":" 卷之一_续序例上_论五运六气之谬","description":"<p>1、原夫五运六气之说，其起于汉魏之后乎？何者？张仲景，汉末人也，其书不载也。华元化，三国人也，其书亦不载也。前之则越人无其文，后之则叔和鲜其说。予是以知其为后世所撰，无益于治疗，而有误乎来学，学者宜深辨之。予见今之医师，学无原本，不明所自，侈口而谈，莫不动云五运六气。将以施之治病，譬之指算法之精微，谓事物之实有，岂不误哉！殊不知五运六气者，虚位也。岁有是气至则算，无是气至则不算。既无其气，焉得有其药乎？一言可竟已。其云“必先岁气”者，譬夫此年忽多淫雨，民病多湿，药宜类用二术苦温以燥之，佐以风药，如防风、羌活、升麻、葛根之属，风能胜湿故也。此必先岁气之谓也。其云“无伐天和”者，即春夏禁用麻黄、桂枝，秋冬禁用石膏、知母、芩、连、芍药之谓。即春夏养阴、秋冬养阳之义耳！乃所以遵养天和之道也。昔人谓“不明五运六气，检遍方书何济”者，正指后人愚蒙，不明五运六气之所以，而误于方册所载，依而用之，动辄成过，则虽检遍方书，亦何益哉！　　</p><p>2、予少检《素问》中载有是说。既长游于四方，见天下医师与学士大夫，在在谈说其义，于时心窃疑之。又见性理所载，元儒草庐吴氏，于天之气运之中，亦备载之。予益自信其为天运气数之法，而非医家治病之书也。后从敝邑见赵少宰家藏宋版仲景《伤寒论》，皆北宋善板，始终详检，并未尝载有是说。六经治法之中，亦并无一字及之。予乃谛信予见之不谬，而断为非治伤寒外感之说。予尝遵仲景法治一切外邪为病，靡不响应。乃信非仲景之言，不可为万世法程。杂学混滥，疑误后人，故特表而出之。俾来学知所决择云。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001036,"no":36}}', '2024-12-21T03:42:05.000Z', '2024-12-21T03:42:05.000Z', '2024-12-21T03:42:05.000Z', '1、原夫五运六气之说，其起于汉魏之后乎？何者？张仲景，汉末人也，其书不载也。华元化，三国人也，其书亦不载也。前之则越人无其文，后之则叔和鲜其说。予是以知其为后世所撰，无益于治疗，而有误乎来学，学者宜深辨之。予见今之医师，学无原本，不明所自，侈口而谈，莫不动云五运六气。将以施之治病，譬之指算法之精微，谓事物之实有，岂不误哉！殊不知五运六气者，虚位也。岁有是气至则算，无是气至则不算。既无其气，焉得有其药乎？一言可竟已。其云“必先岁气”者，譬夫此年忽多淫雨，民病多湿，药宜类用二术苦温以燥之，佐以风药，如防风、羌活、升麻、葛根之属，风能胜湿故也。此必先岁气之谓也。其云“无伐天和”者，即春夏禁用麻黄、桂枝，秋冬禁用石膏、知母、芩、连、芍药之谓。即春夏养阴、秋冬养阳之义耳！乃所以遵养天和之道也。昔人谓“不明五运六气，检遍方书何济”者，正指后人愚蒙，不明五运六气之所以，而误于方册所载，依而用之，动辄成过，则虽检遍方书，亦何益哉！ 2、予少检《素问》中载有是说。既长游于四方，见天下医师与学士大夫，在在谈说其义，于时心窃疑之。又见性理所载，元儒草庐吴氏，于天之气运之中，亦备载之。予益自信其为天运气数之法，而非医家治病之书也。后从敝邑见赵少宰家藏宋版仲景《伤寒论》，皆北宋善板，始终详检，并未尝载有是说。六经治法之中，亦并无一字及之。予乃谛信予见之不谬，而断为非治伤寒外感之说。予尝遵仲景法治一切外邪为病，靡不响应。乃信非仲景之言，不可为万世法程。杂学混滥，疑误后人，故特表而出之。俾来学知所决择云。', '2024-12-21T03:42:05.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Scn5eB4EbzW', 1, '{"title":"卷之一_续序例上_祝医五则","description":"<p>1、凡人疾病，皆由前生不惜众生身命，竭用人财，好杀鸟兽昆虫，好箠楚下贱，甚则枉用毒刑，加诸无罪。种种业因，感此苦报。业作医师，为人司命，见诸苦恼，当兴悲悯。详检方书，精求药道，谛察深思，务期协中。常自思惟，药不对病，病不对机，二旨或乖，则下咽不返。人命至重，冥报难逃。勿为一时衣食，自贻莫忏之罪于千百劫。戒之哉！宜惧不宜喜也。</p><p>2、凡为医师，当先读书。凡欲读书，当先识字。字者，文之始也。不识字义，宁解文理？文理不通，动成窒碍。虽诗书满目，于神不染，触途成滞，何由省入？譬诸面墙，亦同木偶。望其拯生民之疾苦，顾不难哉？故昔称太医，今曰儒医太医者，读书穷理，本之身心，验之事物，战战兢兢，求中于道。造次之际，罔敢或肆者也。外此则俗工耳，不可以言医矣。</p><p>3、凡为医师，先当识药。药之所产，方隅不同，则精粗顿异，收采不时，则力用全乖。又或市肆饰伪，足以混真。苟非确认形质，精尝气味，鲜有不为其误者。譬诸将不知兵，立功何自？医之于药，亦犹是耳。既识药矣，宜习修事。《雷公炮炙》，固为大法，或有未尽，可以意通。必期躬亲，勿图苟且。譬诸饮食，烹调失度，尚不益人，反能增害，何况药物关乎躯命者耶？可不慎诸！</p><p>4、凡作医师，宜先虚怀。灵知空洞，本无一物。苟执我见，便与物对。我见坚固，势必轻人；我是人非，与境角立。一灵空窍，动为所塞，虽日亲至人，终不获益。白首故吾，良可悲已！执而不化，害加于人。清夜深思，宜生愧耻。况人之才识，自非生知，必假问学。问学之益，广博难量。脱不虚怀，何由纳受？不耻无学，而耻下问。师心自圣，于道何益？苟非至愚，能不儆省乎！</p><p>5、医师不患道术不精，而患取金不多。舍其本业，专事旁求。假宠贵人，翼其口吻，以希世重。纵得多金，无拔苦力。于当来世，岂不酬偿？作是思惟，是苦非乐。故当勤求道术，以济物命。纵有功效，任其自酬，勿责厚报。等心施治，勿轻贫贱。如此则德植厥躬，鬼神幽赞矣。</p><p>6、上来所祝五条，皆关切医师才品道术，利济功过。仰愿来学，俯从吾祝，则进乎道而不囿于技矣。讵非生人之至幸，斯道之大光也哉！</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001037,"no":37}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '1、凡人疾病，皆由前生不惜众生身命，竭用人财，好杀鸟兽昆虫，好箠楚下贱，甚则枉用毒刑，加诸无罪。种种业因，感此苦报。业作医师，为人司命，见诸苦恼，当兴悲悯。详检方书，精求药道，谛察深思，务期协中。常自思惟，药不对病，病不对机，二旨或乖，则下咽不返。人命至重，冥报难逃。勿为一时衣食，自贻莫忏之罪于千百劫。戒之哉！宜惧不宜喜也。 2、凡为医师，当先读书。凡欲读书，当先识字。字者，文之始也。不识字义，宁解文理？文理不通，动成窒碍。虽诗书满目，于神不染，触途成滞，何由省入？譬诸面墙，亦同木偶。望其拯生民之疾苦，顾不难哉？故昔称太医，今曰儒医太医者，读书穷理，本之身心，验之事物，战战兢兢，求中于道。造次之际，罔敢或肆者也。外此则俗工耳，不可以言医矣。 3、凡为医师，先当识药。药之所产，方隅不同，则精粗顿异，收采不时，则力用全乖。又或市肆饰伪，足以混真。苟非确认形质，精尝气味，鲜有不为其误者。譬诸将不知兵，立功何自？医之于药，亦犹是耳。既识药矣，宜习修事。《雷公炮炙》，固为大法，或有未尽，可以意通。必期躬亲，勿图苟且。譬诸饮食，烹调失度，尚不益人，反能增害，何况药物关乎躯命者耶？可不慎诸！ 4、凡作医师，宜先虚怀。灵知空洞，本无一物。苟执我见，便与物对。我见坚固，势必轻人；我是人非，与境角立。一灵空窍，动为所塞，虽日亲至人，终不获益。白首故吾，良可悲已！执而不化，害加于人。清夜深思，宜生愧耻。况人之才识，自非生知，必假问学。问学之益，广博难量。脱不虚怀，何由纳受？不耻无学，而耻下问。师心自圣，于道何益？苟非至愚，能不儆省乎！ 5、医师不患道术不精，而患取金不多。舍其本业，专事旁求。假宠贵人，翼其口吻，以希世重。纵得多金，无拔苦力。于当来世，岂不酬偿？作是思惟，是苦非乐。故当勤求道术，以济物命。纵有功效，任其自酬，勿责厚报。等心施治，勿轻贫贱。如此则德植厥躬，鬼神幽赞矣。 6、上来所祝五条，皆关切医师才品道术，利济功过。仰愿来学，俯从吾祝，则进乎道而不囿于技矣。讵非生人之至幸，斯道之大光也哉！', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U9Nk26DtJpK', 1, '{"title":"卷之二_诸病应忌药总例","description":"<p>1、补气：人参、黄耆、二术、人胞、红铅。</p><p>2、温补：人胞、红铅、白胶、鹿茸、巴戟天、人参、黄耆、二术、淫羊藿、肉苁蓉、补骨脂、当归、狗阴茎、菟丝子、蛇床子。</p><p>3、大热：附子、肉桂、仙茅、阳起石、乌头、硫黄、海狗肾、羊肉、雀肉、天雄、葫芦巴。</p><p>4、破气：青皮、枳实、枳壳、槟榔、厚朴、牵牛。</p><p>5、闭气：银杏、米面食、猪脂油、二术、黄芪。</p><p>6、降气：降真香、苏子、郁金、枇杷叶、橘红、沉香、乌药。</p><p>7、破血：桃仁、红花、苏方木、延胡索、干漆、五灵脂、花蕊石、乳香、没药、姜黄、三棱、蓬荗、水蛭、虻虫、䗪虫、肉桂、桃袅、穿山甲、麒麟竭。</p><p>8、升提发散：升麻、柴胡、川芎、紫苏、麻黄、干葛、羌活、独活、防风、白芷、生姜、细辛、荆芥、前胡、藁本、葱白、薄荷。</p><p>9、辛温辛热发散：吴茱萸、干姜、桂枝、麻黄、细辛、羌活、独活、防风、藁本、川芎、白芷、葱白。</p><p>10、吐：瓜蒂、栀子、豉、皂荚、藜芦、常山、人参芦、虾汁、盐汤。</p><p>11、下：大黄、芒硝、巴豆、牵牛、玄明粉、枳实、厚朴。</p><p>12、降泄：山栀、知母、天门冬、玄参。</p><p>13、利水：猪苓、泽泻、木通、瞿麦、车前子、葶苈、滑石、海金沙、商陆、茯苓、扁蓄、乌桕根皮、琥珀、芫花、甘遂、大戟、续随子、汉防己、郁李仁。</p><p>14、损津液：郁李仁、白矾、矾红、半夏。</p><p>15、敛摄：白芍药、五味子、醋、乌梅、白梅、酸枣仁。</p><p>16、固涩：龙骨、牡蛎、粟壳、诃黎勒、益智子、山茱萸、桑螵蛸、蛇床子、肉果、莲须、阿芙蓉、金樱子、原蚕蛾。</p><p>17、消导：山查、麦芽、草果、槟榔、三棱、蓬荗、神曲、枳壳、枳实、绿矾、莱菔子、红曲、橘红、砂仁。</p><p>18、开窍：龙脑香、麝香、苏合香、檀香、安息香。</p><p>19、香燥：沉香、麝香、龙脑香、缩砂蜜、豆蔻、藿香、香附、丁香、乌药、木香。</p><p>20、辛燥：火酒、蒜、半夏、南星、二术。</p><p>21、辛热：干姜、吴茱萸、胡椒、蒜、蘹香、生姜、巴豆、龙脑香。</p><p>22、湿润：地黄、当归、肉苁蓉、天门冬、知母、猪脂油、麻仁、栝楼仁。</p><p>23、滞腻：猪羊犬肉、鹅、地黄、南面、油腻、炙煿。</p><p>24、滑利：冬葵子、榆皮、牛乳、椿根白皮、柿、瓜、李、桃、梨、蜜、青菜、莼菜、酥、茄子。</p><p>25、发湿：鳜鱼、南面。</p><p>26、苦寒伤胃：山栀、黄檗、黄芩、黄连、大黄、苦参、玄参、知母、芦荟。</p><p>27、补命门相火：鹿茸、巴戟天、附子、人胞、红铅、白胶、肉桂、仙茅、阳起石、腽肭脐、淫羊藿、补骨脂、狗阴茎、菟丝子、原蚕蛾。</p><p>28、补肾水苦寒：黄檗、天门冬、玄参、知母。</p><p>29、酸寒：白芍药、牛膝、乌梅。</p><p>30、咸寒：童便、芒硝、玄参、秋石。</p><p>31、生冷：菱、梨、菜、李。</p><p>32、甘：甘草、饴糖、大枣、蜜。</p><p>33、咸：食盐、商陆、碱水、鹿茸、蛤蜊、蛎黄、蛏。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001038,"no":38}}', '2024-12-21T04:02:20.000Z', '2024-12-21T04:02:20.000Z', '2024-12-21T04:02:20.000Z', '1、补气：人参、黄耆、二术、人胞、红铅。 2、温补：人胞、红铅、白胶、鹿茸、巴戟天、人参、黄耆、二术、淫羊藿、肉苁蓉、补骨脂、当归、狗阴茎、菟丝子、蛇床子。 3、大热：附子、肉桂、仙茅、阳起石、乌头、硫黄、海狗肾、羊肉、雀肉、天雄、葫芦巴。 4、破气：青皮、枳实、枳壳、槟榔、厚朴、牵牛。 5、闭气：银杏、米面食、猪脂油、二术、黄芪。 6、降气：降真香、苏子、郁金、枇杷叶、橘红、沉香、乌药。 7、破血：桃仁、红花、苏方木、延胡索、干漆、五灵脂、花蕊石、乳香、没药、姜黄、三棱、蓬荗、水蛭、虻虫、䗪虫、肉桂、桃袅、穿山甲、麒麟竭。 8、升提发散：升麻、柴胡、川芎、紫苏、麻黄、干葛、羌活、独活、防风、白芷、生姜、细辛、荆芥、前胡、藁本、葱白、薄荷。 9、辛温辛热发散：吴茱萸、干姜、桂枝、麻黄、细辛、羌活、独活、防风、藁本、川芎、白芷、葱白。 10、吐：瓜蒂、栀子、豉、皂荚、藜芦、常山、人参芦、虾汁、盐汤。 11、下：大黄、芒硝、巴豆、牵牛、玄明粉、枳实、厚朴。 12、降泄：山栀、知母、天门冬、玄参。 13、利水：猪苓、泽泻、木通、瞿麦、车前子、葶苈、滑石、海金沙、商陆、茯苓、扁蓄、乌桕根皮、琥珀、芫花、甘遂、大戟、续随子、汉防己、郁李仁。 14、损津液：郁李仁、白矾、矾红、半夏。 15、敛摄：白芍药、五味子、醋、乌梅、白梅、酸枣仁。 16、固涩：龙骨、牡蛎、粟壳、诃黎勒、益智子、山茱萸、桑螵蛸、蛇床子、肉果、莲须、阿芙蓉、金樱子、原蚕蛾。 17、消导：山查、麦芽、草果、槟榔、三棱、蓬荗、神曲、枳壳、枳实、绿矾、莱菔子、红曲、橘红、砂仁。 18、开窍：龙脑香、麝香、苏合香、檀香、安息香。 19、香燥：沉香、麝香、龙脑香、缩砂蜜、豆蔻、藿香、香附、丁香、乌药、木香。 20、辛燥：火酒、蒜、半夏、南星、二术。 21、辛热：干姜、吴茱萸、胡椒、蒜、蘹香、生姜、巴豆、龙脑香。 22、湿润：地黄、当归、肉苁蓉、天门冬、知母、猪脂油、麻仁、栝楼仁。 23、滞腻：猪羊犬肉、鹅、地黄、南面、油腻、炙煿。 24、滑利：冬葵子、榆皮、牛乳、椿根白皮、柿、瓜、李、桃、梨、蜜、青菜、莼菜、酥、茄子。 25、发湿：鳜鱼、南面。 26、苦寒伤胃：山栀、黄檗、黄芩、黄连、大黄、苦参、玄参、知母、芦荟。 27、补命门相火：鹿茸、巴戟天、附子、人胞、红铅、白胶、肉桂、仙茅、阳起石、腽肭脐、淫羊藿、补骨脂、狗阴茎、菟丝子、原蚕蛾。 28、补肾水苦寒：黄檗、天门冬、玄参、知母。 29、酸寒：白芍药、牛膝、乌梅。 30、咸寒：童便、芒硝、玄参、秋石。 31、生冷：菱、梨、菜、李。 32、甘：甘草、饴糖、大枣、蜜。 33、咸：食盐、商陆、碱水、鹿茸、蛤蜊、蛎黄、蛏。', '2024-12-21T04:02:20.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PJf0Q8INIUL', 1, '{"title":"卷之二_续序例下_阴阳表里虚实门","description":"<p>1、阳虚：即真气虚。其证恶寒，或发热自汗，汗多亡阳。阳虚不发热，单恶寒者居多。</p>\n<p></p>\n<p>【忌】破气、降泄、利水、苦寒、又忌辛热发散。</p>\n<p></p>\n<p>        青皮、枳壳、厚朴、牵牛、槟榔（已上破气）、大黄、石膏、山栀、知母、天门冬、生地黄、栝楼（已上降泄）、泽泻、木通、瞿麦、木桕根皮、汉防己、葶苈、猪苓、滑石、海金沙、商陆（已上利水）、黄芩、黄连、黄檗、玄参、槐花（已上苦寒）、芍药、乌梅、醋（已上酸）、吴茱萸、麻黄、羌活、独活、前胡、防风、荆芥（已上辛热发散）。</p>\n<p></p>\n<p>【宜】补、甘、温、热。</p>\n<p></p>\n<p>       人参、黄耆、二术、炙甘草、当归、白胶、淫羊藿、人胞、红铅、补骨脂、巴戟天、桂、附子、仙茅、鹿茸、大蘹香、阳起石、羊肉、雀肉。</p><p>2、阴虚：即精血虚。其证为咳嗽多痰，吐血，咯血，嗽血，鼻衄，齿衄，盗汗，自汗，发热，寒热，潮热，骨乏无力，不眠，气急，腰背痛。</p>\n<p></p>\n<p>【忌】补气，复忌破气、燥热辛温，又忌大寒大苦伤胃，并升提发散、利水。</p>\n<p></p>\n<p>         人参、黄耆、二术、人胞（已上补气）、南星、半夏、附子、官桂、桂枝、仙茅、鹿茸、干姜、硫黄、阳起石、海狗肾、丁香、胡椒、乌头、火酒、吴茱萸、乌药、生姜（已上燥热辛温）、山栀、黄芩、黄连、大黄、芒硝、玄明粉（已上大寒大苦伤胃）、麻黄、升麻、柴胡、羌活、独活、藁本、川芎、防风（已上升提发散）、破气利水药见前。</p>\n<p></p>\n<p>【宜】生精补血，兼清虚热、敛摄、酸寒、甘寒、甘平、咸寒，略兼苦寒。</p>\n<p></p>\n<p>           地黄、柏子仁、人乳、沙苑蒺藜、枸杞子、牛膝、麋角胶、阿胶、沙参、酸枣仁、白芍药、五味子、山茱萸、石斛、麦门冬、薯蓣、牡丹皮、续断、地骨皮、车前子、溺白垽、鳖甲、黄檗、知母、青蒿。</p><p>3、表虚：其证自汗恶风，洒淅寒热，喜就温暖，脉浮无力。</p>\n<p></p>\n<p>【忌】破气、升发、辛热。</p>\n<p></p>\n<p>           麻黄、升麻、防风、柴胡、羌活、独活、前胡、干葛、紫苏、薄荷、白芷、生姜、荆芥（已上升发）、吴茱萸、桂枝（表虚而中寒者不忌）、干姜（已上辛热）、破气药见前。</p>\n<p></p>\n<p>【宜】补敛、益气实表、甘、酸。</p>\n<p></p>\n<p>        人参、黄耆、白芍药、甘草、桂枝（有热者勿用）、五味子。</p><p>4、里虚：其证洞泄，或完谷不化，心腹痛，按之即止。或腹胀，或伤寒下后痞满。</p>\n<p></p>\n<p>【忌】破气、下、苦寒。</p>\n<p></p>\n<p>         大黄、芒硝、巴豆、玄明粉、牵牛（已上下）、黄芩、黄连、山栀、知母、黄檗、天门冬、茗（已上苦寒）、破气药见前。</p>\n<p></p>\n<p>【宜】温补、甘、佐以辛热。</p>\n<p></p>\n<p>           人参、炙甘草、术、大枣、糯米、肉桂、附子（有热者勿用）、干姜。</p><p>5、阳实：即表邪热盛，其证头痛发热，遍身骨痛，无汗。</p>\n<p></p>\n<p>【忌】补敛、下、大热。</p>\n<p></p>\n<p>         黄耆、人参、二术、桂枝、芍药、五味子、米面食、猪羊犬肉、醋（已上补敛）、附子、胡椒、干姜、肉桂、蒜、吴茱萸（已上大热）、下药见前。</p>\n<p></p>\n<p>【宜】辛寒、发散，天寒略加辛热、辛温佐之。</p>\n<p></p>\n<p>         石膏、知母、葛根、麦门冬、前胡、柴胡、黄芩、紫苏、薄荷、升麻、防风、葱白、荆芥、羌活、麻黄（冬月可用，春夏忌之）。</p><p>6、阴实：即里实。外感证属邪热内结者，其证胸腹硬痛，手不可近，大便七八日不行，或挟热下痢。</p>\n<p></p>\n<p>【忌】辛温发散、补敛。</p>\n<p></p>\n<p>       诸药俱见前。</p>\n<p></p>\n<p>【宜】下、苦寒、咸寒、甘辛。</p>\n<p></p>\n<p>        大黄、厚朴、枳实、滑石、山栀、黄芩、黄连、蓝、茵蔯、陈、芒硝、桃仁。</p><p>7、阳厥：即热厥。其证四肢厥逆，身热面赤，唇燥，大渴，口干舌苦，目闭或不闭，小便赤涩短少，大便燥结，不省人事。</p>\n<p></p>\n<p>【忌】升发、补敛、燥热、辛温。</p>\n<p></p>\n<p>          诸药俱见前。</p>\n<p></p>\n<p>【宜】下、清热、甘寒、苦寒、咸寒。</p>\n<p></p>\n<p>      大黄、芒硝、石膏、黄芩、黄连、山栀、知母、童便。</p>\n<p>如挟虚有痰者，宜麦门冬、竹沥、芦根汁、梨汁、牛黄、童便。</p>\n<p>如妇人热入血室，因而厥者，药中以童便为君，加赤芍药、生地黄、牛膝、牡丹皮、桃仁。甚者大便结燥，加芒硝、大黄下之。通即止，勿尽剂。</p><p>8、阴厥：即寒厥。其证四肢厥逆，身冷，面青蜷卧，手指爪青黯，腹痛，大便溏，或完谷不化，小便自利，不渴，不省人事。</p>\n<p></p>\n<p>【忌】下、破气、苦寒、咸寒、酸寒。</p>\n<p></p>\n<p>     食盐、太阴玄精石、童便（已上咸寒）、芍药、醋（已上酸寒）。</p>\n<p></p>\n<p>     下、破气、苦寒诸药俱见前。</p>\n<p></p>\n<p>【宜】补气、温中、甘温、辛热。</p>\n<p></p>\n<p>          人参、干姜、附子、桂、吴茱萸。</p><p>9、上盛下虚：属阳盛阴虚。</p>\n<p></p>\n<p>【忌】升散、下、助阳、补气、复忌破气、燥热辛温。</p>\n<p></p>\n<p>      诸药俱见阴虚条下。</p>\n<p></p>\n<p>【宜】降、益阴、甘寒、酸寒、佐以咸寒、苦寒。</p>\n<p></p>\n<p>         苏子、枇杷叶、麦门冬、枸杞子、生地、沙参、白芍药、山茱萸、五味子、牛膝、童便、玄参、黄檗、天门冬。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001039,"no":39}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '1、阳虚：即真气虚。其证恶寒，或发热自汗，汗多亡阳。阳虚不发热，单恶寒者居多。 【忌】破气、降泄、利水、苦寒、又忌辛热发散。 青皮、枳壳、厚朴、牵牛、槟榔（已上破气）、大黄、石膏、山栀、知母、天门冬、生地黄、栝楼（已上降泄）、泽泻、木通、瞿麦、木桕根皮、汉防己、葶苈、猪苓、滑石、海金沙、商陆（已上利水）、黄芩、黄连、黄檗、玄参、槐花（已上苦寒）、芍药、乌梅、醋（已上酸）、吴茱萸、麻黄、羌活、独活、前胡、防风、荆芥（已上辛热发散）。 【宜】补、甘、温、热。 人参、黄耆、二术、炙甘草、当归、白胶、淫羊藿、人胞、红铅、补骨脂、巴戟天、桂、附子、仙茅、鹿茸、大蘹香、阳起石、羊肉、雀肉。 2、阴虚：即精血虚。其证为咳嗽多痰，吐血，咯血，嗽血，鼻衄，齿衄，盗汗，自汗，发热，寒热，潮热，骨乏无力，不眠，气急，腰背痛。 【忌】补气，复忌破气、燥热辛温，又忌大寒大苦伤胃，并升提发散、利水。 人参、黄耆、二术、人胞（已上补气）、南星、半夏、附子、官桂、桂枝、仙茅、鹿茸、干姜、硫黄、阳起石、海狗肾、丁香、胡椒、乌头、火酒、吴茱萸、乌药、生姜（已上燥热辛温）、山栀、黄芩、黄连、大黄、芒硝、玄明粉（已上大寒大苦伤胃）、麻黄、升麻、柴胡、羌活、独活、藁本、川芎、防风（已上升提发散）、破气利水药见前。 【宜】生精补血，兼清虚热、敛摄、酸寒、甘寒、甘平、咸寒，略兼苦寒。 地黄、柏子仁、人乳、沙苑蒺藜、枸杞子、牛膝、麋角胶、阿胶、沙参、酸枣仁、白芍药、五味子、山茱萸、石斛、麦门冬、薯蓣、牡丹皮、续断、地骨皮、车前子、溺白垽、鳖甲、黄檗、知母、青蒿。 3、表虚：其证自汗恶风，洒淅寒热，喜就温暖，脉浮无力。 【忌】破气、升发、辛热。 麻黄、升麻、防风、柴胡、羌活、独活、前胡、干葛、紫苏、薄荷、白芷、生姜、荆芥（已上升发）、吴茱萸、桂枝（表虚而中寒者不忌）、干姜（已上辛热）、破气药见前。 【宜】补敛、益气实表、甘、酸。 人参、黄耆、白芍药、甘草、桂枝（有热者勿用）、五味子。 4、里虚：其证洞泄，或完谷不化，心腹痛，按之即止。或腹胀，或伤寒下后痞满。 【忌】破气、下、苦寒。 大黄、芒硝、巴豆、玄明粉、牵牛（已上下）、黄芩、黄连、山栀、知母、黄檗、天门冬、茗（已上苦寒）、破气药见前。 【宜】温补、甘、佐以辛热。 人参、炙甘草、术、大枣、糯米、肉桂、附子（有热者勿用）、干姜。 5、阳实：即表邪热盛，其证头痛发热，遍身骨痛，无汗。 【忌】补敛、下、大热。 黄耆、人参、二术、桂枝、芍药、五味子、米面食、猪羊犬肉、醋（已上补敛）、附子、胡椒、干姜、肉桂、蒜、吴茱萸（已上大热）、下药见前。 【宜】辛寒、发散，天寒略加辛热、辛温佐之。 石膏、知母、葛根、麦门冬、前胡、柴胡、黄芩、紫苏、薄荷、升麻、防风、葱白、荆芥、羌活、麻黄（冬月可用，春夏忌之）。 6、阴实：即里实。外感证属邪热内结者，其证胸腹硬痛，手不可近，大便七八日不行，或挟热下痢。 【忌】辛温发散、补敛。 诸药俱见前。 【宜】下、苦寒、咸寒、甘辛。 大黄、厚朴、枳实、滑石、山栀、黄芩、黄连、蓝、茵蔯、陈、芒硝、桃仁。 7、阳厥：即热厥。其证四肢厥逆，身热面赤，唇燥，大渴，口干舌苦，目闭或不闭，小便赤涩短少，大便燥结，不省人事。 【忌】升发、补敛、燥热、辛温。 诸药俱见前。 【宜】下、清热、甘寒、苦寒、咸寒。 大黄、芒硝、石膏、黄芩、黄连、山栀、知母、童便。 如挟虚有痰者，宜麦门冬、竹沥、芦根汁、梨汁、牛黄、童便。 如妇人热入血室，因而厥者，药中以童便为君，加赤芍药、生地黄、牛膝、牡丹皮、桃仁。甚者大便结燥，加芒硝、大黄下之。通即止，勿尽剂。 8、阴厥：即寒厥。其证四肢厥逆，身冷，面青蜷卧，手指爪青黯，腹痛，大便溏，或完谷不化，小便自利，不渴，不省人事。 【忌】下、破气、苦寒、咸寒、酸寒。 食盐、太阴玄精石、童便（已上咸寒）、芍药、醋（已上酸寒）。 下、破气、苦寒诸药俱见前。 【宜】补气、温中、甘温、辛热。 人参、干姜、附子、桂、吴茱萸。 9、上盛下虚：属阳盛阴虚。 【忌】升散、下、助阳、补气、复忌破气、燥热辛温。 诸药俱见阴虚条下。 【宜】降、益阴、甘寒、酸寒、佐以咸寒、苦寒。 苏子、枇杷叶、麦门冬、枸杞子、生地、沙参、白芍药、山茱萸、五味子、牛膝、童便、玄参、黄檗、天门冬。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zdblnqWOPQO', 1, '{"title":"卷之二_续序例下_五脏六腑虚实门   　","description":"<p>1、五脏六腑虚实门</p>\n<p>安息香、丹砂、磁石、神水</p>\n<p>五心烦热，属真阴不足。</p><p>2、心虚（八证）</p>\n<p>【忌】升发、破气、苦寒、辛燥、大热。诸药俱见前。</p>\n<p>【宜】补血、甘温、酸敛、佐以咸寒、镇坠。生地黄、龙眼肉、人参、炙甘草、石斛、酸枣仁、五味子、柏子仁、丹参、茯神、远志、鹿茸、炒盐、丹砂。</p><p>3、惊邪，属心气虚。</p>\n<p>【忌】升、破气。诸药俱见前。</p>\n<p>【宜】降、清热、豁痰、平。《经》曰：惊者平之。犀角、丹砂、琥珀、真珠、龙齿、金箔、牛黄、代赭石、羚羊角、麦门冬、石斛、桔梗、胆星、麝香、竹沥、天竺黄、远志、鬼臼。</p><p>4、癫痫，属心气虚有热。</p>\n<p>【忌】补敛、升。诸药俱见前。</p>\n<p>【宜】降、清热、豁痰。诸药见惊邪条，加：贝母、丹参、钓藤钩、郁金、铅丹、神水、白矾。</p>\n<p></p><p>5、不得眠，属心血虚有热。</p>\n<p>【忌】升、辛燥、热。诸药俱见前。</p>\n<p>【宜】敛、养阴血、清热。酸枣仁、五味子、龙眼肉、丹参、芍药、人参、石斛、竹叶、生地黄、茯神、远志、黄连、玄参、麦门冬、辰砂六一散、竹茹、木通、生甘草。</p>\n<p>心烦，属心家有热。</p>\n<p>【忌】升、破气、燥热。诸药俱见前。</p>\n<p>【宜】清热、生津液、甘寒、甘平、辛酸。参用不得眠中诸药：竹叶、麦门冬、生甘草、石斛、丹参、龙眼肉、生地黄、玄参、沙参、茯神、远志、知母、酸枣仁。</p>\n<p></p><p>6、怔忡，属心血不足。忌、宜俱同心虚。</p>\n<p></p><p>7、心澹澹动。忌、宜俱同心虚。</p>\n<p></p><p>8、盗汗，属心血虚。汗者，心之液也。</p>\n<p>【忌】破气、辛散、燥热。诸药俱见前。</p>\n<p>【宜】补敛、清虚热、甘酸、甘平、甘寒、苦寒、咸寒。生地黄、当归、茯神、龙眼肉、黄耆、五味子、白芍药、酸枣仁、黄芩、黄檗、黄连、牡蛎。</p>\n<p></p><p>9、伏梁，属心经气血虚，以致邪留不去。</p>\n<p>【忌】破血、汗、下。三棱、蓬荗、姜黄、虻虫、䗪虫、红蓝花、水蛭、桃仁（已上破血）。汗、下诸药俱见前。</p>\n<p>【宜】活血、凉血、散热通结、辛咸。郁金、五灵脂、乳香、没药、当归、延胡索、赤芍药、远志、菖蒲、茯神、牡蛎。参用东垣伏梁丸治之。</p><p>10、肝虚（十证）</p>\n<p>【忌】收敛、破气、升散、苦寒、下。诸药俱见前。</p>\n<p>【宜】辛散、甘缓。当归、陈皮、生姜、地黄、甘菊、甘草、胡麻、谷精草、决明子、刺蒺藜、羊牛兔肝。因郁而虚者，加：细辛、木香、缩砂蜜、沉木香、川芎、香附。</p><p>11、胸胁痛，属肝血虚，肝气实，因而上逆。</p>\n<p>【忌】敛、补气、破血。诸药俱见前。</p>\n<p>【宜】降气、养血和肝、辛甘、平缓。苏子、郁金、番降香、川通草、当归、生地黄、橘皮、甘草、白芍药、续断、鹿角胶。</p><p>12、转筋，属血虚。</p>\n<p>【忌】下，复忌升、燥热、闭气、苦寒、破气。二术、黄耆、银杏、猪脂、羊肉、面（已上闭气）。馀忌药俱见前。</p>\n<p>【宜】酸、辛、甘平。木瓜、牛膝、当归身、白芍药、石斛、续断、炙甘草、陈皮、缩砂蜜。</p><p>13、目光短，属肝血虚，及肾水真阴不足。</p>\n<p>【忌】破气、升、燥、热。诸药俱见前。</p>\n<p>【宜】补肝兼滋肾、甘温益血、甘寒除热。甘枸杞、生地黄、甘菊花、沙苑蒺藜、谷精草、五味子、决明子、天门冬、麦门冬。</p><p>14、目昏，属肝血虚有热，兼肾水真阴不足。</p>\n<p>【忌】同前目光短。</p>\n<p>【宜】同目光短，加：黄檗、羚羊角。</p><p>15、目翳，属肝热，兼肾水不足。</p>\n<p>【忌】破气、升、燥热、苦寒。诸药俱见前。</p>\n<p>【宜】补肝血、除热、退翳。甘菊花、生地黄、决明子、石决明、沙苑蒺藜、女贞实、青羊胆、羚羊角、犀角、空青、黄连、天龙、伏翼粪、木贼、谷精草、蜜蒙花、人爪、蝉蜕、玛瑙、石蟹、珊瑚、真珠、琥珀、马目毒公、贝子。</p><p>16、亡血过多，角弓反张，属肝血虚有热。</p>\n<p>【忌】风燥、升、破气、下。诸药俱见前。</p>\n<p>【宜】补血清热、甘寒、甘温、酸寒、咸寒、辛润。当归、生地黄、白芍药、炙甘草、牛膝、麦门冬、牡丹皮、甘菊花、童便。有汗加：人参、黄耆、五味子、酸枣仁。</p><p>17、少腹连阴作痛、按之则止，属足厥阴经血虚。</p>\n<p>【忌】同角弓反张。</p>\n<p>【宜】同角弓反张，加：白胶。</p><p>18、偏头痛，属血虚、肝家有热，不急治，久之必损目。</p>\n<p>【忌】升、燥、热、苦寒。诸药俱见前。</p>\n<p>【宜】养血清虚热、甘寒、酸寒、辛寒。生地黄、天门冬、甘菊花、白芍药、当归、川芎、乌梅、炙甘草、土茯苓、金银藤、黑豆。有实火者可加：黄芩（酒炒）、大黄（酒蒸）、芎、雨前茶、石膏。</p><p>19、目黑黯、眩晕，属血虚，兼肾水真阴不足。</p>\n<p>【忌】破气、燥、热、辛温。诸药俱见前。</p>\n<p>【宜】养血补肝、清热、甘寒、甘平、酸寒、苦寒。生地黄、枸杞子、甘菊花、当归、薯蓣、五味子、白蒺藜、甘草、山茱萸、白芍药、天门冬、黄檗。</p><p>20、肥气，属气血两虚，肝气不和，逆气与瘀血相并而成。</p>\n<p>【忌】破气、下、苦寒。诸药俱见前。</p>\n<p>【宜】和肝散结气，兼行气血凝滞、甘温、甘平。川芎、当归、沉香、干姜、肉桂、橘皮、红花、郁金、延胡索、香附、山查、赤芍药、红曲、砂仁。参用东垣肥气丸治之。</p><p>21、脾虚（十二证）</p>\n<p>【忌】下、降泄、破气、苦寒。诸药俱见前。</p>\n<p>【宜】甘温，佐以辛香、酸平。人参、大枣、黄耆、薯蓣、炙甘草、莲肉、白茯苓、白扁豆、缩砂蜜、橘红、白豆蔻、藿香、木瓜、白芍药、酸枣仁。</p><p>22、饮食劳倦、伤脾发热。</p>\n<p>【忌】破气、发散、下、苦寒。诸药俱见前。</p>\n<p>【宜】补中益气、甘温、升、酸。人参、黄耆、术、炙甘草、大枣、柴胡、升麻、石斛、麦门冬、橘红、白芍药、酸枣仁。</p><p>23、饮食不消化，属脾气虚。</p>\n<p>【忌】破气、消导克伐、苦寒、复忌燥。草果、枳实、槟榔、蓬荗、三棱、绿矾（已上消导）。馀忌药见前。</p>\n<p>【宜】益真气、香、甘温、甘辛。同脾虚，加：谷糵、麦糵、肉豆蔻。</p><p>24、伤食，必恶食。</p>\n<p>【忌】润湿、苦寒。当归、肉苁蓉、锁阳、天门冬、地黄、知母、玄参、猪脂、茄子、酒、糟、面食（已上湿润）。苦寒诸药见前。</p>\n<p>【宜】健脾消导、甘温、辛香。橘皮、薯蓣、莲肉、白扁豆、白芍药、白茯苓、草果、山查、麦芽、草豆蔻、缩砂蜜、谷糵。如腹痛大便不通，宜下之：枳实、槟榔、厚朴、大黄。元气虚人不可下，宜加：参、术。伤肉食，轻者宜蒜、山查，兼黄连；重者宜矾红、枣肉为丸。服二钱，不可过，终身忌荞麦。伤面食，宜炒莱菔子。</p><p>25、停饮，为恣饮汤水，或冷茶、冷酒所致。</p>\n<p>【忌】下、酸敛、湿润、滞腻。诸药俱见前，加忌栝楼根及仁、桃仁、郁李仁。</p>\n<p>【宜】健脾利水、淡渗，兼辛散。人参、白术、半夏、茯苓、橘皮、泽泻、猪苓、木通、桑白皮、旋覆花、紫苏、白豆蔻。</p><p>26、水肿，属脾气虚。</p>\n<p>【忌】破气、下泄、湿润、咸、苦寒。食盐、商陆（已上咸）。馀忌药俱见前。</p>\n<p>【宜】补脾益气、燥湿、利水、辛香、甘温，佐以淡渗。人参、二术、橘皮、薯蓣、木瓜、薏苡仁、桑白皮、茯苓、赤小豆、香薷、乌蠡鱼、车前子、猪苓、泽泻、姜皮、乌芋、缩砂蜜、通草。</p><p>27、脾虚中满，属脾气虚，兼脾阴虚。</p>\n<p>【忌】破气、下、消导、利水、甘。饴糖、大枣、蜜、甘草（已上甘）。馀忌药俱见前。</p>\n<p>昼剧夜静，属脾气虚。【宜】补气键脾、甘温、淡渗，佐以辛香。人参、二术、白芍药、桑白皮、茯苓、车前子、橘红、姜皮、藿香、缩砂蜜。无热证者佐以桂。</p>\n<p>夜剧昼静，属脾阴虚。【宜】补脾阴，兼制肝清热、甘平、酸寒、淡渗。酸枣仁、白芍药、石斛、白扁豆、莲肉、橘皮、山药、苏子、五味子、木瓜、桑白皮、车前子、茯苓。</p><p>28、噎膈，属气血两虚，由于血液衰少，而非痰气壅逆所成。</p>\n<p>【忌】破气、升，复忌下、消导、燥、苦寒、辛热。诸药俱见前。</p>\n<p>【宜】降、清热润燥，甘温、甘平以益血，略佐辛香以顺气。苏子、橘红、枇杷叶、人参、白芍药、酸枣仁、龙眼肉、人乳、牛乳、蔗浆、梨汁、韭汁、芦根汁、姜汁、白豆蔻仁。</p><p>29、脾泄，属气虚。</p>\n<p>【忌】破气、下、消导、苦寒。诸药俱见前。</p>\n<p>【宜】温中补气、升清、甘温、甘平，佐以辛香。人参、术、炙甘草、薯蓣、莲肉、白扁豆、茯苓、车前子、白芍药、升麻、柴胡、肉豆蔻、缩砂蜜、橘皮、木香、丁香、藿香、白莱菔。兼有湿及痰，经年不愈，粪色白者，须服九制松脂。</p><p>30、健忘，属气血两虚。</p>\n<p>【忌】升、燥热，复忌苦寒、辛散。诸药俱见前。</p>\n<p>【宜】益脾阴，兼补气，酸敛、甘温、甘寒、辛平以通窍。酸枣仁、白芍药、五味子、人参、炙甘草、黄耆、龙眼肉、柏子仁、麦门冬、丹参、茯苓、茯神、石菖蒲、远志。</p><p>31、倦怠嗜卧，属脾气不足。</p>\n<p>【忌】破气、消导、苦寒。诸药俱见前。</p>\n<p>【宜】补气，兼健脾、甘温、辛香。人参、白术、黄耆、茯苓、薯蓣、炙甘草、谷糵、白扁豆、缩砂蜜、橘皮、藿香、白豆蔻。</p><p>32、脾虚腹痛，按之则止，属血虚。</p>\n<p>【忌】破气、破血、香燥、苦寒。诸药俱见前。</p>\n<p>【宜】益气补血、甘温、酸平。人参、炙甘草、龙眼肉、大枣、酸枣仁、石斛、麦门冬、白芍药。</p><p>33、痞气，属脾气虚及气郁所致。</p>\n<p>【忌】破气、下、湿润、苦寒。诸药俱见前。</p>\n<p>【宜】健脾，兼散结滞、甘温、辛香。人参、白芍药、橘红、缩砂蜜、藿香、吴茱萸、谷糵、麦糵、红曲、香附、木香。参用东垣痞气丸治之。</p><p>34、肺虚（七证）</p>\n<p>【忌】补气、升散、辛燥、温热。诸药俱见前。</p>\n<p>【宜】清热、降气、酸敛、润燥。天门冬、麦门冬、苏子、枇杷叶、贝母、沙参、百部、百合、桑白皮、五味子、杏仁、五倍子、蜜、梨、柿。无热者加：人参。</p><p>35、齁喘，属肺虚有热，因而痰壅。</p>\n<p>【忌】破气、升、发散、收涩。诃子、亚芙蓉、粟壳（已上收涩）。馀忌药俱见前。</p>\n<p>【宜】降气、消痰、辛凉、甘寒、苦平。苏子、枇杷叶、贝母、桑根白皮、栝楼根、竹沥、天门冬、麦门冬、百部、百合、薄荷、马兜铃、款冬花、沙参、前胡、白前、射干。</p><p>36、咳嗽吐血痰，属肺热甚。</p>\n<p>【忌】升、破气，复忌补气、破血、辛燥、温热、收涩。诸药俱见前。</p>\n<p>【宜】降气清热、润肺生津液、凉血益血、甘寒、甘平、咸寒、佐以苦寒。郁金、生地黄、蒲黄、侧柏叶、茅根、剪草、白及、阿胶、童便、知母。馀药肺虚条内参用。</p><p>37、声哑，属肺热甚。忌、宜俱同咳嗽。</p><p>38、咽喉燥痛，属水涸火炎，肺热之极。此证法所难治。忌、宜俱同咳嗽。</p><p>39、肺痿，属肺气虚有热。忌、宜俱同肺虚。</p><p>40、龟胸，属肺热有痰。忌、宜俱同齁喘咳嗽。</p><p>41、息贲，属肺气虚，痰热壅结所致。</p>\n<p>【忌】破气、辛热、补敛。诸药俱见前。</p>\n<p>【宜】降气、清热开痰、佐以散结。橘皮、白豆蔻、白芥子、射干、桔梗、旋覆花、桑白皮。参用东垣息贲丸治之。</p><p>42、肾虚（十八证）</p>\n<p>即肾水真阴不足。</p>\n<p>【忌】升、破气、利水、温热、辛燥、补命门相火。仙茅、巴戟天、葫芦巴、人参、补骨脂、鹿茸、人胞（已上补命门相火）。馀忌药俱见前。</p>\n<p>【宜】滋阴、润、生精补血、除热、甘寒、酸寒、苦寒、咸寒。地黄、枸杞子、牛膝、人乳、肉苁蓉、柏子仁、胡麻、沙苑蒺藜、杜仲、续断、天门冬、麦门冬、五味子、山茱萸、薯蓣、牡丹皮、菟丝子、车前子、地骨皮、知母、黄柏、鳖甲、青蒿、童便。</p><p>43、肾虚腰痛，属精气虚。</p>\n<p>【忌】破气、燥、热。诸药俱见前。</p>\n<p>【宜】同肾虚。</p><p>44、骨乏无力，属阴精不足，肾主骨故也。忌、宜俱同肾虚。</p><p>45、骨蒸潮热，属精血虚极，以致阳无所附，火空上炎。忌、宜俱同肾虚。</p><p>46、传尸劳。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】除热益阴、杀劳虫，兼清镇。诸药同肾虚，加：鬼臼、干漆、漆叶、芦荟、象胆、獭肝、胡黄连。忌、宜俱同肾虚。</p><p>47、梦遗泄精，属肾虚有火。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】滋阴、生津补血、除热、酸敛、佐以涩精。莲花蕊、生甘草、石斛、缩砂蜜、龙骨、覆盆子、鱼胶、莲肉、牡蛎、远志、韭子、桑螵蛸。馀药同肾虚条。</p><p>48、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。</p><p>49、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。</p>\n<p></p><p>50、溺有馀沥，属气虚。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】同肾虚，以五味子、黄檗、人参为君，加菟丝子、覆盆子为臣，益智为佐。如觉平日肺家有热，或咳嗽有火者，忌人参，用沙参。</p><p>51、溺血、血淋，属肾虚有火，热伤血分。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】同肾虚，加：侧柏叶、阿胶、茅根、韭白、干地黄、戎盐、蒲黄。</p><p>52、伤精白浊，属房劳过度，以致精伤流出，似白浊证。</p>\n<p>【忌】利小便、燥、辛热。诸药俱见前。</p>\n<p>【宜】同肾虚。</p><p>53、五淋，属肾虚兼有湿热。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】同肾虚，加清湿热。茯苓、黄檗、车前子、石斛、萆薢、薏苡仁。</p><p>54、精塞水窍不通，属房欲不竟，或思欲不遂，或惧泄忍精，或老人气不足以送精出窍。</p>\n<p>【忌】破气、下、利小便、燥热。诸药俱见前。</p>\n<p>【宜】行败精，壮实人宜兼泄火。老人宜兼补气血。外治用吮法。牛膝、生地黄、当归、桃仁、红花、车前子、鹿角霜。</p><p>55、齿浮、真牙摇动，及下龈软或齿衄，属肾虚有热。</p>\n<p>【忌】同肾虚，又忌当归、芎。</p>\n<p>【宜】益阴、凉血、固肾。诸药略同肾虚，应以地黄、黄檗、五味子为君；桑椹、牛膝、沙苑蒺藜、鹿茸、天门冬为臣；龙骨、牡蛎为使。</p><p>56、下消，属肾阴虚，火伏下焦。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】清热，及峻补真气、润、酸敛。诸药同肾虚，宜以黄檗、五味子、生地黄、天麦门冬、人参为君；石斛、牛膝、知母、人乳、童便为臣；地骨皮、青蒿、侧柏叶为佐。</p><p>57、善恐，属肾气虚。肾藏志故也。</p>\n<p>【忌】破气、苦寒。诸药俱见前。</p>\n<p>【宜】补气强志、辛平、甘温、佐以辛香。人参、远志、茯苓、鹿茸、酸枣仁、柏子仁、石斛、沉水香。</p><p>58、阴窍漏气，属肾气虚不固。肾主纳气，虚则不能纳，故见是证。</p>\n<p>【忌】破气、降、香燥、辛热。苏子、郁金、降香、沉水香、橘皮、通草（已上降）。白豆蔻、木香、香附（已上香燥）。馀忌药俱见前。</p>\n<p>【宜】补真气、酸敛、固涩。人参、五味子、山茱萸、沙苑蒺藜、覆盆子、枸杞子、益智子、远志、龙骨、牡蛎、金樱子、莲须。参用肾虚条内诸药。</p><p>59、疝，属肾虚，寒湿邪乘虚客之所致。丹溪谓与肾经绝无相干者，误也。又有先因湿邪为病，后成湿热者，药宜分寒热、先后二途。</p>\n<p>【忌】升、破气、苦寒、湿润。诸药俱见前。</p>\n<p>【宜】补气、通肾气、除湿。又有阴虚有热之人病此，兼宜除热。人参、黄耆、橘核、合欢子、荔枝核、川楝子、牛膝、木瓜、杜仲、萆薢、巴戟天。虚寒而痛，加：桂、蘹香、补骨脂、仙茅。虚热而痛，加：黄檗、车前子。湿盛者，加：术。</p><p>60、奔豚，属肾虚，脾家湿邪下传客肾所致。</p>\n<p>【忌】同疝，兼忌燥。诸药俱见前。</p>\n<p>【宜】补气、健脾、辛温、散结。人参、薯蓣、桂、山茱萸、牛膝、蘹香、蛇床子。参用东垣奔豚丸治之。</p><p>61、命门虚（四证）</p>\n<p>即元阳真火不足。</p>\n<p>【忌】下泄、破气、发散、辛寒、苦寒、淡渗、燥、补肾水苦寒药。黄檗、知母、生地黄、天门冬（已上补肾水苦寒药）。馀药俱见前。</p>\n<p>【宜】益真阳之气、甘温、咸温、甘热、酸敛。人参、红铅、人胞、鹿茸、白胶、肉苁蓉、菟丝子、枸杞子、覆盆子、五味子、巴戟天、山茱萸、附子、补骨脂、仙茅、阳起石。</p><p>62、阴痿，属命门火衰，下焦虚寒。</p>\n<p>【忌】同命门虚。</p>\n<p>【宜】同命门虚，加：海狗肾、天雄、蛇床子、原蚕蛾、狗阴茎、雀卵、牛膝、白马阴茎。</p><p>63、精寒、精薄，属命门火衰，阳气不足。忌、宜俱同阴痿。</p><p>64、肾泄，即五更及黎明泄泻者是也。亦名大瘕泄。属命门真火不足。</p>\n<p>【忌】同命门虚。</p>\n<p>【宜】益气、甘温、酸敛。人参、薯蓣、莲肉、肉豆蔻、砂仁、补骨脂、木香、吴茱萸、五味子。</p><p>65、畏寒足冷。忌、宜俱同命门虚。</p><p>66、小肠虚（一证）</p>\n<p>【忌】破气、辛散、燥热。诸药俱见前。</p>\n<p>【宜】补气、甘温、酸温。人参、黄耆、麦门冬、五味子、山茱萸。</p>\n<p>遗尿，属小肠虚，兼肾气虚。</p>\n<p>【忌】同小肠虚。</p>\n<p>【宜】同小肠虚，兼固涩。牡蛎、益智子、龙骨、金樱子。</p><p>67、胆虚（二证）</p>\n<p>【忌】汗、吐、下、苦寒、破气、燥。山栀、瓜蒂、藜芦、盐汤、常山（已上吐）。馀忌药俱见前。</p>\n<p>【宜】甘温、甘平、酸敛，佐以微辛。人参、当归、谷精草、决明子、木贼草、甘草、竹叶、竹茹、白芍药、酸枣仁。</p><p>68、易惊，属胆气虚。</p>\n<p>【忌】破气、升发、燥热。诸药俱见前。</p>\n<p>【宜】补胆气、甘温、辛温、酸平。人参、酸枣仁、甘草、竹叶、当归、白芍药、竹茹、橘皮。</p><p>69、病后不得眠，属胆虚。忌、宜俱同胆虚。</p><p>70、胃虚（七证）</p>\n<p>【忌】下、破气、苦寒、燥热。诸药俱见前。</p>\n<p>【宜】益气、甘平、甘淡、酸。人参、白术、白扁豆、莲肉、石斛、橘皮、白茯苓、木瓜、白芍药。兼寒加：生姜、白豆蔻、缩砂蜜。兼热加：竹茹、枇杷叶、麦门冬、芦根汁、蔗浆。</p><p>71、胃弱不纳食及不思饮食。</p>\n<p>【忌】同胃虚。</p>\n<p>【宜】同胃虚，仍分寒热治。</p><p>72、胃虚呕吐，宜分寒热。忌、宜俱同胃虚。</p><p>73、霍乱转筋，属胃虚，猝中邪恶气及毒气，兼有停滞所致。（转筋与肝经血虚不同。）</p>\n<p>【忌】闭气、滞腻、收敛、温补、大热。诸药俱见前。</p>\n<p>【宜】调气和中、辛散、消导。由于暑，必口渴，或口干、齿燥、口苦、小便短赤：白梅、白扁豆并叶、丝瓜叶、滑石、石膏、甘草、橘皮、香薷、木瓜、石斛、童溺、食盐、泥浆、缩砂蜜、厚朴。由于寒，则小水清白，不渴不热：缩砂蜜、丁香、橘皮、藿香。甚者加：吴茱萸、肉桂。外治用杉木、楠材，煎汤浸洗。</p><p>74、绞肠痧，属胃气虚，猝中天地邪恶秽污之气，郁于胸腹间，上不得吐，下不得泻，以致肠胃绞痛异常，胸腹骤胀，遍体紫黑，头顶心必有红发，急寻出拔去之，急以三棱鑱针刺委中，挤出热血，可立苏。次用新汲凉水，投入盐两许，恣饮，得吐泻即止。委中穴在两膝下湾横纹中间，两筋之中，刺入一分。</p>\n<p>【忌】温补、敛。诸药俱见前，切忌火酒、生姜、蒜及谷气、米饮、热汤，入口即死。</p>\n<p>【宜】通窍辟恶、辛散、咸寒。龙脑香、苏合香、藿香、檀香、乳香、芒硝、童便。煎药亦宜冷服。</p><p>75、中恶腹中㽲痛，属胃气虚，恶气客之所致。</p>\n<p>【忌】补、酸敛。诸药俱见前。</p>\n<p>【宜】辟恶气、通畅胃气、辛散。龙脑香、檀香、麝香（孕妇忌用）、牛黄、乳香、苏合香、丹砂、雄黄、鬼臼、藿香、橘皮、木香、沉水香、白豆蔻、远志、石菖蒲、干姜、桂。</p><p>76、反胃，属胃气虚。</p>\n<p>【忌】破气、升、苦寒、甘、燥热。诸药俱见前。</p>\n<p>【宜】补气、降气、和胃、清热、酸敛以制肝。人参、苏子、橘皮、枇杷叶、木瓜、竹茹、麦门冬、芦根汁、石斛、白茯苓、白芍药、梅酱、蔗浆。若因虚寒而得者，加：生姜、术、白豆蔻。</p><p>77、中酒，属胃弱。</p>\n<p>【忌】闭气、升、甘温、燥热、收涩。诸药俱见前。</p>\n<p>【宜】养胃、酸、辛散、淡渗。人参、麦门冬、白扁豆、葛花、五味子、梅酱、橘皮、白豆蔻、黄连、缩砂蜜、白茯苓、泽泻。</p><p>78、大肠虚（四证）</p>\n<p>【忌】破气、下、燥、热。诸药俱见前。</p>\n<p>【宜】补气、润燥、甘温。人参、黄耆、麦门冬、五味子、白芍药、炙甘草。</p><p>79、虚热便闭不通，属血虚，津液不足。</p>\n<p>【忌】破气、下、燥热、苦温、损津液。郁李仁（损津液）。馀忌药俱见前。</p>\n<p>【宜】生津液、润燥、凉血、益血。五味子、麦门冬、芝麻、麻仁、生蜜、天门冬、肉苁蓉、生地黄、当归、芦荟、炙甘草。</p><p>80、虚寒滑泄不禁，属气虚。</p>\n<p>【忌】破气、下、湿润、苦寒。诸药俱见前。</p>\n<p>【宜】补气、升、甘温、酸敛。人参、黄耆、白术、莲肉、升麻、炙甘草、吴茱萸、肉豆蔻、补骨脂、五味子、木瓜、赤石脂。</p><p>81、肠鸣，属气虚。</p>\n<p>【忌】破气、下、苦寒。诸药俱见前。</p>\n<p>【宜】同大肠虚，加升麻、柴胡以佐之。</p><p>82、脱肛，属气虚，兼有湿热。</p>\n<p>【忌】同大肠虚。</p>\n<p>【宜】补气、升提、除湿热。人参、黄耆、炙甘草、白术、莲肉、白扁豆、升麻、干葛、柴胡、黄檗、防风、黄连、黄芩、樗根白皮、白芍药。外用五倍子傅之。</p><p>83、膀胱虚（三证）</p>\n<p>【忌】破气、燥、利小便。诸药俱见前。</p>\n<p>【宜】补气、酸敛。人参、五味子、山茱萸、益智子、金樱子。</p><p>84、小便不禁，属气血虚。</p>\n<p>【忌】降下、湿润、燥热。诸药俱见前。</p>\n<p>【宜】同膀胱虚，加：牡蛎、龙骨、鹿茸、桑螵蛸、鸡䏶胵。频数不能少忍，加：麦门冬、五味子、黄檗、山茱萸、天门冬、鳖甲、牛膝、柏子仁、甘枸杞子。</p><p>85、遗尿，属本经气虚，见小肠虚条内。因膀胱虚亦能致遗尿，故复列此。忌、宜俱见小肠虚。</p><p>86、膀胱气。忌、宜俱同疝。</p><p>87、三焦虚（二证）</p>\n<p>【忌】破气、降、复忌升发、苦寒。诸药俱见前。</p>\n<p>【宜】补中益气，佐以辛温。人参、黄耆、白术、益智子、沉香、五味子。</p><p>88、腹寒，属中气虚。忌、宜俱同三焦虚。</p><p>89、短气、少气，属气虚。</p>\n<p>【忌】同三焦虚。</p>\n<p>【宜】补气益精、甘温、甘寒、酸温。人参、黄耆、麦门冬、五味子。</p><p>90、心实（五证）</p>\n<p>即实火实热。</p>\n<p>【忌】补敛、升、热、温燥。诸药俱见前。</p>\n<p>【宜】降火清热，苦寒以折之，辛寒以散之，甘寒以缓之，咸寒以润之。黄连、犀角、石膏、丹砂、牡丹皮、滑石、生甘草、麦门冬、竹叶、童便。大便结燥，加：芒硝、大黄。发狂亦如之。</p><p>91、谵语，属心家邪热。忌、宜俱同心实。</p><p>92、舌破，属心火。忌、宜俱同心实。</p><p>93、烦躁，属心家邪热及心火内炎。烦属心，躁属肾。忌、宜俱同心实。</p><p>94、自笑，属心家有热邪。忌、宜俱同心实。</p><p>95、发狂，属心家有邪热甚。忌、宜俱同心实。</p><p>96、肝实（五证）</p>\n<p>【忌】补气、升、酸敛、辛热、辛温、燥。诸药俱见前。</p>\n<p>【宜】清热降气、苦寒、辛寒、甘寒、酸寒。橘皮、青皮、苏子、黄连、黄芩、龙胆草、柴胡、生甘草、赤芍药、竹叶、青黛。</p><p>97、善怒，怒则气上逆，甚则呕血及飧泄。</p>\n<p>【忌】补、升、热、燥、闭气。诸药俱见前。</p>\n<p>【宜】降气、清热、甘寒、酸寒、咸寒，佐以辛散。苏子、郁金、番降香、生甘草、青黛、麦冬、生地黄、赤芍药、橘皮、蒲黄、当归、延胡索、砂仁、香附、童便。</p><p>987、善太息，忽忽不乐。忌、宜俱同善怒。</p><p>99、胁痛呕血，属肝气逆，肝火盛，肝血虚。忌、宜俱同善怒。</p><p>100、发搐，属肝家邪热，热则生风，风主掉眩故也。</p>\n<p>【忌】同善怒。</p>\n<p>【宜】清热、降气、利小便、缓中。生地黄、白芍药、黄连、丹砂、羚羊角、童便、苏子、麦门冬、生甘草、竹叶、甘菊花、白茯苓、木通。</p><p>101、目赤肿痛，属血热。</p>\n<p>【忌】同肝实善怒。</p>\n<p>【宜】凉血清热、甘寒、苦寒、酸寒。生地黄、赤芍药、甘草、甘菊、谷精草、蜜蒙花、荆芥、黄檗、大黄、黄连、连翘、玄参、山栀、竹叶、龙胆草、空青、曾青、木通、童便。外治：铜青、芒硝、石胆、蕤核。急者宜以三棱针刺破眼眶肿处，捋出热血，立解。迟则血贯瞳人，目损矣。</p><p>102、脾实（六证）</p>\n<p>即湿热邪胜。</p>\n<p>【忌】湿润、收涩、滞腻、热、咸、甘。诸药俱见前。</p>\n<p>【宜】除湿清热、利小便、辛散、风燥、苦寒。术、山栀、猪苓、泽泻、滑石、车前子、茯苓、白豆蔻、防风、干葛、黄连、枳实。</p><p>103、蛊胀，由于脾家湿热积滞，或内伤瘀血停积而成。</p>\n<p>【忌】补气、甘温、燥热。诸药俱见前。</p>\n<p>【宜】除湿、清热、利小便、消积。木通、防己、车前子、猪苓、泽泻、茯苓、葶苈、乌蠡鱼、桑白皮、山查、红曲、三棱、蓬术。</p><p>104、易饥，属脾家邪火。</p>\n<p>【忌】升、辛易、大热、香燥。沉香、麝香、龙脑、缩砂蜜、豆蔻、藿香（已上香燥）。馀忌药俱见前。</p>\n<p>【宜】清火除热、生津液、益脾阴、甘寒、苦寒、酸寒。黄连、青黛、连翘、山栀、石膏、竹叶、麦冬、石斛、白芍药、酸枣仁。</p><p>105、口唇生疮。</p>\n<p>【忌】温燥、热。诸药俱见前。</p>\n<p>【宜】甘寒、酸寒、苦寒、辛寒。麦门冬、生地黄、甘草、白芍药、乌梅、黄连、黄檗、玄参、连翘、栝楼根、干葛、石膏、龙胆草、大青、竹叶。</p><p>106、口糜。忌、宜俱同口唇生疮。</p><p>107、中消，属脾家实火。</p>\n<p>【忌】破气、下、温燥、热。诸药俱见前。</p>\n<p>【宜】服诸药同口唇生疮，加人参。</p><p>108、湿热腹痛，按之愈甚。</p>\n<p>【忌】闷气、酸敛、温热、燥。诸药俱见前。</p>\n<p>【宜】利小便，兼升提、苦寒。滑石、车前子、木通、黄连、黄芩、升麻、柴胡、葛根、防风。不愈加熟大黄，即 “土郁则夺之” 之义也。</p><p>109、肺实（八证）</p>\n<p>【忌】敛涩、补气、升、燥热、酸、咸。诸药俱见前。</p>\n<p>【宜】降气、润、甘寒、苦寒，佐以辛散。苏子、枇杷叶、桑白皮、天门冬、贝母、栝楼根、杏仁、白前、前胡、知母、车前子、桑黄、石膏、黄芩。</p><p>110、喘急，属肺有实热，及肺气上逆。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】同肺实，加：桔梗、甘草、栝楼仁、玄参、青黛。</p><p>111、气壅，属肺热气逆。忌、宜俱同肺实。</p><p>112、声重痰稠，属肺热。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】同肺实，加：薄荷、竹沥。</p><p>113、肺痈，属肺热极。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】清热、消痰、降火、解毒散结、甘寒、辛寒。桑白皮、桑黄、黄芩、贝母、栝楼根、薏苡仁、蕺菜、虎耳草、鼠粘子、连翘、甘草、败酱草、百年腌芥菜汁。</p><p>114、肺胀闷，属肺热。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】同肺实，并参用肺痈诸药。</p><p>115、吐脓血、血痰，咳嗽嗽血，属肺家火实热甚。此正 “邪气胜则实” 之谓。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】清热降气、凉血、豁痰。童便、苏子、枇杷叶、桑白皮、麦门冬、剪草、蒲黄、生地黄、天门冬、百部、桑黄、百合、薏苡仁、甘草、贝母、白芍药、白及、梧梗、款冬花、紫菀。</p><p>116、喉癣，属肺热。</p>\n<p>【忌】同肺热。</p>\n<p>【宜】同肺实，加：鼠粘子、玄参、射干。</p><p>117、上消，属肺家实火，及上焦热。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】降气、清热、补肺、生津、甘寒、苦寒、酸寒、辛寒。苏子、麦门冬、枇杷叶、桑白皮、桔梗、百部、百合、黄芩、天门冬、沙参、黄连、栝楼根、葛根、知母、玄参、石膏、甘草、五味子、白芍药、䈽竹叶、芦根、冬瓜、人乳、天酒。</p><p>118、肾无实，故无泻法。</p><p>119、命门实（二证）</p>\n<p>【忌】补气、温、热。诸药俱见前。</p>\n<p>【宜】苦寒、甘寒、咸寒。黄檗、知母、玄参、天门冬、麦门冬、牡丹皮、车前子、木通、泽泻。</p><p>120、强阳不倒，属命门火实，孤阳无阴所致。此证多不治。</p>\n<p>【忌】同命门实。</p>\n<p>【宜】同命门实，加：五味子、童便、生地黄。</p><p>121、水窍涩痛，属命门实火。</p>\n<p>【忌】同命门实。</p>\n<p>【宜】清热、利窍、甘寒、苦寒、咸寒，佐以淡渗。黄檗、知母、车前子、生地黄、天门冬、生甘草、黄芩、牛膝、麦门冬、童便、茯苓、木通。</p><p>122、小肠实（一证）</p>\n<p>【忌】敛涩、补气。诸药俱见前。</p>\n<p>【宜】通利、淡渗、苦寒、甘寒、咸寒。车前子、白茯苓、木通、生甘草、黄檗、知母、黄芩、黄连、牛膝、麦门冬、生地黄、童溺。</p>\n<p>小水不利，及赤、或涩痛尿血。忌、宜俱同小肠实。</p><p>123、胆实（二证）</p>\n<p>【忌】汗、吐、下。诸药俱见前。</p>\n<p>【宜】和解、辛寒、甘寒、苦寒、辛温。柴胡、黄芩、半夏、生姜、甘草、橘皮、龙胆草。</p><p>124、口苦耳聋胁痛，往来寒热。</p>\n<p>【忌】同胆实。</p>\n<p>【宜】用仲景小柴胡汤，随所见兼证加减。</p><p>125、鼻渊，属胆移热于脑。</p>\n<p>【忌】辛温、燥、热。诸药俱见前。</p>\n<p>【宜】清热、补脑、甘寒、甘平、佐以辛寒。天门冬、甘菊花、生地黄、沙苑蒺藜、山茱萸、沙参、薄荷、柴胡、辛夷、黄芩、玄参、知母。</p><p>126、胃实（六证）</p>\n<p>【忌】升、补敛、辛温、燥、热、湿润。诸药俱见前。</p>\n<p>【宜】下。如邪未结，宜清热发散、苦寒、辛寒、甘寒。大黄、枳实、知母、石膏、葛根、竹叶、大青、小青、青黛、麦冬、甘草。</p><p>127、谵语发狂、发斑，弃衣而走，登高而歌，属胃家邪热实。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】同胃实。如大便结者，加芒硝，亟下之；发斑者，加鼠粘子、玄参、栝楼根，多用石膏为君。便结亦加大黄下之。</p><p>128、口臭，数欲饮食，属胃火。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】清热降火、苦寒、甘寒、辛寒。黄连、青黛、连翘、麦门冬、石斛、芦根汁、竹叶、石膏。</p><p>129、嘈杂，属胃火。</p>\n<p>【忌】同口臭。</p>\n<p>【宜】同口臭，略兼消导。山查、麦芽、橘红、神曲。</p><p>130、口淡，属胃热。忌、宜俱同口臭。</p><p>131、呕吐，属胃火者，必面赤，小便短赤或涩，大便多燥，口苦或干渴。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】同胃实，加：枇杷叶、竹茹、木瓜、芦根、橘皮、通草、白茯苓。</p><p>132、吞酸，属胃火。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】同嘈杂。</p><p>133、大肠实（四证）</p>\n<p>【忌】补敛、燥、热。诸药俱见前。</p>\n<p>【宜】润下、苦寒、辛寒。生地黄、麻仁、桃仁、黄连、黄芩、槐花、大黄、石膏、知母、枳壳。</p><p>134、便硬闭。</p>\n<p>【忌】同大肠实。</p>\n<p>【宜】同大肠实，加：芒硝、猪胆、槟榔、郁李仁、石蜜。</p><p>135、肠风下血，属大肠湿热。</p>\n<p>【忌】下、燥、热。诸药俱见前。</p>\n<p>【宜】清热凉血、兼升、甘寒、苦寒。生地黄、槐花、地榆、黄连、黄芩、荆芥、防风、甘草、红曲、白芍药、侧柏叶、白头翁、蒲黄、鸡子、葛谷。</p><p>136、脏毒，属血热。</p>\n<p>【忌】同肠风下血。</p>\n<p>【宜】同肠风下血，加：忍冬、麦门冬、倍加地榆、蒲黄。</p><p>137、肠痈，属大肠实火。</p>\n<p>【忌】同肠风下血。</p>\n<p>【宜】下、苦寒、解毒。大黄、白药子、白芷、白及、白敛、连翘、忍冬藤、天明精、甘草、黄耆、生地黄、明矾、黄蜡、生蜜（已上三味作丸）。</p><p>138、膀胱实（一证）</p>\n<p>【忌】燥、热、收涩。诸药俱见前。</p>\n<p>【宜】润、淡渗。知母、黄檗、车前子、木通、瞿麦、滑石、茯苓、猪苓、泽泻。</p>\n<p>癃闭，属膀胱实热。</p>\n<p>【忌】破气、发散、燥、热。如属水液不足，兼忌利小便。诸药俱见前。</p>\n<p>【宜】同膀胱实，佐以升提。升麻、柴胡。</p><p>139、三焦实（三证）</p>\n<p>【忌】补敛、升、燥热。诸药俱见前。</p>\n<p>【宜】降、清热、调气、甘寒、苦寒、咸寒。苏子、麦门冬、知母、黄檗、玄参、山栀、黄芩、黄连、童便。</p><p>140、喉痹，即缠喉风。属少阳相火、少阴君火并炽。《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也。一阳者，少阳相火也。</p>\n<p>【忌】同三焦实。</p>\n<p>【宜】辛散，佐以苦寒、咸寒。急则有针法、吹法、吐法。鼠粘子、山豆根、射干、黄连、黄檗、知母、玄参、童便、苏子、麦门冬、贝母、甘草、生犀角、山慈菇、苦桔梗、续随子。急治用胆矾、朴硝、牛黄为末，和匀吹入喉中。又法：用明矾三钱、巴豆七粒去壳，同矾煅，矾枯，去巴豆，即取矾为细末，吹入喉中，流出热涎即宽。</p><p>141、头面赤热，属上焦火升。</p>\n<p>【忌】同三焦实。</p>\n<p>【宜】降、清热、甘缓，佐以酸敛。苏子、枇杷叶、天门冬、麦门冬、玄参、薄荷、栝楼根、梨、柿、蔗、童便、白芍药、五味子。</p><p>142、赤白游风，属血热，热则生风，故善游走，俗名火丹。小儿多患此，大人亦时有之。</p>\n<p>【忌】同三焦实。</p>\n<p>【宜】清热、凉血，兼行血、辛寒、甘寒、苦寒、咸寒。生地黄、黄连、黄檗、生甘草、牡丹皮、蒲黄、红蓝花、连翘、玄参、鼠粘子、牛膝、蓝汁、苎根、童便、赤芍药。宜兼外治，砭出热血，及用漆姑草、慎火草捣烂敷之，即易愈。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001040,"no":40}}', '2024-12-23T02:38:53.000Z', '2024-12-23T02:38:53.000Z', '2024-12-23T02:38:53.000Z', '1、五脏六腑虚实门 安息香、丹砂、磁石、神水 五心烦热，属真阴不足。 2、心虚（八证） 【忌】升发、破气、苦寒、辛燥、大热。诸药俱见前。 【宜】补血、甘温、酸敛、佐以咸寒、镇坠。生地黄、龙眼肉、人参、炙甘草、石斛、酸枣仁、五味子、柏子仁、丹参、茯神、远志、鹿茸、炒盐、丹砂。 3、惊邪，属心气虚。 【忌】升、破气。诸药俱见前。 【宜】降、清热、豁痰、平。《经》曰：惊者平之。犀角、丹砂、琥珀、真珠、龙齿、金箔、牛黄、代赭石、羚羊角、麦门冬、石斛、桔梗、胆星、麝香、竹沥、天竺黄、远志、鬼臼。 4、癫痫，属心气虚有热。 【忌】补敛、升。诸药俱见前。 【宜】降、清热、豁痰。诸药见惊邪条，加：贝母、丹参、钓藤钩、郁金、铅丹、神水、白矾。 5、不得眠，属心血虚有热。 【忌】升、辛燥、热。诸药俱见前。 【宜】敛、养阴血、清热。酸枣仁、五味子、龙眼肉、丹参、芍药、人参、石斛、竹叶、生地黄、茯神、远志、黄连、玄参、麦门冬、辰砂六一散、竹茹、木通、生甘草。 心烦，属心家有热。 【忌】升、破气、燥热。诸药俱见前。 【宜】清热、生津液、甘寒、甘平、辛酸。参用不得眠中诸药：竹叶、麦门冬、生甘草、石斛、丹参、龙眼肉、生地黄、玄参、沙参、茯神、远志、知母、酸枣仁。 6、怔忡，属心血不足。忌、宜俱同心虚。 7、心澹澹动。忌、宜俱同心虚。 8、盗汗，属心血虚。汗者，心之液也。 【忌】破气、辛散、燥热。诸药俱见前。 【宜】补敛、清虚热、甘酸、甘平、甘寒、苦寒、咸寒。生地黄、当归、茯神、龙眼肉、黄耆、五味子、白芍药、酸枣仁、黄芩、黄檗、黄连、牡蛎。 9、伏梁，属心经气血虚，以致邪留不去。 【忌】破血、汗、下。三棱、蓬荗、姜黄、虻虫、䗪虫、红蓝花、水蛭、桃仁（已上破血）。汗、下诸药俱见前。 【宜】活血、凉血、散热通结、辛咸。郁金、五灵脂、乳香、没药、当归、延胡索、赤芍药、远志、菖蒲、茯神、牡蛎。参用东垣伏梁丸治之。 10、肝虚（十证） 【忌】收敛、破气、升散、苦寒、下。诸药俱见前。 【宜】辛散、甘缓。当归、陈皮、生姜、地黄、甘菊、甘草、胡麻、谷精草、决明子、刺蒺藜、羊牛兔肝。因郁而虚者，加：细辛、木香、缩砂蜜、沉木香、川芎、香附。 11、胸胁痛，属肝血虚，肝气实，因而上逆。 【忌】敛、补气、破血。诸药俱见前。 【宜】降气、养血和肝、辛甘、平缓。苏子、郁金、番降香、川通草、当归、生地黄、橘皮、甘草、白芍药、续断、鹿角胶。 12、转筋，属血虚。 【忌】下，复忌升、燥热、闭气、苦寒、破气。二术、黄耆、银杏、猪脂、羊肉、面（已上闭气）。馀忌药俱见前。 【宜】酸、辛、甘平。木瓜、牛膝、当归身、白芍药、石斛、续断、炙甘草、陈皮、缩砂蜜。 13、目光短，属肝血虚，及肾水真阴不足。 【忌】破气、升、燥、热。诸药俱见前。 【宜】补肝兼滋肾、甘温益血、甘寒除热。甘枸杞、生地黄、甘菊花、沙苑蒺藜、谷精草、五味子、决明子、天门冬、麦门冬。 14、目昏，属肝血虚有热，兼肾水真阴不足。 【忌】同前目光短。 【宜】同目光短，加：黄檗、羚羊角。 15、目翳，属肝热，兼肾水不足。 【忌】破气、升、燥热、苦寒。诸药俱见前。 【宜】补肝血、除热、退翳。甘菊花、生地黄、决明子、石决明、沙苑蒺藜、女贞实、青羊胆、羚羊角、犀角、空青、黄连、天龙、伏翼粪、木贼、谷精草、蜜蒙花、人爪、蝉蜕、玛瑙、石蟹、珊瑚、真珠、琥珀、马目毒公、贝子。 16、亡血过多，角弓反张，属肝血虚有热。 【忌】风燥、升、破气、下。诸药俱见前。 【宜】补血清热、甘寒、甘温、酸寒、咸寒、辛润。当归、生地黄、白芍药、炙甘草、牛膝、麦门冬、牡丹皮、甘菊花、童便。有汗加：人参、黄耆、五味子、酸枣仁。 17、少腹连阴作痛、按之则止，属足厥阴经血虚。 【忌】同角弓反张。 【宜】同角弓反张，加：白胶。 18、偏头痛，属血虚、肝家有热，不急治，久之必损目。 【忌】升、燥、热、苦寒。诸药俱见前。 【宜】养血清虚热、甘寒、酸寒、辛寒。生地黄、天门冬、甘菊花、白芍药、当归、川芎、乌梅、炙甘草、土茯苓、金银藤、黑豆。有实火者可加：黄芩（酒炒）、大黄（酒蒸）、芎、雨前茶、石膏。 19、目黑黯、眩晕，属血虚，兼肾水真阴不足。 【忌】破气、燥、热、辛温。诸药俱见前。 【宜】养血补肝、清热、甘寒、甘平、酸寒、苦寒。生地黄、枸杞子、甘菊花、当归、薯蓣、五味子、白蒺藜、甘草、山茱萸、白芍药、天门冬、黄檗。 20、肥气，属气血两虚，肝气不和，逆气与瘀血相并而成。 【忌】破气、下、苦寒。诸药俱见前。 【宜】和肝散结气，兼行气血凝滞、甘温、甘平。川芎、当归、沉香、干姜、肉桂、橘皮、红花、郁金、延胡索、香附、山查、赤芍药、红曲、砂仁。参用东垣肥气丸治之。 21、脾虚（十二证） 【忌】下、降泄、破气、苦寒。诸药俱见前。 【宜】甘温，佐以辛香、酸平。人参、大枣、黄耆、薯蓣、炙甘草、莲肉、白茯苓、白扁豆、缩砂蜜、橘红、白豆蔻、藿香、木瓜、白芍药、酸枣仁。 22、饮食劳倦、伤脾发热。 【忌】破气、发散、下、苦寒。诸药俱见前。 【宜】补中益气、甘温、升、酸。人参、黄耆、术、炙甘草、大枣、柴胡、升麻、石斛、麦门冬、橘红、白芍药、酸枣仁。 23、饮食不消化，属脾气虚。 【忌】破气、消导克伐、苦寒、复忌燥。草果、枳实、槟榔、蓬荗、三棱、绿矾（已上消导）。馀忌药见前。 【宜】益真气、香、甘温、甘辛。同脾虚，加：谷糵、麦糵、肉豆蔻。 24、伤食，必恶食。 【忌】润湿、苦寒。当归、肉苁蓉、锁阳、天门冬、地黄、知母、玄参、猪脂、茄子、酒、糟、面食（已上湿润）。苦寒诸药见前。 【宜】健脾消导、甘温、辛香。橘皮、薯蓣、莲肉、白扁豆、白芍药、白茯苓、草果、山查、麦芽、草豆蔻、缩砂蜜、谷糵。如腹痛大便不通，宜下之：枳实、槟榔、厚朴、大黄。元气虚人不可下，宜加：参、术。伤肉食，轻者宜蒜、山查，兼黄连；重者宜矾红、枣肉为丸。服二钱，不可过，终身忌荞麦。伤面食，宜炒莱菔子。 25、停饮，为恣饮汤水，或冷茶、冷酒所致。 【忌】下、酸敛、湿润、滞腻。诸药俱见前，加忌栝楼根及仁、桃仁、郁李仁。 【宜】健脾利水、淡渗，兼辛散。人参、白术、半夏、茯苓、橘皮、泽泻、猪苓、木通、桑白皮、旋覆花、紫苏、白豆蔻。 26、水肿，属脾气虚。 【忌】破气、下泄、湿润、咸、苦寒。食盐、商陆（已上咸）。馀忌药俱见前。 【宜】补脾益气、燥湿、利水、辛香、甘温，佐以淡渗。人参、二术、橘皮、薯蓣、木瓜、薏苡仁、桑白皮、茯苓、赤小豆、香薷、乌蠡鱼、车前子、猪苓、泽泻、姜皮、乌芋、缩砂蜜、通草。 27、脾虚中满，属脾气虚，兼脾阴虚。 【忌】破气、下、消导、利水、甘。饴糖、大枣、蜜、甘草（已上甘）。馀忌药俱见前。 昼剧夜静，属脾气虚。【宜】补气键脾、甘温、淡渗，佐以辛香。人参、二术、白芍药、桑白皮、茯苓、车前子、橘红、姜皮、藿香、缩砂蜜。无热证者佐以桂。 夜剧昼静，属脾阴虚。【宜】补脾阴，兼制肝清热、甘平、酸寒、淡渗。酸枣仁、白芍药、石斛、白扁豆、莲肉、橘皮、山药、苏子、五味子、木瓜、桑白皮、车前子、茯苓。 28、噎膈，属气血两虚，由于血液衰少，而非痰气壅逆所成。 【忌】破气、升，复忌下、消导、燥、苦寒、辛热。诸药俱见前。 【宜】降、清热润燥，甘温、甘平以益血，略佐辛香以顺气。苏子、橘红、枇杷叶、人参、白芍药、酸枣仁、龙眼肉、人乳、牛乳、蔗浆、梨汁、韭汁、芦根汁、姜汁、白豆蔻仁。 29、脾泄，属气虚。 【忌】破气、下、消导、苦寒。诸药俱见前。 【宜】温中补气、升清、甘温、甘平，佐以辛香。人参、术、炙甘草、薯蓣、莲肉、白扁豆、茯苓、车前子、白芍药、升麻、柴胡、肉豆蔻、缩砂蜜、橘皮、木香、丁香、藿香、白莱菔。兼有湿及痰，经年不愈，粪色白者，须服九制松脂。 30、健忘，属气血两虚。 【忌】升、燥热，复忌苦寒、辛散。诸药俱见前。 【宜】益脾阴，兼补气，酸敛、甘温、甘寒、辛平以通窍。酸枣仁、白芍药、五味子、人参、炙甘草、黄耆、龙眼肉、柏子仁、麦门冬、丹参、茯苓、茯神、石菖蒲、远志。 31、倦怠嗜卧，属脾气不足。 【忌】破气、消导、苦寒。诸药俱见前。 【宜】补气，兼健脾、甘温、辛香。人参、白术、黄耆、茯苓、薯蓣、炙甘草、谷糵、白扁豆、缩砂蜜、橘皮、藿香、白豆蔻。 32、脾虚腹痛，按之则止，属血虚。 【忌】破气、破血、香燥、苦寒。诸药俱见前。 【宜】益气补血、甘温、酸平。人参、炙甘草、龙眼肉、大枣、酸枣仁、石斛、麦门冬、白芍药。 33、痞气，属脾气虚及气郁所致。 【忌】破气、下、湿润、苦寒。诸药俱见前。 【宜】健脾，兼散结滞、甘温、辛香。人参、白芍药、橘红、缩砂蜜、藿香、吴茱萸、谷糵、麦糵、红曲、香附、木香。参用东垣痞气丸治之。 34、肺虚（七证） 【忌】补气、升散、辛燥、温热。诸药俱见前。 【宜】清热、降气、酸敛、润燥。天门冬、麦门冬、苏子、枇杷叶、贝母、沙参、百部、百合、桑白皮、五味子、杏仁、五倍子、蜜、梨、柿。无热者加：人参。 35、齁喘，属肺虚有热，因而痰壅。 【忌】破气、升、发散、收涩。诃子、亚芙蓉、粟壳（已上收涩）。馀忌药俱见前。 【宜】降气、消痰、辛凉、甘寒、苦平。苏子、枇杷叶、贝母、桑根白皮、栝楼根、竹沥、天门冬、麦门冬、百部、百合、薄荷、马兜铃、款冬花、沙参、前胡、白前、射干。 36、咳嗽吐血痰，属肺热甚。 【忌】升、破气，复忌补气、破血、辛燥、温热、收涩。诸药俱见前。 【宜】降气清热、润肺生津液、凉血益血、甘寒、甘平、咸寒、佐以苦寒。郁金、生地黄、蒲黄、侧柏叶、茅根、剪草、白及、阿胶、童便、知母。馀药肺虚条内参用。 37、声哑，属肺热甚。忌、宜俱同咳嗽。 38、咽喉燥痛，属水涸火炎，肺热之极。此证法所难治。忌、宜俱同咳嗽。 39、肺痿，属肺气虚有热。忌、宜俱同肺虚。 40、龟胸，属肺热有痰。忌、宜俱同齁喘咳嗽。 41、息贲，属肺气虚，痰热壅结所致。 【忌】破气、辛热、补敛。诸药俱见前。 【宜】降气、清热开痰、佐以散结。橘皮、白豆蔻、白芥子、射干、桔梗、旋覆花、桑白皮。参用东垣息贲丸治之。 42、肾虚（十八证） 即肾水真阴不足。 【忌】升、破气、利水、温热、辛燥、补命门相火。仙茅、巴戟天、葫芦巴、人参、补骨脂、鹿茸、人胞（已上补命门相火）。馀忌药俱见前。 【宜】滋阴、润、生精补血、除热、甘寒、酸寒、苦寒、咸寒。地黄、枸杞子、牛膝、人乳、肉苁蓉、柏子仁、胡麻、沙苑蒺藜、杜仲、续断、天门冬、麦门冬、五味子、山茱萸、薯蓣、牡丹皮、菟丝子、车前子、地骨皮、知母、黄柏、鳖甲、青蒿、童便。 43、肾虚腰痛，属精气虚。 【忌】破气、燥、热。诸药俱见前。 【宜】同肾虚。 44、骨乏无力，属阴精不足，肾主骨故也。忌、宜俱同肾虚。 45、骨蒸潮热，属精血虚极，以致阳无所附，火空上炎。忌、宜俱同肾虚。 46、传尸劳。 【忌】同肾虚。 【宜】除热益阴、杀劳虫，兼清镇。诸药同肾虚，加：鬼臼、干漆、漆叶、芦荟、象胆、獭肝、胡黄连。忌、宜俱同肾虚。 47、梦遗泄精，属肾虚有火。 【忌】同肾虚。 【宜】滋阴、生津补血、除热、酸敛、佐以涩精。莲花蕊、生甘草、石斛、缩砂蜜、龙骨、覆盆子、鱼胶、莲肉、牡蛎、远志、韭子、桑螵蛸。馀药同肾虚条。 48、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。 49、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。 50、溺有馀沥，属气虚。 【忌】同肾虚。 【宜】同肾虚，以五味子、黄檗、人参为君，加菟丝子、覆盆子为臣，益智为佐。如觉平日肺家有热，或咳嗽有火者，忌人参，用沙参。 51、溺血、血淋，属肾虚有火，热伤血分。 【忌】同肾虚。 【宜】同肾虚，加：侧柏叶、阿胶、茅根、韭白、干地黄、戎盐、蒲黄。 52、伤精白浊，属房劳过度，以致精伤流出，似白浊证。 【忌】利小便、燥、辛热。诸药俱见前。 【宜】同肾虚。 53、五淋，属肾虚兼有湿热。 【忌】同肾虚。 【宜】同肾虚，加清湿热。茯苓、黄檗、车前子、石斛、萆薢、薏苡仁。 54、精塞水窍不通，属房欲不竟，或思欲不遂，或惧泄忍精，或老人气不足以送精出窍。 【忌】破气、下、利小便、燥热。诸药俱见前。 【宜】行败精，壮实人宜兼泄火。老人宜兼补气血。外治用吮法。牛膝、生地黄、当归、桃仁、红花、车前子、鹿角霜。 55、齿浮、真牙摇动，及下龈软或齿衄，属肾虚有热。 【忌】同肾虚，又忌当归、芎。 【宜】益阴、凉血、固肾。诸药略同肾虚，应以地黄、黄檗、五味子为君；桑椹、牛膝、沙苑蒺藜、鹿茸、天门冬为臣；龙骨、牡蛎为使。 56、下消，属肾阴虚，火伏下焦。 【忌】同肾虚。 【宜】清热，及峻补真气、润、酸敛。诸药同肾虚，宜以黄檗、五味子、生地黄、天麦门冬、人参为君；石斛、牛膝、知母、人乳、童便为臣；地骨皮、青蒿、侧柏叶为佐。 57、善恐，属肾气虚。肾藏志故也。 【忌】破气、苦寒。诸药俱见前。 【宜】补气强志、辛平、甘温、佐以辛香。人参、远志、茯苓、鹿茸、酸枣仁、柏子仁、石斛、沉水香。 58、阴窍漏气，属肾气虚不固。肾主纳气，虚则不能纳，故见是证。 【忌】破气、降、香燥、辛热。苏子、郁金、降香、沉水香、橘皮、通草（已上降）。白豆蔻、木香、香附（已上香燥）。馀忌药俱见前。 【宜】补真气、酸敛、固涩。人参、五味子、山茱萸、沙苑蒺藜、覆盆子、枸杞子、益智子、远志、龙骨、牡蛎、金樱子、莲须。参用肾虚条内诸药。 59、疝，属肾虚，寒湿邪乘虚客之所致。丹溪谓与肾经绝无相干者，误也。又有先因湿邪为病，后成湿热者，药宜分寒热、先后二途。 【忌】升、破气、苦寒、湿润。诸药俱见前。 【宜】补气、通肾气、除湿。又有阴虚有热之人病此，兼宜除热。人参、黄耆、橘核、合欢子、荔枝核、川楝子、牛膝、木瓜、杜仲、萆薢、巴戟天。虚寒而痛，加：桂、蘹香、补骨脂、仙茅。虚热而痛，加：黄檗、车前子。湿盛者，加：术。 60、奔豚，属肾虚，脾家湿邪下传客肾所致。 【忌】同疝，兼忌燥。诸药俱见前。 【宜】补气、健脾、辛温、散结。人参、薯蓣、桂、山茱萸、牛膝、蘹香、蛇床子。参用东垣奔豚丸治之。 61、命门虚（四证） 即元阳真火不足。 【忌】下泄、破气、发散、辛寒、苦寒、淡渗、燥、补肾水苦寒药。黄檗、知母、生地黄、天门冬（已上补肾水苦寒药）。馀药俱见前。 【宜】益真阳之气、甘温、咸温、甘热、酸敛。人参、红铅、人胞、鹿茸、白胶、肉苁蓉、菟丝子、枸杞子、覆盆子、五味子、巴戟天、山茱萸、附子、补骨脂、仙茅、阳起石。 62、阴痿，属命门火衰，下焦虚寒。 【忌】同命门虚。 【宜】同命门虚，加：海狗肾、天雄、蛇床子、原蚕蛾、狗阴茎、雀卵、牛膝、白马阴茎。 63、精寒、精薄，属命门火衰，阳气不足。忌、宜俱同阴痿。 64、肾泄，即五更及黎明泄泻者是也。亦名大瘕泄。属命门真火不足。 【忌】同命门虚。 【宜】益气、甘温、酸敛。人参、薯蓣、莲肉、肉豆蔻、砂仁、补骨脂、木香、吴茱萸、五味子。 65、畏寒足冷。忌、宜俱同命门虚。 66、小肠虚（一证） 【忌】破气、辛散、燥热。诸药俱见前。 【宜】补气、甘温、酸温。人参、黄耆、麦门冬、五味子、山茱萸。 遗尿，属小肠虚，兼肾气虚。 【忌】同小肠虚。 【宜】同小肠虚，兼固涩。牡蛎、益智子、龙骨、金樱子。 67、胆虚（二证） 【忌】汗、吐、下、苦寒、破气、燥。山栀、瓜蒂、藜芦、盐汤、常山（已上吐）。馀忌药俱见前。 【宜】甘温、甘平、酸敛，佐以微辛。人参、当归、谷精草、决明子、木贼草、甘草、竹叶、竹茹、白芍药、酸枣仁。 68、易惊，属胆气虚。 【忌】破气、升发、燥热。诸药俱见前。 【宜】补胆气、甘温、辛温、酸平。人参、酸枣仁、甘草、竹叶、当归、白芍药、竹茹、橘皮。 69、病后不得眠，属胆虚。忌、宜俱同胆虚。 70、胃虚（七证） 【忌】下、破气、苦寒、燥热。诸药俱见前。 【宜】益气、甘平、甘淡、酸。人参、白术、白扁豆、莲肉、石斛、橘皮、白茯苓、木瓜、白芍药。兼寒加：生姜、白豆蔻、缩砂蜜。兼热加：竹茹、枇杷叶、麦门冬、芦根汁、蔗浆。 71、胃弱不纳食及不思饮食。 【忌】同胃虚。 【宜】同胃虚，仍分寒热治。 72、胃虚呕吐，宜分寒热。忌、宜俱同胃虚。 73、霍乱转筋，属胃虚，猝中邪恶气及毒气，兼有停滞所致。（转筋与肝经血虚不同。） 【忌】闭气、滞腻、收敛、温补、大热。诸药俱见前。 【宜】调气和中、辛散、消导。由于暑，必口渴，或口干、齿燥、口苦、小便短赤：白梅、白扁豆并叶、丝瓜叶、滑石、石膏、甘草、橘皮、香薷、木瓜、石斛、童溺、食盐、泥浆、缩砂蜜、厚朴。由于寒，则小水清白，不渴不热：缩砂蜜、丁香、橘皮、藿香。甚者加：吴茱萸、肉桂。外治用杉木、楠材，煎汤浸洗。 74、绞肠痧，属胃气虚，猝中天地邪恶秽污之气，郁于胸腹间，上不得吐，下不得泻，以致肠胃绞痛异常，胸腹骤胀，遍体紫黑，头顶心必有红发，急寻出拔去之，急以三棱鑱针刺委中，挤出热血，可立苏。次用新汲凉水，投入盐两许，恣饮，得吐泻即止。委中穴在两膝下湾横纹中间，两筋之中，刺入一分。 【忌】温补、敛。诸药俱见前，切忌火酒、生姜、蒜及谷气、米饮、热汤，入口即死。 【宜】通窍辟恶、辛散、咸寒。龙脑香、苏合香、藿香、檀香、乳香、芒硝、童便。煎药亦宜冷服。 75、中恶腹中㽲痛，属胃气虚，恶气客之所致。 【忌】补、酸敛。诸药俱见前。 【宜】辟恶气、通畅胃气、辛散。龙脑香、檀香、麝香（孕妇忌用）、牛黄、乳香、苏合香、丹砂、雄黄、鬼臼、藿香、橘皮、木香、沉水香、白豆蔻、远志、石菖蒲、干姜、桂。 76、反胃，属胃气虚。 【忌】破气、升、苦寒、甘、燥热。诸药俱见前。 【宜】补气、降气、和胃、清热、酸敛以制肝。人参、苏子、橘皮、枇杷叶、木瓜、竹茹、麦门冬、芦根汁、石斛、白茯苓、白芍药、梅酱、蔗浆。若因虚寒而得者，加：生姜、术、白豆蔻。 77、中酒，属胃弱。 【忌】闭气、升、甘温、燥热、收涩。诸药俱见前。 【宜】养胃、酸、辛散、淡渗。人参、麦门冬、白扁豆、葛花、五味子、梅酱、橘皮、白豆蔻、黄连、缩砂蜜、白茯苓、泽泻。 78、大肠虚（四证） 【忌】破气、下、燥、热。诸药俱见前。 【宜】补气、润燥、甘温。人参、黄耆、麦门冬、五味子、白芍药、炙甘草。 79、虚热便闭不通，属血虚，津液不足。 【忌】破气、下、燥热、苦温、损津液。郁李仁（损津液）。馀忌药俱见前。 【宜】生津液、润燥、凉血、益血。五味子、麦门冬、芝麻、麻仁、生蜜、天门冬、肉苁蓉、生地黄、当归、芦荟、炙甘草。 80、虚寒滑泄不禁，属气虚。 【忌】破气、下、湿润、苦寒。诸药俱见前。 【宜】补气、升、甘温、酸敛。人参、黄耆、白术、莲肉、升麻、炙甘草、吴茱萸、肉豆蔻、补骨脂、五味子、木瓜、赤石脂。 81、肠鸣，属气虚。 【忌】破气、下、苦寒。诸药俱见前。 【宜】同大肠虚，加升麻、柴胡以佐之。 82、脱肛，属气虚，兼有湿热。 【忌】同大肠虚。 【宜】补气、升提、除湿热。人参、黄耆、炙甘草、白术、莲肉、白扁豆、升麻、干葛、柴胡、黄檗、防风、黄连、黄芩、樗根白皮、白芍药。外用五倍子傅之。 83、膀胱虚（三证） 【忌】破气、燥、利小便。诸药俱见前。 【宜】补气、酸敛。人参、五味子、山茱萸、益智子、金樱子。 84、小便不禁，属气血虚。 【忌】降下、湿润、燥热。诸药俱见前。 【宜】同膀胱虚，加：牡蛎、龙骨、鹿茸、桑螵蛸、鸡䏶胵。频数不能少忍，加：麦门冬、五味子、黄檗、山茱萸、天门冬、鳖甲、牛膝、柏子仁、甘枸杞子。 85、遗尿，属本经气虚，见小肠虚条内。因膀胱虚亦能致遗尿，故复列此。忌、宜俱见小肠虚。 86、膀胱气。忌、宜俱同疝。 87、三焦虚（二证） 【忌】破气、降、复忌升发、苦寒。诸药俱见前。 【宜】补中益气，佐以辛温。人参、黄耆、白术、益智子、沉香、五味子。 88、腹寒，属中气虚。忌、宜俱同三焦虚。 89、短气、少气，属气虚。 【忌】同三焦虚。 【宜】补气益精、甘温、甘寒、酸温。人参、黄耆、麦门冬、五味子。 90、心实（五证） 即实火实热。 【忌】补敛、升、热、温燥。诸药俱见前。 【宜】降火清热，苦寒以折之，辛寒以散之，甘寒以缓之，咸寒以润之。黄连、犀角、石膏、丹砂、牡丹皮、滑石、生甘草、麦门冬、竹叶、童便。大便结燥，加：芒硝、大黄。发狂亦如之。 91、谵语，属心家邪热。忌、宜俱同心实。 92、舌破，属心火。忌、宜俱同心实。 93、烦躁，属心家邪热及心火内炎。烦属心，躁属肾。忌、宜俱同心实。 94、自笑，属心家有热邪。忌、宜俱同心实。 95、发狂，属心家有邪热甚。忌、宜俱同心实。 96、肝实（五证） 【忌】补气、升、酸敛、辛热、辛温、燥。诸药俱见前。 【宜】清热降气、苦寒、辛寒、甘寒、酸寒。橘皮、青皮、苏子、黄连、黄芩、龙胆草、柴胡、生甘草、赤芍药、竹叶、青黛。 97、善怒，怒则气上逆，甚则呕血及飧泄。 【忌】补、升、热、燥、闭气。诸药俱见前。 【宜】降气、清热、甘寒、酸寒、咸寒，佐以辛散。苏子、郁金、番降香、生甘草、青黛、麦冬、生地黄、赤芍药、橘皮、蒲黄、当归、延胡索、砂仁、香附、童便。 987、善太息，忽忽不乐。忌、宜俱同善怒。 99、胁痛呕血，属肝气逆，肝火盛，肝血虚。忌、宜俱同善怒。 100、发搐，属肝家邪热，热则生风，风主掉眩故也。 【忌】同善怒。 【宜】清热、降气、利小便、缓中。生地黄、白芍药、黄连、丹砂、羚羊角、童便、苏子、麦门冬、生甘草、竹叶、甘菊花、白茯苓、木通。 101、目赤肿痛，属血热。 【忌】同肝实善怒。 【宜】凉血清热、甘寒、苦寒、酸寒。生地黄、赤芍药、甘草、甘菊、谷精草、蜜蒙花、荆芥、黄檗、大黄、黄连、连翘、玄参、山栀、竹叶、龙胆草、空青、曾青、木通、童便。外治：铜青、芒硝、石胆、蕤核。急者宜以三棱针刺破眼眶肿处，捋出热血，立解。迟则血贯瞳人，目损矣。 102、脾实（六证） 即湿热邪胜。 【忌】湿润、收涩、滞腻、热、咸、甘。诸药俱见前。 【宜】除湿清热、利小便、辛散、风燥、苦寒。术、山栀、猪苓、泽泻、滑石、车前子、茯苓、白豆蔻、防风、干葛、黄连、枳实。 103、蛊胀，由于脾家湿热积滞，或内伤瘀血停积而成。 【忌】补气、甘温、燥热。诸药俱见前。 【宜】除湿、清热、利小便、消积。木通、防己、车前子、猪苓、泽泻、茯苓、葶苈、乌蠡鱼、桑白皮、山查、红曲、三棱、蓬术。 104、易饥，属脾家邪火。 【忌】升、辛易、大热、香燥。沉香、麝香、龙脑、缩砂蜜、豆蔻、藿香（已上香燥）。馀忌药俱见前。 【宜】清火除热、生津液、益脾阴、甘寒、苦寒、酸寒。黄连、青黛、连翘、山栀、石膏、竹叶、麦冬、石斛、白芍药、酸枣仁。 105、口唇生疮。 【忌】温燥、热。诸药俱见前。 【宜】甘寒、酸寒、苦寒、辛寒。麦门冬、生地黄、甘草、白芍药、乌梅、黄连、黄檗、玄参、连翘、栝楼根、干葛、石膏、龙胆草、大青、竹叶。 106、口糜。忌、宜俱同口唇生疮。 107、中消，属脾家实火。 【忌】破气、下、温燥、热。诸药俱见前。 【宜】服诸药同口唇生疮，加人参。 108、湿热腹痛，按之愈甚。 【忌】闷气、酸敛、温热、燥。诸药俱见前。 【宜】利小便，兼升提、苦寒。滑石、车前子、木通、黄连、黄芩、升麻、柴胡、葛根、防风。不愈加熟大黄，即 “土郁则夺之” 之义也。 109、肺实（八证） 【忌】敛涩、补气、升、燥热、酸、咸。诸药俱见前。 【宜】降气、润、甘寒、苦寒，佐以辛散。苏子、枇杷叶、桑白皮、天门冬、贝母、栝楼根、杏仁、白前、前胡、知母、车前子、桑黄、石膏、黄芩。 110、喘急，属肺有实热，及肺气上逆。 【忌】同肺实。 【宜】同肺实，加：桔梗、甘草、栝楼仁、玄参、青黛。 111、气壅，属肺热气逆。忌、宜俱同肺实。 112、声重痰稠，属肺热。 【忌】同肺实。 【宜】同肺实，加：薄荷、竹沥。 113、肺痈，属肺热极。 【忌】同肺实。 【宜】清热、消痰、降火、解毒散结、甘寒、辛寒。桑白皮、桑黄、黄芩、贝母、栝楼根、薏苡仁、蕺菜、虎耳草、鼠粘子、连翘、甘草、败酱草、百年腌芥菜汁。 114、肺胀闷，属肺热。 【忌】同肺实。 【宜】同肺实，并参用肺痈诸药。 115、吐脓血、血痰，咳嗽嗽血，属肺家火实热甚。此正 “邪气胜则实” 之谓。 【忌】同肺实。 【宜】清热降气、凉血、豁痰。童便、苏子、枇杷叶、桑白皮、麦门冬、剪草、蒲黄、生地黄、天门冬、百部、桑黄、百合、薏苡仁、甘草、贝母、白芍药、白及、梧梗、款冬花、紫菀。 116、喉癣，属肺热。 【忌】同肺热。 【宜】同肺实，加：鼠粘子、玄参、射干。 117、上消，属肺家实火，及上焦热。 【忌】同肺实。 【宜】降气、清热、补肺、生津、甘寒、苦寒、酸寒、辛寒。苏子、麦门冬、枇杷叶、桑白皮、桔梗、百部、百合、黄芩、天门冬、沙参、黄连、栝楼根、葛根、知母、玄参、石膏、甘草、五味子、白芍药、䈽竹叶、芦根、冬瓜、人乳、天酒。 118、肾无实，故无泻法。 119、命门实（二证） 【忌】补气、温、热。诸药俱见前。 【宜】苦寒、甘寒、咸寒。黄檗、知母、玄参、天门冬、麦门冬、牡丹皮、车前子、木通、泽泻。 120、强阳不倒，属命门火实，孤阳无阴所致。此证多不治。 【忌】同命门实。 【宜】同命门实，加：五味子、童便、生地黄。 121、水窍涩痛，属命门实火。 【忌】同命门实。 【宜】清热、利窍、甘寒、苦寒、咸寒，佐以淡渗。黄檗、知母、车前子、生地黄、天门冬、生甘草、黄芩、牛膝、麦门冬、童便、茯苓、木通。 122、小肠实（一证） 【忌】敛涩、补气。诸药俱见前。 【宜】通利、淡渗、苦寒、甘寒、咸寒。车前子、白茯苓、木通、生甘草、黄檗、知母、黄芩、黄连、牛膝、麦门冬、生地黄、童溺。 小水不利，及赤、或涩痛尿血。忌、宜俱同小肠实。 123、胆实（二证） 【忌】汗、吐、下。诸药俱见前。 【宜】和解、辛寒、甘寒、苦寒、辛温。柴胡、黄芩、半夏、生姜、甘草、橘皮、龙胆草。 124、口苦耳聋胁痛，往来寒热。 【忌】同胆实。 【宜】用仲景小柴胡汤，随所见兼证加减。 125、鼻渊，属胆移热于脑。 【忌】辛温、燥、热。诸药俱见前。 【宜】清热、补脑、甘寒、甘平、佐以辛寒。天门冬、甘菊花、生地黄、沙苑蒺藜、山茱萸、沙参、薄荷、柴胡、辛夷、黄芩、玄参、知母。 126、胃实（六证） 【忌】升、补敛、辛温、燥、热、湿润。诸药俱见前。 【宜】下。如邪未结，宜清热发散、苦寒、辛寒、甘寒。大黄、枳实、知母、石膏、葛根、竹叶、大青、小青、青黛、麦冬、甘草。 127、谵语发狂、发斑，弃衣而走，登高而歌，属胃家邪热实。 【忌】同胃实。 【宜】同胃实。如大便结者，加芒硝，亟下之；发斑者，加鼠粘子、玄参、栝楼根，多用石膏为君。便结亦加大黄下之。 128、口臭，数欲饮食，属胃火。 【忌】同胃实。 【宜】清热降火、苦寒、甘寒、辛寒。黄连、青黛、连翘、麦门冬、石斛、芦根汁、竹叶、石膏。 129、嘈杂，属胃火。 【忌】同口臭。 【宜】同口臭，略兼消导。山查、麦芽、橘红、神曲。 130、口淡，属胃热。忌、宜俱同口臭。 131、呕吐，属胃火者，必面赤，小便短赤或涩，大便多燥，口苦或干渴。 【忌】同胃实。 【宜】同胃实，加：枇杷叶、竹茹、木瓜、芦根、橘皮、通草、白茯苓。 132、吞酸，属胃火。 【忌】同胃实。 【宜】同嘈杂。 133、大肠实（四证） 【忌】补敛、燥、热。诸药俱见前。 【宜】润下、苦寒、辛寒。生地黄、麻仁、桃仁、黄连、黄芩、槐花、大黄、石膏、知母、枳壳。 134、便硬闭。 【忌】同大肠实。 【宜】同大肠实，加：芒硝、猪胆、槟榔、郁李仁、石蜜。 135、肠风下血，属大肠湿热。 【忌】下、燥、热。诸药俱见前。 【宜】清热凉血、兼升、甘寒、苦寒。生地黄、槐花、地榆、黄连、黄芩、荆芥、防风、甘草、红曲、白芍药、侧柏叶、白头翁、蒲黄、鸡子、葛谷。 136、脏毒，属血热。 【忌】同肠风下血。 【宜】同肠风下血，加：忍冬、麦门冬、倍加地榆、蒲黄。 137、肠痈，属大肠实火。 【忌】同肠风下血。 【宜】下、苦寒、解毒。大黄、白药子、白芷、白及、白敛、连翘、忍冬藤、天明精、甘草、黄耆、生地黄、明矾、黄蜡、生蜜（已上三味作丸）。 138、膀胱实（一证） 【忌】燥、热、收涩。诸药俱见前。 【宜】润、淡渗。知母、黄檗、车前子、木通、瞿麦、滑石、茯苓、猪苓、泽泻。 癃闭，属膀胱实热。 【忌】破气、发散、燥、热。如属水液不足，兼忌利小便。诸药俱见前。 【宜】同膀胱实，佐以升提。升麻、柴胡。 139、三焦实（三证） 【忌】补敛、升、燥热。诸药俱见前。 【宜】降、清热、调气、甘寒、苦寒、咸寒。苏子、麦门冬、知母、黄檗、玄参、山栀、黄芩、黄连、童便。 140、喉痹，即缠喉风。属少阳相火、少阴君火并炽。《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也。一阳者，少阳相火也。 【忌】同三焦实。 【宜】辛散，佐以苦寒、咸寒。急则有针法、吹法、吐法。鼠粘子、山豆根、射干、黄连、黄檗、知母、玄参、童便、苏子、麦门冬、贝母、甘草、生犀角、山慈菇、苦桔梗、续随子。急治用胆矾、朴硝、牛黄为末，和匀吹入喉中。又法：用明矾三钱、巴豆七粒去壳，同矾煅，矾枯，去巴豆，即取矾为细末，吹入喉中，流出热涎即宽。 141、头面赤热，属上焦火升。 【忌】同三焦实。 【宜】降、清热、甘缓，佐以酸敛。苏子、枇杷叶、天门冬、麦门冬、玄参、薄荷、栝楼根、梨、柿、蔗、童便、白芍药、五味子。 142、赤白游风，属血热，热则生风，故善游走，俗名火丹。小儿多患此，大人亦时有之。 【忌】同三焦实。 【宜】清热、凉血，兼行血、辛寒、甘寒、苦寒、咸寒。生地黄、黄连、黄檗、生甘草、牡丹皮、蒲黄、红蓝花、连翘、玄参、鼠粘子、牛膝、蓝汁、苎根、童便、赤芍药。宜兼外治，砭出热血，及用漆姑草、慎火草捣烂敷之，即易愈。', '2024-12-23T02:38:53.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d0PDBuKgLXR', 1, '{"title":"卷之二_续序例下_六淫门","description":"<p>1、风（四证）</p>\n<p>诸暴强直，支痛软戾，里急筋缩，皆属于风。</p><p>2、真中风，猝僵仆，口噤不言，不省人事。如遗尿，直视，口开，手撒，汗出如珠，属不治证。西北高寒之地有之，东南无。</p>\n<p>【忌】破气、下、吐、苦寒、酸敛。诸药俱见前。</p>\n<p>【宜】辛甘发散、峻补真气。桂枝、附子、甘草、独活、羌活、天麻、麻黄、防风、芎、细辛、藁本、蔓荆实、牛黄、辛夷、牡荆实、白芷、人参、黄耆。有痰加：竹沥、南星、半夏、姜汁。</p><p>3、类中风，口眼歪斜，语言謇涩，半身不遂，口噤不言，四肢不举，痰涎壅盛，昏眊不省人事。</p>\n<p>【忌】汗、吐、下，大忌破气、温热、苦寒，及一切治风湿辛燥发散，并开窍走真气、行血诸药，慎勿犯之，犯之则轻必重，重必毙。麝香、苏合香、檀香、龙脑香、安息香（已上开窍走真气）。馀忌药俱见前。</p>\n<p>【宜】滋补，阳虚者补气，阴虚者补血，阴阳两虚则气血双补，兼宜清热、降气、豁痰，及保脾胃。天门冬（脾胃薄弱者勿多用）、麦门冬、荆沥、苏子、栝楼根、贝母、橘红、枇杷叶、甘草、竹沥、童便、霞天膏、梨汁、黄檗。次益血，于前药中加：胡麻仁、石斛、牛膝、生地黄、五味子、甘菊花、枸杞子、何首乌、薯蓣、菟丝子、白芍药、丹参、山茱萸、白蒺藜、酸枣仁、柏子仁、车前子、竹叶、羚羊角、鳖甲、木瓜、青蒿、远志、栝楼仁、沙参、巴戟天、茯苓、茯神。如便闭，加：肉苁蓉、当归，倍麻仁。如兼气虚，加人参、黄耆。有肺热者勿入人参。</p><p>4、感冒风寒，俗名伤风。其证或头疼身热，轻者则否，鼻必塞，兼流清涕，必恶风寒，或声重，或声哑，甚者痰壅气喘咳嗽。</p>\n<p>【忌】补气、酸敛、闭气。诸药俱见前。</p>\n<p>【宜】发散、辛甘、温。芎、细辛、藁本、防风、甘草、荆芥、白芷、前胡、桑白皮、桔梗、紫苏、薄荷、杏仁、石膏。</p><p>5、伤风热。</p>\n<p>【忌】同感冒风寒。</p>\n<p>【宜】辛寒、甘寒、发散。石膏、知母、甘草、竹叶、麦门冬、前胡、桔梗、薄荷、葛根、桑白皮。久而不愈者属虚。阳虚者加人参、黄耆；阴虚者，加五味子、地黄，倍门冬、白芍药。</p><p>6、寒（二证）</p>\n<p>诸病上下所出水液，澄澈清冷，癥瘕㿗疝坚痞，腹满急痛，下利清白，食已不饥，吐利腥秽，屈伸不便，厥逆禁固，皆属于寒。凡中寒，必本于阳虚。</p>\n<p>【忌】破气、苦寒、下、甘寒、辛寒。诸药俱见前。</p>\n<p>【宜】补气、散寒、辛甘、温热，轻者解表，重者温补。桂枝、干姜、麻黄、人参、附子、黄耆。</p><p>7、中寒，忌宜同前。</p><p>8、伤寒，冬月即病，宜从仲景法。</p><p>9、伤寒，太阳病、阳明病、少阳病、三阳合病、食、愈后劳复食复女劳复明阳易。冬月即病，宜从仲景冶法。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001042,"no":41}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '1、风（四证） 诸暴强直，支痛软戾，里急筋缩，皆属于风。 2、真中风，猝僵仆，口噤不言，不省人事。如遗尿，直视，口开，手撒，汗出如珠，属不治证。西北高寒之地有之，东南无。 【忌】破气、下、吐、苦寒、酸敛。诸药俱见前。 【宜】辛甘发散、峻补真气。桂枝、附子、甘草、独活、羌活、天麻、麻黄、防风、芎、细辛、藁本、蔓荆实、牛黄、辛夷、牡荆实、白芷、人参、黄耆。有痰加：竹沥、南星、半夏、姜汁。 3、类中风，口眼歪斜，语言謇涩，半身不遂，口噤不言，四肢不举，痰涎壅盛，昏眊不省人事。 【忌】汗、吐、下，大忌破气、温热、苦寒，及一切治风湿辛燥发散，并开窍走真气、行血诸药，慎勿犯之，犯之则轻必重，重必毙。麝香、苏合香、檀香、龙脑香、安息香（已上开窍走真气）。馀忌药俱见前。 【宜】滋补，阳虚者补气，阴虚者补血，阴阳两虚则气血双补，兼宜清热、降气、豁痰，及保脾胃。天门冬（脾胃薄弱者勿多用）、麦门冬、荆沥、苏子、栝楼根、贝母、橘红、枇杷叶、甘草、竹沥、童便、霞天膏、梨汁、黄檗。次益血，于前药中加：胡麻仁、石斛、牛膝、生地黄、五味子、甘菊花、枸杞子、何首乌、薯蓣、菟丝子、白芍药、丹参、山茱萸、白蒺藜、酸枣仁、柏子仁、车前子、竹叶、羚羊角、鳖甲、木瓜、青蒿、远志、栝楼仁、沙参、巴戟天、茯苓、茯神。如便闭，加：肉苁蓉、当归，倍麻仁。如兼气虚，加人参、黄耆。有肺热者勿入人参。 4、感冒风寒，俗名伤风。其证或头疼身热，轻者则否，鼻必塞，兼流清涕，必恶风寒，或声重，或声哑，甚者痰壅气喘咳嗽。 【忌】补气、酸敛、闭气。诸药俱见前。 【宜】发散、辛甘、温。芎、细辛、藁本、防风、甘草、荆芥、白芷、前胡、桑白皮、桔梗、紫苏、薄荷、杏仁、石膏。 5、伤风热。 【忌】同感冒风寒。 【宜】辛寒、甘寒、发散。石膏、知母、甘草、竹叶、麦门冬、前胡、桔梗、薄荷、葛根、桑白皮。久而不愈者属虚。阳虚者加人参、黄耆；阴虚者，加五味子、地黄，倍门冬、白芍药。 6、寒（二证） 诸病上下所出水液，澄澈清冷，癥瘕㿗疝坚痞，腹满急痛，下利清白，食已不饥，吐利腥秽，屈伸不便，厥逆禁固，皆属于寒。凡中寒，必本于阳虚。 【忌】破气、苦寒、下、甘寒、辛寒。诸药俱见前。 【宜】补气、散寒、辛甘、温热，轻者解表，重者温补。桂枝、干姜、麻黄、人参、附子、黄耆。 7、中寒，忌宜同前。 8、伤寒，冬月即病，宜从仲景法。 9、伤寒，太阳病、阳明病、少阳病、三阳合病、食、愈后劳复食复女劳复明阳易。冬月即病，宜从仲景冶法。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oZrDIippIjy', 1, '{"title":"卷之二_续序例下_论伤寒古今时地不同，因之六经治法宜异","description":"<p>     夫伤寒者，大病也。时者，圣人所不能违者也。以关乎死生之大病，而药不从时，顾不殆哉！仲景，医门之圣也。其立法造论，后之明师，如华佗、孙思邈辈，莫不宗之。汉末去古未远，风景犹厚，形多壮伟，气尚敦厖。其药大都为北方感寒即病而设。况南北地殊，厚薄不侔，故其意可师也，其法不可改也。循至今时，千有余年，风气浇矣，人物脆矣。况在荆、扬、交、广、梁、益之地，与北土全别，故其药则有时而可改。非违仲景也，实师其意，变而通之，以从时也。如是则法不终穷矣，故作斯议，条列其方，稍为损益，以从时地。俾后之医师，知所适从，庶几患斯疾者，可免于夭枉尔！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001043,"no":42}}', '2024-12-23T04:00:23.000Z', '2024-12-23T04:00:23.000Z', '2024-12-23T04:00:23.000Z', '夫伤寒者，大病也。时者，圣人所不能违者也。以关乎死生之大病，而药不从时，顾不殆哉！仲景，医门之圣也。其立法造论，后之明师，如华佗、孙思邈辈，莫不宗之。汉末去古未远，风景犹厚，形多壮伟，气尚敦厖。其药大都为北方感寒即病而设。况南北地殊，厚薄不侔，故其意可师也，其法不可改也。循至今时，千有余年，风气浇矣，人物脆矣。况在荆、扬、交、广、梁、益之地，与北土全别，故其药则有时而可改。非违仲景也，实师其意，变而通之，以从时也。如是则法不终穷矣，故作斯议，条列其方，稍为损益，以从时地。俾后之医师，知所适从，庶几患斯疾者，可免于夭枉尔！', '2024-12-23T04:00:23.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VZ6HjEbNrN8', 1, '{"title":"卷之二_续序例下_辨验外感真伪法","description":"<p>       凡外感必头疼。其疼也，不间昼夜。探其舌本，必从喉咙内干出于外，多兼烦躁。不烦躁者，即轻证也。不头疼而发热，不发热而头疼，头虽疼而有时暂止，口虽干而舌本不燥，骨虽疼而头不疼，虽渴而不欲引饮，至夜或偶得寐，遇食不好亦不恶，居处虽若尪怯，而神气安静。凡若此者，皆非伤寒也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001044,"no":43}}', '2024-12-23T04:01:07.000Z', '2024-12-23T04:01:07.000Z', '2024-12-23T04:01:07.000Z', '凡外感必头疼。其疼也，不间昼夜。探其舌本，必从喉咙内干出于外，多兼烦躁。不烦躁者，即轻证也。不头疼而发热，不发热而头疼，头虽疼而有时暂止，口虽干而舌本不燥，骨虽疼而头不疼，虽渴而不欲引饮，至夜或偶得寐，遇食不好亦不恶，居处虽若尪怯，而神气安静。凡若此者，皆非伤寒也。', '2024-12-23T04:01:07.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Il7ZOmChJB3', 1, '{"title":"卷之二_续序例下_三阳治法总要","description":"<p>1、太阳病其证发热，恶寒恶风，头痛项强，腰脊强，遍身骨痛，脉虽浮洪而不数，多不传经。烦躁脉数急者，是欲传经。宜先发汗以解表邪。</p><p>2、其药以羌活汤为主：羌活（三钱）、前胡（二钱）、甘草（八分）、葛根（二钱）、生姜（三片）、枣（二枚）、杏仁（九粒，去皮，研烂）</p>\n<p>水煎服。秋深冬月应用此方，亦可量加紫苏、葱白。如冬月天气严寒，感邪即病，服此方不得汗，本方加麻黄（一钱），生姜（四片），共前（七片），得汗，勿再服。</p><p>3、如病人自觉烦躁，喜就清凉，不喜就热，兼口渴，即欲传入阳明也。若外证头疼，遍身骨疼不解，或带口渴、鼻干、目疼、不得卧，即系太阳阳明证。羌活汤中加石膏、知母、麦冬，大剂与之，得汗即解。</p><p>4、如自汗烦躁，头疼、遍身骨疼不解者，羌活（一钱），桂枝（七分），石膏（一两二钱），麦冬（六钱），知母（三钱），竹叶（一百二十片），白芍药（二钱），甘草（八分）。</p><p>5、如冬月即病太阳证，恶寒、畏风、头疼、遍身骨疼、自汗、不渴，宜用桂枝（八分），芍药（二钱），甘草（一钱），大枣（二枚），生姜（一片）。</p><p>6、太阳病不解，热结膀胱，其人如狂，血自下，下之愈。其外证不解者，不可下，当先解表。表证罢，少腹急结者，乃可下之，桃仁承气汤。无蓄血证，大承气汤。</p><p>7、正阳阳明病</p>\n<p>正阳阳明者，胃家实热是也。其证不大便，自汗，潮热，口渴，咽干，鼻干，呕或干呕，目眴眴不得眠，畏人声、畏木声、畏火，不恶寒反恶热，或先恶寒不久旋发热，甚则谵语狂乱，循衣摸床，脉洪大而长。宜急解其表，用竹叶石膏汤，大剂与之。不呕，无汗，与葛根汤，亦须大剂。若表证已罢，脉缓，小便利，是病解矣。</p><p>8、若表证罢后，邪结于里，大便闭，小便短赤，宜用调胃承气汤或小承气汤下之。下后，按其腹中不作痛而和，病即已解。如作痛，是燥粪未尽也。再用前药下之。以腹中和，二便通利为度。</p><p>9、阳明病，不能食。若其人本虚，勿轻议下。</p><p>10、阳明病，头眩，咳而咽痛者，用葛根、甘草、桔梗、麦冬四味浓煎，数数与之。阳明病无汗，小便不利，心中懊憹者，当发黄。急用栀子、麦冬、淡豆豉，大剂浓煎与之。如已见身黄，急加茵陈为君主之。</p><p>11、阳明病衄血，此缘失于发汗，宜用荆芥（二钱），葛根（三钱），麦门冬（五钱），牡丹皮（一钱五分），蒲黄（二钱），茅根（二两），侧柏叶（二钱），生地黄（三钱），浓煎与之，兼饮童便。阳明病心下硬满者，此邪未入于腹中，慎勿下之。用竹叶石膏汤，加栝楼（一个，捣碎），桔梗（二钱），黄连（一钱）。</p><p>12、阳明病邪结于里，汗出身重，短气，腹满而喘，潮热，手足濈然汗出者，此大便已硬也。六七日已来，宜下之，用小承气汤。不行，换大承气汤，勿大其剂。若大便不硬者，慎勿轻下。</p><p>13、阳明病发汗不解，腹满急者，亟下之。伤寒六七日，目中不了了，睛不和，无表证，大便难，宜承气汤下之。</p><p>14、阳明病，下之早，外有热，手足温，不结胸，心中懊憹不能食，但头汗出，栀子豉汤主之。</p><p>15、阳明病，发潮热，大便溏，胸满不去者，与小柴胡汤去人参，加栝楼、黄连。</p><p>16、阳明病自汗出，或发汗后，小便利，津液内竭，大便虽硬，不可攻之。须俟其自大便，或用蜜导、胆导法通之。大下后，六七日不大便，烦不解，腹满痛，本有宿食，宜再用承气汤下之。</p><p>17、食谷欲呕，属阳明，非少阳也。胸中烦热者，竹茹汤主之：竹茹（三钱），麦门冬（五钱），枇杷叶（三大片），芦根（三两）。内无热证者，小便利，口不渴，此为阳明虚也。吴茱萸汤主之。吴茱萸（二钱），人参（三钱），生姜（一钱五分），大枣（三枚），水煎，日三服。</p><p>18、凡阳明病多汗，津液外出，胃中燥，大便必硬，硬则谵语，以小承气汤下之。若一服谵语止者，勿再服。</p><p>19、阳明病谵语，发潮热，脉滑而数者，小承气汤主之。服药后腹中转气者，更与一服。若不转气者，勿更与之。若服药后次日不大便，脉反微涩者，里虚也，为难治。勿复议下。</p><p>20、阳明病，下血谵语者，此为热入血室，汗止在头。用荆芥（三钱），葛根（三钱），黄芩（一钱五分），麦冬（五钱），牡丹皮（一钱五分），生蒲黄（二钱），浓煎，以童便对饮之。</p><p>21、阳阳明病脉浮紧，咽燥口苦，腹满而喘，发热汗出，恶热身重。若下之，则胃中空虚，客气动膈，心中懊憹，舌上有胎者，栀子豉汤主之。若渴欲饮水，舌燥者，白虎汤加人参主之，若脉浮，发热口渴，小便不利者，猪苓汤主之。</p><p>22、阳明病，协热下利者，宜六一散。心下痞者，以黄连栝楼汤调服之。脉浮迟，表热里寒，下利清谷者，四逆汤主之：附子、干姜、甘草。趺阳脉浮而涩，小便数，大便硬，其脾为约，麻子仁丸主之。麻仁（十三两），芍药（四两），枳实（四两），大黄（八两），厚朴（三两），杏仁（六两），蜜丸如梧子大，每用十丸，日三服。</p><p>23、阳明实则谵语，虚则郑声。郑声者，重语也。直视、谵语、喘满者死。下利者亦死。发汗多，若重发其汗，谵语脉短者死；脉和者，不死。若吐、若下后不解，不大便五六日，或至十余日，日晡时发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣妄撮，惕而不安，微喘直视，脉弦者生，涩者死（涩者阳证见阴脉也）。微者但发热谵语者，大承气汤下之。利，勿再服。</p><p>24、阳明病发狂，弃衣而走，登高而歌，此阳明实也。以承气汤亟下之。如便不结者，大剂白虎汤灌之。石膏（四两），麦冬（二两），知母（一两五钱），加大青（一两），甘草（七钱）。</p><p>25、太阳阳明病协热下利者，宜六一散，以黄连煎汤调服之。</p><p>26、太阳阳明并病六七日，表证仍在，其人发狂者，以热在下焦，少腹当硬满，小便自利，下其血乃愈，当用桃仁承气汤。</p><p>27、又二阳并病，太阳证罢，潮热，汗出，大便难，谵语者，宜大承气汤。</p><p>28、少阳病其证口苦，咽干，目眩，往来寒热，胸胁痛，胸满或痛，耳聋。脉法弦细。头痛发热者，属少阳。少阳不可发汗，发汗则谵语。胃和者，当自愈；不和者，则烦而悸。</p><p>29、伤寒三日，少阳脉小者，欲己也。</p><p>30、凡太阳病不解，传入少阳者，胁下硬满，干呕不能食，往来寒热，未经吐下，脉沉紧者，与小柴胡汤：柴胡（二钱四分），人参（九分），黄芩（九分），甘草（九分），半夏（一钱五分），生姜（九分），大枣（二枚），水煎，温服，日三。加减法：若胸中烦而不呕，去半夏、人参，加栝楼实（一枚）。若心下痞硬，去大枣，加牡蛎（二钱半）。若渴者，去半夏，加人参、栝楼根。若腹中痛者，去黄芩，加芍药（三钱）。若心下悸，小便不利者，去黄芩，加茯苓（二钱）。若不渴，外有微热者，去人参，加桂（一钱，夏勿用）。温覆，取微汗愈。若咳者，去人参、大枣，加五味子（一钱），少佐以干姜。</p><p>31、阳明少阳并病，必下利，脉滑而数，有宿食也。当承气汤下之。若吐、下、发汗、温针，谵语，柴胡汤证罢，此为坏病。知犯何逆，以法治之。</p><p>32、三阳合病，脉大上关上，但欲睡眠，目合则汗，药用百合（一两），麦门冬（五钱），炙甘草（一钱），知母（二钱），竹叶（五十片），栝楼根（二钱），鳖甲（如法三钱），白芍药（二钱）。</p><p>33、三阳合病，腹满身重，谵语遗尿，白虎汤加百合主之。</p><p>34、伤寒六七日，无大热，其人烦躁者，此以阳去入阴故也。</p><p>35、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001045,"no":44}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '1、太阳病其证发热，恶寒恶风，头痛项强，腰脊强，遍身骨痛，脉虽浮洪而不数，多不传经。烦躁脉数急者，是欲传经。宜先发汗以解表邪。 2、其药以羌活汤为主：羌活（三钱）、前胡（二钱）、甘草（八分）、葛根（二钱）、生姜（三片）、枣（二枚）、杏仁（九粒，去皮，研烂） 水煎服。秋深冬月应用此方，亦可量加紫苏、葱白。如冬月天气严寒，感邪即病，服此方不得汗，本方加麻黄（一钱），生姜（四片），共前（七片），得汗，勿再服。 3、如病人自觉烦躁，喜就清凉，不喜就热，兼口渴，即欲传入阳明也。若外证头疼，遍身骨疼不解，或带口渴、鼻干、目疼、不得卧，即系太阳阳明证。羌活汤中加石膏、知母、麦冬，大剂与之，得汗即解。 4、如自汗烦躁，头疼、遍身骨疼不解者，羌活（一钱），桂枝（七分），石膏（一两二钱），麦冬（六钱），知母（三钱），竹叶（一百二十片），白芍药（二钱），甘草（八分）。 5、如冬月即病太阳证，恶寒、畏风、头疼、遍身骨疼、自汗、不渴，宜用桂枝（八分），芍药（二钱），甘草（一钱），大枣（二枚），生姜（一片）。 6、太阳病不解，热结膀胱，其人如狂，血自下，下之愈。其外证不解者，不可下，当先解表。表证罢，少腹急结者，乃可下之，桃仁承气汤。无蓄血证，大承气汤。 7、正阳阳明病 正阳阳明者，胃家实热是也。其证不大便，自汗，潮热，口渴，咽干，鼻干，呕或干呕，目眴眴不得眠，畏人声、畏木声、畏火，不恶寒反恶热，或先恶寒不久旋发热，甚则谵语狂乱，循衣摸床，脉洪大而长。宜急解其表，用竹叶石膏汤，大剂与之。不呕，无汗，与葛根汤，亦须大剂。若表证已罢，脉缓，小便利，是病解矣。 8、若表证罢后，邪结于里，大便闭，小便短赤，宜用调胃承气汤或小承气汤下之。下后，按其腹中不作痛而和，病即已解。如作痛，是燥粪未尽也。再用前药下之。以腹中和，二便通利为度。 9、阳明病，不能食。若其人本虚，勿轻议下。 10、阳明病，头眩，咳而咽痛者，用葛根、甘草、桔梗、麦冬四味浓煎，数数与之。阳明病无汗，小便不利，心中懊憹者，当发黄。急用栀子、麦冬、淡豆豉，大剂浓煎与之。如已见身黄，急加茵陈为君主之。 11、阳明病衄血，此缘失于发汗，宜用荆芥（二钱），葛根（三钱），麦门冬（五钱），牡丹皮（一钱五分），蒲黄（二钱），茅根（二两），侧柏叶（二钱），生地黄（三钱），浓煎与之，兼饮童便。阳明病心下硬满者，此邪未入于腹中，慎勿下之。用竹叶石膏汤，加栝楼（一个，捣碎），桔梗（二钱），黄连（一钱）。 12、阳明病邪结于里，汗出身重，短气，腹满而喘，潮热，手足濈然汗出者，此大便已硬也。六七日已来，宜下之，用小承气汤。不行，换大承气汤，勿大其剂。若大便不硬者，慎勿轻下。 13、阳明病发汗不解，腹满急者，亟下之。伤寒六七日，目中不了了，睛不和，无表证，大便难，宜承气汤下之。 14、阳明病，下之早，外有热，手足温，不结胸，心中懊憹不能食，但头汗出，栀子豉汤主之。 15、阳明病，发潮热，大便溏，胸满不去者，与小柴胡汤去人参，加栝楼、黄连。 16、阳明病自汗出，或发汗后，小便利，津液内竭，大便虽硬，不可攻之。须俟其自大便，或用蜜导、胆导法通之。大下后，六七日不大便，烦不解，腹满痛，本有宿食，宜再用承气汤下之。 17、食谷欲呕，属阳明，非少阳也。胸中烦热者，竹茹汤主之：竹茹（三钱），麦门冬（五钱），枇杷叶（三大片），芦根（三两）。内无热证者，小便利，口不渴，此为阳明虚也。吴茱萸汤主之。吴茱萸（二钱），人参（三钱），生姜（一钱五分），大枣（三枚），水煎，日三服。 18、凡阳明病多汗，津液外出，胃中燥，大便必硬，硬则谵语，以小承气汤下之。若一服谵语止者，勿再服。 19、阳明病谵语，发潮热，脉滑而数者，小承气汤主之。服药后腹中转气者，更与一服。若不转气者，勿更与之。若服药后次日不大便，脉反微涩者，里虚也，为难治。勿复议下。 20、阳明病，下血谵语者，此为热入血室，汗止在头。用荆芥（三钱），葛根（三钱），黄芩（一钱五分），麦冬（五钱），牡丹皮（一钱五分），生蒲黄（二钱），浓煎，以童便对饮之。 21、阳阳明病脉浮紧，咽燥口苦，腹满而喘，发热汗出，恶热身重。若下之，则胃中空虚，客气动膈，心中懊憹，舌上有胎者，栀子豉汤主之。若渴欲饮水，舌燥者，白虎汤加人参主之，若脉浮，发热口渴，小便不利者，猪苓汤主之。 22、阳明病，协热下利者，宜六一散。心下痞者，以黄连栝楼汤调服之。脉浮迟，表热里寒，下利清谷者，四逆汤主之：附子、干姜、甘草。趺阳脉浮而涩，小便数，大便硬，其脾为约，麻子仁丸主之。麻仁（十三两），芍药（四两），枳实（四两），大黄（八两），厚朴（三两），杏仁（六两），蜜丸如梧子大，每用十丸，日三服。 23、阳明实则谵语，虚则郑声。郑声者，重语也。直视、谵语、喘满者死。下利者亦死。发汗多，若重发其汗，谵语脉短者死；脉和者，不死。若吐、若下后不解，不大便五六日，或至十余日，日晡时发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣妄撮，惕而不安，微喘直视，脉弦者生，涩者死（涩者阳证见阴脉也）。微者但发热谵语者，大承气汤下之。利，勿再服。 24、阳明病发狂，弃衣而走，登高而歌，此阳明实也。以承气汤亟下之。如便不结者，大剂白虎汤灌之。石膏（四两），麦冬（二两），知母（一两五钱），加大青（一两），甘草（七钱）。 25、太阳阳明病协热下利者，宜六一散，以黄连煎汤调服之。 26、太阳阳明并病六七日，表证仍在，其人发狂者，以热在下焦，少腹当硬满，小便自利，下其血乃愈，当用桃仁承气汤。 27、又二阳并病，太阳证罢，潮热，汗出，大便难，谵语者，宜大承气汤。 28、少阳病其证口苦，咽干，目眩，往来寒热，胸胁痛，胸满或痛，耳聋。脉法弦细。头痛发热者，属少阳。少阳不可发汗，发汗则谵语。胃和者，当自愈；不和者，则烦而悸。 29、伤寒三日，少阳脉小者，欲己也。 30、凡太阳病不解，传入少阳者，胁下硬满，干呕不能食，往来寒热，未经吐下，脉沉紧者，与小柴胡汤：柴胡（二钱四分），人参（九分），黄芩（九分），甘草（九分），半夏（一钱五分），生姜（九分），大枣（二枚），水煎，温服，日三。加减法：若胸中烦而不呕，去半夏、人参，加栝楼实（一枚）。若心下痞硬，去大枣，加牡蛎（二钱半）。若渴者，去半夏，加人参、栝楼根。若腹中痛者，去黄芩，加芍药（三钱）。若心下悸，小便不利者，去黄芩，加茯苓（二钱）。若不渴，外有微热者，去人参，加桂（一钱，夏勿用）。温覆，取微汗愈。若咳者，去人参、大枣，加五味子（一钱），少佐以干姜。 31、阳明少阳并病，必下利，脉滑而数，有宿食也。当承气汤下之。若吐、下、发汗、温针，谵语，柴胡汤证罢，此为坏病。知犯何逆，以法治之。 32、三阳合病，脉大上关上，但欲睡眠，目合则汗，药用百合（一两），麦门冬（五钱），炙甘草（一钱），知母（二钱），竹叶（五十片），栝楼根（二钱），鳖甲（如法三钱），白芍药（二钱）。 33、三阳合病，腹满身重，谵语遗尿，白虎汤加百合主之。 34、伤寒六七日，无大热，其人烦躁者，此以阳去入阴故也。 35、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('stqSBbvWj00', 1, '{"title":"卷之二_续序例下_三阴治法总要 ","description":"<p>1、三阴病　其证有二。一者病发于三阳，不时解表，以致邪热传入于里。虽云阴分，病属于热。粪结宜下，腹满不可按宜下，有燥粪协热下利宜下。腹痛下利，宜芍药、黄芩、炙甘草以和之。如便脓血，即加滑石、黄连，佐以升麻、干葛。如邪虽入里，粪犹未结，宜清其热。渴者用白虎汤、竹叶石膏汤；不渴或心下痞者，宜黄连、黄芩、芍药、枳壳、麦冬、栝楼辈以清之。或邪未结于下焦，少腹不坚痛，而误用芒硝以伐真阴，洞泄不己，元气将脱，宜用人参、白术、炙甘草、大枣、干姜、芍药，大剂与之。不止，佐以升提，升麻、葛根、柴胡之类。</p><p>2、若从无阳邪表证，从不头疼发热，寒邪直中阴经，此必元气素虚之人，或在极北高寒之地，始有是证。法宜温补以接其阳，附子、人参、干姜、官桂，大剂与之。阳回寒退，即以平补之剂调之。勿过用附、桂，以防其毒。　　</p><p>3、三阴各经见证，悉从仲景《伤寒论》法治之。如少阴咽痛，咽中生疮，声不出，用苦酒汤，到咽即效。故知古人立法，非今人所及也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001046,"no":45}}', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '1、三阴病 其证有二。一者病发于三阳，不时解表，以致邪热传入于里。虽云阴分，病属于热。粪结宜下，腹满不可按宜下，有燥粪协热下利宜下。腹痛下利，宜芍药、黄芩、炙甘草以和之。如便脓血，即加滑石、黄连，佐以升麻、干葛。如邪虽入里，粪犹未结，宜清其热。渴者用白虎汤、竹叶石膏汤；不渴或心下痞者，宜黄连、黄芩、芍药、枳壳、麦冬、栝楼辈以清之。或邪未结于下焦，少腹不坚痛，而误用芒硝以伐真阴，洞泄不己，元气将脱，宜用人参、白术、炙甘草、大枣、干姜、芍药，大剂与之。不止，佐以升提，升麻、葛根、柴胡之类。 2、若从无阳邪表证，从不头疼发热，寒邪直中阴经，此必元气素虚之人，或在极北高寒之地，始有是证。法宜温补以接其阳，附子、人参、干姜、官桂，大剂与之。阳回寒退，即以平补之剂调之。勿过用附、桂，以防其毒。 3、三阴各经见证，悉从仲景《伤寒论》法治之。如少阴咽痛，咽中生疮，声不出，用苦酒汤，到咽即效。故知古人立法，非今人所及也。', '2024-12-23T06:03:27.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x9Sl6hTKPIq', 1, '{"title":"卷之二_续序例下_春温夏热病大法","description":"<p>1、冬伤于寒，至春变为温病，大都头疼发热，或渴或不渴。三阳证俱然。亦间有先微寒后即发热者。大抵发热其常也。药用辛温，佐以辛寒，以解表邪。太阳宜羌活汤，阳明宜白虎汤，无汗不呕者，间用葛根汤。少阳往来寒热等证，不可汗、吐、下，宜和解，小柴胡汤。渴者，去半夏，加栝楼根；耳聋，热盛，去人参，加麦冬、知母、栝楼根，渴亦加之。</p><p>2、至夏变为热病，其表证大约与春温同，但热比于温，则邪气更烈耳。解表用白虎汤、竹叶石膏汤。有太阳证则加羌活，有少阳证则加柴胡、黄芩。如发斑，白虎汤、竹叶石膏汤，加玄参、栀子、桔梗、鼠粘子、连翘、大青、小青、青黛，大剂与之。二证若大便秘，宜按之。其邪已结于内，便硬宜察，邪结中焦，小承气汤、调胃承气汤下之；邪结下焦，少腹坚痛，始用大承气汤下之。</p><p>3、伤寒、温疫，其不可治及难治者，皆属下元虚。</p>\n<p></p><p>4、伤寒、温疫，三阳证中，往往多带阳明者，以手阳明经属大肠，与肺为表里，同开窍于鼻，足阳明经属胃，与脾为表里，同开窍于口。凡邪气之入，必从口鼻，故兼阳明证者独多。</p><p>5、邪在三阳，法宜速逐，迟则胃烂发斑，或传入于里，则属三阴。邪热炽者，令阴水枯竭，于法不治矣。此治之后时之过也。</p><p>6、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取妇人中裈近阴处，剪，烧灰，以水和服方寸匕，日三。小便即利，阴头微肿则愈。妇人病，取男子裈裆烧灰。</p><p>7、大病差后，劳复者，枳实栀子汤主之：枳实（三枚）　栀子（十四枚）　豉（一升，绵裹），以清浆水七升，空煮取四升，内枳实、栀子，煮取二升，下豉，更煮五六沸，去滓，温分再服。覆令微似汗。若有宿食者，加大黄如博棋子大五六枚。</p><p>8、伤寒差已后，更发热者，小柴胡汤主之。脉浮者，以汗解之。脉沉实者，以下解之。</p><p>9、百合病者，百脉一宗，悉致其病也。其证神思常默然，饮食不美、亦不恶，如寒无寒，如热无热，口苦，小便赤，百合地黄汤主之。汗后者，百合知母汤。下后者，滑石代赭汤。吐后者，百合鸡子汤。</p><p>10、近代医师鲁莽，既不明伤寒治法，又不识杂证类伤寒，往往妄投汗、下之药，以致虚人元气，变证丛生。元气本虚之人，未有不因之而毙者矣。戒之哉！汗、下之药，焉可尝试也！</p><p>11、时气伤寒（除阴证不可服。）</p>\n<p>        苦参（一两），水、酒各一碗，煎八分。重者水、醋各半服之。一汗而愈。不论伤寒久近，立效。本草云：天行尤良。</p><p>12、暑（三证）</p>\n<p>诸病喘呕，暴注下迫，霍乱转筋，身热瞀郁，小便浊赤，皆属于暑。</p>\n<p>【忌】破气、升，复忌下、湿润、辛温、辛燥、热、发散、闭气。诸药俱见前。</p>\n<p>【宜】清暑益气、健脾、甘寒、甘温、辛寒、酸寒、苦寒。黄连、香薷、葛根、石膏、知母、甘草、人参、黄芪、白术、白扁豆、神曲、橘皮、白茯苓、木瓜、麦门冬、五味子、白芍药、白梅、乌梅。大约用清暑益气汤、香薷饮、生脉散。凡病暑之人，其气必虚。暑伤气，无气以动，故当补气为本。惟肺热多火者，忌人参、术。</p>\n<p></p><p>13、中暑，猝昏晕，急以童便灌入即省。</p>\n<p></p>\n<p>       忌、宜俱同暑。又方：用丝瓜叶一片，白盐梅肉一枚，并取核中仁，共研如泥，新汲水调灌，立瘥。兼治中暑霍乱有神。</p><p>14、太阳病中暍。</p>\n<p>【忌】同暑。</p>\n<p>【宜】人参白虎汤。有肺热火病人，不能服参者，用竹叶石膏汤。脾胃作泻者，水调六一散。</p><p>15、霍乱，见胃虚条内。忌、宜俱同。</p><p>16、疰夏，由于脾胃薄弱，胃家有湿热，及留饮所致。</p>\n<p>【忌】同前。</p>\n<p>【宜】益气健脾、酸寒、苦寒、淡渗。人参、白术、半夏、橘皮、白茯苓、白扁豆、白芍药、木瓜、泽泻。兼服生脉散。</p><p>17、湿（一证）</p>\n<p>诸痉强直，积饮痞膈，中满霍乱，吐下体重，胕肿肉如泥，按之不起，皆属于湿。《经》曰：地之湿气，感则害人皮肉筋脉。故其病筋骨疼痛，腰重痛不可转侧，身重，四肢不利。湿在上，病呕吐、头重、胸满；湿在中，病腹胀、中满、泄泻；湿在下，病足胫跗肿，脚气臁疮久不愈。</p>\n<p>【忌】湿润、甘、咸。诸药俱见前。</p>\n<p>【宜】散、渗泄、燥、辛、苦。木瓜、薏苡仁、术、石斛、萆薢、石菖蒲、茯苓。佐以防风、葛根。寒湿加半夏、五加皮，风湿加独活，湿热加黄檗、车前子、木通，甚者加汉防己。</p><p>18、脚气，由于湿热。</p>\n<p>【忌】温燥、湿热、补气，复忌破气、升。诸药俱见前。</p>\n<p>【宜】清热、除湿、利小便、甘平、酸寒、苦寒、辛温、淡渗。黄檗、石斛、麦门冬、木瓜、石菖蒲、车前子、茯苓、木通、泽泻、萆薢、防己。</p><p>19、燥火（十三证）</p>\n<p>诸涩枯涸，干劲皴揭，皆属于燥。角弓反张，筋挛急不舒，舌强不能言，二便闭涩，口渴，口干舌苦，皮肤皴揭，毛发脆折，津液不生，血枯胃槁，以致饮食不化，噎膈吐食。</p>\n<p>【忌】升散、破气、下、辛燥、大热、温。诸药俱见前。</p>\n<p>【宜】润、益血、辛、甘寒、酸寒、咸寒，有热证者宜兼清热。麦门冬、当归、地黄、肉苁蓉、酥、人乳、牛乳、蜜、胡桃、甘菊花、麻仁、胡麻、柏子仁、人参、松实、天门冬、五味子、酸枣仁、白芍药、蔗浆、芦根汁、童便、梨汁、韭汁。佐以姜汁。</p><p>20、火，诸热瞀瘈，暴瘖冒昧，躁扰狂越，骂詈惊骇，胕肿疼酸，气逆上冲，禁栗如丧神守，啑呕，疮疡，喉痹，耳鸣及聋，呕涌溢食不下，目昧不明，暴注，瞤瘈，暴病暴死者，皆属于火。</p>\n<p>【忌】补敛、升发、闭气、辛燥、温热。诸药俱见前。</p>\n<p>【宜】降折、下、咸寒、苦寒、辛寒、甘寒。大黄、童便、芒硝、黄芩、黄连、黄檗、连翘、石膏、山栀、玄参、生甘草、知母、天门冬、麦门冬、生地黄、蓝汁。虚者宜甘寒、咸寒以滋水，不宜用苦寒伤胃。</p><p>21、猝眩仆、九窍流血，多不治。</p>\n<p>【忌】同火。</p>\n<p>【宜】服童便、盐汤、竹沥、蓝汁、梨、生犀角汁。</p><p>22、猝心痛。</p>\n<p>【忌】同火。</p>\n<p>【宜】服山栀、白芍药、延胡索、生甘草、盐汤、苏子。</p><p>23、目暴赤肿痛甚，见肝实条内。忌、宜俱同。</p><p>24、二便忽闭，以利小便为先。</p>\n<p>【忌】同火。</p>\n<p>【宜】降润、苦寒、甘寒、辛寒、利窍。大黄、苏子、生蜜、麻仁、桃仁、石膏、贝母、天门冬、麦门冬、黄芩、山栀、滑石、泽泻、猪苓、车前子、木通、海金沙。</p><p>25、头面赤肿。</p>\n<p>【忌】同火。</p>\n<p>【宜】清热解毒、发散、苦寒、辛寒、甘寒、咸寒。甘菊花、鼠粘子、连翘、荆芥、薄荷、蝉蜕、大黄、玄参、石膏、知母、竹叶、生甘草、童溺。</p><p>26、忽大渴思冰水。</p>\n<p>【忌】同火。</p>\n<p>【宜】润、生津液、辛寒、甘寒、咸寒。石膏、知母、玄参、麦门冬、竹叶、栝楼根、五味子、梨汁、蔗浆、童便、凉水、冰。</p><p>27、口干舌苦。忌、宜俱同火。</p><p>28、暴瘄。</p>\n<p>【忌】同火。</p>\n<p>【宜】降气、发音声、苦、甘寒、辛凉、咸寒。苏子、枇杷叶、贝母、桔梗、百部、竹沥、梨汁、天门冬、麦门冬、甘草、薄荷、玄参、桑白皮、童便。</p><p>29、暴注。</p>\n<p>【忌】同火。</p>\n<p>【宜】利水、苦寒、酸寒。茯苓、黄连、黄芩、白芍药、生甘草、葛根、滑石、木通。虚者加：人参、莲肉、白扁豆。</p><p>30、躁扰狂越，骂詈惊骇。</p>\n<p>【忌】同火。</p>\n<p>【宜】清镇、苦寒、辛寒、咸寒。丹砂、牛黄、黄连、黄芩、山栀、滑石、知母、童便。大便闭者，加大黄下之。不行，加芒硝。</p><p>31、禁栗如丧神守。</p>\n<p>【忌】同火。</p>\n<p>【宜】同躁扰狂越。</p><p>32、气逆冲上。</p>\n<p>【忌】同火。</p>\n<p>【宜】降气、酸敛、甘寒、苦寒、咸寒。苏子、枇杷叶、橘红、五味子、番降香、山茱萸、白芍药、麦门冬、石斛、黄檗、牛膝、桑白皮、童溺。</p><p>33、瞤瘈瞀瘈。</p>\n<p>【忌】同火。</p>\n<p>【宜】清热和肝、酸寒、苦寒、辛寒、甘寒。白芍药、生甘草、竹叶、玄参、黄连、黄檗、生地黄、甘菊花、麦门冬、知母、石膏。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001047,"no":46}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '1、冬伤于寒，至春变为温病，大都头疼发热，或渴或不渴。三阳证俱然。亦间有先微寒后即发热者。大抵发热其常也。药用辛温，佐以辛寒，以解表邪。太阳宜羌活汤，阳明宜白虎汤，无汗不呕者，间用葛根汤。少阳往来寒热等证，不可汗、吐、下，宜和解，小柴胡汤。渴者，去半夏，加栝楼根；耳聋，热盛，去人参，加麦冬、知母、栝楼根，渴亦加之。 2、至夏变为热病，其表证大约与春温同，但热比于温，则邪气更烈耳。解表用白虎汤、竹叶石膏汤。有太阳证则加羌活，有少阳证则加柴胡、黄芩。如发斑，白虎汤、竹叶石膏汤，加玄参、栀子、桔梗、鼠粘子、连翘、大青、小青、青黛，大剂与之。二证若大便秘，宜按之。其邪已结于内，便硬宜察，邪结中焦，小承气汤、调胃承气汤下之；邪结下焦，少腹坚痛，始用大承气汤下之。 3、伤寒、温疫，其不可治及难治者，皆属下元虚。 4、伤寒、温疫，三阳证中，往往多带阳明者，以手阳明经属大肠，与肺为表里，同开窍于鼻，足阳明经属胃，与脾为表里，同开窍于口。凡邪气之入，必从口鼻，故兼阳明证者独多。 5、邪在三阳，法宜速逐，迟则胃烂发斑，或传入于里，则属三阴。邪热炽者，令阴水枯竭，于法不治矣。此治之后时之过也。 6、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取妇人中裈近阴处，剪，烧灰，以水和服方寸匕，日三。小便即利，阴头微肿则愈。妇人病，取男子裈裆烧灰。 7、大病差后，劳复者，枳实栀子汤主之：枳实（三枚） 栀子（十四枚） 豉（一升，绵裹），以清浆水七升，空煮取四升，内枳实、栀子，煮取二升，下豉，更煮五六沸，去滓，温分再服。覆令微似汗。若有宿食者，加大黄如博棋子大五六枚。 8、伤寒差已后，更发热者，小柴胡汤主之。脉浮者，以汗解之。脉沉实者，以下解之。 9、百合病者，百脉一宗，悉致其病也。其证神思常默然，饮食不美、亦不恶，如寒无寒，如热无热，口苦，小便赤，百合地黄汤主之。汗后者，百合知母汤。下后者，滑石代赭汤。吐后者，百合鸡子汤。 10、近代医师鲁莽，既不明伤寒治法，又不识杂证类伤寒，往往妄投汗、下之药，以致虚人元气，变证丛生。元气本虚之人，未有不因之而毙者矣。戒之哉！汗、下之药，焉可尝试也！ 11、时气伤寒（除阴证不可服。） 苦参（一两），水、酒各一碗，煎八分。重者水、醋各半服之。一汗而愈。不论伤寒久近，立效。本草云：天行尤良。 12、暑（三证） 诸病喘呕，暴注下迫，霍乱转筋，身热瞀郁，小便浊赤，皆属于暑。 【忌】破气、升，复忌下、湿润、辛温、辛燥、热、发散、闭气。诸药俱见前。 【宜】清暑益气、健脾、甘寒、甘温、辛寒、酸寒、苦寒。黄连、香薷、葛根、石膏、知母、甘草、人参、黄芪、白术、白扁豆、神曲、橘皮、白茯苓、木瓜、麦门冬、五味子、白芍药、白梅、乌梅。大约用清暑益气汤、香薷饮、生脉散。凡病暑之人，其气必虚。暑伤气，无气以动，故当补气为本。惟肺热多火者，忌人参、术。 13、中暑，猝昏晕，急以童便灌入即省。 忌、宜俱同暑。又方：用丝瓜叶一片，白盐梅肉一枚，并取核中仁，共研如泥，新汲水调灌，立瘥。兼治中暑霍乱有神。 14、太阳病中暍。 【忌】同暑。 【宜】人参白虎汤。有肺热火病人，不能服参者，用竹叶石膏汤。脾胃作泻者，水调六一散。 15、霍乱，见胃虚条内。忌、宜俱同。 16、疰夏，由于脾胃薄弱，胃家有湿热，及留饮所致。 【忌】同前。 【宜】益气健脾、酸寒、苦寒、淡渗。人参、白术、半夏、橘皮、白茯苓、白扁豆、白芍药、木瓜、泽泻。兼服生脉散。 17、湿（一证） 诸痉强直，积饮痞膈，中满霍乱，吐下体重，胕肿肉如泥，按之不起，皆属于湿。《经》曰：地之湿气，感则害人皮肉筋脉。故其病筋骨疼痛，腰重痛不可转侧，身重，四肢不利。湿在上，病呕吐、头重、胸满；湿在中，病腹胀、中满、泄泻；湿在下，病足胫跗肿，脚气臁疮久不愈。 【忌】湿润、甘、咸。诸药俱见前。 【宜】散、渗泄、燥、辛、苦。木瓜、薏苡仁、术、石斛、萆薢、石菖蒲、茯苓。佐以防风、葛根。寒湿加半夏、五加皮，风湿加独活，湿热加黄檗、车前子、木通，甚者加汉防己。 18、脚气，由于湿热。 【忌】温燥、湿热、补气，复忌破气、升。诸药俱见前。 【宜】清热、除湿、利小便、甘平、酸寒、苦寒、辛温、淡渗。黄檗、石斛、麦门冬、木瓜、石菖蒲、车前子、茯苓、木通、泽泻、萆薢、防己。 19、燥火（十三证） 诸涩枯涸，干劲皴揭，皆属于燥。角弓反张，筋挛急不舒，舌强不能言，二便闭涩，口渴，口干舌苦，皮肤皴揭，毛发脆折，津液不生，血枯胃槁，以致饮食不化，噎膈吐食。 【忌】升散、破气、下、辛燥、大热、温。诸药俱见前。 【宜】润、益血、辛、甘寒、酸寒、咸寒，有热证者宜兼清热。麦门冬、当归、地黄、肉苁蓉、酥、人乳、牛乳、蜜、胡桃、甘菊花、麻仁、胡麻、柏子仁、人参、松实、天门冬、五味子、酸枣仁、白芍药、蔗浆、芦根汁、童便、梨汁、韭汁。佐以姜汁。 20、火，诸热瞀瘈，暴瘖冒昧，躁扰狂越，骂詈惊骇，胕肿疼酸，气逆上冲，禁栗如丧神守，啑呕，疮疡，喉痹，耳鸣及聋，呕涌溢食不下，目昧不明，暴注，瞤瘈，暴病暴死者，皆属于火。 【忌】补敛、升发、闭气、辛燥、温热。诸药俱见前。 【宜】降折、下、咸寒、苦寒、辛寒、甘寒。大黄、童便、芒硝、黄芩、黄连、黄檗、连翘、石膏、山栀、玄参、生甘草、知母、天门冬、麦门冬、生地黄、蓝汁。虚者宜甘寒、咸寒以滋水，不宜用苦寒伤胃。 21、猝眩仆、九窍流血，多不治。 【忌】同火。 【宜】服童便、盐汤、竹沥、蓝汁、梨、生犀角汁。 22、猝心痛。 【忌】同火。 【宜】服山栀、白芍药、延胡索、生甘草、盐汤、苏子。 23、目暴赤肿痛甚，见肝实条内。忌、宜俱同。 24、二便忽闭，以利小便为先。 【忌】同火。 【宜】降润、苦寒、甘寒、辛寒、利窍。大黄、苏子、生蜜、麻仁、桃仁、石膏、贝母、天门冬、麦门冬、黄芩、山栀、滑石、泽泻、猪苓、车前子、木通、海金沙。 25、头面赤肿。 【忌】同火。 【宜】清热解毒、发散、苦寒、辛寒、甘寒、咸寒。甘菊花、鼠粘子、连翘、荆芥、薄荷、蝉蜕、大黄、玄参、石膏、知母、竹叶、生甘草、童溺。 26、忽大渴思冰水。 【忌】同火。 【宜】润、生津液、辛寒、甘寒、咸寒。石膏、知母、玄参、麦门冬、竹叶、栝楼根、五味子、梨汁、蔗浆、童便、凉水、冰。 27、口干舌苦。忌、宜俱同火。 28、暴瘄。 【忌】同火。 【宜】降气、发音声、苦、甘寒、辛凉、咸寒。苏子、枇杷叶、贝母、桔梗、百部、竹沥、梨汁、天门冬、麦门冬、甘草、薄荷、玄参、桑白皮、童便。 29、暴注。 【忌】同火。 【宜】利水、苦寒、酸寒。茯苓、黄连、黄芩、白芍药、生甘草、葛根、滑石、木通。虚者加：人参、莲肉、白扁豆。 30、躁扰狂越，骂詈惊骇。 【忌】同火。 【宜】清镇、苦寒、辛寒、咸寒。丹砂、牛黄、黄连、黄芩、山栀、滑石、知母、童便。大便闭者，加大黄下之。不行，加芒硝。 31、禁栗如丧神守。 【忌】同火。 【宜】同躁扰狂越。 32、气逆冲上。 【忌】同火。 【宜】降气、酸敛、甘寒、苦寒、咸寒。苏子、枇杷叶、橘红、五味子、番降香、山茱萸、白芍药、麦门冬、石斛、黄檗、牛膝、桑白皮、童溺。 33、瞤瘈瞀瘈。 【忌】同火。 【宜】清热和肝、酸寒、苦寒、辛寒、甘寒。白芍药、生甘草、竹叶、玄参、黄连、黄檗、生地黄、甘菊花、麦门冬、知母、石膏。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nablzij19SG', 1, '{"title":"卷之二_续序例下_杂证门","description":"<p>1、疟 </p>\n<p>      《经》曰：夏伤于暑，秋必痎疟。其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，或先寒后热，或先热后寒，或有汗、无汗，或汗少、汗多，或自汗、盗汗，或头疼骨痛，或大渴引饮，口苦舌干，或呕吐不思食，或烦躁不得眠，或大便燥结，或泻利，或连发，或间发，或三日发，或发于阳，或发于阴，要皆中气不足，脾胃虚弱，暑邪乘虚客之而作。虽随经随证投药解散，必先清暑益气，调理脾胃为主。有伤食者兼消导夺食，有风兼散风，有老痰伏饮者兼豁痰逐饮，感瘴疠者兼消瘴疠，汗多者固表，无汗者解表，泄利者升发、兼利小便，便燥者兼益阴润燥。病有阴阳，药分气血，证有缓急，治因先后，人有虚实，法异攻补。久而不解，必属于虚。气虚者补气，血虚者补血，两虚者气血兼补，非大补真气，大健脾胃不得瘳也。</p>\n<p>【忌】破气、下。</p>\n<p>诸药俱见前。</p><p>2、疟必由于中气虚，破气则伤中气，邪不得解，甚则中满不思食，作泄，恶寒，口干，惟伤食宜消，不同此法。</p><p>3、误下则邪气陷于内，变为滞下，或腹满肿胀，呕恶不思食。凡属破气、下泄药，切戒勿施！</p>\n<p>【宜】清暑益气，健脾开胃，兼消痰。</p>\n<p>【宜】分脏腑手足六经所见证拖治。</p>\n<p>先清暑：热多者宜服白虎汤加减：硬石膏（自一两至四两），知母（自四钱至二两四钱），竹叶（自一百片至四百片），麦门冬（自八钱至三两二钱），粳米（自一小撮至二大撮）。病人素虚或作劳者，加人参（自三钱至一两）。</p>\n<p>有痰加广橘红（三钱），竹沥（一杯），大渴者，加栝楼根（三钱至六钱）。</p>\n<p>不渴者，用清暑益气汤。</p>\n<p>兼饮食停滞者，加枳实、青皮、草果一二剂，食消即止。勿多服。多服则损中气。其药俱宜黄昏煎，以井水澄冷，须露一宿，五更时温服。盖疟乃暑邪为病，暑得露则散也。</p><p>4、《内经》六经疟候汤液</p>\n<p>足太阳经属膀胱，其证令人腰痛，头痛头重，寒从背起，先寒后热，熇熇暍暍然，热止汗出难已，或遍身骨痛，小便短赤：</p>\n<p>羌活（一钱至三四钱），广陈皮（去白二钱五分），黄芩（二钱），前胡（二钱），甘草（炙五分），猪苓（一钱），知母（二钱五分）。</p>\n<p>若口渴者，即兼阳明，宜加石膏、麦门冬，倍知母。渴而汗少，或无汗，并加葛根。</p>\n<p>若涉深秋或入冬，无汗，宜多加姜皮。</p>\n<p>因虚而无汗，或汗少者，加人参（三五钱），麦门冬（四五钱），佐以姜皮（二三钱），露一宿，发日五更温服。</p>\n<p>因虚汗多者，加黄耆（三四钱），桂枝（七八分）。汗止，即去桂枝，不可多服。</p>\n<p>若病人素有热者，勿服桂枝，以芍药、五味子代之。</p>\n<p>若发于阴，并加当归。</p>\n<p>小便短涩或赤者，与六一散二三服。</p>\n<p>有湿者，以猪苓、茯苓代滑石。下午服理脾健胃药：</p>\n<p>橘红（二钱五分），白豆蔻（五分），白茯苓（三钱），山查（三钱），麦芽（炒三钱），藿香（一钱），人参（三钱），白术（二钱），白芍药（三钱），白扁豆（三钱）。</p>\n<p>有肺火者，去人参、白术，加麦门冬（五钱），石斛（三钱），乌梅肉（一枚）。</p>\n<p>停食者必恶食，加山查。伤肉食者加黄连、红曲。伤谷食者加枳实、草果（各七分）。伤面食者加炒莱菔子。食消即已，不可多服，多服则损中气。</p>\n<p>胃家素有湿痰者，其证不渴、寒多，方可用半夏、橘红、二术，大剂与之。呕甚者兼用姜皮。</p><p>5、足阳明经属胃，其证发热头疼，鼻干，渴欲引饮，目眴眴不得眠，甚则烦躁，畏火光、人声、木声。宜服大剂竹叶石膏汤。无汗或汗少不呕者，可加干葛（二三钱）。</p>\n<p>病人虚而作劳者，加人参。</p>\n<p>汗多，加白术。</p>\n<p>痰多，加贝母、橘红，得汗即解。</p>\n<p>寒热俱甚，渴甚，汗多，寒时指爪皆紫黯者，加桂枝（七八分）。</p>\n<p>久而不解属气虚，用人参（两许），姜皮（两许），煎成露一宿，五更温服。下午服理脾健胃药如前方，加减亦如之。</p><p>6、足少阳经属胆，其证往来寒热，口苦，耳聋，胸胁痛，或呕。宜服小柴胡汤。</p>\n<p>渴者，去半夏，加石膏、麦门冬。</p>\n<p>肺家有热者，去人参，加知母，倍门冬。</p>\n<p>有痰不渴者，本方加贝母（三钱至八钱），术、茯苓（各三钱），姜皮（一钱至三四钱）。</p>\n<p>病人阴虚而有热者，虽呕吐忌用半夏、生姜，误投则损人津液，令人声哑，宜用竹茹、橘皮、麦门冬、白茯苓、乌梅以代之。</p><p>7、以上三阳经疟邪客之者，其证多热多渴，亦易得汗，药宜大剂，急逐暑邪，毋得迟留，则病易愈。继以理脾开胃，大补真气，蔑不瘳矣。邪在三阳，药宜辛寒，如石膏、知母、柴胡；甘寒，如葛根、麦门冬、竹叶、粳米；苦寒，如黄芩之属为君，乃可以散暑邪，除热渴，坠头痛。兼寒甚者，则间用辛温，如姜皮、桂枝以为向导，以伏其邪，则病易退。凡寒甚者，病因于虚。或作劳者，亦因于虚，皆宜甘温。以人参、黄耆、术为君，佐以辛甘，如桂枝、姜皮之属。脾胃虚弱，饮食不消者，则补之以参、术，佐以消导，如白豆蔻、麦芽、砂仁、草豆蔻、枳实、橘皮、山查之属。在阴分者，则以当归、牛膝为君，佐以姜、桂。如热甚而渴者去姜、桂，加知母、麦门冬、竹叶、牛膝、鳖甲。</p><p>8、足厥阴经属肝，其证先寒后热，色苍苍然，善太息，甚者状如欲死，或头疼而渴。</p>\n<p>【宜】先服三黄石膏汤加柴胡、鳖甲、橘皮，以祛暑邪。后用当归（两许），橘皮（三四钱），鳖甲（四五钱），牛膝（两许），柴胡（一二钱），浓煎露一宿，发日五更温服。</p>\n<p>如热甚而渴，加栝楼根（三四钱），麦门冬（四五钱），竹叶（一百片），知母（三四钱），鳖甲（五六钱）。</p>\n<p>如脾胃薄弱，或溏泄，去当归，加人参（三五钱）。</p>\n<p>如有肺火，不可服参者，只照本方，多服自愈。</p>\n<p>寒多或寒甚，指爪青黯者，加桂枝、姜皮、人参。</p><p>9、足太阴经属脾，其证先寒后热，或寒多。若脾疟，必寒从中起，善呕，呕已乃衰，然后发热，热过汗出乃已。热甚者或渴，否则不渴喜火。</p>\n<p>【宜】服桂枝汤、建中汤。</p>\n<p>病人虚者，以人参、姜皮各两许浓煎，露一宿，五更温服。</p>\n<p>有痰者，宜加术、橘皮（各三四钱）。</p><p>10、足少阴经属肾，其证寒热俱甚，腰痛脊强，口渴，寒从下起，小便短赤。</p>\n<p>【宜】先服人参白虎汤加桂枝，以祛暑邪，后用鳖甲（四五钱），牛膝（两许），热甚者加知母、麦门冬（各四五钱）。寒甚者加桂枝钱许。</p>\n<p>呕则兼加姜皮（三四钱）。如热甚而呕者，去桂枝、姜皮，加竹茹（三钱），人参、橘皮（各三四钱）。用牛膝、桂枝者，肝肾同一治故也。</p><p>11、疟病多挟痰。以故热痰须用贝母为君，自三钱至八钱，竹沥、竹茹、栝楼根、橘红、白茯苓，称是以佐之。甚者可加霞天膏。如寒痰发疟，寒多不渴者，用半夏、白术、橘皮为君，多加生姜皮。</p><p>12、疟病多挟风。有风者必用何首乌为君，白术、橘皮为臣，葛根、姜皮、羌活以佐之。不头痛者除羌活。</p><p>13、暑邪盛，解散不早，陷入于里，则变为滞下。急投芩、连、芍药、滑石、红曲、甘草，佐以葛根、升麻、柴胡，以表里分消之。脾胃薄弱者，加人参、扁豆、莲肉，大剂与之，以愈为度。滞下若愈，疟亦随止，即不止，其热必轻，仍随经随证以治之，不烦多药而自止也。</p><p>14、又，暑热湿之邪内伏，百药不效者，用独雄丸立愈。</p><p>15、凡劳疟，病人阴不足，或作劳，或房劳，病发于阴，或间日一发，或三日一发。三日一发为病深，须以鳖甲、牛膝、何首乌为君，橘皮为佐。发于夜而便燥者，加当归。脾胃薄弱者勿加，佐以姜皮，热甚勿入。大剂与之，日三乃瘥。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001048,"no":47}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '1、疟 《经》曰：夏伤于暑，秋必痎疟。其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，或先寒后热，或先热后寒，或有汗、无汗，或汗少、汗多，或自汗、盗汗，或头疼骨痛，或大渴引饮，口苦舌干，或呕吐不思食，或烦躁不得眠，或大便燥结，或泻利，或连发，或间发，或三日发，或发于阳，或发于阴，要皆中气不足，脾胃虚弱，暑邪乘虚客之而作。虽随经随证投药解散，必先清暑益气，调理脾胃为主。有伤食者兼消导夺食，有风兼散风，有老痰伏饮者兼豁痰逐饮，感瘴疠者兼消瘴疠，汗多者固表，无汗者解表，泄利者升发、兼利小便，便燥者兼益阴润燥。病有阴阳，药分气血，证有缓急，治因先后，人有虚实，法异攻补。久而不解，必属于虚。气虚者补气，血虚者补血，两虚者气血兼补，非大补真气，大健脾胃不得瘳也。 【忌】破气、下。 诸药俱见前。 2、疟必由于中气虚，破气则伤中气，邪不得解，甚则中满不思食，作泄，恶寒，口干，惟伤食宜消，不同此法。 3、误下则邪气陷于内，变为滞下，或腹满肿胀，呕恶不思食。凡属破气、下泄药，切戒勿施！ 【宜】清暑益气，健脾开胃，兼消痰。 【宜】分脏腑手足六经所见证拖治。 先清暑：热多者宜服白虎汤加减：硬石膏（自一两至四两），知母（自四钱至二两四钱），竹叶（自一百片至四百片），麦门冬（自八钱至三两二钱），粳米（自一小撮至二大撮）。病人素虚或作劳者，加人参（自三钱至一两）。 有痰加广橘红（三钱），竹沥（一杯），大渴者，加栝楼根（三钱至六钱）。 不渴者，用清暑益气汤。 兼饮食停滞者，加枳实、青皮、草果一二剂，食消即止。勿多服。多服则损中气。其药俱宜黄昏煎，以井水澄冷，须露一宿，五更时温服。盖疟乃暑邪为病，暑得露则散也。 4、《内经》六经疟候汤液 足太阳经属膀胱，其证令人腰痛，头痛头重，寒从背起，先寒后热，熇熇暍暍然，热止汗出难已，或遍身骨痛，小便短赤： 羌活（一钱至三四钱），广陈皮（去白二钱五分），黄芩（二钱），前胡（二钱），甘草（炙五分），猪苓（一钱），知母（二钱五分）。 若口渴者，即兼阳明，宜加石膏、麦门冬，倍知母。渴而汗少，或无汗，并加葛根。 若涉深秋或入冬，无汗，宜多加姜皮。 因虚而无汗，或汗少者，加人参（三五钱），麦门冬（四五钱），佐以姜皮（二三钱），露一宿，发日五更温服。 因虚汗多者，加黄耆（三四钱），桂枝（七八分）。汗止，即去桂枝，不可多服。 若病人素有热者，勿服桂枝，以芍药、五味子代之。 若发于阴，并加当归。 小便短涩或赤者，与六一散二三服。 有湿者，以猪苓、茯苓代滑石。下午服理脾健胃药： 橘红（二钱五分），白豆蔻（五分），白茯苓（三钱），山查（三钱），麦芽（炒三钱），藿香（一钱），人参（三钱），白术（二钱），白芍药（三钱），白扁豆（三钱）。 有肺火者，去人参、白术，加麦门冬（五钱），石斛（三钱），乌梅肉（一枚）。 停食者必恶食，加山查。伤肉食者加黄连、红曲。伤谷食者加枳实、草果（各七分）。伤面食者加炒莱菔子。食消即已，不可多服，多服则损中气。 胃家素有湿痰者，其证不渴、寒多，方可用半夏、橘红、二术，大剂与之。呕甚者兼用姜皮。 5、足阳明经属胃，其证发热头疼，鼻干，渴欲引饮，目眴眴不得眠，甚则烦躁，畏火光、人声、木声。宜服大剂竹叶石膏汤。无汗或汗少不呕者，可加干葛（二三钱）。 病人虚而作劳者，加人参。 汗多，加白术。 痰多，加贝母、橘红，得汗即解。 寒热俱甚，渴甚，汗多，寒时指爪皆紫黯者，加桂枝（七八分）。 久而不解属气虚，用人参（两许），姜皮（两许），煎成露一宿，五更温服。下午服理脾健胃药如前方，加减亦如之。 6、足少阳经属胆，其证往来寒热，口苦，耳聋，胸胁痛，或呕。宜服小柴胡汤。 渴者，去半夏，加石膏、麦门冬。 肺家有热者，去人参，加知母，倍门冬。 有痰不渴者，本方加贝母（三钱至八钱），术、茯苓（各三钱），姜皮（一钱至三四钱）。 病人阴虚而有热者，虽呕吐忌用半夏、生姜，误投则损人津液，令人声哑，宜用竹茹、橘皮、麦门冬、白茯苓、乌梅以代之。 7、以上三阳经疟邪客之者，其证多热多渴，亦易得汗，药宜大剂，急逐暑邪，毋得迟留，则病易愈。继以理脾开胃，大补真气，蔑不瘳矣。邪在三阳，药宜辛寒，如石膏、知母、柴胡；甘寒，如葛根、麦门冬、竹叶、粳米；苦寒，如黄芩之属为君，乃可以散暑邪，除热渴，坠头痛。兼寒甚者，则间用辛温，如姜皮、桂枝以为向导，以伏其邪，则病易退。凡寒甚者，病因于虚。或作劳者，亦因于虚，皆宜甘温。以人参、黄耆、术为君，佐以辛甘，如桂枝、姜皮之属。脾胃虚弱，饮食不消者，则补之以参、术，佐以消导，如白豆蔻、麦芽、砂仁、草豆蔻、枳实、橘皮、山查之属。在阴分者，则以当归、牛膝为君，佐以姜、桂。如热甚而渴者去姜、桂，加知母、麦门冬、竹叶、牛膝、鳖甲。 8、足厥阴经属肝，其证先寒后热，色苍苍然，善太息，甚者状如欲死，或头疼而渴。 【宜】先服三黄石膏汤加柴胡、鳖甲、橘皮，以祛暑邪。后用当归（两许），橘皮（三四钱），鳖甲（四五钱），牛膝（两许），柴胡（一二钱），浓煎露一宿，发日五更温服。 如热甚而渴，加栝楼根（三四钱），麦门冬（四五钱），竹叶（一百片），知母（三四钱），鳖甲（五六钱）。 如脾胃薄弱，或溏泄，去当归，加人参（三五钱）。 如有肺火，不可服参者，只照本方，多服自愈。 寒多或寒甚，指爪青黯者，加桂枝、姜皮、人参。 9、足太阴经属脾，其证先寒后热，或寒多。若脾疟，必寒从中起，善呕，呕已乃衰，然后发热，热过汗出乃已。热甚者或渴，否则不渴喜火。 【宜】服桂枝汤、建中汤。 病人虚者，以人参、姜皮各两许浓煎，露一宿，五更温服。 有痰者，宜加术、橘皮（各三四钱）。 10、足少阴经属肾，其证寒热俱甚，腰痛脊强，口渴，寒从下起，小便短赤。 【宜】先服人参白虎汤加桂枝，以祛暑邪，后用鳖甲（四五钱），牛膝（两许），热甚者加知母、麦门冬（各四五钱）。寒甚者加桂枝钱许。 呕则兼加姜皮（三四钱）。如热甚而呕者，去桂枝、姜皮，加竹茹（三钱），人参、橘皮（各三四钱）。用牛膝、桂枝者，肝肾同一治故也。 11、疟病多挟痰。以故热痰须用贝母为君，自三钱至八钱，竹沥、竹茹、栝楼根、橘红、白茯苓，称是以佐之。甚者可加霞天膏。如寒痰发疟，寒多不渴者，用半夏、白术、橘皮为君，多加生姜皮。 12、疟病多挟风。有风者必用何首乌为君，白术、橘皮为臣，葛根、姜皮、羌活以佐之。不头痛者除羌活。 13、暑邪盛，解散不早，陷入于里，则变为滞下。急投芩、连、芍药、滑石、红曲、甘草，佐以葛根、升麻、柴胡，以表里分消之。脾胃薄弱者，加人参、扁豆、莲肉，大剂与之，以愈为度。滞下若愈，疟亦随止，即不止，其热必轻，仍随经随证以治之，不烦多药而自止也。 14、又，暑热湿之邪内伏，百药不效者，用独雄丸立愈。 15、凡劳疟，病人阴不足，或作劳，或房劳，病发于阴，或间日一发，或三日一发。三日一发为病深，须以鳖甲、牛膝、何首乌为君，橘皮为佐。发于夜而便燥者，加当归。脾胃薄弱者勿加，佐以姜皮，热甚勿入。大剂与之，日三乃瘥。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ke9RDwkwBhU', 1, '{"title":"卷之二_续序例下_附录：诸疟主治","description":"<p>1、附录：诸疟主治</p>\n<p>热多宜贝母、石膏、麦门冬、橘红、干葛、滑石、竹叶、牛膝、知母、黄芩、柴胡、白茯苓、乌梅、何首乌、牡蛎、鳖甲。</p>\n<p>寒多宜桂枝、姜皮、人参、二术、黄耆、当归、橘红、半夏、草豆蔻、白豆蔻、炙甘草。</p>\n<p>汗多宜人参、白术、黄耆，秋冬加桂枝。</p>\n<p>无汗宜干葛、柴胡、石膏、羌活、姜皮、人参、苍术。</p>\n<p>疟母宜鳖甲、射干、牡蛎、三棱、缩砂蜜、桂、橘皮、青皮、人参。</p>\n<p>凡疟疾多热，久不解者，其人必本阴虚，法当益阴除热，非鳖甲、牛膝不能除也。多寒而久不解者，其人必本阳虚，非人参、白术、黄耆不能除也。</p>\n<p>按：疟有山岚瘴气、停痰留饮而发者，古方类用常山、砒霜等吐之。今人误执其方，见疟辄用，不知二药有大毒，损人真气，犯之多致危殆。慎之！慎之！</p><p>2、滞下</p>\n<p>俗呼痢疾。其证腹痛便脓血，或赤或白，或赤白相杂，或下纯血，或下紫黑血块，或如豆汁，或如鱼冻，或如屋漏水，或下纯黄积粪。多里急后重，数登圊而不得便，小便短赤不利，或发热，或口渴，甚则呕恶不思食。此皆暑湿之邪与饮食积滞胶固肠胃而作，必先祛暑渗湿安胃为主。伤气分则调气益气，伤血分则和血补血，挟瘀血则行血。药虽因证而设，要皆以补养胃气为急。故其证以噤口痢为最重，胃气一绝则不可治矣。故曰：安谷则昌，绝谷则亡。俗治多藉口 “迎而夺之” 之说，轻用大黄、朴硝，及误用巴豆、牵牛，以致洞泄肠开而毙。又有妄投诃子、粟壳、亚芙蓉、肉豆蔻收涩之剂，以致便闭腹胀，或湿热上攻，肢节肿胀拘挛，痛不可忍，难以救疗。慎之！慎之！</p>\n<p>【忌】破气、闭气、收涩、燥、温热、咸寒、滑腻。诸药俱见前。</p>\n<p>【宜】清热消积、开胃气、升、利小便。黄连、黄芩、白芍药、红曲、山查、广橘红、升麻、葛根、甘草、滑石、莲肉、白扁豆、乌梅。</p>\n<p>如胃弱，加人参（三四钱），莲子（四十粒），橘红（二钱），升麻（七分）。</p>\n<p>如腹痛，以黄连（四钱），白芍药（三钱），炙甘草（一钱五分），黄檗（一钱），升麻（七分）煎服。</p>\n<p>如里急，同上药加当归（二钱）。</p>\n<p>如后重甚，加槟榔（一钱五分），枳壳（一钱五分），木香汁（七匙）。</p>\n<p>如口渴，去木香，倍滑石。</p>\n<p>如小便赤涩短少，或不利，亦倍之。</p>\n<p>赤多，倍乌梅、山查、红曲。白多，加吴茱萸（七分）。</p>\n<p>恶心欲呕，即噤口痢，多用人参、莲肉、扁豆、白芍药，以绿色升麻（七分）佐之。</p>\n<p>久痢不止，加肉豆蔻（一钱），人参（三钱），砂仁（一钱五分），白茯苓（二钱）。</p>\n<p>凡滞下，非元气壮实、多啖能食之人，慎勿轻用大黄、巴豆、牵牛等下药。</p>\n<p>复有毒痢一证，或痧毒内陷下脓血，各药不效者，加忍冬藤为君，地榆、丹砂、犀角汁饮之。</p>\n<p>凡产后滞下，积滞虽多，腹痛虽极，不可用大黄等药行之，致伤胃气，遂不可救。但用人参、白芍、当归、红曲、升麻、益母草、炙甘草、滑石末足矣。若恶露未净，兼用乳香、没药（各七分五厘），炒砂仁（一钱），久之自愈。血虚可加阿胶（三钱）。</p>\n<p>凡胎前滞下，宜用黄芩、黄连、白芍、炙甘草、橘红、赤曲、枳壳、莲肉，略用升麻。未满七月，勿用滑石。</p><p>3、泻利</p>\n<p>俗称泄泻，因于湿。</p>\n<p>【忌】湿润、破气、下、苦寒、滑利。诸药俱见前。</p>\n<p>【宜】安胃补脾、升、利小便。人参、白茯苓、莲肉、白扁豆、白术、车前子、升麻、橘红、藿香、木瓜、干葛、炙甘草、白莱菔。</p>\n<p>虚寒者，加肉豆蔻、补骨脂、吴茱萸。</p>\n<p>虚热者，去白术，加川黄连，倍芍药、莲肉。</p>\n<p>暑湿为病则小水短赤，或口渴。倍用姜炒黄连为君，佐以干葛、升麻。</p>\n<p>由于感风寒者，二术、吴茱萸、砂仁、陈皮、干姜、紫苏主之。</p>\n<p>若由饮食停滞者，兼消导，山查、麦芽、神曲、陈皮、肉豆蔻。</p><p>4、五疸</p>\n<p>方书所载五疸，酒、食、大饥后、过饱、女劳失治而成。然其证必由湿热伤脾及饮食停滞。又有瘀血发黄一证，方所不载。分别一误，则药不对证，多致不救。慎之！慎之！</p>\n<p>【忌】破气、闭气、下、咸、滑利、滞腻、润、燥热，有瘀血者兼忌酸寒。诸药俱见前。</p>\n<p>【宜】清热、利水、除湿、养胃气，有停滞者宜消积滞，有瘀血者宜行血。茵陈蒿、黄连、苜蓿（酒疸非此不愈）、栀子、紫草、栝楼根、秦艽、黄芩、滑石、车前子、白鲜皮、仙人对坐草、白茯苓、连钱草（一名蟹靥草，一名九里香，取汁，入姜汁少许，饮之良。）</p>\n<p>虚者，加人参。</p>\n<p>停滞者，加红曲、橘红、谷麦糵、山查。</p>\n<p>瘀血，加琥珀、牡丹皮、红曲、红花、桃仁、延胡索、蒲黄、五灵脂、韭。</p>\n<p>元气壮实者，服前药瘀血不行，可加熟大黄。虚者勿用。</p><p>5、痰</p>\n<p>由于热：忌燥、温热、补敛，升。诸药俱见前。</p>\n<p>【宜】降、润、清热、苦寒、辛寒、佐以咸寒。苏子、橘红、天门冬、枇杷叶、麦门冬、黄芩、桑白皮、薄荷、百部、栝楼根、栝楼仁、桔梗、贝母、蛤粉、竹沥、童便。</p>\n<p>胶固者加霞天膏，并用猫儿刺。</p>\n<p>由于风寒：忌补敛，湿润、酸、咸。诸药俱见前。</p>\n<p>【宜】降气、辛散。橘红、苏子、杏仁、天麻、前胡、半夏、南星、葛根、桑白皮、薄荷、白前、生姜汁。</p>\n<p>由于湿：忌润、咸、酸、滞腻、发湿。诸药俱见前。</p>\n<p>【宜】健脾、燥湿、辛散、佐以淡渗。人参、二术、橘红、半夏、桑白皮、白茯苓、泽泻。</p><p>6、饮</p>\n<p>如涎而薄者，或如涎而稠者，伏于胸中及脾胃间，或吐酸水、苦水、黄水、绿水，或伏而不吐，上支心胸胃脘，作痛不可忍，按之不得下，或发寒热，呕吐不能饮食。</p>\n<p>忌、宜俱同脾虚证内停饮条。</p><p>7、诸气</p>\n<p>    气有余即是火。</p>\n<p>【忌】升、闭气、酸敛、滞腻。诸药俱见前。</p>\n<p>虚者宜降、补敛、调、温、酸、辛、甘。苏子、枇杷叶、橘红、麦门冬、芦根汁、甘蔗、番降香、沉水香、白豆蔻、郁金、甘草、童便、白芍药、五味子。</p>\n<p>因虚极而气不得行者，加人参。</p>\n<p>实者宜破散、香燥、辛苦、辛寒。枳壳、青皮、槟榔、厚朴、木香、沉香、香附、乌药、降香、藿香、缩砂蜜。</p><p>8、郁</p>\n<p>【忌】酸敛、滞腻、补气、闭气。诸药俱见前。</p>\n<p>属情抱者宜开发志意，调气散结，和中健脾。远志、贝母、郁金、石菖蒲、香附、苏子、橘红、白豆蔻、木香、苏合香、缩砂蜜、麦门冬。</p>\n<p>属五脏者，木郁达之，宜升、吐。升麻、柴胡、川芎、瓜蒂、人参芦。</p>\n<p>火郁发之，宜散。升麻、葛根、柴胡、防风、羌活。</p>\n<p>土郁夺之，宜下。槟榔、枳实、厚朴、大黄。</p>\n<p>金郁泄之，宜降。橘红、苏子、桑白皮、猪苓、泽泻、茯苓、木通。</p>\n<p>水郁折之，宜利。茯苓、海金沙、猪苓、泽泻、木通、赤小豆、车前子、乌蠡鱼。</p><p>9、关格</p>\n<p>不得大小便为关，是热在丹田也。吐逆水浆不得下为格，是寒反在胸中也。是阴阳易位，故上下俱病。先投辛香通窍下降之药以治其上，次用下泄苦寒之药以通二便。此急证，法难缓治。纵有里虚，通后再补。</p>\n<p>【忌】升、补敛、闭气、酸。诸药俱见前。</p>\n<p>【宜】降下、辛寒、辛温。沉香、白豆蔻、丁香、苏子、龙脑香、苏合香、橘红、生姜、藿香。</p>\n<p>次用大黄、黄檗、知母、滑石、木通、车前子、牛膝。</p><p>10、哕</p>\n<p>俗呼呃逆。久病沉痼而发者，属真气虚，多不治。</p>\n<p>【忌】破气、升、散。诸药俱见前。</p>\n<p>【宜】补敛、甘温、甘寒。人参、黄耆、炙甘草、麦门冬、五味子、益智子、白芍药、石斛。</p>\n<p>伤寒失下而发者，忌补敛、酸、燥热、滞腻。诸药俱见前。</p>\n<p>大便硬闭宜下，大小承气之类。便不硬闭，按之腹中和软，未经汗吐者，宜辛寒解表，白虎汤之类。</p>\n<p>因气逆冲上而发者，忌升、补。诸药俱见前。</p>\n<p>【宜】降气、甘寒、咸寒。苏子、橘红、枇杷叶、竹茹、芦根汁、麦门冬、童便。</p>\n<p>因痰水停膈而发者，忌升、润、苦寒、甘寒、酸寒。诸药俱见前。</p>\n<p>【宜】降气、开痰、辛散。橘红、苏子、贝母、桑白皮、半夏、旋覆花、生姜、白豆蔻。</p><p>11、诸血</p>\n<p>吐血、咯血、鼻衄、齿衄、耳衄、舌上出血。</p>\n<p>【忌】升提发散、下、破血、补气、闭气、破气、温热、辛燥，复忌极苦寒伤胃。诸药俱见前。</p>\n<p>【宜】降气、清热、凉血益阴，兼行血、咸寒、酸寒、甘寒。苏子、麦门冬、橘皮、枇杷叶、降香、郁金、天门冬、沙参、牛膝、阿胶、生地黄、枸杞子、五味子、鳖甲、白芍药、犀角汁、牡丹皮、青蒿、剪草、白药子、童便、侧柏叶、小蓟、茅根、棕灰、藕节、当归、蒲黄。</p><p>12、蓄血</p>\n<p>俗名内伤。或积劳，或多怒，或饱后行房，或负重努力，或登高坠下，或奔逐过急，皆致蓄血。其证多发热，其热类外感而不头疼、不作渴。天明少间，至午复剧。有汗，汗多剂颈而还，自汗，无气以息，目光短，不思饮食，不得眠，二便自利，小便或赤，大便或泄。</p>\n<p>【忌】破气，复忌补气、下、苦寒、辛燥。诸药俱见前。</p>\n<p>【宜】行血、辛温，佐以咸寒，瘀血行后宜补血益脾，和肝。桃仁、红蓝花、延胡索、桂（有火之人勿用）、郁金、当归尾、苏方木、乳香、番降香、没药、穿山甲、䗪虫、赤芍药、五灵脂、蒲黄、红曲、麒麟竭、韭汁、童便、桃枭。</p>\n<p>甚者用大黄、花蕊石。瘀行则止，勿过剂。如元气虚，脾胃素弱者，慎勿轻用大黄。如瘀血行后，宜生地黄、川续断、白胶、当归身、麦门冬、牛膝、白芍药、炙甘草、酸枣仁、大枣、龙眼肉、枸杞子、山茱萸。</p><p>13、头痛</p>\n<p>挟风寒者：忌补敛。诸药俱见前。</p>\n<p>【宜】辛温、发散。羌活、防风、细辛、荆芥、薄荷、川芎、藁本、升麻、白芷、蔓荆子、生姜、葱白。</p>\n<p></p>\n<p>挟邪热者：忌同挟风寒。</p>\n<p>【宜】辛寒、苦寒、解散。石膏、薄荷、黄芩（酒炒）、芽茶、黑豆、乌梅、甘菊花、土茯苓。</p>\n<p></p>\n<p>热极目昏便燥者，加酒蒸大黄。</p>\n<p>挟痰者：忌升、补敛、酸甘、滞腻。诸药俱见前。</p>\n<p>【宜】豁痰降气、辛燥。苏子、橘红、贝母、半夏、前胡、竹沥、术、天麻。</p>\n<p></p>\n<p>阴虚者：忌辛热发散。诸药俱见前。</p>\n<p>【宜】补血益阴、酸敛、甘寒、酸寒。生地黄、甘菊花、当归、天门冬、麦门冬、枸杞子、黄檗、白芍药、忍冬、五味子、乌梅。</p><p>14、眉棱骨痛</p>\n<p>忌、宜俱同阴虚头痛。</p><p>15、齿痛</p>\n<p>【忌】升、补敛、燥热、辛温。诸药俱见前。</p>\n<p>【宜】清热凉血、苦寒、辛寒、甘寒、咸寒。麦门冬、生地黄、赤芍药、牡丹皮、竹叶、知母、黄连、黄芩、黄檗、玄参、石膏、薄荷、苏子、甘草、童便。</p>\n<p>上下龈属胃与大肠火，宜石膏、熟大黄、麦门冬、黄芩、黄连、赤芍药、生地黄、生甘草、青黛、细辛、西瓜皮灰、薄荷、枇杷叶、苏子、木通。</p>\n<p>真牙浮动及黑烂，属肾虚有火，已见肾虚条内，忌、宜俱同。</p><p>16、胃脘痛</p>\n<p>因火者，忌补敛、燥热。诸药俱见前。</p>\n<p>【宜】降、苦寒、甘寒、咸寒、辛寒。苏子、橘红、黄连、山栀、麦门冬、炙甘草、石膏、知母、玄参、童便。</p>\n<p></p>\n<p>因寒者：忌破气、滞腻、苦寒。诸药俱见前。</p>\n<p>【宜】辛温发散。橘皮、草豆蔻、益智子、丁香、桂、白术、藿香、白豆蔻、缩砂蜜、吴茱萸、厚朴、香附、干姜。</p>\n<p></p>\n<p>因宿食者：忌升、补敛、苦寒。诸药俱见前。</p>\n<p>【宜】消导，兼降气。山查、橘皮、草果、红曲、枳实、术、槟榔、草豆蔻、青皮、厚朴、谷麦糵、缩砂蜜。</p>\n<p></p>\n<p>因脾胃虚弱以致食停者：消导药中加入人参。</p>\n<p>因瘀血者：忌补气、酸敛。诸药俱见前。</p>\n<p>【宜】辛温、苦温以行血。桃仁、延胡索、红曲、红花、山查肉、牡丹皮、韭菜、通草、番降香、郁金、肉桂、三棱、童溺、琥珀、菴闾子、牛膝、赤芍药。</p>\n<p></p>\n<p>因血虚者，按之则痈止：忌破气，复忌补气、燥热、辛温。诸药俱见前。</p>\n<p>【宜】润、补敛、甘寒、甘温。麦门冬、炙甘草、酸枣仁、石斛、白芍药、生地黄、当归。</p>\n<p></p>\n<p>因虫者：忌补、升、发散、甘。诸药俱见前。</p>\n<p>【宜】杀虫、苦、酸。锡灰、苦楝根、槟榔、鹤虱、雷丸、使君子、芜荑、薏苡仁根、大黄、乌梅。</p>\n<p></p>\n<p>因恼怒者：虚弱人忌破气，壮实人忌补气，总忌酸敛、升。诸药俱见前。</p>\n<p>【宜】降气、辛温。苏子、枇杷叶、白豆蔻、番降香、缩砂蜜、木香、橘红、延胡索、五灵脂。</p>\n<p>因痰饮者：忌、宜俱见痰饮证下。</p><p>17、腹痛</p>\n<p>因于寒：忌苦寒、下利。诸药俱见前。</p>\n<p>【宜】温中、辛散。白术、厚朴、干姜、吴茱萸、桂、炙甘草、木香、缩砂蜜、橘皮。</p>\n<p></p>\n<p>因于热，火在少腹则绞痛：忌辛热、香燥、补敛。诸药俱见前。</p>\n<p>【宜】甘、苦寒。山栀仁、麦门冬、石斛、白芍药、甘草、桔梗、黄芩、黄连、滑石、木通、戎盐。</p>\n<p></p>\n<p>诸痛不可按，属实：忌补气、大热。诸药俱见前。</p>\n<p>【宜】破散、疏利、苦寒。枳实、青皮、槟榔、三棱、滑石、蓬莪术、木通、大黄（有积滞宜用，无者勿用）。</p>\n<p></p>\n<p>诸痛可按，属虚：忌破气、破血、下利、发散。诸药俱见前。</p>\n<p>【宜】补气血、甘温、酸敛。人参、黄耆、二术、生地黄、当归、炙甘草、白芍药、薯蓣、酸枣仁、五味子。</p><p>18、痹</p>\n<p>拘挛而痛也。因风寒湿三者合而成。风气胜者为行痹，寒气胜者为痛痹，湿气胜者为着痹。</p>\n<p>【忌】下、收敛、酸寒、苦寒、咸寒。诸药俱见前。</p>\n<p>【宜】辛散、行气、燥湿、甘温、淡渗。漆叶、续断、黄耆、甘草、甘菊花、萆薢、防己、白术、防风、羌活、独活、秦艽、牛膝、木瓜、天麻、茯苓、泽泻、菖蒲、车前子、桑寄生、狗脊、蔓荆实、杜仲、白藓皮、石斛、细辛、松节、松叶、葈耳、原蚕沙、威灵仙、海风藤。</p><p>19、痿</p>\n<p>属湿热。《经》曰：治痿独取阳明。</p>\n<p>【忌】破气、升、辛热发散。诸药俱见前。</p>\n<p>【宜】大补气血、清热除湿、甘寒、甘温、苦寒、酸寒。人参、黄耆、二术、炙甘草、生地黄、麦门冬、白芍药、木瓜、石斛、薏苡仁、黄檗、茯苓、泽泻、车前子、木通、黄连、黄芩。</p><p>20、交肠</p>\n<p>其病大小便易位而出。或因大怒，或因醉饱，遂至脏气乖乱，不循常道。法当宣吐以开提其气，使阑门清利，得司泌别之职，则愈矣。</p>\n<p>【忌】破气、燥、热。诸药俱见前。</p>\n<p>【宜】升清降浊，兼补气、淡渗。升麻、柴胡、苏子、降香、橘红、人参、术、茯苓、泽泻、猪苓、木通、滑石、车前子。</p><p>21、鬼疰、尸疰、飞尸、客忤</p>\n<p>此系天地阴邪杀厉之气乘虚中人，或遍身青暗，或忽消瘦声哑，面色青黄不定，或忽惊厥，目直视，手握拳，或遍身骨节疼痛非常。</p>\n<p>【忌】破气，复忌补气、升、澡热、酸敛。诸药俱见前。</p>\n<p>【宜】辟恶气、安神镇心、辛香发散、金石镇坠。牛黄、丹砂、苏合香、天竺黄、琥珀、沉水香、龙脑香、乳香、安息香、檀香、木香、麝香、真珠、雄黄、鬼臼、龙齿、犀角、金银箔、虎骨、代赭石、天灵盖、獭肝、生地黄、菖蒲、远志。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001049,"no":48}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '1、附录：诸疟主治 热多宜贝母、石膏、麦门冬、橘红、干葛、滑石、竹叶、牛膝、知母、黄芩、柴胡、白茯苓、乌梅、何首乌、牡蛎、鳖甲。 寒多宜桂枝、姜皮、人参、二术、黄耆、当归、橘红、半夏、草豆蔻、白豆蔻、炙甘草。 汗多宜人参、白术、黄耆，秋冬加桂枝。 无汗宜干葛、柴胡、石膏、羌活、姜皮、人参、苍术。 疟母宜鳖甲、射干、牡蛎、三棱、缩砂蜜、桂、橘皮、青皮、人参。 凡疟疾多热，久不解者，其人必本阴虚，法当益阴除热，非鳖甲、牛膝不能除也。多寒而久不解者，其人必本阳虚，非人参、白术、黄耆不能除也。 按：疟有山岚瘴气、停痰留饮而发者，古方类用常山、砒霜等吐之。今人误执其方，见疟辄用，不知二药有大毒，损人真气，犯之多致危殆。慎之！慎之！ 2、滞下 俗呼痢疾。其证腹痛便脓血，或赤或白，或赤白相杂，或下纯血，或下紫黑血块，或如豆汁，或如鱼冻，或如屋漏水，或下纯黄积粪。多里急后重，数登圊而不得便，小便短赤不利，或发热，或口渴，甚则呕恶不思食。此皆暑湿之邪与饮食积滞胶固肠胃而作，必先祛暑渗湿安胃为主。伤气分则调气益气，伤血分则和血补血，挟瘀血则行血。药虽因证而设，要皆以补养胃气为急。故其证以噤口痢为最重，胃气一绝则不可治矣。故曰：安谷则昌，绝谷则亡。俗治多藉口 “迎而夺之” 之说，轻用大黄、朴硝，及误用巴豆、牵牛，以致洞泄肠开而毙。又有妄投诃子、粟壳、亚芙蓉、肉豆蔻收涩之剂，以致便闭腹胀，或湿热上攻，肢节肿胀拘挛，痛不可忍，难以救疗。慎之！慎之！ 【忌】破气、闭气、收涩、燥、温热、咸寒、滑腻。诸药俱见前。 【宜】清热消积、开胃气、升、利小便。黄连、黄芩、白芍药、红曲、山查、广橘红、升麻、葛根、甘草、滑石、莲肉、白扁豆、乌梅。 如胃弱，加人参（三四钱），莲子（四十粒），橘红（二钱），升麻（七分）。 如腹痛，以黄连（四钱），白芍药（三钱），炙甘草（一钱五分），黄檗（一钱），升麻（七分）煎服。 如里急，同上药加当归（二钱）。 如后重甚，加槟榔（一钱五分），枳壳（一钱五分），木香汁（七匙）。 如口渴，去木香，倍滑石。 如小便赤涩短少，或不利，亦倍之。 赤多，倍乌梅、山查、红曲。白多，加吴茱萸（七分）。 恶心欲呕，即噤口痢，多用人参、莲肉、扁豆、白芍药，以绿色升麻（七分）佐之。 久痢不止，加肉豆蔻（一钱），人参（三钱），砂仁（一钱五分），白茯苓（二钱）。 凡滞下，非元气壮实、多啖能食之人，慎勿轻用大黄、巴豆、牵牛等下药。 复有毒痢一证，或痧毒内陷下脓血，各药不效者，加忍冬藤为君，地榆、丹砂、犀角汁饮之。 凡产后滞下，积滞虽多，腹痛虽极，不可用大黄等药行之，致伤胃气，遂不可救。但用人参、白芍、当归、红曲、升麻、益母草、炙甘草、滑石末足矣。若恶露未净，兼用乳香、没药（各七分五厘），炒砂仁（一钱），久之自愈。血虚可加阿胶（三钱）。 凡胎前滞下，宜用黄芩、黄连、白芍、炙甘草、橘红、赤曲、枳壳、莲肉，略用升麻。未满七月，勿用滑石。 3、泻利 俗称泄泻，因于湿。 【忌】湿润、破气、下、苦寒、滑利。诸药俱见前。 【宜】安胃补脾、升、利小便。人参、白茯苓、莲肉、白扁豆、白术、车前子、升麻、橘红、藿香、木瓜、干葛、炙甘草、白莱菔。 虚寒者，加肉豆蔻、补骨脂、吴茱萸。 虚热者，去白术，加川黄连，倍芍药、莲肉。 暑湿为病则小水短赤，或口渴。倍用姜炒黄连为君，佐以干葛、升麻。 由于感风寒者，二术、吴茱萸、砂仁、陈皮、干姜、紫苏主之。 若由饮食停滞者，兼消导，山查、麦芽、神曲、陈皮、肉豆蔻。 4、五疸 方书所载五疸，酒、食、大饥后、过饱、女劳失治而成。然其证必由湿热伤脾及饮食停滞。又有瘀血发黄一证，方所不载。分别一误，则药不对证，多致不救。慎之！慎之！ 【忌】破气、闭气、下、咸、滑利、滞腻、润、燥热，有瘀血者兼忌酸寒。诸药俱见前。 【宜】清热、利水、除湿、养胃气，有停滞者宜消积滞，有瘀血者宜行血。茵陈蒿、黄连、苜蓿（酒疸非此不愈）、栀子、紫草、栝楼根、秦艽、黄芩、滑石、车前子、白鲜皮、仙人对坐草、白茯苓、连钱草（一名蟹靥草，一名九里香，取汁，入姜汁少许，饮之良。） 虚者，加人参。 停滞者，加红曲、橘红、谷麦糵、山查。 瘀血，加琥珀、牡丹皮、红曲、红花、桃仁、延胡索、蒲黄、五灵脂、韭。 元气壮实者，服前药瘀血不行，可加熟大黄。虚者勿用。 5、痰 由于热：忌燥、温热、补敛，升。诸药俱见前。 【宜】降、润、清热、苦寒、辛寒、佐以咸寒。苏子、橘红、天门冬、枇杷叶、麦门冬、黄芩、桑白皮、薄荷、百部、栝楼根、栝楼仁、桔梗、贝母、蛤粉、竹沥、童便。 胶固者加霞天膏，并用猫儿刺。 由于风寒：忌补敛，湿润、酸、咸。诸药俱见前。 【宜】降气、辛散。橘红、苏子、杏仁、天麻、前胡、半夏、南星、葛根、桑白皮、薄荷、白前、生姜汁。 由于湿：忌润、咸、酸、滞腻、发湿。诸药俱见前。 【宜】健脾、燥湿、辛散、佐以淡渗。人参、二术、橘红、半夏、桑白皮、白茯苓、泽泻。 6、饮 如涎而薄者，或如涎而稠者，伏于胸中及脾胃间，或吐酸水、苦水、黄水、绿水，或伏而不吐，上支心胸胃脘，作痛不可忍，按之不得下，或发寒热，呕吐不能饮食。 忌、宜俱同脾虚证内停饮条。 7、诸气 气有余即是火。 【忌】升、闭气、酸敛、滞腻。诸药俱见前。 虚者宜降、补敛、调、温、酸、辛、甘。苏子、枇杷叶、橘红、麦门冬、芦根汁、甘蔗、番降香、沉水香、白豆蔻、郁金、甘草、童便、白芍药、五味子。 因虚极而气不得行者，加人参。 实者宜破散、香燥、辛苦、辛寒。枳壳、青皮、槟榔、厚朴、木香、沉香、香附、乌药、降香、藿香、缩砂蜜。 8、郁 【忌】酸敛、滞腻、补气、闭气。诸药俱见前。 属情抱者宜开发志意，调气散结，和中健脾。远志、贝母、郁金、石菖蒲、香附、苏子、橘红、白豆蔻、木香、苏合香、缩砂蜜、麦门冬。 属五脏者，木郁达之，宜升、吐。升麻、柴胡、川芎、瓜蒂、人参芦。 火郁发之，宜散。升麻、葛根、柴胡、防风、羌活。 土郁夺之，宜下。槟榔、枳实、厚朴、大黄。 金郁泄之，宜降。橘红、苏子、桑白皮、猪苓、泽泻、茯苓、木通。 水郁折之，宜利。茯苓、海金沙、猪苓、泽泻、木通、赤小豆、车前子、乌蠡鱼。 9、关格 不得大小便为关，是热在丹田也。吐逆水浆不得下为格，是寒反在胸中也。是阴阳易位，故上下俱病。先投辛香通窍下降之药以治其上，次用下泄苦寒之药以通二便。此急证，法难缓治。纵有里虚，通后再补。 【忌】升、补敛、闭气、酸。诸药俱见前。 【宜】降下、辛寒、辛温。沉香、白豆蔻、丁香、苏子、龙脑香、苏合香、橘红、生姜、藿香。 次用大黄、黄檗、知母、滑石、木通、车前子、牛膝。 10、哕 俗呼呃逆。久病沉痼而发者，属真气虚，多不治。 【忌】破气、升、散。诸药俱见前。 【宜】补敛、甘温、甘寒。人参、黄耆、炙甘草、麦门冬、五味子、益智子、白芍药、石斛。 伤寒失下而发者，忌补敛、酸、燥热、滞腻。诸药俱见前。 大便硬闭宜下，大小承气之类。便不硬闭，按之腹中和软，未经汗吐者，宜辛寒解表，白虎汤之类。 因气逆冲上而发者，忌升、补。诸药俱见前。 【宜】降气、甘寒、咸寒。苏子、橘红、枇杷叶、竹茹、芦根汁、麦门冬、童便。 因痰水停膈而发者，忌升、润、苦寒、甘寒、酸寒。诸药俱见前。 【宜】降气、开痰、辛散。橘红、苏子、贝母、桑白皮、半夏、旋覆花、生姜、白豆蔻。 11、诸血 吐血、咯血、鼻衄、齿衄、耳衄、舌上出血。 【忌】升提发散、下、破血、补气、闭气、破气、温热、辛燥，复忌极苦寒伤胃。诸药俱见前。 【宜】降气、清热、凉血益阴，兼行血、咸寒、酸寒、甘寒。苏子、麦门冬、橘皮、枇杷叶、降香、郁金、天门冬、沙参、牛膝、阿胶、生地黄、枸杞子、五味子、鳖甲、白芍药、犀角汁、牡丹皮、青蒿、剪草、白药子、童便、侧柏叶、小蓟、茅根、棕灰、藕节、当归、蒲黄。 12、蓄血 俗名内伤。或积劳，或多怒，或饱后行房，或负重努力，或登高坠下，或奔逐过急，皆致蓄血。其证多发热，其热类外感而不头疼、不作渴。天明少间，至午复剧。有汗，汗多剂颈而还，自汗，无气以息，目光短，不思饮食，不得眠，二便自利，小便或赤，大便或泄。 【忌】破气，复忌补气、下、苦寒、辛燥。诸药俱见前。 【宜】行血、辛温，佐以咸寒，瘀血行后宜补血益脾，和肝。桃仁、红蓝花、延胡索、桂（有火之人勿用）、郁金、当归尾、苏方木、乳香、番降香、没药、穿山甲、䗪虫、赤芍药、五灵脂、蒲黄、红曲、麒麟竭、韭汁、童便、桃枭。 甚者用大黄、花蕊石。瘀行则止，勿过剂。如元气虚，脾胃素弱者，慎勿轻用大黄。如瘀血行后，宜生地黄、川续断、白胶、当归身、麦门冬、牛膝、白芍药、炙甘草、酸枣仁、大枣、龙眼肉、枸杞子、山茱萸。 13、头痛 挟风寒者：忌补敛。诸药俱见前。 【宜】辛温、发散。羌活、防风、细辛、荆芥、薄荷、川芎、藁本、升麻、白芷、蔓荆子、生姜、葱白。 挟邪热者：忌同挟风寒。 【宜】辛寒、苦寒、解散。石膏、薄荷、黄芩（酒炒）、芽茶、黑豆、乌梅、甘菊花、土茯苓。 热极目昏便燥者，加酒蒸大黄。 挟痰者：忌升、补敛、酸甘、滞腻。诸药俱见前。 【宜】豁痰降气、辛燥。苏子、橘红、贝母、半夏、前胡、竹沥、术、天麻。 阴虚者：忌辛热发散。诸药俱见前。 【宜】补血益阴、酸敛、甘寒、酸寒。生地黄、甘菊花、当归、天门冬、麦门冬、枸杞子、黄檗、白芍药、忍冬、五味子、乌梅。 14、眉棱骨痛 忌、宜俱同阴虚头痛。 15、齿痛 【忌】升、补敛、燥热、辛温。诸药俱见前。 【宜】清热凉血、苦寒、辛寒、甘寒、咸寒。麦门冬、生地黄、赤芍药、牡丹皮、竹叶、知母、黄连、黄芩、黄檗、玄参、石膏、薄荷、苏子、甘草、童便。 上下龈属胃与大肠火，宜石膏、熟大黄、麦门冬、黄芩、黄连、赤芍药、生地黄、生甘草、青黛、细辛、西瓜皮灰、薄荷、枇杷叶、苏子、木通。 真牙浮动及黑烂，属肾虚有火，已见肾虚条内，忌、宜俱同。 16、胃脘痛 因火者，忌补敛、燥热。诸药俱见前。 【宜】降、苦寒、甘寒、咸寒、辛寒。苏子、橘红、黄连、山栀、麦门冬、炙甘草、石膏、知母、玄参、童便。 因寒者：忌破气、滞腻、苦寒。诸药俱见前。 【宜】辛温发散。橘皮、草豆蔻、益智子、丁香、桂、白术、藿香、白豆蔻、缩砂蜜、吴茱萸、厚朴、香附、干姜。 因宿食者：忌升、补敛、苦寒。诸药俱见前。 【宜】消导，兼降气。山查、橘皮、草果、红曲、枳实、术、槟榔、草豆蔻、青皮、厚朴、谷麦糵、缩砂蜜。 因脾胃虚弱以致食停者：消导药中加入人参。 因瘀血者：忌补气、酸敛。诸药俱见前。 【宜】辛温、苦温以行血。桃仁、延胡索、红曲、红花、山查肉、牡丹皮、韭菜、通草、番降香、郁金、肉桂、三棱、童溺、琥珀、菴闾子、牛膝、赤芍药。 因血虚者，按之则痈止：忌破气，复忌补气、燥热、辛温。诸药俱见前。 【宜】润、补敛、甘寒、甘温。麦门冬、炙甘草、酸枣仁、石斛、白芍药、生地黄、当归。 因虫者：忌补、升、发散、甘。诸药俱见前。 【宜】杀虫、苦、酸。锡灰、苦楝根、槟榔、鹤虱、雷丸、使君子、芜荑、薏苡仁根、大黄、乌梅。 因恼怒者：虚弱人忌破气，壮实人忌补气，总忌酸敛、升。诸药俱见前。 【宜】降气、辛温。苏子、枇杷叶、白豆蔻、番降香、缩砂蜜、木香、橘红、延胡索、五灵脂。 因痰饮者：忌、宜俱见痰饮证下。 17、腹痛 因于寒：忌苦寒、下利。诸药俱见前。 【宜】温中、辛散。白术、厚朴、干姜、吴茱萸、桂、炙甘草、木香、缩砂蜜、橘皮。 因于热，火在少腹则绞痛：忌辛热、香燥、补敛。诸药俱见前。 【宜】甘、苦寒。山栀仁、麦门冬、石斛、白芍药、甘草、桔梗、黄芩、黄连、滑石、木通、戎盐。 诸痛不可按，属实：忌补气、大热。诸药俱见前。 【宜】破散、疏利、苦寒。枳实、青皮、槟榔、三棱、滑石、蓬莪术、木通、大黄（有积滞宜用，无者勿用）。 诸痛可按，属虚：忌破气、破血、下利、发散。诸药俱见前。 【宜】补气血、甘温、酸敛。人参、黄耆、二术、生地黄、当归、炙甘草、白芍药、薯蓣、酸枣仁、五味子。 18、痹 拘挛而痛也。因风寒湿三者合而成。风气胜者为行痹，寒气胜者为痛痹，湿气胜者为着痹。 【忌】下、收敛、酸寒、苦寒、咸寒。诸药俱见前。 【宜】辛散、行气、燥湿、甘温、淡渗。漆叶、续断、黄耆、甘草、甘菊花、萆薢、防己、白术、防风、羌活、独活、秦艽、牛膝、木瓜、天麻、茯苓、泽泻、菖蒲、车前子、桑寄生、狗脊、蔓荆实、杜仲、白藓皮、石斛、细辛、松节、松叶、葈耳、原蚕沙、威灵仙、海风藤。 19、痿 属湿热。《经》曰：治痿独取阳明。 【忌】破气、升、辛热发散。诸药俱见前。 【宜】大补气血、清热除湿、甘寒、甘温、苦寒、酸寒。人参、黄耆、二术、炙甘草、生地黄、麦门冬、白芍药、木瓜、石斛、薏苡仁、黄檗、茯苓、泽泻、车前子、木通、黄连、黄芩。 20、交肠 其病大小便易位而出。或因大怒，或因醉饱，遂至脏气乖乱，不循常道。法当宣吐以开提其气，使阑门清利，得司泌别之职，则愈矣。 【忌】破气、燥、热。诸药俱见前。 【宜】升清降浊，兼补气、淡渗。升麻、柴胡、苏子、降香、橘红、人参、术、茯苓、泽泻、猪苓、木通、滑石、车前子。 21、鬼疰、尸疰、飞尸、客忤 此系天地阴邪杀厉之气乘虚中人，或遍身青暗，或忽消瘦声哑，面色青黄不定，或忽惊厥，目直视，手握拳，或遍身骨节疼痛非常。 【忌】破气，复忌补气、升、澡热、酸敛。诸药俱见前。 【宜】辟恶气、安神镇心、辛香发散、金石镇坠。牛黄、丹砂、苏合香、天竺黄、琥珀、沉水香、龙脑香、乳香、安息香、檀香、木香、麝香、真珠、雄黄、鬼臼、龙齿、犀角、金银箔、虎骨、代赭石、天灵盖、獭肝、生地黄、菖蒲、远志。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OkfAFj3JDi1', 1, '{"title":"卷之二_续序例下_妇人门","description":"<p>1、赤白带下</p>\n<p>妇人多忧思郁怒，损伤心脾，肝火时发，血走不归经，所以多患赤白带也。白带多是脾虚。盖肝气郁则脾受伤，脾伤则湿土之气下陷，是脾精不守，不能输为荣血，而下白滑之物矣。皆由风木郁于地中使然耳。法当开提肝气，补助脾元。宜以补中益气汤，加酸枣仁、茯苓、山药、黄檗、苍术、麦门冬之类，浓煎，不时饮之。再用六味地黄丸中加牡蛎粉、海螵蛸、杜仲、牛膝，蜜丸，光大如豆。空心饥时吞下五六钱。阳虚火炽加枸杞子、五味子、黄檗。白带多属气虚，补气健脾，治法之要领也。</p><p>2、带下如浓泔而臭秽特甚者，湿热甚也，且多有湿痰下坠者，宜苍术、白术、黄檗、黄芩、车前子为主，佐以升提。</p><p>3、带下如鸡子清者，脾肾极虚也。面色必不华，足胫必浮，腰腿必酸，宜五味子、八味丸。间用开脾养心之剂，如归脾汤之类。阴虚有火，宜八味丸中加五味子、菟丝子、车前子、黄檗。叔和云：崩中日久为白带，漏下多时肾水枯。盖言崩久气血虚脱，而白滑之物下不止耳。此证虽有气血寒热之分，要归总属于虚。</p><p>4、赤淋多因于心火、肝火时炽不已，久而阴血渐虚，中气渐损，遂下赤矣。治宜养心为主，兼以和肝缓中，凉血清气。</p><p>5、赤带久不止则血虚，宜胶艾四物汤加便煅牡蛎粉、酸枣仁、麦门冬。</p><p>6、标急而元气不甚惫者，先救其标；标急而元气衰剧者，则当本而标之可也。</p>\n<p>【忌】破气、降、温热。诸药俱见前。</p>\n<p>【宜】补敛、清热、辛甘、苦寒，佐以淡渗。生地黄、人参、白芍药、阿胶、山茱萸、黄檗、五味子、麦门冬、白胶、枸杞子、续断、杜仲、牛膝、白茯苓、车前子、泽泻、蛇床子、香附、补骨脂、牡蛎、艾、二术。</p><p>7、血枯经闭</p>\n<p>由于脾胃薄弱，气血不生。</p>\n<p>【忌】破气、破血、燥热、腻膈滑肠、升发、苦寒。诸药俱见前。</p>\n<p>【宜】补脾胃、甘温、甘平。人参、莲肉、酸枣仁、白扁豆、甘草、茯苓、薯蓣、橘红、白芍药、缩砂蜜、菟丝子、牛膝、牡丹皮、白胶、阿胶、芡实、麦门冬。</p><p>8、经行先期</p>\n<p>为血热。</p>\n<p>【忌】升、补气、辛温、燥热。香附、当归、乌药、艾（已上辛温）。余忌药俱见前。</p>\n<p>【宜】凉血清热、补肝肾，兼降气、甘寒、酸寒、苦寒。生地黄、牡丹皮、白芍药、天门冬、麦门冬、枸杞子、杜仲、青蒿、枇杷叶、苏子、鳖甲、阿胶、黄檗、黄芩、知母。</p><p>9、经行后期</p>\n<p>为血虚。</p>\n<p>【忌】行血、破气、燥热、苦寒。诸药俱见前。</p>\n<p>【宜】补肝肾、甘温、酸温。熟地黄、薯蓣、人参、菟丝子、山茱萸、杜仲、续断、阿胶、艾、五味子、当归、枸杞子、白胶、牛膝。</p><p>10、月事过多</p>\n<p>属心火盛，脾气弱。</p>\n<p>【忌】破气、降、辛温、苦寒。诸药俱见前。</p>\n<p>【宜】凉血、敛摄、酸平、甘寒。麦冬、生地（泻泄禁用）、青蒿、生甘草、牡丹皮、白芍药、酸枣仁、五味子。</p><p>11、崩中</p>\n<p>属气血两虚有热。</p>\n<p>【忌】破气、行血、降、温热、辛燥、苦寒。诸药俱见前。</p>\n<p>【宜】补气血，兼清热、甘温、甘寒、酸敛。人参、黄耆、生地黄、熟地黄、地榆、芍药、白胶、阿胶、香附、续断、甘草、麦门冬、山茱萸、杜仲、五味子、白茅根、蒲黄（炒）、桑耳灰、侧柏叶、艾叶、木耳灰。</p><p>12、热血入室</p>\n<p>类伤寒，或经事适来忽住，或届期不行，忽发大热、口渴，或厥，但不头疼为异于伤寒耳。</p>\n<p>【忌】补气、温燥、辛燥、收敛、下泄、大热、升发。诸药俱见前。</p>\n<p>【宜】行血清热、甘寒、咸寒、苦寒。生地黄、牡丹皮、蒲黄、苏木、牛膝、延胡索、麦门冬、犀角、白芍药、黄芩、童溺、荆芥穗。如便闭，加大黄。</p><p>13、种子</p>\n<p>内分男、女，气虚、血虚、精寒、血热、火炽、精滑，因证选用。</p>\n<p>【忌】破气、破血、燥、过用辛热。诸药俱见前。</p>\n<p>【宜】调气补血，男子宜固精。桑螵蛸（温，平，治男子精滑）、柏实（甘，温，治男子精滑精寒）、海狗肾（咸，热，治男子精寒）、鱼胶（平，治男子精滑）、阳起石（热，治男子精寒）、覆盆子（甘，温，治男子精滑）、车前子（咸，寒，治男女火炽）、鹿茸（温，咸，治男子精寒）、莲须（甘，温，治男子精滑）、巴戟天（温，治男子精寒）、何首乌（苦，温，益男子气血）、牛膝（苦，平，治男子血虚阴痿）、补骨脂（辛，温，治男子精寒阴弱）、沙苑蒺藜（甘，平，男子固精益血）、白胶（温，平，治男女气血两虚精寒）、肉苁蓉（温，酸，咸，治男女血虚精寒）、黄檗（苦，寒，治男女火炽）、人参（微温，治男女气虚、脾胃薄弱）、麦门冬（甘，寒，男女血热）、五味子（酸，温，治男女精滑精寒）、山茱萸（酸，温，治男女精滑精寒）、天门冬（苦，寒，治男女火炽）、莲肉（甘，平，治男女胃弱精滑）、熟地黄（甘，寒，男女益血生精）、白薇（温平，女）、当归（辛温，女）、白芍药（酸寒，女）、紫石英（温，女）、艾叶（辛温，女）。</p><p>14、妊娠恶阻</p>\n<p>【忌】破气、升散、燥热、苦寒、滑肠、腻膈。诸药俱见前。</p>\n<p>【宜】顺气、甘寒、酸寒。苏子、橘红、枇杷叶、白茯苓、麦门冬、芦根、竹茹、木瓜、白芍药、竹叶、人参、缩砂蜜、白梅、乌梅。</p><p>15、安胎</p>\n<p>【忌】破气、破血、升散、辛热、辛燥。诸药俱见前。</p>\n<p>八月以后及胎前滞下者，方可用枳壳，气虚者不用。</p>\n<p>三月以前宜养脾胃，四月以后宜壮腰肾，补血益阴，顺气，总宜清热。茯苓、麦门冬、薯蓣、人参、芍药、白术、橘红、炙甘草、缩砂蜜、艾叶、杜仲、生地黄、益母草、白胶、阿胶、续断、黄芩、枸杞子、青蒿子、桑寄生、鲤鱼、乌雌鸡、葱白。</p><p>16、胎漏</p>\n<p>属气血虚有热。</p>\n<p>忌、宜俱同安胎条。</p><p>17、难产</p>\n<p>【忌】破气、破血、收敛。诸药俱见前。</p>\n<p>【宜】补气血、滑利、润。人参、柞树枝、鱼胶、冬葵子、千里马、白芷梢、牛膝、桂心、当归、芎、益母草、百草霜、石燕、弓弩、麻油、猪脂、酒、生鸡子、兔头、滑石、麝香。</p><p>18、预防血晕</p>\n<p>腹痛坐草时，即用苏木菊花心者一两，生地黄一两，降香末二钱，水三碗，煎一碗，加童便半碗，儿堕地即饮之，永无恶血冲心之患。房中常打醋、炭，万一血晕亦须此药。更以家宝丹一丸，灌下神效。</p>\n<p></p>\n<p>凡妇人气弱者，无气力送子出产门，须服人参。此药能兼治横生、倒产，世医不知也。</p>\n<p></p>\n<p>凡临产交骨不开，惟浓煮柞木枝汤，饮之则自开。柞木俗名一叶一刺，其木枝干直上，每一叶必发一刺。</p>\n<p></p>\n<p>胞衣不下，用乳香、没药末各七分五厘，麝香一分，芒硝一钱五分，研细。以酒调服，立下。饮热童便以滋药力，更妙。</p>\n<p></p><p>19、产后诸病（十四证）</p>\n<p>【忌】破气、升、汗、吐、下、燥、苦寒、大热。诸药俱见前。</p>\n<p>【宜】行血，次宜补血清热，总宜补养肝脾肾、辛温、甘寒、酸寒。苏木、黑豆、鹿角末、红花、乳香、没药、牛膝、炮姜、当归（脾胃弱者勿用）、桃仁（胃弱者禁用，亦不可过用）、桂（天寒无火之人可用）、益母草、泽兰、干地黄、续断、白胶、杜仲、山茱萸、人参、青蒿、麦门冬、白芍药、五味子。</p><p>20、产后少腹痛 按之痛甚有结块，名儿枕痛。</p>\n<p>【忌】酸敛、补气、破气、升、下、汗、燥。诸药俱见前。</p>\n<p>【宜】行血活血散结，兼健脾。延胡索、红蓝花、牡丹皮、苏方木、山查肉、益母草、蓬莪术、蒲黄、白胶、当归、黑豆、生地黄、泽兰、牛膝、五灵脂、缩砂蜜、橘红、童便、桃仁、干姜。</p>\n<p>痛极加乳香、没药（各六七分）。天寒加桂，暑月勿用，肺热有火勿用。</p><p>21、产后少腹痛按之即止者，属血虚。</p>\n<p>【忌】行血、破气、汗、吐、下、燥、苦寒、大热。诸药俱见前。</p>\n<p>【宜】补血、补脾、和肝。干地黄、白芍药、当归、续断、白胶、阿胶、牛膝、人参、酸枣仁、麦门冬、炙甘草、大枣、薯蓣、橘皮。</p><p>22、产后泄泻。</p>\n<p>【忌】消导、滑肠、腻膈、发散、生冷、破气、苦寒。诸药俱见前。</p>\n<p>【宜】温中补气、健脾开胃。人参、甘草、薯蓣、莲肉、扁豆、茯苓、白芍药、橘皮、车前子、肉豆蔻（内热津液不足者少用）、藿香、五味子、补骨脂（内热火炽者勿用）、缩砂蜜。</p><p>23、产后发热或自汗盗汗。</p>\n<p>【忌】苦寒、发散、升提、破气、破血、下、辛燥、大热、寒滑伤脾。诸药俱见前。</p>\n<p>【宜】补血、凉血、补肝、补心、生津液、兼敛摄实表。干地黄、炙甘草、白芍药、五味子、麦门冬、酸枣仁、牡丹皮、童便、青蒿、鳖甲、泽兰、黑豆、黄耆、人参（肺热者禁用）。</p><p>24、产后头痛 由于血虚。</p>\n<p>【忌】发散、破血、升提、辛燥、大热。诸药俱见前。</p>\n<p>【宜】益血、凉血、降、甘温、甘寒，佐以酸寒。生地黄、甘菊花、乌梅、麦门冬、苏子、童便、甘草、当归、白芍药、黑豆、五味子、鳖甲。</p><p>25、产后发渴 由于血虚有热。</p>\n<p>【忌】同产后发热。</p>\n<p>【宜】同产后发热，加蔗浆，倍麦门冬、五味子。</p><p>26、产后气喘 由于气血两虚。</p>\n<p>【忌】同产后发热。</p>\n<p>【宜】补气血、润肺、下降。人参、橘红、生地黄、天门冬、麦门冬、苏子、枇杷叶、栝楼仁、栝楼根、童便、五味子、竹茹。</p><p>27、产后恶寒 由于气血两虚。</p>\n<p>【忌】同产后发热。</p>\n<p>【宜】补气血、温中、甘温，佐以辛温。人参、黄耆、炙甘草、干地黄、龙眼肉、当归、炮干姜。</p><p>28、产后小便不利或短赤 由于肾水真阴不足。</p>\n<p>【忌】利小便，馀忌同产后发热。诸药俱见前。</p>\n<p>【宜】生津液、益阴、补血、凉血、清热、甘温、甘寒、酸寒。天门冬、麦门冬、生地黄、枸杞子、山茱萸、白芍药、车前子、牛膝、五味子、青蒿子、鳖甲、竹叶。</p><p>29、产后大便闭结 由于血枯内热。</p>\n<p>【忌】补气、行血、辛热、燥、下、升、苦寒。诸药俱见前。</p>\n<p>【宜】益血、凉血、润燥、滋肝肾、生津液。生地黄、熟地黄、天门冬、麦门冬、五味子、蔗浆、牡丹皮、肉苁蓉、当归、麻仁、人乳、蜜。</p><p>30、产后不得眠。</p>\n<p>【忌】同产后大便闭结。</p>\n<p>【宜】补心、降心火、补肝、补脾阴，兼清内热。生地黄、麦门冬、茯神、丹参、沙参、酸枣仁、白芍药、竹叶、远志、莲肉、龙眼肉。</p><p>31、产后腹胀 由于阴血虚、脾阴虚。</p>\n<p>【忌】破气宽中、升提发散、消导、吐、下、甘、苦寒、咸寒、大热、温燥、滞腻。诸药俱见前。</p>\n<p>【宜】益脾阴、补脾、和肝、酸寒、收敛、甘温。白芍药、酸枣仁、人参、茯苓、石斛、橘皮、薯蓣、五味子、木瓜、莲实、车前子、芡实。</p><p>32、产后恶心欲呕或吐 由于胃虚。</p>\n<p>【忌】升提发散、湿润、滞腻、苦寒、生冷、燥热。诸药俱见前。</p>\n<p>【宜】降气、补气、安胃、酸寒，佐以辛温。苏子、枇杷叶、竹茹、人参、橘红、麦门冬、白芍药、藿香、石斛、木瓜、白豆蔻、生姜。</p>\n<p>由于寒，倍生姜、白豆蔻、藿香。由于热，倍竹茹，去生姜、白豆蔻、藿香。</p><p>33、下乳汁。</p>\n<p>漏芦、狗四足、猪四足、麦门冬、人参、栝楼仁、土瓜根、葵子、猪胰、木通。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001050,"no":49}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '1、赤白带下 妇人多忧思郁怒，损伤心脾，肝火时发，血走不归经，所以多患赤白带也。白带多是脾虚。盖肝气郁则脾受伤，脾伤则湿土之气下陷，是脾精不守，不能输为荣血，而下白滑之物矣。皆由风木郁于地中使然耳。法当开提肝气，补助脾元。宜以补中益气汤，加酸枣仁、茯苓、山药、黄檗、苍术、麦门冬之类，浓煎，不时饮之。再用六味地黄丸中加牡蛎粉、海螵蛸、杜仲、牛膝，蜜丸，光大如豆。空心饥时吞下五六钱。阳虚火炽加枸杞子、五味子、黄檗。白带多属气虚，补气健脾，治法之要领也。 2、带下如浓泔而臭秽特甚者，湿热甚也，且多有湿痰下坠者，宜苍术、白术、黄檗、黄芩、车前子为主，佐以升提。 3、带下如鸡子清者，脾肾极虚也。面色必不华，足胫必浮，腰腿必酸，宜五味子、八味丸。间用开脾养心之剂，如归脾汤之类。阴虚有火，宜八味丸中加五味子、菟丝子、车前子、黄檗。叔和云：崩中日久为白带，漏下多时肾水枯。盖言崩久气血虚脱，而白滑之物下不止耳。此证虽有气血寒热之分，要归总属于虚。 4、赤淋多因于心火、肝火时炽不已，久而阴血渐虚，中气渐损，遂下赤矣。治宜养心为主，兼以和肝缓中，凉血清气。 5、赤带久不止则血虚，宜胶艾四物汤加便煅牡蛎粉、酸枣仁、麦门冬。 6、标急而元气不甚惫者，先救其标；标急而元气衰剧者，则当本而标之可也。 【忌】破气、降、温热。诸药俱见前。 【宜】补敛、清热、辛甘、苦寒，佐以淡渗。生地黄、人参、白芍药、阿胶、山茱萸、黄檗、五味子、麦门冬、白胶、枸杞子、续断、杜仲、牛膝、白茯苓、车前子、泽泻、蛇床子、香附、补骨脂、牡蛎、艾、二术。 7、血枯经闭 由于脾胃薄弱，气血不生。 【忌】破气、破血、燥热、腻膈滑肠、升发、苦寒。诸药俱见前。 【宜】补脾胃、甘温、甘平。人参、莲肉、酸枣仁、白扁豆、甘草、茯苓、薯蓣、橘红、白芍药、缩砂蜜、菟丝子、牛膝、牡丹皮、白胶、阿胶、芡实、麦门冬。 8、经行先期 为血热。 【忌】升、补气、辛温、燥热。香附、当归、乌药、艾（已上辛温）。余忌药俱见前。 【宜】凉血清热、补肝肾，兼降气、甘寒、酸寒、苦寒。生地黄、牡丹皮、白芍药、天门冬、麦门冬、枸杞子、杜仲、青蒿、枇杷叶、苏子、鳖甲、阿胶、黄檗、黄芩、知母。 9、经行后期 为血虚。 【忌】行血、破气、燥热、苦寒。诸药俱见前。 【宜】补肝肾、甘温、酸温。熟地黄、薯蓣、人参、菟丝子、山茱萸、杜仲、续断、阿胶、艾、五味子、当归、枸杞子、白胶、牛膝。 10、月事过多 属心火盛，脾气弱。 【忌】破气、降、辛温、苦寒。诸药俱见前。 【宜】凉血、敛摄、酸平、甘寒。麦冬、生地（泻泄禁用）、青蒿、生甘草、牡丹皮、白芍药、酸枣仁、五味子。 11、崩中 属气血两虚有热。 【忌】破气、行血、降、温热、辛燥、苦寒。诸药俱见前。 【宜】补气血，兼清热、甘温、甘寒、酸敛。人参、黄耆、生地黄、熟地黄、地榆、芍药、白胶、阿胶、香附、续断、甘草、麦门冬、山茱萸、杜仲、五味子、白茅根、蒲黄（炒）、桑耳灰、侧柏叶、艾叶、木耳灰。 12、热血入室 类伤寒，或经事适来忽住，或届期不行，忽发大热、口渴，或厥，但不头疼为异于伤寒耳。 【忌】补气、温燥、辛燥、收敛、下泄、大热、升发。诸药俱见前。 【宜】行血清热、甘寒、咸寒、苦寒。生地黄、牡丹皮、蒲黄、苏木、牛膝、延胡索、麦门冬、犀角、白芍药、黄芩、童溺、荆芥穗。如便闭，加大黄。 13、种子 内分男、女，气虚、血虚、精寒、血热、火炽、精滑，因证选用。 【忌】破气、破血、燥、过用辛热。诸药俱见前。 【宜】调气补血，男子宜固精。桑螵蛸（温，平，治男子精滑）、柏实（甘，温，治男子精滑精寒）、海狗肾（咸，热，治男子精寒）、鱼胶（平，治男子精滑）、阳起石（热，治男子精寒）、覆盆子（甘，温，治男子精滑）、车前子（咸，寒，治男女火炽）、鹿茸（温，咸，治男子精寒）、莲须（甘，温，治男子精滑）、巴戟天（温，治男子精寒）、何首乌（苦，温，益男子气血）、牛膝（苦，平，治男子血虚阴痿）、补骨脂（辛，温，治男子精寒阴弱）、沙苑蒺藜（甘，平，男子固精益血）、白胶（温，平，治男女气血两虚精寒）、肉苁蓉（温，酸，咸，治男女血虚精寒）、黄檗（苦，寒，治男女火炽）、人参（微温，治男女气虚、脾胃薄弱）、麦门冬（甘，寒，男女血热）、五味子（酸，温，治男女精滑精寒）、山茱萸（酸，温，治男女精滑精寒）、天门冬（苦，寒，治男女火炽）、莲肉（甘，平，治男女胃弱精滑）、熟地黄（甘，寒，男女益血生精）、白薇（温平，女）、当归（辛温，女）、白芍药（酸寒，女）、紫石英（温，女）、艾叶（辛温，女）。 14、妊娠恶阻 【忌】破气、升散、燥热、苦寒、滑肠、腻膈。诸药俱见前。 【宜】顺气、甘寒、酸寒。苏子、橘红、枇杷叶、白茯苓、麦门冬、芦根、竹茹、木瓜、白芍药、竹叶、人参、缩砂蜜、白梅、乌梅。 15、安胎 【忌】破气、破血、升散、辛热、辛燥。诸药俱见前。 八月以后及胎前滞下者，方可用枳壳，气虚者不用。 三月以前宜养脾胃，四月以后宜壮腰肾，补血益阴，顺气，总宜清热。茯苓、麦门冬、薯蓣、人参、芍药、白术、橘红、炙甘草、缩砂蜜、艾叶、杜仲、生地黄、益母草、白胶、阿胶、续断、黄芩、枸杞子、青蒿子、桑寄生、鲤鱼、乌雌鸡、葱白。 16、胎漏 属气血虚有热。 忌、宜俱同安胎条。 17、难产 【忌】破气、破血、收敛。诸药俱见前。 【宜】补气血、滑利、润。人参、柞树枝、鱼胶、冬葵子、千里马、白芷梢、牛膝、桂心、当归、芎、益母草、百草霜、石燕、弓弩、麻油、猪脂、酒、生鸡子、兔头、滑石、麝香。 18、预防血晕 腹痛坐草时，即用苏木菊花心者一两，生地黄一两，降香末二钱，水三碗，煎一碗，加童便半碗，儿堕地即饮之，永无恶血冲心之患。房中常打醋、炭，万一血晕亦须此药。更以家宝丹一丸，灌下神效。 凡妇人气弱者，无气力送子出产门，须服人参。此药能兼治横生、倒产，世医不知也。 凡临产交骨不开，惟浓煮柞木枝汤，饮之则自开。柞木俗名一叶一刺，其木枝干直上，每一叶必发一刺。 胞衣不下，用乳香、没药末各七分五厘，麝香一分，芒硝一钱五分，研细。以酒调服，立下。饮热童便以滋药力，更妙。 19、产后诸病（十四证） 【忌】破气、升、汗、吐、下、燥、苦寒、大热。诸药俱见前。 【宜】行血，次宜补血清热，总宜补养肝脾肾、辛温、甘寒、酸寒。苏木、黑豆、鹿角末、红花、乳香、没药、牛膝、炮姜、当归（脾胃弱者勿用）、桃仁（胃弱者禁用，亦不可过用）、桂（天寒无火之人可用）、益母草、泽兰、干地黄、续断、白胶、杜仲、山茱萸、人参、青蒿、麦门冬、白芍药、五味子。 20、产后少腹痛 按之痛甚有结块，名儿枕痛。 【忌】酸敛、补气、破气、升、下、汗、燥。诸药俱见前。 【宜】行血活血散结，兼健脾。延胡索、红蓝花、牡丹皮、苏方木、山查肉、益母草、蓬莪术、蒲黄、白胶、当归、黑豆、生地黄、泽兰、牛膝、五灵脂、缩砂蜜、橘红、童便、桃仁、干姜。 痛极加乳香、没药（各六七分）。天寒加桂，暑月勿用，肺热有火勿用。 21、产后少腹痛按之即止者，属血虚。 【忌】行血、破气、汗、吐、下、燥、苦寒、大热。诸药俱见前。 【宜】补血、补脾、和肝。干地黄、白芍药、当归、续断、白胶、阿胶、牛膝、人参、酸枣仁、麦门冬、炙甘草、大枣、薯蓣、橘皮。 22、产后泄泻。 【忌】消导、滑肠、腻膈、发散、生冷、破气、苦寒。诸药俱见前。 【宜】温中补气、健脾开胃。人参、甘草、薯蓣、莲肉、扁豆、茯苓、白芍药、橘皮、车前子、肉豆蔻（内热津液不足者少用）、藿香、五味子、补骨脂（内热火炽者勿用）、缩砂蜜。 23、产后发热或自汗盗汗。 【忌】苦寒、发散、升提、破气、破血、下、辛燥、大热、寒滑伤脾。诸药俱见前。 【宜】补血、凉血、补肝、补心、生津液、兼敛摄实表。干地黄、炙甘草、白芍药、五味子、麦门冬、酸枣仁、牡丹皮、童便、青蒿、鳖甲、泽兰、黑豆、黄耆、人参（肺热者禁用）。 24、产后头痛 由于血虚。 【忌】发散、破血、升提、辛燥、大热。诸药俱见前。 【宜】益血、凉血、降、甘温、甘寒，佐以酸寒。生地黄、甘菊花、乌梅、麦门冬、苏子、童便、甘草、当归、白芍药、黑豆、五味子、鳖甲。 25、产后发渴 由于血虚有热。 【忌】同产后发热。 【宜】同产后发热，加蔗浆，倍麦门冬、五味子。 26、产后气喘 由于气血两虚。 【忌】同产后发热。 【宜】补气血、润肺、下降。人参、橘红、生地黄、天门冬、麦门冬、苏子、枇杷叶、栝楼仁、栝楼根、童便、五味子、竹茹。 27、产后恶寒 由于气血两虚。 【忌】同产后发热。 【宜】补气血、温中、甘温，佐以辛温。人参、黄耆、炙甘草、干地黄、龙眼肉、当归、炮干姜。 28、产后小便不利或短赤 由于肾水真阴不足。 【忌】利小便，馀忌同产后发热。诸药俱见前。 【宜】生津液、益阴、补血、凉血、清热、甘温、甘寒、酸寒。天门冬、麦门冬、生地黄、枸杞子、山茱萸、白芍药、车前子、牛膝、五味子、青蒿子、鳖甲、竹叶。 29、产后大便闭结 由于血枯内热。 【忌】补气、行血、辛热、燥、下、升、苦寒。诸药俱见前。 【宜】益血、凉血、润燥、滋肝肾、生津液。生地黄、熟地黄、天门冬、麦门冬、五味子、蔗浆、牡丹皮、肉苁蓉、当归、麻仁、人乳、蜜。 30、产后不得眠。 【忌】同产后大便闭结。 【宜】补心、降心火、补肝、补脾阴，兼清内热。生地黄、麦门冬、茯神、丹参、沙参、酸枣仁、白芍药、竹叶、远志、莲肉、龙眼肉。 31、产后腹胀 由于阴血虚、脾阴虚。 【忌】破气宽中、升提发散、消导、吐、下、甘、苦寒、咸寒、大热、温燥、滞腻。诸药俱见前。 【宜】益脾阴、补脾、和肝、酸寒、收敛、甘温。白芍药、酸枣仁、人参、茯苓、石斛、橘皮、薯蓣、五味子、木瓜、莲实、车前子、芡实。 32、产后恶心欲呕或吐 由于胃虚。 【忌】升提发散、湿润、滞腻、苦寒、生冷、燥热。诸药俱见前。 【宜】降气、补气、安胃、酸寒，佐以辛温。苏子、枇杷叶、竹茹、人参、橘红、麦门冬、白芍药、藿香、石斛、木瓜、白豆蔻、生姜。 由于寒，倍生姜、白豆蔻、藿香。由于热，倍竹茹，去生姜、白豆蔻、藿香。 33、下乳汁。 漏芦、狗四足、猪四足、麦门冬、人参、栝楼仁、土瓜根、葵子、猪胰、木通。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eUMDgHf5J7z', 1, '{"title":"卷之二_续序例下_小儿门","description":"<p>1、痘疮</p>\n<p>血热证：忌温补、燥热。天灵盖、鸡冠血、桑蠹、鲮鲤甲、人齿、官桂、附子、丁香、木香、冰片（已上燥热）、馀忌药俱见前。</p>\n<p>【宜】凉血、活血、解毒、甘寒、苦寒。犀角、生地黄、人中黄、紫草、黄连、麦门冬、牡丹皮、白芍药、童溺、连翘、金银花、玄参、贝母、蝉蜕、鼠粘子。</p>\n<p></p>\n<p>虚寒证：忌汗、吐、下、苦寒、酸寒。诸药俱见前。</p>\n<p>【宜】辛甘发散、补气、温，疮密者佐以解毒。人参、红铅、黄耆、甘草、桂枝、丁香、当归（胃弱大便不闭者禁用）、莲肉、糯米、大枣、龙眼肉、干葛、木香、忍冬藤。</p><p>2、痧疹</p>\n<p>此证多有呕吐者，勿治呕吐，但治痧毒，则呕自止，况呕中便有发散之义。</p>\n<p>【忌】破气、温补、酸敛、燥热、辛温、滞腻。诸药俱见前。</p>\n<p>【宜】清热透肌、辛寒、甘寒、苦寒。石膏、鼠粘子、赤柽木（即西河柳）、知母、甘草、玄参、麦门冬、连翘、薄荷、竹叶、黄连、黄芩、葛根、黄檗、蝉蜕、栝楼根、青黛、蔗浆、贝母。</p><p>3、如冬月，佐之以辛散，荆芥、麻黄（去节沫，蜜酒炒，只可用一剂）。</p><p>4、痧疹者，手太阴肺、足阳明胃二经之火热发而为病者也。小儿居多，大人亦时有之。殆时气瘟疫之类欤？其证类多咳嗽，多嚏，眼中如泪，多泄泻，多痰，多热，多渴，多烦闷，甚则躁乱，咽痛，唇焦神昏，是其候也。治法当以清凉发散为主。药用辛寒、甘寒、苦寒以升发之。惟忌酸敛，最宜辛散。误施温补，祸不旋踵。辛散如荆芥、西河柳、干葛、石膏、鼠粘子、麻黄；清凉如玄参、竹叶、栝楼根、青黛、薄荷；甘寒如麦门冬、生甘草、蔗浆；苦寒如黄芩、黄连、黄檗、贝母、连翘。随证轻重，制剂大小，中病则已，毋太过焉。</p><p>5、痧疹乃肺胃邪热所致，初发时必咳嗽，宜清热透毒，不得止嗽。疹后咳嗽，但用贝母、苦梗、甘草、薄荷、栝楼根、玄参、麦门冬，以清余热、消痰壅，则自愈，慎勿用五味子等收敛之剂。多喘，喘者邪热壅于肺故也，慎勿用定喘药，惟应大剂竹叶石膏汤加西河柳两许，玄参、薄荷各二钱。如冬天寒甚，痧毒郁于内，不得透出者，加蜜酒炒麻黄一剂，立止。凡热势甚者，即用白虎汤加西河柳，忌用升麻，服之必喘。多泄泻，慎勿止泻，惟用黄连、干葛、升麻、甘草、则泻自止。疹家不忌泻，泻则阳明之邪热得解，是亦表里分消之义也。疹后泄泻及便脓血，皆由邪热内陷故也，大忌止涩，惟宜升散，仍用升麻、甘草、干葛、黄连、白芍药、白扁豆。便脓血则加滑石末，必自愈。</p><p>6、疹后牙疳最危，外用牡黄牛粪尖，煅存性，研极细，加真片脑一分，研匀吹之；内用连翘、干葛、荆芥穗、升麻、玄参、黄连、甘草、生地黄，水煎，加生犀角汁二三十匙调服。缓则不可救药。</p><p>7、痧后元气不复，脾胃薄弱者，宜用白芍药、炙甘草为君，莲肉、山药、白扁豆、麦门冬、青黛、龙眼肉为臣。多服必渐强，慎勿轻用参、术。</p><p>8、痧后生疮不已，余热未尽故也。宜用金银花、荆芥穗、连翘、玄参、甘草、怀生地、鳖虱胡麻、黄连、木通，浓煎饮之良。</p><p>9、痧疹不宜依证施治，惟当治本。本者，手太阴、足阳明二经之邪热也。解其邪热，则诸证自退矣。</p><p>10、呕吐</p>\n<p>因伤乳食者。</p>\n<p>【忌】升、苦寒。诸药俱见前。</p>\n<p>【宜】温中、消导。橘皮、缩砂蜜、枳实、厚朴、谷麦糵、草果、山查、红曲、半夏、人参。</p>\n<p></p>\n<p>因寒者：忌破气、升、苦寒。诸药俱见前者。</p>\n<p>【宜】辛热、温中。藿香、橘皮、丁香、人参、白术、生姜、半夏、白豆蔻。</p>\n<p></p>\n<p>因暑者：忌升、破气、温热。诸药俱见前。</p>\n<p>【宜】清暑、补气、安胃，兼利小便。黄连、香薷、人参、木瓜、茯苓、竹茹、石斛、橘皮、甘草、白扁豆、麦门冬、白梅、滑石、木通、泽泻。</p>\n<p></p>\n<p>有虫者：忌升、甘。诸药俱见前。</p>\n<p>【宜】酸敛，佐以苦寒。白芍药、五味子、木瓜、黄连、楝根、乌梅、槟榔、榧子肉、木香、使君子。</p>\n<p>总之，数呕吐宜安胃，久则宜补气。</p><p>11、泄泻</p>\n<p>总忌破气、下、滑利、滞腻。诸药俱见前。</p>\n<p>因食者：宜和胃消食。橘皮、草果、红曲、谷麦糵、白豆蔻、白术、山查、白茯苓、肉豆蔻、缩砂蜜。</p>\n<p></p>\n<p>因湿者：宜燥脾、利水。二术、橘皮、木瓜、茯苓、泽泻、车前子、石斛、黄连、薯蓣、猪苓、升麻、葛根。</p>\n<p></p>\n<p>因暑者：宜前药中加人参、莲肉、白扁豆。</p>\n<p>总之当补脾胃，兼升，兼利小便。</p><p>12、急惊</p>\n<p>【忌】补敛、升、燥热。诸药俱见前。</p>\n<p>【宜】降、清热、镇坠、豁痰、和肝。丹砂、琥珀、牛黄、天竺黄、贝母、竹沥、钓藤钩、僵蚕、茯神、犀角、金箔、胆星、真珠、全蝎、龙脑、麝香、白檀香。</p><p>13、慢惊</p>\n<p>多因久吐泻、大病后阴阳两虚而成。</p>\n<p>【忌】破气、下、升、苦寒，及治急惊药。诸药俱见前。</p>\n<p>【宜】补脾健胃、和肝益气、甘温、酸平、佐以辛热。人参、黄耆、茯苓、白芍药、甘草、龙眼肉、酸枣仁、石菖蒲、远志、麦门冬、茯神、冬瓜仁、橘红。</p><p>14、疳积</p>\n<p>【忌】破气、酸敛、燥热。诸药俱见前。</p>\n<p>【宜】除疳热，兼消导、苦寒、甘寒，佐以辛寒、辛温。胡黄连、川黄连、肉豆蔻、谷麦糵、神曲、山查、木香、橘皮、白芜荑、使君子、芦会、白术、白芙蓉花、五谷虫、雷丸、青黛、厚朴。</p><p>15、诸虫</p>\n<p>【忌】升，甘。诸药俱见前。</p>\n<p>【宜】杀虫、酸寒、苦寒，佐以辛寒。槟榔、雷丸、使君子、苦楝根、锡灰、鹤虱、芦荟、芍药、乌梅、黄连、黄芩、牵牛。</p><p>16、胎毒</p>\n<p>【忌】补敛、燥热、辛温。诸药俱见前。</p>\n<p>【宜】凉血清热、解毒，兼发散于外。勿从外治，以致热毒内攻。生地黄、玄参、牡丹皮、黄檗、黄连、忍冬藤、甘草、连翘、麦门冬、贝母、犀角、荆芥、鼠粘子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001051,"no":50}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '1、痘疮 血热证：忌温补、燥热。天灵盖、鸡冠血、桑蠹、鲮鲤甲、人齿、官桂、附子、丁香、木香、冰片（已上燥热）、馀忌药俱见前。 【宜】凉血、活血、解毒、甘寒、苦寒。犀角、生地黄、人中黄、紫草、黄连、麦门冬、牡丹皮、白芍药、童溺、连翘、金银花、玄参、贝母、蝉蜕、鼠粘子。 虚寒证：忌汗、吐、下、苦寒、酸寒。诸药俱见前。 【宜】辛甘发散、补气、温，疮密者佐以解毒。人参、红铅、黄耆、甘草、桂枝、丁香、当归（胃弱大便不闭者禁用）、莲肉、糯米、大枣、龙眼肉、干葛、木香、忍冬藤。 2、痧疹 此证多有呕吐者，勿治呕吐，但治痧毒，则呕自止，况呕中便有发散之义。 【忌】破气、温补、酸敛、燥热、辛温、滞腻。诸药俱见前。 【宜】清热透肌、辛寒、甘寒、苦寒。石膏、鼠粘子、赤柽木（即西河柳）、知母、甘草、玄参、麦门冬、连翘、薄荷、竹叶、黄连、黄芩、葛根、黄檗、蝉蜕、栝楼根、青黛、蔗浆、贝母。 3、如冬月，佐之以辛散，荆芥、麻黄（去节沫，蜜酒炒，只可用一剂）。 4、痧疹者，手太阴肺、足阳明胃二经之火热发而为病者也。小儿居多，大人亦时有之。殆时气瘟疫之类欤？其证类多咳嗽，多嚏，眼中如泪，多泄泻，多痰，多热，多渴，多烦闷，甚则躁乱，咽痛，唇焦神昏，是其候也。治法当以清凉发散为主。药用辛寒、甘寒、苦寒以升发之。惟忌酸敛，最宜辛散。误施温补，祸不旋踵。辛散如荆芥、西河柳、干葛、石膏、鼠粘子、麻黄；清凉如玄参、竹叶、栝楼根、青黛、薄荷；甘寒如麦门冬、生甘草、蔗浆；苦寒如黄芩、黄连、黄檗、贝母、连翘。随证轻重，制剂大小，中病则已，毋太过焉。 5、痧疹乃肺胃邪热所致，初发时必咳嗽，宜清热透毒，不得止嗽。疹后咳嗽，但用贝母、苦梗、甘草、薄荷、栝楼根、玄参、麦门冬，以清余热、消痰壅，则自愈，慎勿用五味子等收敛之剂。多喘，喘者邪热壅于肺故也，慎勿用定喘药，惟应大剂竹叶石膏汤加西河柳两许，玄参、薄荷各二钱。如冬天寒甚，痧毒郁于内，不得透出者，加蜜酒炒麻黄一剂，立止。凡热势甚者，即用白虎汤加西河柳，忌用升麻，服之必喘。多泄泻，慎勿止泻，惟用黄连、干葛、升麻、甘草、则泻自止。疹家不忌泻，泻则阳明之邪热得解，是亦表里分消之义也。疹后泄泻及便脓血，皆由邪热内陷故也，大忌止涩，惟宜升散，仍用升麻、甘草、干葛、黄连、白芍药、白扁豆。便脓血则加滑石末，必自愈。 6、疹后牙疳最危，外用牡黄牛粪尖，煅存性，研极细，加真片脑一分，研匀吹之；内用连翘、干葛、荆芥穗、升麻、玄参、黄连、甘草、生地黄，水煎，加生犀角汁二三十匙调服。缓则不可救药。 7、痧后元气不复，脾胃薄弱者，宜用白芍药、炙甘草为君，莲肉、山药、白扁豆、麦门冬、青黛、龙眼肉为臣。多服必渐强，慎勿轻用参、术。 8、痧后生疮不已，余热未尽故也。宜用金银花、荆芥穗、连翘、玄参、甘草、怀生地、鳖虱胡麻、黄连、木通，浓煎饮之良。 9、痧疹不宜依证施治，惟当治本。本者，手太阴、足阳明二经之邪热也。解其邪热，则诸证自退矣。 10、呕吐 因伤乳食者。 【忌】升、苦寒。诸药俱见前。 【宜】温中、消导。橘皮、缩砂蜜、枳实、厚朴、谷麦糵、草果、山查、红曲、半夏、人参。 因寒者：忌破气、升、苦寒。诸药俱见前者。 【宜】辛热、温中。藿香、橘皮、丁香、人参、白术、生姜、半夏、白豆蔻。 因暑者：忌升、破气、温热。诸药俱见前。 【宜】清暑、补气、安胃，兼利小便。黄连、香薷、人参、木瓜、茯苓、竹茹、石斛、橘皮、甘草、白扁豆、麦门冬、白梅、滑石、木通、泽泻。 有虫者：忌升、甘。诸药俱见前。 【宜】酸敛，佐以苦寒。白芍药、五味子、木瓜、黄连、楝根、乌梅、槟榔、榧子肉、木香、使君子。 总之，数呕吐宜安胃，久则宜补气。 11、泄泻 总忌破气、下、滑利、滞腻。诸药俱见前。 因食者：宜和胃消食。橘皮、草果、红曲、谷麦糵、白豆蔻、白术、山查、白茯苓、肉豆蔻、缩砂蜜。 因湿者：宜燥脾、利水。二术、橘皮、木瓜、茯苓、泽泻、车前子、石斛、黄连、薯蓣、猪苓、升麻、葛根。 因暑者：宜前药中加人参、莲肉、白扁豆。 总之当补脾胃，兼升，兼利小便。 12、急惊 【忌】补敛、升、燥热。诸药俱见前。 【宜】降、清热、镇坠、豁痰、和肝。丹砂、琥珀、牛黄、天竺黄、贝母、竹沥、钓藤钩、僵蚕、茯神、犀角、金箔、胆星、真珠、全蝎、龙脑、麝香、白檀香。 13、慢惊 多因久吐泻、大病后阴阳两虚而成。 【忌】破气、下、升、苦寒，及治急惊药。诸药俱见前。 【宜】补脾健胃、和肝益气、甘温、酸平、佐以辛热。人参、黄耆、茯苓、白芍药、甘草、龙眼肉、酸枣仁、石菖蒲、远志、麦门冬、茯神、冬瓜仁、橘红。 14、疳积 【忌】破气、酸敛、燥热。诸药俱见前。 【宜】除疳热，兼消导、苦寒、甘寒，佐以辛寒、辛温。胡黄连、川黄连、肉豆蔻、谷麦糵、神曲、山查、木香、橘皮、白芜荑、使君子、芦会、白术、白芙蓉花、五谷虫、雷丸、青黛、厚朴。 15、诸虫 【忌】升，甘。诸药俱见前。 【宜】杀虫、酸寒、苦寒，佐以辛寒。槟榔、雷丸、使君子、苦楝根、锡灰、鹤虱、芦荟、芍药、乌梅、黄连、黄芩、牵牛。 16、胎毒 【忌】补敛、燥热、辛温。诸药俱见前。 【宜】凉血清热、解毒，兼发散于外。勿从外治，以致热毒内攻。生地黄、玄参、牡丹皮、黄檗、黄连、忍冬藤、甘草、连翘、麦门冬、贝母、犀角、荆芥、鼠粘子。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MFU1LNRaXHa', 1, '{"title":"卷之二_续序例下_外科","description":"<p>1、疬风</p>\n<p>【忌】破气、酸敛、燥热、下。诸药俱见前。</p>\n<p>【宜】凉血、杀虫、祛风、苦寒，佐以辛寒辛平。豨莶、天门冬、甘菊花、生地黄、青黛、漆叶、苦参、何首乌、鳖虱胡麻仁、白芷、荆芥、天麻、续断、羌、独活、半枝莲、白花蛇、乌梢蛇、皂角刺。</p><p>2、痈疽先后发渴</p>\n<p>【忌】升、破气、辛温、燥热、吐、下。诸药俱见前。</p>\n<p>【宜】活血、凉血、解毒散结。生地黄、连翘、忍冬藤、白芷、白及、白敛、茜草、紫花地丁、夏枯草、甘菊花、地榆、贝母、鼠粘子、黄檗、栝楼根、乳香、没药、芍药、生绿豆、半枝莲、白药子、红药子、黄蜡、明矾。</p>\n<p>已溃者加人参、黄耆、麦门冬、五味子。</p><p>3、肿疡</p>\n<p>忌、宜俱同痈疽。先后发渴，更忌当归。</p><p>4、痈疽毒气攻心，发谵语</p>\n<p>【宜】以生绿豆粉、丹砂、乳香，为丸服之。</p><p>5、溃疡</p>\n<p>【忌】闭气、苦寒、破气，又忌躁。诸药俱见前。</p>\n<p>【宜】补气血、甘、酸温，佐以解毒。人参、红铅、胎骨、黄耆、当归、地黄、芍药、甘草、白及、白敛、忍冬藤、甘菊花、贝母、薯蓣、大枣、五味子、麦门冬。</p>\n<p>散毒（外傅）。雄黄、雌黄、粉锡、矾石、龙脑香、松脂、地榆、水银粉、铁锈、白及、白敛、漏芦、檗木、青葙子、楝实、䕡茹、石灰、铁浆、苦参、菖蒲、槲皮、葵根、柳华、五加皮、梓叶、苎根、紫草、马鞭草、艾（灸）。</p>\n<p></p>\n<p>止痛排脓（外傅）。白及、白敛、大黄、乳香、没药、丹砂、红药子、龙脑、金华、白药子、麦饭石、米醋、蜜。</p>\n<p></p>\n<p>去瘀肉（外傅）。巴豆膏、轻粉、粉霜、乌梅肉灰。</p>\n<p></p>\n<p>蚀脓（外傅）。蛀竹屑、䕡茹、雄黄、白芷、大黄、巴豆、地榆、枯矾。</p>\n<p></p>\n<p>长肉收口（外傅）。仙人杖（烧油）、人参、金华、白蜡、黄蜡、血竭、蛀竹屑、枯矾末、黄芩末、珠末、象牙末、铅丹、红粉霜、胡粉、芝麻油、猪蹄汤。</p><p>6、疔疮</p>\n<p>【忌】补敛、温热。诸药俱见前。</p>\n<p>【宜】凉血活血、解毒、祛风、汗、下。生甘草、辟虺雷、茜草、生地草、贝母、紫花地丁、白药子、大黄、金银花、苍耳草、连翘、夏枯草、鼠粘子、矾石（已上内）、半枝莲、牛黄、蟾酥、红药子、白及、白敛（已上内外）、龙脑、铁锈、桑硇、铜青、雄黄（已上外）。</p><p>7、瘰疬（马刀疮附）</p>\n<p>同属少阳胆经，治法亦同。</p>\n<p>【忌】补气、辛热、酸敛。诸药俱见前。</p>\n<p>【宜】清热散结、和肝凉胆、苦寒、甘寒、咸寒，佐以辛寒。连翘、玄参、忍冬藤、紫背天葵、乳香、麝香、夏枯草、鼠粘子、贝母、天明精、没药、薄荷、肥皂荚、皂角子、何首乌、柴胡、黄芩、甘草、昆布、牡蛎、鳖甲、栝楼根、恶实、漏芦、守宫（煅）、猫头、天荷叶、映山红、海藻、海蛤、苏合油、雄黄、矾石、斑猫、蟾酥、鳖虱胡麻、回燕窝泥。</p><p>8、瘿瘤</p>\n<p>忌、宜俱同瘰疬，兼宜薜荔、半夏、文蛤、南星、通草、生姜。</p><p>9、痔（有内外二证）</p>\n<p>【忌】破气、降、燥热、辛温。诸药俱见前。</p>\n<p>【宜】凉血、活血、除大肠热，兼升。去血过多者宜补血、甘寒、苦寒、酸寒，佐以辛寒。生地黄、五倍子、黄连、黄芩、白芍药、地榆、猬皮、大小蓟、黄檗、侧柏叶、槐实、皂荚灰、熊胆、升麻、鳖甲、红蓝花、龙脑香、茜草、黄耆、赤石脂、猪悬蹄、蛇蜕、榧实、白矾、金银花、青黛、象牙末、蛀竹屑、牛角䚡、白蜡。</p><p>10、通肠漏</p>\n<p>【忌】破气、下、发散、温燥、辛热。诸药俱见前。</p>\n<p>【宜】凉血、清利湿热、解毒、消漏管、补气血、长肉。槐实、黄连、黄芩、青黛、地榆、白及、忍冬藤、半枝莲、生地黄（已上凉血解毒）、猪悬蹄、黄牛角䚡、刺猬皮、蛀竹屑、明矾、金头蜈蚣（已上消漏管）、黄耆、熟地黄、当归、人参、白芍药、五味子、牛膝、山药、枯矾、黄蜡、白蜡、麻皮灰、铅华、月经布、没食子（已上补气血长肉）、天明精、地骨皮（俱要鲜者）、皮硝、文蛤（已上煎浓汤熏洗）。</p><p>11、乳岩、乳痈、内外吹</p>\n<p>【忌】补气、升、温补、辛热、燥、酸敛。</p>\n<p>【宜】散结气、和肝、凉血活血，清热解毒。贝母、橘叶、连翘、栝楼根、山慈菇、山豆根、蒲公英、紫花地丁、黄连、甘草、柴胡、白芷、青皮、橘皮、牡鼠粪、王不留行、乳香、没药、漏芦、夏枯草、忍冬藤、栝楼仁、头垢、人爪、鲮鲤甲、半枝莲、茜根。</p><p>12、阴蚀（即下部疮）</p>\n<p>【忌】同乳岩。</p>\n<p>【宜】凉血活血、除热散毒、苦寒、辛寒。青黛、茜草、苦参、鲜地骨皮、黄檗、小蓟、艾叶、马鞭草、木瓜、牛膝、木通、全蝎（外）、蛇床子（外）、橄榄核（外）、蛀竹屑（外）、猪脊髓（外）、青葙子（外）、腻粉（外）、官粉（外）、杏仁（外）、珠末（外）、皂角末（外）、铅丹（外）、象牙末（外）、龙脑香（外）、白僵蚕（外）、粉霜（外）、烟膏（外）、天灵盖（外）、滴乳石（外）、白蜡（外）。</p><p>13、金疮</p>\n<p>【忌】破气、闭气、升散、酸敛、苦寒、冷利、燥、酸寒。诸药俱见前。</p>\n<p>【【宜】止血、和血、凉血、甘温、甘寒，佐以辛温。地黄、䗪虫、当归、续断、牛膝、甘草、麦门冬、地榆、半夏、茜草、白胶、杜仲、芎、乳香、没药、艾叶、水杨花、钓樟根、黄荆子（炒黑）、王不留行、古钱、自然铜、狗头骨、黄麻皮灰、芦竹箨、韭、大小蓟（内外）、刘寄奴（内外）、花蕊石（内外）、麒麟竭（内外）、古石灰（外）、白蜡（外）、降香（外）、海螵蛸（外）、桑柴灰（外）、人骨灰（外）、紫檀末（外）、三七（外）。</p><p>14、破伤风</p>\n<p>【忌】同金疮。</p>\n<p>【宜】同金疮，佐以祛风药，如白芷、荆芥、防风、柴胡之属。</p><p>15、跌扑损伤</p>\n<p>【忌】同金疮。</p>\n<p>【宜】同金疮。有瘀血停滞者，宜加行血药，如桃仁、红花、苏木、自然铜、䗪虫、千年灰、古文钱之属。</p><p>16、踒折挫闪</p>\n<p>忌、宜俱同金疮、跌扑。</p><p>17、火灼</p>\n<p>【忌】燥热及寒物涂罨。井泥、冰、凉水、芭蕉根、醋（已上寒物涂罨）、馀忌药俱见前。</p>\n<p>【宜】拔散火毒、辛散、润、甘寒、辛寒、苦寒。柴胡、葛根、甘草、升麻、黄连、麦门冬、连翘、栝楼根、石膏、黄檗、鸡子油、柏白皮、生胡麻、食盐、豆酱、黄芩、地榆、山栀。</p>\n<p>外用好酒满浸伤处，温即易之。如遍体被伤，用酒满浸，时时易之即不死。一方用蜜水润之。一方石灰水和生芝麻油敷，治已烂臭甚者，神验。一方用粘米炒黑，为末，将菜汁调敷，神效。</p><p>18、漆疮</p>\n<p>【宜】蟹、茱萸皮、鸡子白、杉材、石蟹、漆姑草、韭莱（炒热罨上）、井中苔萍。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001052,"no":51}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '1、疬风 【忌】破气、酸敛、燥热、下。诸药俱见前。 【宜】凉血、杀虫、祛风、苦寒，佐以辛寒辛平。豨莶、天门冬、甘菊花、生地黄、青黛、漆叶、苦参、何首乌、鳖虱胡麻仁、白芷、荆芥、天麻、续断、羌、独活、半枝莲、白花蛇、乌梢蛇、皂角刺。 2、痈疽先后发渴 【忌】升、破气、辛温、燥热、吐、下。诸药俱见前。 【宜】活血、凉血、解毒散结。生地黄、连翘、忍冬藤、白芷、白及、白敛、茜草、紫花地丁、夏枯草、甘菊花、地榆、贝母、鼠粘子、黄檗、栝楼根、乳香、没药、芍药、生绿豆、半枝莲、白药子、红药子、黄蜡、明矾。 已溃者加人参、黄耆、麦门冬、五味子。 3、肿疡 忌、宜俱同痈疽。先后发渴，更忌当归。 4、痈疽毒气攻心，发谵语 【宜】以生绿豆粉、丹砂、乳香，为丸服之。 5、溃疡 【忌】闭气、苦寒、破气，又忌躁。诸药俱见前。 【宜】补气血、甘、酸温，佐以解毒。人参、红铅、胎骨、黄耆、当归、地黄、芍药、甘草、白及、白敛、忍冬藤、甘菊花、贝母、薯蓣、大枣、五味子、麦门冬。 散毒（外傅）。雄黄、雌黄、粉锡、矾石、龙脑香、松脂、地榆、水银粉、铁锈、白及、白敛、漏芦、檗木、青葙子、楝实、䕡茹、石灰、铁浆、苦参、菖蒲、槲皮、葵根、柳华、五加皮、梓叶、苎根、紫草、马鞭草、艾（灸）。 止痛排脓（外傅）。白及、白敛、大黄、乳香、没药、丹砂、红药子、龙脑、金华、白药子、麦饭石、米醋、蜜。 去瘀肉（外傅）。巴豆膏、轻粉、粉霜、乌梅肉灰。 蚀脓（外傅）。蛀竹屑、䕡茹、雄黄、白芷、大黄、巴豆、地榆、枯矾。 长肉收口（外傅）。仙人杖（烧油）、人参、金华、白蜡、黄蜡、血竭、蛀竹屑、枯矾末、黄芩末、珠末、象牙末、铅丹、红粉霜、胡粉、芝麻油、猪蹄汤。 6、疔疮 【忌】补敛、温热。诸药俱见前。 【宜】凉血活血、解毒、祛风、汗、下。生甘草、辟虺雷、茜草、生地草、贝母、紫花地丁、白药子、大黄、金银花、苍耳草、连翘、夏枯草、鼠粘子、矾石（已上内）、半枝莲、牛黄、蟾酥、红药子、白及、白敛（已上内外）、龙脑、铁锈、桑硇、铜青、雄黄（已上外）。 7、瘰疬（马刀疮附） 同属少阳胆经，治法亦同。 【忌】补气、辛热、酸敛。诸药俱见前。 【宜】清热散结、和肝凉胆、苦寒、甘寒、咸寒，佐以辛寒。连翘、玄参、忍冬藤、紫背天葵、乳香、麝香、夏枯草、鼠粘子、贝母、天明精、没药、薄荷、肥皂荚、皂角子、何首乌、柴胡、黄芩、甘草、昆布、牡蛎、鳖甲、栝楼根、恶实、漏芦、守宫（煅）、猫头、天荷叶、映山红、海藻、海蛤、苏合油、雄黄、矾石、斑猫、蟾酥、鳖虱胡麻、回燕窝泥。 8、瘿瘤 忌、宜俱同瘰疬，兼宜薜荔、半夏、文蛤、南星、通草、生姜。 9、痔（有内外二证） 【忌】破气、降、燥热、辛温。诸药俱见前。 【宜】凉血、活血、除大肠热，兼升。去血过多者宜补血、甘寒、苦寒、酸寒，佐以辛寒。生地黄、五倍子、黄连、黄芩、白芍药、地榆、猬皮、大小蓟、黄檗、侧柏叶、槐实、皂荚灰、熊胆、升麻、鳖甲、红蓝花、龙脑香、茜草、黄耆、赤石脂、猪悬蹄、蛇蜕、榧实、白矾、金银花、青黛、象牙末、蛀竹屑、牛角䚡、白蜡。 10、通肠漏 【忌】破气、下、发散、温燥、辛热。诸药俱见前。 【宜】凉血、清利湿热、解毒、消漏管、补气血、长肉。槐实、黄连、黄芩、青黛、地榆、白及、忍冬藤、半枝莲、生地黄（已上凉血解毒）、猪悬蹄、黄牛角䚡、刺猬皮、蛀竹屑、明矾、金头蜈蚣（已上消漏管）、黄耆、熟地黄、当归、人参、白芍药、五味子、牛膝、山药、枯矾、黄蜡、白蜡、麻皮灰、铅华、月经布、没食子（已上补气血长肉）、天明精、地骨皮（俱要鲜者）、皮硝、文蛤（已上煎浓汤熏洗）。 11、乳岩、乳痈、内外吹 【忌】补气、升、温补、辛热、燥、酸敛。 【宜】散结气、和肝、凉血活血，清热解毒。贝母、橘叶、连翘、栝楼根、山慈菇、山豆根、蒲公英、紫花地丁、黄连、甘草、柴胡、白芷、青皮、橘皮、牡鼠粪、王不留行、乳香、没药、漏芦、夏枯草、忍冬藤、栝楼仁、头垢、人爪、鲮鲤甲、半枝莲、茜根。 12、阴蚀（即下部疮） 【忌】同乳岩。 【宜】凉血活血、除热散毒、苦寒、辛寒。青黛、茜草、苦参、鲜地骨皮、黄檗、小蓟、艾叶、马鞭草、木瓜、牛膝、木通、全蝎（外）、蛇床子（外）、橄榄核（外）、蛀竹屑（外）、猪脊髓（外）、青葙子（外）、腻粉（外）、官粉（外）、杏仁（外）、珠末（外）、皂角末（外）、铅丹（外）、象牙末（外）、龙脑香（外）、白僵蚕（外）、粉霜（外）、烟膏（外）、天灵盖（外）、滴乳石（外）、白蜡（外）。 13、金疮 【忌】破气、闭气、升散、酸敛、苦寒、冷利、燥、酸寒。诸药俱见前。 【【宜】止血、和血、凉血、甘温、甘寒，佐以辛温。地黄、䗪虫、当归、续断、牛膝、甘草、麦门冬、地榆、半夏、茜草、白胶、杜仲、芎、乳香、没药、艾叶、水杨花、钓樟根、黄荆子（炒黑）、王不留行、古钱、自然铜、狗头骨、黄麻皮灰、芦竹箨、韭、大小蓟（内外）、刘寄奴（内外）、花蕊石（内外）、麒麟竭（内外）、古石灰（外）、白蜡（外）、降香（外）、海螵蛸（外）、桑柴灰（外）、人骨灰（外）、紫檀末（外）、三七（外）。 14、破伤风 【忌】同金疮。 【宜】同金疮，佐以祛风药，如白芷、荆芥、防风、柴胡之属。 15、跌扑损伤 【忌】同金疮。 【宜】同金疮。有瘀血停滞者，宜加行血药，如桃仁、红花、苏木、自然铜、䗪虫、千年灰、古文钱之属。 16、踒折挫闪 忌、宜俱同金疮、跌扑。 17、火灼 【忌】燥热及寒物涂罨。井泥、冰、凉水、芭蕉根、醋（已上寒物涂罨）、馀忌药俱见前。 【宜】拔散火毒、辛散、润、甘寒、辛寒、苦寒。柴胡、葛根、甘草、升麻、黄连、麦门冬、连翘、栝楼根、石膏、黄檗、鸡子油、柏白皮、生胡麻、食盐、豆酱、黄芩、地榆、山栀。 外用好酒满浸伤处，温即易之。如遍体被伤，用酒满浸，时时易之即不死。一方用蜜水润之。一方石灰水和生芝麻油敷，治已烂臭甚者，神验。一方用粘米炒黑，为末，将菜汁调敷，神效。 18、漆疮 【宜】蟹、茱萸皮、鸡子白、杉材、石蟹、漆姑草、韭莱（炒热罨上）、井中苔萍。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9bBR1z4YSBd', 1, '{"title":"卷之三_玉石部上品","description":"<p>1、丹砂</p><p>2、云母</p><p>3、石钟乳</p><p>4、矾石</p><p>5、芒硝</p><p>6、朴硝</p><p>7、玄明粉</p><p>8、滑石</p><p>9、空青</p><p>10、紫石英</p><p>11、赤石脂</p><p>12、无名异</p><p>13、绿矾</p><p>14、铁锈</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","section":4001053,"no":52}}', '2024-12-23T08:51:43.000Z', '2024-12-23T08:51:43.000Z', '2024-12-23T08:51:43.000Z', '1、丹砂 2、云母 3、石钟乳 4、矾石 5、芒硝 6、朴硝 7、玄明粉 8、滑石 9、空青 10、紫石英 11、赤石脂 12、无名异 13、绿矾 14、铁锈', '2024-12-23T08:51:43.000Z', 1, NULL, 'OsOP62cyp3j', 'chapter', NULL);
