INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DGzpTF6vkAJ', 4, '{"title":"第400100101条・梓行《本草疏》题辞","description":"<p>      药性之道，具在本草。虽代有哲匠，演其奥义，然去古弥远，寖失其旨。予以绵质，性复疏戆，本不堪尘俗。年方弱冠，直门户衰冷，世累纠缠。以是多见愤激，碍膺之事，十常八九。自兹数婴疾病，於是检讨《图经》，求其本意。积累既久，恍焉有会心处，辄札记之。历三十馀年，遂成此《疏》。学士大夫见而奇之，欲予付诸梓人，予未之许也。予以昔人尝云：“切忌说破，恐塞断后学悟门”，将兹是咎。外孙毛凤苞文学曰：“不然，世间上根人少，中下人多。设使上根人出，自得无师智获，睹此书当不言而喻，默默相契；下根人读之，如盲人谭五色，总不能别；惟中人已上之资，得窥其概，则所得多矣。其为利济，宁有量耶！请亟登梓，以拯夭枉。”予曰：“善”。且曰：“舅祖许可，凤苞愿力任其役。”乃悉检《疏》稿付之。即集予同里门人李枝，通家子云间康元浤，松陵顾澄先二文学，并其舅氏隐沦戈汕辈董督校雠，早夜孜孜，惟恐或后，其用意可谓勤矣！志存及物，有君子之嗜尚焉，良足多也。予年已髦，倘书成而得早行於世，亦足以副海内求明斯道者之企望也。　</p>\n<p>　</p>\n<p>            时天启乙丑暮春海虞遗民缪希雍题于吴江舟次　　</p>\n<p></p>\n<p>      吴兴晚学姚凝之书　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-20T01:24:50.000Z', '2024-12-20T01:24:50.000Z', '2024-12-20T01:24:50.000Z', '药性之道，具在本草。虽代有哲匠，演其奥义，然去古弥远，寖失其旨。予以绵质，性复疏戆，本不堪尘俗。年方弱冠，直门户衰冷，世累纠缠。以是多见愤激，碍膺之事，十常八九。自兹数婴疾病，於是检讨《图经》，求其本意。积累既久，恍焉有会心处，辄札记之。历三十馀年，遂成此《疏》。学士大夫见而奇之，欲予付诸梓人，予未之许也。予以昔人尝云：“切忌说破，恐塞断后学悟门”，将兹是咎。外孙毛凤苞文学曰：“不然，世间上根人少，中下人多。设使上根人出，自得无师智获，睹此书当不言而喻，默默相契；下根人读之，如盲人谭五色，总不能别；惟中人已上之资，得窥其概，则所得多矣。其为利济，宁有量耶！请亟登梓，以拯夭枉。”予曰：“善”。且曰：“舅祖许可，凤苞愿力任其役。”乃悉检《疏》稿付之。即集予同里门人李枝，通家子云间康元浤，松陵顾澄先二文学，并其舅氏隐沦戈汕辈董督校雠，早夜孜孜，惟恐或后，其用意可谓勤矣！志存及物，有君子之嗜尚焉，良足多也。予年已髦，倘书成而得早行於世，亦足以副海内求明斯道者之企望也。 时天启乙丑暮春海虞遗民缪希雍题于吴江舟次 吴兴晚学姚凝之书', '2024-12-20T01:24:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DwmosvL5ofD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w7QDORmHrTl', 4, '{"title":"第400100201条・自序","description":"<p>       《神农本草经》者，古“三坟”之一也。其成於黄帝之世乎？观其尝药别味，对病主治，施之百世，无可逾越。其为开天大圣，悯生民疾苦，於饮食衣服之外，复设针石药物，用拯夭札，俾得尽其天年。是已原夫药之生也，气禀乎天，味成乎地，性在其间。气为阳，味为阴，五味四气，各归其类，斯亲上、亲下之义也。既述之以本性，又制之以君臣，合之以佐使，以成其攻邪已疾之能。遂使无情之用，同诸有识，自非生而神灵、冥契万物者，其孰能与於斯乎！去古滋远，民性滋漓，心识粗浮，莫能研精殚思，深入玄要，而不察乎即象即理，物物昭然，弭疾延年，功力自著。正以“三坟”之书，言大道也，言其然而不言其所以然。言亦象也。予因据经以疏义，缘义以致用，参互以尽其长，简误以防其失；而复详列病忌药忌；以别其微；条析诸药，应病分门，以究其用；刊定七方十剂，以定其法；阐发五藏苦欲补泻，以畅其神。著论三十馀首，以通古今之变。始悉一经之趣，命之曰《神农本草经疏》。读之者宜因疏以通经，因经以契往，俾炎黄之旨，晦而复明，药物之生，利而罔害，乃余述疏意也。余生也晚，亲年已衰，得于禀者固薄，故少善病。长嗜方伎，僻耽药妙，顾念自昔仙人道士，靡不悉由药道以济群生。加之友生协赞，后先不一。驯届耳顺，良友凋丧，百念灰冷。惟兹一事，尚用婴怀，手所论著，裒然成帙。倘典则可师，幽隐可显，试用于世，有广来学，固所愿也，不敢必也。采真同好，其相证诸？</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-20T01:28:14.000Z', '2024-12-20T01:28:14.000Z', '2024-12-20T01:28:14.000Z', '《神农本草经》者，古“三坟”之一也。其成於黄帝之世乎？观其尝药别味，对病主治，施之百世，无可逾越。其为开天大圣，悯生民疾苦，於饮食衣服之外，复设针石药物，用拯夭札，俾得尽其天年。是已原夫药之生也，气禀乎天，味成乎地，性在其间。气为阳，味为阴，五味四气，各归其类，斯亲上、亲下之义也。既述之以本性，又制之以君臣，合之以佐使，以成其攻邪已疾之能。遂使无情之用，同诸有识，自非生而神灵、冥契万物者，其孰能与於斯乎！去古滋远，民性滋漓，心识粗浮，莫能研精殚思，深入玄要，而不察乎即象即理，物物昭然，弭疾延年，功力自著。正以“三坟”之书，言大道也，言其然而不言其所以然。言亦象也。予因据经以疏义，缘义以致用，参互以尽其长，简误以防其失；而复详列病忌药忌；以别其微；条析诸药，应病分门，以究其用；刊定七方十剂，以定其法；阐发五藏苦欲补泻，以畅其神。著论三十馀首，以通古今之变。始悉一经之趣，命之曰《神农本草经疏》。读之者宜因疏以通经，因经以契往，俾炎黄之旨，晦而复明，药物之生，利而罔害，乃余述疏意也。余生也晚，亲年已衰，得于禀者固薄，故少善病。长嗜方伎，僻耽药妙，顾念自昔仙人道士，靡不悉由药道以济群生。加之友生协赞，后先不一。驯届耳顺，良友凋丧，百念灰冷。惟兹一事，尚用婴怀，手所论著，裒然成帙。倘典则可师，幽隐可显，试用于世，有广来学，固所愿也，不敢必也。采真同好，其相证诸？', '2024-12-20T01:28:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'gYfrTaT6HUn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XYJaD1UhbQ6', 4, '{"title":"第400100301条・凡例","description":"<p>一、《本经》为“三坟”之书，后增入《名医别录》，有朱字、墨字之分，总言药之主治，从未有发其所以然者。兹《疏》直接神圣立言之旨，故总题之曰《神农本草经疏》。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-20T01:35:21.000Z', '2024-12-20T01:35:21.000Z', '2024-12-20T01:35:21.000Z', '一、《本经》为“三坟”之书，后增入《名医别录》，有朱字、墨字之分，总言药之主治，从未有发其所以然者。兹《疏》直接神圣立言之旨，故总题之曰《神农本草经疏》。', '2024-12-20T01:35:21.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KrOb38WErF7', 4, '{"title":"第400100313条・凡例","description":"<p>       先生殚一生精力，发千古神圣之奥，以利万世。门人李季虬氏，几经参录，悉以付新安吴康虞氏刻之金陵，未竟而遗焉。流传於知交者，西吴朱氏集而刻之，不及其半，然且序次弗伦，考核未审也。先生以医为司命，一字有讹，遗祸无极。遂命澄先检其存稿若干卷，按部选类，汇得全帙；细复检阅，以为定本。</p>\n<p></p>\n<p>      凡 “续序例” 二卷，药四百九十味，用识年月，书此凡例云。</p>\n<p></p>\n<p>      时天启五年岁在乙丑六月十有一日松陵通家子顾澄先谨识。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100313,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '先生殚一生精力，发千古神圣之奥，以利万世。门人李季虬氏，几经参录，悉以付新安吴康虞氏刻之金陵，未竟而遗焉。流传於知交者，西吴朱氏集而刻之，不及其半，然且序次弗伦，考核未审也。先生以医为司命，一字有讹，遗祸无极。遂命澄先检其存稿若干卷，按部选类，汇得全帙；细复检阅，以为定本。 凡 “续序例” 二卷，药四百九十味，用识年月，书此凡例云。 时天启五年岁在乙丑六月十有一日松陵通家子顾澄先谨识。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qQ6Wpfx1gQY', 4, '{"title":"第400100312条・凡例","description":"<p>一、“续序例” 下卷，倶系病药忌宜。今总列应忌诸药於前，以见必不可轻用。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100312,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、“续序例” 下卷，倶系病药忌宜。今总列应忌诸药於前，以见必不可轻用。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SsGi97KGHPQ', 4, '{"title":"第400100311条・凡例","description":"<p>一、本文顶行立款。其附入之条，有正文者仍从顶行；原系附入者，低字加圈，以别正文。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100311,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、本文顶行立款。其附入之条，有正文者仍从顶行；原系附入者，低字加圈，以别正文。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oJ7UiKHUYgj', 4, '{"title":"第400100310条・凡例","description":"<p>一、《证类本草》第三十卷，倶载有名未用之药。今有常用之物，而本经未载；有《拾遗》载之而未详者，兹列为三十卷 “补遗”。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100310,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、《证类本草》第三十卷，倶载有名未用之药。今有常用之物，而本经未载；有《拾遗》载之而未详者，兹列为三十卷 “补遗”。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aU33CjKzcyu', 4, '{"title":"第400100309条・凡例","description":"<p>一、本文悉遵《证类》善本。但是书流传已久，字画谬讹颇多，兹逐条参订。有一二意义难通者，稍为厘正，如 “伤” 作 “疡”，“动” 作 “痛” 之类。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、本文悉遵《证类》善本。但是书流传已久，字画谬讹颇多，兹逐条参订。有一二意义难通者，稍为厘正，如 “伤” 作 “疡”，“动” 作 “痛” 之类。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('77TbTswQL83', 4, '{"title":"第400100308条・凡例","description":"<p>一、目录次序，悉从《证类本草》，有部分混杂，如木部之藿香，菜部之假苏，今为移正。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、目录次序，悉从《证类本草》，有部分混杂，如木部之藿香，菜部之假苏，今为移正。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5XvTI63rHMA', 4, '{"title":"第400100307条・凡例","description":"<p>一 “简误” 以防误用之失，故有证同而药不宜同者，每条后详书其害。至於性淳功良，有益无损，一药只堪治一病者，悉不复著。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一 “简误” 以防误用之失，故有证同而药不宜同者，每条后详书其害。至於性淳功良，有益无损，一药只堪治一病者，悉不复著。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PCDSH2YAzhD', 4, '{"title":"第400100306条・凡例","description":"<p>一、《证类本草》所载诸方，倶录入 “【主治参与】”，有未当於用者，已为删去。其外诸书所录良方甚多，必详纪述，以便采取。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、《证类本草》所载诸方，倶录入 “【主治参与】”，有未当於用者，已为删去。其外诸书所录良方甚多，必详纪述，以便采取。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H7N1x6E9W21', 4, '{"title":"第400100305条・凡例","description":"<p>一、畏忌制使，物性自然，非可以意求者，俱照本经，列之条下。至其制用之宜，古法倶在。兹复采入，俾得遵守。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、畏忌制使，物性自然，非可以意求者，俱照本经，列之条下。至其制用之宜，古法倶在。兹复采入，俾得遵守。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kvUSH03FKjn', 4, '{"title":"第400100304条・凡例","description":"<p>一、种类随土异形，甚且称名未核。矧近来市肆，饰伪似真。若令误服，遗害非浅。故详辩种类，以正其讹。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、种类随土异形，甚且称名未核。矧近来市肆，饰伪似真。若令误服，遗害非浅。故详辩种类，以正其讹。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ZStS7xbwB1', 4, '{"title":"第400100303条・凡例","description":"<p>一、药类一千二百馀种，品类浩繁，今简治疗之必不可缺，暨近地所产，得於睹记者，备为具疏。馀非必用之药，及罕识难致者，存而不论。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、药类一千二百馀种，品类浩繁，今简治疗之必不可缺，暨近地所产，得於睹记者，备为具疏。馀非必用之药，及罕识难致者，存而不论。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NdajfM2RPYq', 4, '{"title":"第400100302条・凡例","description":"<p>一、药物治疗，《本经》、《别录》业已备悉。间有未尽者，参之以各名家主治，故小字附列於经文之下，或即于疏内叙述，俾采用易稽。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '2024-12-21T01:02:44.000Z', '一、药物治疗，《本经》、《别录》业已备悉。间有未尽者，参之以各名家主治，故小字附列於经文之下，或即于疏内叙述，俾采用易稽。', '2024-12-21T01:02:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oi4Khfzdv9I');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EUBauTo64Ma', 4, '{"title":"第400100401条・卷之一_读《经疏》引","description":"<p>         予之作是《疏》也，赅括经文，义难概述；求其宗趣，宜有裁节。是以或先经而阐义，或随文而畅旨，或断章以相比，或因源以导流，或从末而会本，或根性以知非。凡兹数者，期在发明经旨，适当於用。然惧偏见多遗，难为准的，必欲使纤悉洞了，小大靡遗。开扩来学，臻乎无惑，尚有望于明哲之助焉。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:27:47.000Z', '2024-12-21T01:27:47.000Z', '2024-12-21T01:27:47.000Z', '予之作是《疏》也，赅括经文，义难概述；求其宗趣，宜有裁节。是以或先经而阐义，或随文而畅旨，或断章以相比，或因源以导流，或从末而会本，或根性以知非。凡兹数者，期在发明经旨，适当於用。然惧偏见多遗，难为准的，必欲使纤悉洞了，小大靡遗。开扩来学，臻乎无惑，尚有望于明哲之助焉。', '2024-12-21T01:27:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9KHprCHE7rd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xvqe7fUdLLD', 4, '{"title":"第400100501条・卷之一_续序例上_原本药性气味生成指归","description":"<p>        夫物之生也，必禀乎天。其成也，必资乎地。</p>\n<p></p>\n<p>       天布令，主发生，$m{寒、热、温、凉}，四时之气行焉，阳也；地凝质，主成物，$n{酸、苦、辛、咸、甘、淡}，五行之味滋焉，阴也。</p>\n<p></p>\n<p>       故知微寒微温者，春之气也；大温热者，夏之气也；大热者，长夏之气也；凉者，秋之气也；大寒者，冬之气也。</p>\n<p></p>\n<p>      凡言微寒者，禀春之气以生，春气升而生；言$m{温热}者，盛夏之气以生，夏气散而长；言$m{大热}者，感长夏之气以生，长夏之气软而化；言$m{平}者，感秋之气以生，$m{平}即$m{凉}也，秋气降而收；言$m{大寒}者，感冬之气以生，冬气沉而$m{藏}。此物之气得乎天者也。</p>\n<p> </p>\n<p>      天一生水，地六成之。地二生火，天七成之。天三生木，地八成之。地四生金，天九成之。天五生土，地十成之。</p>\n<p></p>\n<p>      水曰润下，润下作$n{咸}。火曰炎上，炎上作$n{苦}。 木曰曲直，曲直作$n{酸}。金曰从革，从革作$n{辛}。  土爰稼穑，稼穑作$n{甘}。本乎天者亲上，本乎地者亲下。气味多少，各从其类也。</p>\n<p></p>\n<p>      凡言$n{酸}者，得木之气；言$n{辛}者，得金之气；言$n{咸}者，得水之气；言$n{苦}者，得火之气；言$n{甘}者，得土之气。</p>\n<p></p>\n<p>      惟土也，寄旺於四季。生成之数皆五，故其气平，其味甘而淡，其性和而无毒。土德冲和，感而类之，莫或不然。固万物之所出，亦万物之所入乎？此物之味，资乎地者也。　　</p>\n<p></p>\n<p>      气之毒者必$m{热}，味之毒者必$n{辛}。炎黄言味而不加气性者何也？盖古文尚简，故只言味。物有味，必有气，有气斯有性，自然之道也。气味生成，原本乎是。知其所自，则思过半矣。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:29:57.000Z', '2024-12-21T01:29:57.000Z', '2024-12-21T01:29:57.000Z', '夫物之生也，必禀乎天。其成也，必资乎地。 天布令，主发生，$m{寒、热、温、凉}，四时之气行焉，阳也；地凝质，主成物，$n{酸、苦、辛、咸、甘、淡}，五行之味滋焉，阴也。 故知微寒微温者，春之气也；大温热者，夏之气也；大热者，长夏之气也；凉者，秋之气也；大寒者，冬之气也。 凡言微寒者，禀春之气以生，春气升而生；言$m{温热}者，盛夏之气以生，夏气散而长；言$m{大热}者，感长夏之气以生，长夏之气软而化；言$m{平}者，感秋之气以生，$m{平}即$m{凉}也，秋气降而收；言$m{大寒}者，感冬之气以生，冬气沉而$m{藏}。此物之气得乎天者也。 天一生水，地六成之。地二生火，天七成之。天三生木，地八成之。地四生金，天九成之。天五生土，地十成之。 水曰润下，润下作$n{咸}。火曰炎上，炎上作$n{苦}。 木曰曲直，曲直作$n{酸}。金曰从革，从革作$n{辛}。 土爰稼穑，稼穑作$n{甘}。本乎天者亲上，本乎地者亲下。气味多少，各从其类也。 凡言$n{酸}者，得木之气；言$n{辛}者，得金之气；言$n{咸}者，得水之气；言$n{苦}者，得火之气；言$n{甘}者，得土之气。 惟土也，寄旺於四季。生成之数皆五，故其气平，其味甘而淡，其性和而无毒。土德冲和，感而类之，莫或不然。固万物之所出，亦万物之所入乎？此物之味，资乎地者也。 气之毒者必$m{热}，味之毒者必$n{辛}。炎黄言味而不加气性者何也？盖古文尚简，故只言味。物有味，必有气，有气斯有性，自然之道也。气味生成，原本乎是。知其所自，则思过半矣。', '2024-12-21T01:29:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'GmpduHksm9v');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FwnIC8SBy6l', 4, '{"title":"第400100601条・卷之一_续序例上_药性【主治参与】指归","description":"<p>         今夫病，譬诸兵焉。料敌出奇者，将之谋也；破军杀贼者，士之力也。</p>\n<p></p>\n<p>        审度病机者，医之智也；攻邪伐病者，药之能也。非士无以破敌，非药无以攻邪。故良将养士，上医蓄药。然不知士，何以养？不知药，何以蓄？夫士犹有情实可考，才略可试，尚曰难知。</p>\n<p></p>\n<p>        以孔明之明，一马谡用违其才，卒致败衄，悔不可追，况乎药石无情，才性莫测，既非言论之可考，又非拟议之可及，而欲知其的然不谬，非神圣之智，其孰能与於斯？ 假令尝试漫为，则下咽不返，死生立判，顾不大可惧耶！</p>\n<p> </p>\n<p>      上古之人，病生於$n{六淫者多}，发于$m{七情者寡}。故其主治，尝以一药治一病，或一药治数病。今时则不然：$n{七情弥厚，五欲弥深，精气既亏，六淫易入}。$m{内外胶固，病情殊古}：则$n{须合众药之所长，而又善护其所短，乃能苏凋瘵而起沉疴，其在良医善知药性}，剂量无差，庶得参互旁通，彼此兼济，以尽其才，而无乖刺败坏之弊矣。故作“【主治参与】”，俾后之医师循而求之，共收平定之功，期无夭枉之患，斯作《疏》意也。昔人云：“用医如用兵。”旨哉言乎！旨哉言乎！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:32:51.000Z', '2024-12-21T01:32:51.000Z', '2024-12-21T01:32:51.000Z', '今夫病，譬诸兵焉。料敌出奇者，将之谋也；破军杀贼者，士之力也。 审度病机者，医之智也；攻邪伐病者，药之能也。非士无以破敌，非药无以攻邪。故良将养士，上医蓄药。然不知士，何以养？不知药，何以蓄？夫士犹有情实可考，才略可试，尚曰难知。 以孔明之明，一马谡用违其才，卒致败衄，悔不可追，况乎药石无情，才性莫测，既非言论之可考，又非拟议之可及，而欲知其的然不谬，非神圣之智，其孰能与於斯？ 假令尝试漫为，则下咽不返，死生立判，顾不大可惧耶！ 上古之人，病生於$n{六淫者多}，发于$m{七情者寡}。故其主治，尝以一药治一病，或一药治数病。今时则不然：$n{七情弥厚，五欲弥深，精气既亏，六淫易入}。$m{内外胶固，病情殊古}：则$n{须合众药之所长，而又善护其所短，乃能苏凋瘵而起沉疴，其在良医善知药性}，剂量无差，庶得参互旁通，彼此兼济，以尽其才，而无乖刺败坏之弊矣。故作“【主治参与】”，俾后之医师循而求之，共收平定之功，期无夭枉之患，斯作《疏》意也。昔人云：“用医如用兵。”旨哉言乎！旨哉言乎！', '2024-12-21T01:32:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'qY6eqI3CHpg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ivjAlttb2rc', 4, '{"title":"第400100701条・卷之一_续序例上_药性简误指归","description":"<p>       夫$x{药石}禀$m{天地偏至之气者也}。$n{虽醇和浓懿}，号称$m{上药}，然所禀既$x{偏}，所至必$x{独}。脱也用违其性之宜，则偏重之害，势所必至。</p>\n<p></p>\n<p>       故凡有益于$x{阳虚者}，必$x{不利乎阴}；有益于$x{阴虚者}，必$x{不利乎阳}。</p>\n<p></p>\n<p>       能治$x{燥者}，必不宜于$x{湿}；</p>\n<p></p>\n<p>       能治$x{湿者}，必不宜于$x{燥}。</p>\n<p></p>\n<p>      能破$x{散者}，不可以$x{治虚}；</p>\n<p></p>\n<p>      能收$x{敛者}，不可以治实。</p>\n<p></p>\n<p>      $x{升}，不可以$x{止升}；</p>\n<p>   </p>\n<p>      $x{降}，不可以$x{疗降}。</p>\n<p></p>\n<p>     $x{寒}有时而不宜于$x{热}，$x{热}有时而不宜于$x{寒}。</p>\n<p></p>\n<p>     古人$u{半夏}有三禁，谓渴家、汗家、血家。</p>\n<p></p>\n<p>     仲景呕家忌$x{甘}，酒家亦忌$x{甘}。王好古论$x{肺热}忌$u{人参}之属。</p>\n<p></p>\n<p>     诸如此类，莫可胜数。苟昧斯旨，吉凶贸焉。人命至重，冥报难逃，医为司命，其可不深思详察也哉！此与“十剂”互证。“十剂”对治，$x{反}则为$m{误}，故作“简误”以防其失。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:33:42.000Z', '2024-12-21T01:33:42.000Z', '2024-12-21T01:33:42.000Z', '夫$x{药石}禀$m{天地偏至之气者也}。$n{虽醇和浓懿}，号称$m{上药}，然所禀既$x{偏}，所至必$x{独}。脱也用违其性之宜，则偏重之害，势所必至。 故凡有益于$x{阳虚者}，必$x{不利乎阴}；有益于$x{阴虚者}，必$x{不利乎阳}。 能治$x{燥者}，必不宜于$x{湿}； 能治$x{湿者}，必不宜于$x{燥}。 能破$x{散者}，不可以$x{治虚}； 能收$x{敛者}，不可以治实。 $x{升}，不可以$x{止升}； $x{降}，不可以$x{疗降}。 $x{寒}有时而不宜于$x{热}，$x{热}有时而不宜于$x{寒}。 古人$u{半夏}有三禁，谓渴家、汗家、血家。 仲景呕家忌$x{甘}，酒家亦忌$x{甘}。王好古论$x{肺热}忌$u{人参}之属。 诸如此类，莫可胜数。苟昧斯旨，吉凶贸焉。人命至重，冥报难逃，医为司命，其可不深思详察也哉！此与“十剂”互证。“十剂”对治，$x{反}则为$m{误}，故作“简误”以防其失。', '2024-12-21T01:33:42.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'J5d0Ry9lo9l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CqsPXJxlU24', 4, '{"title":"第400100809条・卷之一_续序例上_论七方本义","description":"<p>$m{复方}　　</p>\n<p>        岐伯曰：奇之不去则偶之，是谓重方。好古曰：奇之不去复以偶，偶之不去复以奇，故曰复。复者，再也，重也。所谓十补一泄，数泄一补也。又伤寒见风脉，伤风得寒脉，为脉证不相应，宜以复方主之。从正曰：复方有三。有二方、三方及数方相合之复方，如桂枝二越婢一汤、五积散之属是也。有本方之外、别加馀药，如调胃承气加连翘、薄荷、黄芩、栀子为凉膈散之属是也。有分两均齐之复方，如胃风汤各等分之属是也。王太仆以偶为复方，今七方有偶又有复，岂非偶乃二方相合，复乃数方相合之谓乎？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100809,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{复方} 岐伯曰：奇之不去则偶之，是谓重方。好古曰：奇之不去复以偶，偶之不去复以奇，故曰复。复者，再也，重也。所谓十补一泄，数泄一补也。又伤寒见风脉，伤风得寒脉，为脉证不相应，宜以复方主之。从正曰：复方有三。有二方、三方及数方相合之复方，如桂枝二越婢一汤、五积散之属是也。有本方之外、别加馀药，如调胃承气加连翘、薄荷、黄芩、栀子为凉膈散之属是也。有分两均齐之复方，如胃风汤各等分之属是也。王太仆以偶为复方，今七方有偶又有复，岂非偶乃二方相合，复乃数方相合之谓乎？', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IArLL8co1lU', 4, '{"title":"第400100808条・卷之一_续序例上_论七方本义","description":"<p>$m{偶方}　　</p>\n<p>        从正曰：偶方有三：有两味相配之偶方，有古之二方相合之偶方，古谓之复方，皆病在下而远者宜之。有药合阴数二、四、六、八、十之偶方，宜汗不宜下。王太仆言汗药不以偶，则气不足以外发；下药不以奇，则药毒攻而致过。意者下本迅利，故单行则力专，专则直下、不旁及而速；汗或难出，故并行则物众而力微乎？乃仲景制方，桂枝汗药，反以三味为奇；大承气下药，反以四味为偶，何也？岂汗下缓急，在力之大小，而不以数之奇偶为重乎？　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100808,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{偶方} 从正曰：偶方有三：有两味相配之偶方，有古之二方相合之偶方，古谓之复方，皆病在下而远者宜之。有药合阴数二、四、六、八、十之偶方，宜汗不宜下。王太仆言汗药不以偶，则气不足以外发；下药不以奇，则药毒攻而致过。意者下本迅利，故单行则力专，专则直下、不旁及而速；汗或难出，故并行则物众而力微乎？乃仲景制方，桂枝汗药，反以三味为奇；大承气下药，反以四味为偶，何也？岂汗下缓急，在力之大小，而不以数之奇偶为重乎？', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NaBgMD4173y', 4, '{"title":"第400100807条・卷之一_续序例上_论七方本义","description":"<p>$m{奇方}　　</p>\n<p>        王冰曰：单方也。从正曰：奇方有二：有独用一物之奇方，病在下而近者宜之。有药合阳数一、三、五、七、九之奇方，宜下不宜汗。完素曰：假如小承气，奇之小方也；大承气、抵当汤，奇之大方也，所谓因其攻下而为之也。桂枝、麻黄、偶之小方也；葛根、青龙，偶之大方也，所谓因其发散而用之也。故曰：汗不以奇，下不以偶。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100807,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{奇方} 王冰曰：单方也。从正曰：奇方有二：有独用一物之奇方，病在下而近者宜之。有药合阳数一、三、五、七、九之奇方，宜下不宜汗。完素曰：假如小承气，奇之小方也；大承气、抵当汤，奇之大方也，所谓因其攻下而为之也。桂枝、麻黄、偶之小方也；葛根、青龙，偶之大方也，所谓因其发散而用之也。故曰：汗不以奇，下不以偶。', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4s0WoGWJ5ts', 4, '{"title":"第400100806条・卷之一_续序例上_论七方本义","description":"<p>$m{急方}　　</p>\n<p>        完素曰：味厚者为阴，味薄者为阴中之阳，故味厚则下泄，味薄则通气；气厚者为阳，气薄者为阳中之阴，故气厚则发热，气薄则发汗是也。好古曰：治主宜缓，缓则治其本也；治客宜急，急则治其标也。表里汗下，皆有所当缓、所当急。从正曰：急方有四：有急病急攻之急方，中风、关格之病是也。有汤散荡涤之急方，下咽易散而行速也。有毒药之急方，毒性能上涌下泄以夺病势也。有气味俱厚之急方，气味俱厚，直趋于下而力不衰也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100806,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{急方} 完素曰：味厚者为阴，味薄者为阴中之阳，故味厚则下泄，味薄则通气；气厚者为阳，气薄者为阳中之阴，故气厚则发热，气薄则发汗是也。好古曰：治主宜缓，缓则治其本也；治客宜急，急则治其标也。表里汗下，皆有所当缓、所当急。从正曰：急方有四：有急病急攻之急方，中风、关格之病是也。有汤散荡涤之急方，下咽易散而行速也。有毒药之急方，毒性能上涌下泄以夺病势也。有气味俱厚之急方，气味俱厚，直趋于下而力不衰也。', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HHVM6VvW3mC', 4, '{"title":"第400100805条・卷之一_续序例上_论七方本义","description":"<p>$m{缓方}　　</p>\n<p>        岐伯曰：补上治上制以缓，补下治下制以急。急则气味厚，缓则气味薄，适其至所，此之谓也。病所远而中道气味之者，食而过之，无越其制度也。王冰曰：假如病在肾而心气不足，服药宜急过之，不以气味饲心，肾药凌心，心复益散矣。馀上下远近例同。完素曰：圣人治上不犯下，治下不犯上，治中上下俱无犯。故曰：诛伐无过，命曰大惑。好古曰：治上必妨下，治表必违里。用黄芩以治肺必妨脾，用苁蓉以治肾必妨心，用干姜以治中必僭上，服附子以补火必涸水。从正曰：缓方有五：有甘以缓之之方，甘草、糖、蜜之属是也，病在胸膈，取其留恋也；有丸以缓之之方，比之汤散，其行迟慢也；有品件众多之缓方，药众则递相拘制，不得各骋其性也；有无毒治病之缓方，无毒则性纯功缓也；有气味俱薄之缓方，气味薄则长于补上治上，比至其下，药力已衰矣。　　</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100805,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{缓方} 岐伯曰：补上治上制以缓，补下治下制以急。急则气味厚，缓则气味薄，适其至所，此之谓也。病所远而中道气味之者，食而过之，无越其制度也。王冰曰：假如病在肾而心气不足，服药宜急过之，不以气味饲心，肾药凌心，心复益散矣。馀上下远近例同。完素曰：圣人治上不犯下，治下不犯上，治中上下俱无犯。故曰：诛伐无过，命曰大惑。好古曰：治上必妨下，治表必违里。用黄芩以治肺必妨脾，用苁蓉以治肾必妨心，用干姜以治中必僭上，服附子以补火必涸水。从正曰：缓方有五：有甘以缓之之方，甘草、糖、蜜之属是也，病在胸膈，取其留恋也；有丸以缓之之方，比之汤散，其行迟慢也；有品件众多之缓方，药众则递相拘制，不得各骋其性也；有无毒治病之缓方，无毒则性纯功缓也；有气味俱薄之缓方，气味薄则长于补上治上，比至其下，药力已衰矣。', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mr24pBT6Icv', 4, '{"title":"第400100804条・卷之一_续序例上_论七方本义","description":"<p>$m{小方}　　</p>\n<p>          从正曰：小方有二：有君一、臣二之小方，病无兼证，邪气专一，可一二味治者宜之；有分两少而频服之小方，心肺及在上之病者宜之，徐徐细呷是也。完素曰：肝肾位远，数多则其气缓，不能速达于下，必大剂而数少，取其迅急下走也。心肺位近，数少则其气急下走，不能升发于上，必小剂而数多，取其易散而上行也。王氏所谓肺服九，心服七，脾服五，肝服三，肾服一，乃五脏生成之数也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100804,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{小方} 从正曰：小方有二：有君一、臣二之小方，病无兼证，邪气专一，可一二味治者宜之；有分两少而频服之小方，心肺及在上之病者宜之，徐徐细呷是也。完素曰：肝肾位远，数多则其气缓，不能速达于下，必大剂而数少，取其迅急下走也。心肺位近，数少则其气急下走，不能升发于上，必小剂而数多，取其易散而上行也。王氏所谓肺服九，心服七，脾服五，肝服三，肾服一，乃五脏生成之数也。', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bFZt27T154K', 4, '{"title":"第400100803条・卷之一_续序例上_论七方本义","description":"<p>$m{大方}　　</p>\n<p>       岐伯曰：君一、臣三、佐九，制之大也；君一、臣三、佐五，制之中也；君一、臣二，制之小也。又曰：远而奇偶，制大其服；近而偶奇，制小其服。大则数少，小则数多。多则九之，小则二之。完素曰：身表为远，身里为近。大小者，制奇偶之法也。假如小承气汤、调胃承气汤，奇之小方也；大承气汤、抵当汤，奇之大方也，所谓因其攻里而用之也。桂枝、麻黄，偶之小方也；葛根、青龙，偶之大方也，所谓因其发表而用之也。故曰：汗不以奇，下不以偶。张从正曰：大方有二：有君一、臣三、佐九之大方，病有兼证而邪不一，不可以一二味治者宜之；有分两大而顿服之大方，肝肾及下部之病道远者宜之。王太仆以心肺为近，肾肝为远，脾胃为中。刘河间以身表为远，身里为近。以予观之，身半以上其气三，天之分也。身半以下其气三，地之分也。中脘，人之分也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100803,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '$m{大方} 岐伯曰：君一、臣三、佐九，制之大也；君一、臣三、佐五，制之中也；君一、臣二，制之小也。又曰：远而奇偶，制大其服；近而偶奇，制小其服。大则数少，小则数多。多则九之，小则二之。完素曰：身表为远，身里为近。大小者，制奇偶之法也。假如小承气汤、调胃承气汤，奇之小方也；大承气汤、抵当汤，奇之大方也，所谓因其攻里而用之也。桂枝、麻黄，偶之小方也；葛根、青龙，偶之大方也，所谓因其发表而用之也。故曰：汗不以奇，下不以偶。张从正曰：大方有二：有君一、臣三、佐九之大方，病有兼证而邪不一，不可以一二味治者宜之；有分两大而顿服之大方，肝肾及下部之病道远者宜之。王太仆以心肺为近，肾肝为远，脾胃为中。刘河间以身表为远，身里为近。以予观之，身半以上其气三，天之分也。身半以下其气三，地之分也。中脘，人之分也。', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rTVA6uV4mmh', 4, '{"title":"第400100802条・卷之一_续序例上_论七方本义","description":"<p>附录：七方　　</p>\n<p></p>\n<p>       岐伯曰：气有多少，形有盛衰。治有缓急，方有大小。又曰：病有远近，证有中外，治有轻重。近者偶之，远者奇之。汗不以奇，下不以偶。补上治上制以缓，补下治下制以急。近而偶奇，制小其服；远而奇偶，制大其服。大则数小，小则数多。多则九之，少则一之。奇之不去则偶之，偶之不去则反佐以取之。所谓寒热温凉，反从其病也。　　</p>\n<p></p>\n<p>       王冰曰：脏位有高下，腑气有远近。病证有表里，药用有轻重。单方为奇，复方为偶。心肺为近，肝肾为远，脾胃居中。肠、膀、胞、胆，亦有远近。识见高远，权以合宜。方奇而分两偶，方偶而分两奇。近而偶制，多数服之；远而奇制，少数服之。则肺服九，心服七，脾服五，肝服三，肾服一，为常制也，方与其重也宁轻，与其毒也宁良，与其大也宁小。是以奇方不去，偶方主之；偶方不去，则反佐以同病之气而取之。夫微小之热，折之以寒；微小之冷，消之以热。其大寒热，则必能与异气相格，声不同不相应，气不同不相合。是以反其佐，以同其气，夏令寒热参合，使其始同终异也。　</p>\n<p>　</p>\n<p>       逆者正治，从者反治。反佐，即从治也。谓热在下而上有寒邪拒格，则寒药中入热药为佐。下膈之后，热气既散，寒性随发也。寒在下而上有浮火拒格，则热药中入寒药为佐。下膈之后，寒气既消，热性随发也。此寒因热用，热因寒用之妙也。温冷仿此。　</p>\n<p>　</p>\n<p>      完素曰：流变在乎病，主病在乎方，制方在乎人。方有七：大、小、缓、急、奇、偶、复也。制方之体，本於气味。寒、热、温、凉，四气生於天；酸、苦、辛、咸、甘、淡，六味成於地。是以有形为味，无形为气。气为阳，味为阴。辛甘发散为阳，酸苦涌泄为阴。咸味涌泄为阴，淡味渗泄为阳。或收或散，或缓或急，或燥或润，或软或坚，各随脏腑之证。而施药之品味，乃分七方之制也。故奇、偶、复，三方也，大、小、缓、急，四制之法也。故曰：治有缓急，方有大小。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100802,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '附录：七方 岐伯曰：气有多少，形有盛衰。治有缓急，方有大小。又曰：病有远近，证有中外，治有轻重。近者偶之，远者奇之。汗不以奇，下不以偶。补上治上制以缓，补下治下制以急。近而偶奇，制小其服；远而奇偶，制大其服。大则数小，小则数多。多则九之，少则一之。奇之不去则偶之，偶之不去则反佐以取之。所谓寒热温凉，反从其病也。 王冰曰：脏位有高下，腑气有远近。病证有表里，药用有轻重。单方为奇，复方为偶。心肺为近，肝肾为远，脾胃居中。肠、膀、胞、胆，亦有远近。识见高远，权以合宜。方奇而分两偶，方偶而分两奇。近而偶制，多数服之；远而奇制，少数服之。则肺服九，心服七，脾服五，肝服三，肾服一，为常制也，方与其重也宁轻，与其毒也宁良，与其大也宁小。是以奇方不去，偶方主之；偶方不去，则反佐以同病之气而取之。夫微小之热，折之以寒；微小之冷，消之以热。其大寒热，则必能与异气相格，声不同不相应，气不同不相合。是以反其佐，以同其气，夏令寒热参合，使其始同终异也。 逆者正治，从者反治。反佐，即从治也。谓热在下而上有寒邪拒格，则寒药中入热药为佐。下膈之后，热气既散，寒性随发也。寒在下而上有浮火拒格，则热药中入寒药为佐。下膈之后，寒气既消，热性随发也。此寒因热用，热因寒用之妙也。温冷仿此。 完素曰：流变在乎病，主病在乎方，制方在乎人。方有七：大、小、缓、急、奇、偶、复也。制方之体，本於气味。寒、热、温、凉，四气生於天；酸、苦、辛、咸、甘、淡，六味成於地。是以有形为味，无形为气。气为阳，味为阴。辛甘发散为阳，酸苦涌泄为阴。咸味涌泄为阴，淡味渗泄为阳。或收或散，或缓或急，或燥或润，或软或坚，各随脏腑之证。而施药之品味，乃分七方之制也。故奇、偶、复，三方也，大、小、缓、急，四制之法也。故曰：治有缓急，方有大小。', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gYf9yZaIN1Z', 4, '{"title":"第400100801条・卷之一_续序例上_论七方本义","description":"<p>         夫方者，法也。法乃所以制物者也。故$x{大}、$x{小}、$x{缓}、$x{急}、$x{奇}、$x{偶}、$x{复}七者，为法制之变且尽也。</p>\n<p></p>\n<p>       七方不同，同归已疾。其制各异，异以从宜。</p>\n<p></p>\n<p>       岐伯言之已详，后人演之弥悉，凡制方者必本乎是。</p>\n<p></p>\n<p>      $y{苟悖其制，则非法矣}。非法则不能所施合辙，而反致$m{乖刺}，恶在其能攻邪已疾耶！　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '2024-12-21T01:38:40.000Z', '夫方者，法也。法乃所以制物者也。故$x{大}、$x{小}、$x{缓}、$x{急}、$x{奇}、$x{偶}、$x{复}七者，为法制之变且尽也。 七方不同，同归已疾。其制各异，异以从宜。 岐伯言之已详，后人演之弥悉，凡制方者必本乎是。 $y{苟悖其制，则非法矣}。非法则不能所施合辙，而反致$m{乖刺}，恶在其能攻邪已疾耶！', '2024-12-21T01:38:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eOvHKJDNetK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0HhuO4hTOqf', 4, '{"title":"第400100901条・卷之一_续序例上_论十剂本义","description":"<p>        剂者，从齐从刀，用以齐其不齐，而成其所以齐也。</p>\n<p></p>\n<p>       夫独用之谓药，合用之谓剂，而其才有长短、大小、良毒之难齐，故用有$x{相益}、$x{相济}、$x{相畏}、$x{相恶}、$x{相忌}、$x{相制}之不同，则剂有$x{宣}、$x{通}、$x{补}、$x{泻}、$x{轻}、$x{重}、$x{滑}、$x{涩}、$x{燥}、$x{湿}十者对治之各异。</p>\n<p></p>\n<p>       譬夫良相剂量群才，以成治世之功，类良医剂量群药，以成治病之功，其义一也。岐伯论之详矣！凡和剂者必本乎是。苟昧其旨而违其道，即失对治之义，求疾之瘳，其可得乎！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:40:24.000Z', '2024-12-21T01:40:24.000Z', '2024-12-21T01:40:24.000Z', '剂者，从齐从刀，用以齐其不齐，而成其所以齐也。 夫独用之谓药，合用之谓剂，而其才有长短、大小、良毒之难齐，故用有$x{相益}、$x{相济}、$x{相畏}、$x{相恶}、$x{相忌}、$x{相制}之不同，则剂有$x{宣}、$x{通}、$x{补}、$x{泻}、$x{轻}、$x{重}、$x{滑}、$x{涩}、$x{燥}、$x{湿}十者对治之各异。 譬夫良相剂量群才，以成治世之功，类良医剂量群药，以成治病之功，其义一也。岐伯论之详矣！凡和剂者必本乎是。苟昧其旨而违其道，即失对治之义，求疾之瘳，其可得乎！', '2024-12-21T01:40:24.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ROuN4WaQ2dj', 4, '{"title":"第400100912条・卷之一_续序例上_论十剂本义","description":"<p>湿剂　　</p>\n<p>            之才曰：湿可去枯，白石英、紫石英之属是也。从正曰：湿者，润湿也。虽与滑类，少有不同。《经》云：辛以润之。辛能走气、能化液故也。盐、硝味虽咸，属真阴之水，诚濡枯之上药也。人有枯涸皴揭之病，非独金化，盖有火以乘之，故非湿剂不能愈。完素曰：津耗为枯，五脏痿弱，荣卫涸涩，必湿剂以润之。好古曰：有减气而枯，有减血而枯。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100912,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '湿剂 之才曰：湿可去枯，白石英、紫石英之属是也。从正曰：湿者，润湿也。虽与滑类，少有不同。《经》云：辛以润之。辛能走气、能化液故也。盐、硝味虽咸，属真阴之水，诚濡枯之上药也。人有枯涸皴揭之病，非独金化，盖有火以乘之，故非湿剂不能愈。完素曰：津耗为枯，五脏痿弱，荣卫涸涩，必湿剂以润之。好古曰：有减气而枯，有减血而枯。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8day6HJaWAW', 4, '{"title":"第400100911条・卷之一_续序例上_论十剂本义","description":"<p>燥剂　　</p>\n<p>         之才曰：燥可去湿，桑白皮、赤小豆之属是也。完素曰：湿气淫胜，肿满脾湿，必燥剂以除之，桑皮之属。湿胜于上，以苦吐之，以淡渗之是也。从正曰：积寒久冷，吐利腥秽，上下所出水液澄彻清冷，此大寒之病，宜姜、附、胡椒辈以燥之。若病湿气，则陈皮、白术、木香、苍术之属除之，亦燥剂也。而黄连、黄檗、栀子、大黄，其味皆苦，苦属火化，皆能燥湿，此《内经》之本旨也，岂独二术之类为燥剂乎？好古曰：湿有在上、在中、在下、在经、在皮、在里。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100911,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '燥剂 之才曰：燥可去湿，桑白皮、赤小豆之属是也。完素曰：湿气淫胜，肿满脾湿，必燥剂以除之，桑皮之属。湿胜于上，以苦吐之，以淡渗之是也。从正曰：积寒久冷，吐利腥秽，上下所出水液澄彻清冷，此大寒之病，宜姜、附、胡椒辈以燥之。若病湿气，则陈皮、白术、木香、苍术之属除之，亦燥剂也。而黄连、黄檗、栀子、大黄，其味皆苦，苦属火化，皆能燥湿，此《内经》之本旨也，岂独二术之类为燥剂乎？好古曰：湿有在上、在中、在下、在经、在皮、在里。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aDm8LlZN0My', 4, '{"title":"第400100910条・卷之一_续序例上_论十剂本义","description":"<p>涩剂　　</p>\n<p>         之才曰：涩可去脱，牡蛎、龙骨之属是也。完素曰：滑则气脱，如开肠洞泄，便溺遗失之类，必涩剂以收敛之。从正曰：寝汗不禁，涩以牡蛎、五味、五倍之属。滑泄不已，涩以肉豆蔻、诃黎勒、没食子、亚芙蓉、龙骨之属。凡酸味同乎涩者，收敛之义也。然此种皆宜先攻其本，而后收之可也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100910,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '涩剂 之才曰：涩可去脱，牡蛎、龙骨之属是也。完素曰：滑则气脱，如开肠洞泄，便溺遗失之类，必涩剂以收敛之。从正曰：寝汗不禁，涩以牡蛎、五味、五倍之属。滑泄不已，涩以肉豆蔻、诃黎勒、没食子、亚芙蓉、龙骨之属。凡酸味同乎涩者，收敛之义也。然此种皆宜先攻其本，而后收之可也。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UQWNL0TGc0n', 4, '{"title":"第400100909条・卷之一_续序例上_论十剂本义","description":"<p>滑剂　　</p>\n<p>         之才曰：滑可去着，冬葵子、榆白皮之属是也。完素曰：涩则气着，必滑剂以利之。滑能养窍，故润利也。从正曰：大便燥结，宜麻仁、郁李之类；小便癃闭，宜葵子、滑石之类。前后不通，两阴俱闭也，名曰三焦约。约者，束也。宜先以滑剂润养其燥，然后攻之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100909,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '滑剂 之才曰：滑可去着，冬葵子、榆白皮之属是也。完素曰：涩则气着，必滑剂以利之。滑能养窍，故润利也。从正曰：大便燥结，宜麻仁、郁李之类；小便癃闭，宜葵子、滑石之类。前后不通，两阴俱闭也，名曰三焦约。约者，束也。宜先以滑剂润养其燥，然后攻之。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KFJniJF2Ru2', 4, '{"title":"第400100908条・卷之一_续序例上_论十剂本义","description":"<p>重剂　　</p>\n<p>           之才曰：重可去怯，磁石、铁粉之属是也。从正曰：重者，镇坠之谓也。怯则气浮，如丧神失守，而惊悸气上。朱砂、水银、沉香、黄丹、寒水石之伦，皆镇重也。久病咳嗽，涎潮于上，形羸不可攻者，以此坠之。《经》曰：重者因而减之，贵其渐也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '重剂 之才曰：重可去怯，磁石、铁粉之属是也。从正曰：重者，镇坠之谓也。怯则气浮，如丧神失守，而惊悸气上。朱砂、水银、沉香、黄丹、寒水石之伦，皆镇重也。久病咳嗽，涎潮于上，形羸不可攻者，以此坠之。《经》曰：重者因而减之，贵其渐也。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fSazXN8x7lg', 4, '{"title":"第400100907条・卷之一_续序例上_论十剂本义","description":"<p>轻剂　　</p>\n<p>         之才曰：轻可去实，麻黄、葛根之属是也。从正曰：风寒之邪，始客皮肤，头痛身热，宜解其表，《内经》所谓轻而扬之也。痈疮疥痤，俱宜解表。汗以泄之，毒以熏之，皆轻剂也。凡熏、洗、蒸、灸、熨、烙、刺、砭、导引、按摩，皆汗法也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100907,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '轻剂 之才曰：轻可去实，麻黄、葛根之属是也。从正曰：风寒之邪，始客皮肤，头痛身热，宜解其表，《内经》所谓轻而扬之也。痈疮疥痤，俱宜解表。汗以泄之，毒以熏之，皆轻剂也。凡熏、洗、蒸、灸、熨、烙、刺、砭、导引、按摩，皆汗法也。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j5ye9vpIfMU', 4, '{"title":"第400100906条・卷之一_续序例上_论十剂本义","description":"<p>泻剂　　</p>\n<p>            之才曰：泄可去闭，葶苈、大黄之属是也。杲曰：葶苈苦寒，气味俱厚，不减大黄，能泄肺中之闭，又泄大肠。大黄走而不守，能泄血闭、肠胃渣秽之物。一泄气闭利小便，一泄血闭利大便。凡与二药同者皆然。从正曰：实则泄之。诸痛为实，痛随利减。芒硝、大黄、牵牛、甘遂、巴豆之属，皆泻剂也。其催生下乳，磨积逐水，破经泄气，凡下行者，皆下法也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100906,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '泻剂 之才曰：泄可去闭，葶苈、大黄之属是也。杲曰：葶苈苦寒，气味俱厚，不减大黄，能泄肺中之闭，又泄大肠。大黄走而不守，能泄血闭、肠胃渣秽之物。一泄气闭利小便，一泄血闭利大便。凡与二药同者皆然。从正曰：实则泄之。诸痛为实，痛随利减。芒硝、大黄、牵牛、甘遂、巴豆之属，皆泻剂也。其催生下乳，磨积逐水，破经泄气，凡下行者，皆下法也。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WXE340i59rh', 4, '{"title":"第400100905条・卷之一_续序例上_论十剂本义","description":"<p>补剂　　</p>\n<p>         之才曰：补可去弱，人参、羊肉之属是也。杲曰：人参甘温，能补气虚；羊肉甘热，能补血虚。羊肉补形，人参补气。凡气味与二药同者皆是也。从正曰：五脏各有补泻，五味各补其脏，有表虚、里虚、上虚、下虚、阴虚、阳虚、气虚、血虚。《经》曰：精不足者补之以味，形不足者温之以气。五谷、五菜、五果、五肉，皆补养之物也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100905,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '补剂 之才曰：补可去弱，人参、羊肉之属是也。杲曰：人参甘温，能补气虚；羊肉甘热，能补血虚。羊肉补形，人参补气。凡气味与二药同者皆是也。从正曰：五脏各有补泻，五味各补其脏，有表虚、里虚、上虚、下虚、阴虚、阳虚、气虚、血虚。《经》曰：精不足者补之以味，形不足者温之以气。五谷、五菜、五果、五肉，皆补养之物也。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h0eHKTrlSqd', 4, '{"title":"第400100904条・卷之一_续序例上_论十剂本义","description":"<p>通剂　　</p>\n<p>         之才曰：通可去滞，通草、防己之属是也。完素曰：留而不行，必通以行之。如水病为痰澼之类，以木通、防己之属攻其内，则留者行也。滑石、茯苓、芫花、甘遂、大戟、牵牛之类是也。从正曰：通者，流通也。前后不得溲便，宜木通、海金沙、琥珀、大黄之属通之。痹病郁滞，经隧不利，亦宜通之。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100904,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '通剂 之才曰：通可去滞，通草、防己之属是也。完素曰：留而不行，必通以行之。如水病为痰澼之类，以木通、防己之属攻其内，则留者行也。滑石、茯苓、芫花、甘遂、大戟、牵牛之类是也。从正曰：通者，流通也。前后不得溲便，宜木通、海金沙、琥珀、大黄之属通之。痹病郁滞，经隧不利，亦宜通之。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('APRWx1ssD2n', 4, '{"title":"第400100903条・卷之一_续序例上_论十剂本义","description":"<p>宣剂　　</p>\n<p>        之才曰：宣可去壅，生姜、橘皮之属是也。杲曰：外感六淫之邪，欲传入里，三阴实而不受，逆于胸中，天分气分窒塞不通，而或哕或呕，所谓壅也。三阴者，脾也。故必破气，药如姜、橘、藿香、半夏之类，泻其壅塞。从正曰：俚人以宣为泻，又以宣为通，不知十剂之中，已有泻矣。仲景曰：春病在头，大法宜吐，是宣剂即涌剂也。经曰：高者因而越之，木郁则达之。宣者，升而上也，以君召臣曰宣是矣。凡风痫、中风、胸中诸实，痰饮寒结，胸中热郁，上而不下，久则喘嗽满胀，水肿之病生焉，非宣剂莫能愈也。吐中有汗，如引涎、追泪、嚏鼻，凡上行者，皆吐法也。完素曰：郁而不散为壅，必宣以散之，如痞满不通之类是矣。攻其里，则宣者上也，泄者下也。涌剂则瓜蒂、栀子之属是矣。发汗解表亦同。好古曰：《经》有五郁，木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之。皆宣也。教曰：宣，扬制曰宣朗，君召臣曰宣唤，臣奉君命，宣布上意，皆宣之意也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100903,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '宣剂 之才曰：宣可去壅，生姜、橘皮之属是也。杲曰：外感六淫之邪，欲传入里，三阴实而不受，逆于胸中，天分气分窒塞不通，而或哕或呕，所谓壅也。三阴者，脾也。故必破气，药如姜、橘、藿香、半夏之类，泻其壅塞。从正曰：俚人以宣为泻，又以宣为通，不知十剂之中，已有泻矣。仲景曰：春病在头，大法宜吐，是宣剂即涌剂也。经曰：高者因而越之，木郁则达之。宣者，升而上也，以君召臣曰宣是矣。凡风痫、中风、胸中诸实，痰饮寒结，胸中热郁，上而不下，久则喘嗽满胀，水肿之病生焉，非宣剂莫能愈也。吐中有汗，如引涎、追泪、嚏鼻，凡上行者，皆吐法也。完素曰：郁而不散为壅，必宣以散之，如痞满不通之类是矣。攻其里，则宣者上也，泄者下也。涌剂则瓜蒂、栀子之属是矣。发汗解表亦同。好古曰：《经》有五郁，木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之。皆宣也。教曰：宣，扬制曰宣朗，君召臣曰宣唤，臣奉君命，宣布上意，皆宣之意也。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mW18M5ugonH', 4, '{"title":"第400100902条・卷之一_续序例上_论十剂本义","description":"<p>附录：十剂　　</p>\n<p>           刘完素曰：制方之体，欲成七方、十剂之用者，必本于气味也。寒、热、温、凉，四气生于天；酸、苦、辛、咸、甘、淡，六味成于地。是以有形为味，无形为气。气为阳，味为阴。阳气出上窍，阴味出下窍。气化则精生，味化则形长。故地产养形，形不足者，温之以气；天产养精，精不足者，补之以味。辛甘发散为阳，酸苦涌泄为阴；咸味涌泄为阴，淡味渗泄为阳。辛散、酸收、甘缓、苦坚、咸软，各随五脏之病，而制药性之品味。故方有七，剂有十。方不七，不足以尽方之变；剂不十，不足以尽剂之用。方不对证，非方也；剂不蠲疾，非剂也。此乃太古先师，设绳墨而取曲直；叔世方士，乃出规矩以为方圆。夫物各有性，制而用之，变而通之，施于品剂，其功用岂有穷哉！如是有因其性而为用者，有因其用而为使者，有因其所胜而为制者，有气相同则相求者，有气相克则相制者，有气有馀而补不足者，有气相感则以意使者，有质同而性异者，有名异而实同者。故蛇之性上窜而引药，蝉之性外脱而退翳，虻饮血而用以治血，鼠善穿而用以治漏，所谓因其性而为用者如此。弩牙速产，以机发而不括也；杵糠下咽，以杵筑下也，所谓因其用而为使者如此。浮萍不沉水，可以胜湿；独活不摇风，可以治风，所谓因其所胜而为制者如此。麻，木谷而治风；豆，水谷而治水，所谓气相同则相求者如此。牛，土畜，乳可以止渴疾；豕，水畜，心可以镇恍忽，所谓因其气相克则相制也如此。熊肉振羸，兔肝明视，所谓因其气有余补不足也如此。鲤之治水，鹜之利水，所谓因其气相感则以意使者如此。蜜成于蜂，蜜温而蜂寒；油生于麻，麻温而油寒，兹同质而异性者也。靡芜生于芎，蓬蘽并于覆盆，兹名异而实同者也。如斯之类，不可胜举。故天地赋形，不离阴阳，形色自然，皆有法象。毛羽之类，生于阳而属于阴；鳞甲之类，生于阴而属于阳。空青法木，色青而主肝；丹砂法火，色赤而主心；云母法金，色白而主肺；磁石法水，色黑而主肾；黄石脂法土，色黄而主脾。故触类而长之，莫不有自然之理也。欲为医者，上知天文，下知地理，中知人事，三者俱明，然后可以语人之疾病。不然，则如无目夜游，无足登陟，动致颠殒，而欲愈疾者，未之有也。　　</p>\n<p>       徐之才曰：药有宣、通、补、泻、轻、重、滑、涩、燥、湿十种，是药之大体，而《本经》不言，后人未述。凡用药者，审而详之，则靡所遗失矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400100902,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '2024-12-21T01:44:33.000Z', '附录：十剂 刘完素曰：制方之体，欲成七方、十剂之用者，必本于气味也。寒、热、温、凉，四气生于天；酸、苦、辛、咸、甘、淡，六味成于地。是以有形为味，无形为气。气为阳，味为阴。阳气出上窍，阴味出下窍。气化则精生，味化则形长。故地产养形，形不足者，温之以气；天产养精，精不足者，补之以味。辛甘发散为阳，酸苦涌泄为阴；咸味涌泄为阴，淡味渗泄为阳。辛散、酸收、甘缓、苦坚、咸软，各随五脏之病，而制药性之品味。故方有七，剂有十。方不七，不足以尽方之变；剂不十，不足以尽剂之用。方不对证，非方也；剂不蠲疾，非剂也。此乃太古先师，设绳墨而取曲直；叔世方士，乃出规矩以为方圆。夫物各有性，制而用之，变而通之，施于品剂，其功用岂有穷哉！如是有因其性而为用者，有因其用而为使者，有因其所胜而为制者，有气相同则相求者，有气相克则相制者，有气有馀而补不足者，有气相感则以意使者，有质同而性异者，有名异而实同者。故蛇之性上窜而引药，蝉之性外脱而退翳，虻饮血而用以治血，鼠善穿而用以治漏，所谓因其性而为用者如此。弩牙速产，以机发而不括也；杵糠下咽，以杵筑下也，所谓因其用而为使者如此。浮萍不沉水，可以胜湿；独活不摇风，可以治风，所谓因其所胜而为制者如此。麻，木谷而治风；豆，水谷而治水，所谓气相同则相求者如此。牛，土畜，乳可以止渴疾；豕，水畜，心可以镇恍忽，所谓因其气相克则相制也如此。熊肉振羸，兔肝明视，所谓因其气有余补不足也如此。鲤之治水，鹜之利水，所谓因其气相感则以意使者如此。蜜成于蜂，蜜温而蜂寒；油生于麻，麻温而油寒，兹同质而异性者也。靡芜生于芎，蓬蘽并于覆盆，兹名异而实同者也。如斯之类，不可胜举。故天地赋形，不离阴阳，形色自然，皆有法象。毛羽之类，生于阳而属于阴；鳞甲之类，生于阴而属于阳。空青法木，色青而主肝；丹砂法火，色赤而主心；云母法金，色白而主肺；磁石法水，色黑而主肾；黄石脂法土，色黄而主脾。故触类而长之，莫不有自然之理也。欲为医者，上知天文，下知地理，中知人事，三者俱明，然后可以语人之疾病。不然，则如无目夜游，无足登陟，动致颠殒，而欲愈疾者，未之有也。 徐之才曰：药有宣、通、补、泻、轻、重、滑、涩、燥、湿十种，是药之大体，而《本经》不言，后人未述。凡用药者，审而详之，则靡所遗失矣。', '2024-12-21T01:44:33.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'A4FcCLrJj0V');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('13zaHuCd4I8', 4, '{"title":"第400101001条・卷之一_续序例上_十剂补遗","description":"<p>       十剂之后，陶隐居续入寒热二剂。岂知寒有时而不可以治热，热有时而不可以治寒，何者？阴虚内热，当用甘寒滋肾家之阴，是益水以制火也。设用芩、连、栀子苦寒之剂以攻热，则徒败胃气。苦寒损胃而伤血，血愈不足而热愈炽。胃气伤则后天之元气愈无所养，而病转增剧也。阳虚中外俱寒，当以人参、黄耆以益表里之阳气，而少佐桂、附以回阳，则其寒自解，是益火以祛寒也。设专用辛热，如吴茱萸、干姜、麻黄、葫芦巴、荜茇、胡椒之属以散寒，则辛能走散，真气愈虚，其寒愈甚。王安道所谓辛热愈投而沉寒愈滋也。二者非徒无益，而又害之，顾不悖欤！况寒热二剂，摄在补泻，义不重出。今当增入升降二剂。升降者，治法之大机也。《经》曰：高者抑之，即降之义也。下者举之，即升之义也。是以病升者用降剂，病降者用升剂。火空则发，降气则火自下矣，火下是阳交于阴也，此法所宜降者也。劳伤则阳气下陷，入于阴分，东垣所谓阴实阳虚。阳虚则内外皆寒，间有表热类外感者，但不头疼口渴、及热有时而间为异耳，法当升阳益气，用参、耆、炙甘草益元气以除虚寒虚热，佐以升麻、柴胡引阳气上行，则表里之寒热自解，即甘温除大热之谓，此法所宜升者也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:45:28.000Z', '2024-12-21T01:45:28.000Z', '2024-12-21T01:45:28.000Z', '十剂之后，陶隐居续入寒热二剂。岂知寒有时而不可以治热，热有时而不可以治寒，何者？阴虚内热，当用甘寒滋肾家之阴，是益水以制火也。设用芩、连、栀子苦寒之剂以攻热，则徒败胃气。苦寒损胃而伤血，血愈不足而热愈炽。胃气伤则后天之元气愈无所养，而病转增剧也。阳虚中外俱寒，当以人参、黄耆以益表里之阳气，而少佐桂、附以回阳，则其寒自解，是益火以祛寒也。设专用辛热，如吴茱萸、干姜、麻黄、葫芦巴、荜茇、胡椒之属以散寒，则辛能走散，真气愈虚，其寒愈甚。王安道所谓辛热愈投而沉寒愈滋也。二者非徒无益，而又害之，顾不悖欤！况寒热二剂，摄在补泻，义不重出。今当增入升降二剂。升降者，治法之大机也。《经》曰：高者抑之，即降之义也。下者举之，即升之义也。是以病升者用降剂，病降者用升剂。火空则发，降气则火自下矣，火下是阳交于阴也，此法所宜降者也。劳伤则阳气下陷，入于阴分，东垣所谓阴实阳虚。阳虚则内外皆寒，间有表热类外感者，但不头疼口渴、及热有时而间为异耳，法当升阳益气，用参、耆、炙甘草益元气以除虚寒虚热，佐以升麻、柴胡引阳气上行，则表里之寒热自解，即甘温除大热之谓，此法所宜升者也。', '2024-12-21T01:45:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '5Sv2jfePztQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('odU5hiuXr7u', 4, '{"title":"第400101101条・卷之一_续序例上_五脏苦欲补泻论","description":"<p>       五脏苦欲补泻，乃用药第一义。好古为东垣高足，东垣得之洁古，洁古实宗仲景。仲景远师伊尹，伊尹原本炎黄。圣哲授受，百世一源，靡或少异。不明乎此，不足以言医矣。何则？五脏之内，各有其神。神各有性，性复各殊。故《素问》命十二官之名，厥有旨焉。盖形而上者，神也，有知而无质；形而下者，块然者也，五脏之体也，有质而无知。各各分断者也。肝藏魂，肺藏魄，心藏神，脾藏意与智，肾藏精与志，皆指有知之性而言，即神也。神也者，阴阳不测之谓也。是形而上者，脏之性也。惟其无形，故能主乎有形。故知苦欲者，犹言好恶也。违其性故苦，遂其性故欲。欲者，是本脏之神之所好也，即补也。苦者，是本脏之神之所恶也，即泻也。补泻系乎苦欲，苦欲因乎脏性。不属五行，未落阴阳，其神用之谓与！自“虚则补其母”已下，乃言脏体之虚实，始有补母泻子之法，斯则五行之性也。明乎此，斯可以言药道矣。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:47:15.000Z', '2024-12-21T01:47:15.000Z', '2024-12-21T01:47:15.000Z', '五脏苦欲补泻，乃用药第一义。好古为东垣高足，东垣得之洁古，洁古实宗仲景。仲景远师伊尹，伊尹原本炎黄。圣哲授受，百世一源，靡或少异。不明乎此，不足以言医矣。何则？五脏之内，各有其神。神各有性，性复各殊。故《素问》命十二官之名，厥有旨焉。盖形而上者，神也，有知而无质；形而下者，块然者也，五脏之体也，有质而无知。各各分断者也。肝藏魂，肺藏魄，心藏神，脾藏意与智，肾藏精与志，皆指有知之性而言，即神也。神也者，阴阳不测之谓也。是形而上者，脏之性也。惟其无形，故能主乎有形。故知苦欲者，犹言好恶也。违其性故苦，遂其性故欲。欲者，是本脏之神之所好也，即补也。苦者，是本脏之神之所恶也，即泻也。补泻系乎苦欲，苦欲因乎脏性。不属五行，未落阴阳，其神用之谓与！自“虚则补其母”已下，乃言脏体之虚实，始有补母泻子之法，斯则五行之性也。明乎此，斯可以言药道矣。', '2024-12-21T01:47:15.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'cz5fyMpaEiV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FsYruEggTXb', 4, '{"title":"第400101210条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>        肾为作强之官，藏精与志，主五液，属真阴，水脏也。其性本润，故恶涸燥，宜急食辛以润之，知母之属是已。欲坚，急食苦以坚之。盖肾非坚，则无以称作强之职。四气以遇湿热即软，遇寒冷即坚。五味以得咸即软，得苦即坚，故宜急食苦以坚之。黄檗味苦气寒，可以坚肾，故宜急食，以遂其欲坚之性也。以苦补之，是坚即补也，地黄、黄檗之属是已。咸能软坚，软即泻也，泽泻之属是已。虚者，精气夺也。藏精之脏，苦固能坚，然非益精，无以为补，故宜熟地黄、黄檗之属以补之是已。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101210,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肾为作强之官，藏精与志，主五液，属真阴，水脏也。其性本润，故恶涸燥，宜急食辛以润之，知母之属是已。欲坚，急食苦以坚之。盖肾非坚，则无以称作强之职。四气以遇湿热即软，遇寒冷即坚。五味以得咸即软，得苦即坚，故宜急食苦以坚之。黄檗味苦气寒，可以坚肾，故宜急食，以遂其欲坚之性也。以苦补之，是坚即补也，地黄、黄檗之属是已。咸能软坚，软即泻也，泽泻之属是已。虚者，精气夺也。藏精之脏，苦固能坚，然非益精，无以为补，故宜熟地黄、黄檗之属以补之是已。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gydfodNx70L', 4, '{"title":"第400101209条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>      肾苦燥，急食辛以润之，（知母。）欲坚，急食苦以坚之，（黄檗。）以苦补之，（地黄。）以咸泻之，（泽泻。）虚则熟地黄、黄檗补之。肾本无实，不可泻，钱氏止有补肾地黄丸，无泻肾之药。肺乃肾之母，以五味子补肺。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101209,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肾苦燥，急食辛以润之，（知母。）欲坚，急食苦以坚之，（黄檗。）以苦补之，（地黄。）以咸泻之，（泽泻。）虚则熟地黄、黄檗补之。肾本无实，不可泻，钱氏止有补肾地黄丸，无泻肾之药。肺乃肾之母，以五味子补肺。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MMCfoV27jR4', 4, '{"title":"第400101208条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>       肺为华盖之脏，相傅之官，藏魄而主气者也。气常则顺，气变则逆，逆则违其性矣，故宜急食苦以泄之，黄芩之属是已。肺主上焦，其政敛肃，故其性喜收，宜急食酸以收之，白芍药之属是已。贼肺者，热也，肺受热邪，急食辛以泻之，桑白皮之属是已，不敛，则气无所管束，是肺失其职也，故宜补之以酸，使遂其收敛之性，以清肃乎上焦，是即补也。五味子之属是已。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101208,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肺为华盖之脏，相傅之官，藏魄而主气者也。气常则顺，气变则逆，逆则违其性矣，故宜急食苦以泄之，黄芩之属是已。肺主上焦，其政敛肃，故其性喜收，宜急食酸以收之，白芍药之属是已。贼肺者，热也，肺受热邪，急食辛以泻之，桑白皮之属是已，不敛，则气无所管束，是肺失其职也，故宜补之以酸，使遂其收敛之性，以清肃乎上焦，是即补也。五味子之属是已。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mvwb4BhZCMu', 4, '{"title":"第400101207条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>      肺苦气上逆，急食苦以泄之，（诃子皮，一作黄芩。）欲收，急食酸以收之，（白芍药。）以辛泻之，（桑白皮。）以酸补之，（五味子。）虚则五味子补之，如无他证，钱氏阿胶散补之。脾乃肺之母，以甘草补脾。实则桑白皮泻之，如无他证，以泻白散泻之。肾乃肺之子。以泽泻泻肾。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101207,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肺苦气上逆，急食苦以泄之，（诃子皮，一作黄芩。）欲收，急食酸以收之，（白芍药。）以辛泻之，（桑白皮。）以酸补之，（五味子。）虚则五味子补之，如无他证，钱氏阿胶散补之。脾乃肺之母，以甘草补脾。实则桑白皮泻之，如无他证，以泻白散泻之。肾乃肺之子。以泽泻泻肾。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OTHN4z3YfiH', 4, '{"title":"第400101206条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>         脾为仓廪之官，主运动磨物之脏。燥，其性也，宜健而不宜滞。湿，斯滞矣。违其性，故苦而恶之。急食苦以燥之，使复其性之所喜，脾斯健矣。白术之苦温是已。过燥则复欲缓之以甘，甘草之属是已。稼穑之化，故甘先入脾。性欲健运，气旺则行。补之以甘，人参是已。长夏之令，湿热主之。脾气斯困，故当急食苦以泻之，黄连之苦寒是已。虚则宜补，炙甘草之甘以益血，大枣之甘温以益气，乃所以补其不足也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101206,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '脾为仓廪之官，主运动磨物之脏。燥，其性也，宜健而不宜滞。湿，斯滞矣。违其性，故苦而恶之。急食苦以燥之，使复其性之所喜，脾斯健矣。白术之苦温是已。过燥则复欲缓之以甘，甘草之属是已。稼穑之化，故甘先入脾。性欲健运，气旺则行。补之以甘，人参是已。长夏之令，湿热主之。脾气斯困，故当急食苦以泻之，黄连之苦寒是已。虚则宜补，炙甘草之甘以益血，大枣之甘温以益气，乃所以补其不足也。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QqSiJKtfDM9', 4, '{"title":"第400101205条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>       脾苦湿，急食苦以燥之，（白术。）欲缓，急食甘以缓之，（甘草。）以甘补之，（人参。）以苦泻之，（黄连。）虚以甘草、大枣之类补之，如无他证，钱氏益黄散主之。心乃脾之母，以炒盐补心。实则以枳实泻之，如无他证，以泻黄散泻之。肺乃脾之子，以桑白皮泻肺。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101205,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '脾苦湿，急食苦以燥之，（白术。）欲缓，急食甘以缓之，（甘草。）以甘补之，（人参。）以苦泻之，（黄连。）虚以甘草、大枣之类补之，如无他证，钱氏益黄散主之。心乃脾之母，以炒盐补心。实则以枳实泻之，如无他证，以泻黄散泻之。肺乃脾之子，以桑白皮泻肺。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6ED2npnLNhH', 4, '{"title":"第400101204条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>          心为形君，神明之性，恶散缓而喜收敛。散缓则违其性，敛则宁静清明，故宜酸以收其缓也。软者，和调之义也。心君本自和调，邪热乘之则躁急，故复须芒硝之咸寒，除其邪热，以软其躁急坚劲之气，使复其平也。以咸补之，泽泻导心气以入肾也。烦劳则虚而生热，故须人参、黄芪、甘草之甘温，以益元气而虚热自退，故谓之泻也。心以下交于肾为补，炒盐之咸以润下，即得心与肾交也。火空则发，盐为水味，得之俾心气下降，是既济之道也，有补之义焉，故软即补也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101204,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '心为形君，神明之性，恶散缓而喜收敛。散缓则违其性，敛则宁静清明，故宜酸以收其缓也。软者，和调之义也。心君本自和调，邪热乘之则躁急，故复须芒硝之咸寒，除其邪热，以软其躁急坚劲之气，使复其平也。以咸补之，泽泻导心气以入肾也。烦劳则虚而生热，故须人参、黄芪、甘草之甘温，以益元气而虚热自退，故谓之泻也。心以下交于肾为补，炒盐之咸以润下，即得心与肾交也。火空则发，盐为水味，得之俾心气下降，是既济之道也，有补之义焉，故软即补也。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YS3Rf2jzEHe', 4, '{"title":"第400101203条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>        心苦缓，急食酸以收之，（五味子。）欲软，急食咸以软之，（芒硝。）以咸补之，（泽泻。）以甘泻之，（人参、黄耆、甘草。）虚以炒盐补之，虚则补其母。木能生火，肝乃心之母。肝，木也，以生姜补肝。如无他证，钱氏安神丸主之。实则甘草泻之。如无他证，钱氏方中重则泻心汤，轻则导赤散。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101203,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '心苦缓，急食酸以收之，（五味子。）欲软，急食咸以软之，（芒硝。）以咸补之，（泽泻。）以甘泻之，（人参、黄耆、甘草。）虚以炒盐补之，虚则补其母。木能生火，肝乃心之母。肝，木也，以生姜补肝。如无他证，钱氏安神丸主之。实则甘草泻之。如无他证，钱氏方中重则泻心汤，轻则导赤散。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q0t4KeI5cdA', 4, '{"title":"第400101202条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>         肝为将军之官，言不受制者也，急则有摧折之意焉，故苦而恶之。缓之，是使遂其性也。甘可以缓，甘草之属是已。扶苏条达，木之象也；升发开展，魂之用也。故其性欲散，辛以散之，解其束缚也，是散即补也。辛可以散，川芎之属是已。若其太过，则屈制之，毋使逾分。酸可以收，芍药之属是已。急也，敛也，肝性之所苦也。违其性而苦之，肝斯虚矣。补之以辛，是明以散为补也，细辛、生姜、陈皮之属是已。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101202,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肝为将军之官，言不受制者也，急则有摧折之意焉，故苦而恶之。缓之，是使遂其性也。甘可以缓，甘草之属是已。扶苏条达，木之象也；升发开展，魂之用也。故其性欲散，辛以散之，解其束缚也，是散即补也。辛可以散，川芎之属是已。若其太过，则屈制之，毋使逾分。酸可以收，芍药之属是已。急也，敛也，肝性之所苦也。违其性而苦之，肝斯虚矣。补之以辛，是明以散为补也，细辛、生姜、陈皮之属是已。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PKvJLQc79wb', 4, '{"title":"第400101201条・卷之一_续序例上_附录：五脏苦欲补泻（并续解五条）","description":"<p>        肝苦急，急食甘以缓之，（甘草。）欲散，急食辛以散之，（川芎。）以辛补之，（细辛。）以酸泻之，（芍药。）虚以生姜、陈皮之类补之。《经》曰：虚则补其母，水能生木，肾乃肝之母。肾，水也。苦以补肾，熟地黄、黄檗是矣。如无他证，钱氏地黄丸主之。实则白芍药泻之，如无他证，钱氏泻青丸主之。实则泻其子，心乃肝之子，以甘草泻心。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '2024-12-21T01:52:04.000Z', '肝苦急，急食甘以缓之，（甘草。）欲散，急食辛以散之，（川芎。）以辛补之，（细辛。）以酸泻之，（芍药。）虚以生姜、陈皮之类补之。《经》曰：虚则补其母，水能生木，肾乃肝之母。肾，水也。苦以补肾，熟地黄、黄檗是矣。如无他证，钱氏地黄丸主之。实则白芍药泻之，如无他证，钱氏泻青丸主之。实则泻其子，心乃肝之子，以甘草泻心。', '2024-12-21T01:52:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Oh0ftU5iL63');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UnAVmO4zbbz', 4, '{"title":"第400101309条・卷之一_续序例上_治法提纲","description":"<p>9、病属于虚，宜治以缓。虚者精气夺也。若属沉痼，亦必从缓。治虚无速法，亦无巧法。盖病已沉痼，凡欲施治，宜有次第，故亦无速法。病属于实，宜治以急。实者，邪气胜也。邪不速逐，则为害滋蔓，故治实无迟法，亦无巧法。此病缓急一定之法也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '9、病属于虚，宜治以缓。虚者精气夺也。若属沉痼，亦必从缓。治虚无速法，亦无巧法。盖病已沉痼，凡欲施治，宜有次第，故亦无速法。病属于实，宜治以急。实者，邪气胜也。邪不速逐，则为害滋蔓，故治实无迟法，亦无巧法。此病缓急一定之法也。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Aff03b7Dwgx', 4, '{"title":"第400101308条・卷之一_续序例上_治法提纲","description":"<p>8、受邪为本，现证为标；五虚为本，五邪为标。譬夫腹胀由于湿者，其来必速，当利水除湿，则胀自止，是标急于本也，当先治其标。若因脾虚，渐成胀满，夜剧昼静，病属于阴，当补脾阴；夜静昼剧，病属于阳，当益脾气。是病从本生，本急于标也，当先治其本。举一为例，馀可类推矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '8、受邪为本，现证为标；五虚为本，五邪为标。譬夫腹胀由于湿者，其来必速，当利水除湿，则胀自止，是标急于本也，当先治其标。若因脾虚，渐成胀满，夜剧昼静，病属于阴，当补脾阴；夜静昼剧，病属于阳，当益脾气。是病从本生，本急于标也，当先治其本。举一为例，馀可类推矣。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R2vsAkxxaGq', 4, '{"title":"第400101307条・卷之一_续序例上_治法提纲","description":"<p>7、病在于表，毋攻其里；病在于里，毋虚其表。邪之所在，攻必从之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '7、病在于表，毋攻其里；病在于里，毋虚其表。邪之所在，攻必从之。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HaNMBkXIOVE', 4, '{"title":"第400101306条・卷之一_续序例上_治法提纲","description":"<p>6、病从气分，则治其气：虚者温之，实者调之。病从血分，则治其血：虚则补肝、补脾、补心，实则为热、为瘀，热者清之，瘀者行之。因气病而及血者，先治其气；因血病而及气者，先治其血。因证互异，宜精别之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '6、病从气分，则治其气：虚者温之，实者调之。病从血分，则治其血：虚则补肝、补脾、补心，实则为热、为瘀，热者清之，瘀者行之。因气病而及血者，先治其气；因血病而及气者，先治其血。因证互异，宜精别之。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dmJcN2cg3eP', 4, '{"title":"第400101305条・卷之一_续序例上_治法提纲","description":"<p>5、病在于经，则治其经；病流于络，则及其络。经直络横，相维辅也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '5、病在于经，则治其经；病流于络，则及其络。经直络横，相维辅也。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HomenZIQJoV', 4, '{"title":"第400101304条・卷之一_续序例上_治法提纲","description":"<p>4、《经》曰：五脏者，藏精气而不泻者也，故曰满而不能实。是有补而无泻者，其常也。脏偶受邪，则泻其邪，邪尽即止。是泻其邪，非泻脏也。脏不受邪，毋轻犯也。世谓肝无补法，知其谬也。六腑者，传导化物糟粕者也，故曰实而不能满。邪客之而为病，乃可攻也。中病乃已，毋尽剂也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '4、《经》曰：五脏者，藏精气而不泻者也，故曰满而不能实。是有补而无泻者，其常也。脏偶受邪，则泻其邪，邪尽即止。是泻其邪，非泻脏也。脏不受邪，毋轻犯也。世谓肝无补法，知其谬也。六腑者，传导化物糟粕者也，故曰实而不能满。邪客之而为病，乃可攻也。中病乃已，毋尽剂也。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1lowfQp07F2', 4, '{"title":"第400101303条・卷之一_续序例上_治法提纲","description":"<p>3、病之热也，当察其源：火苟实也，苦寒咸寒以折之；若其虚也，甘寒酸寒以摄之。病之寒也，亦察其源：寒从外也，辛热辛温以散之；动于内也，甘温以益之，辛热辛温以佐之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '3、病之热也，当察其源：火苟实也，苦寒咸寒以折之；若其虚也，甘寒酸寒以摄之。病之寒也，亦察其源：寒从外也，辛热辛温以散之；动于内也，甘温以益之，辛热辛温以佐之。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qWXGjl6jLfa', 4, '{"title":"第400101302条・卷之一_续序例上_治法提纲","description":"<p>2、病在于阴，毋犯其阳；病在于阳，毋犯其阴。犯之者，是谓诛伐无过。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2、病在于阴，毋犯其阳；病在于阳，毋犯其阴。犯之者，是谓诛伐无过。', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('edkB5X7NKV4', 4, '{"title":"第400101301条・卷之一_续序例上_治法提纲","description":"<p>1、（阴阳、寒热、脏腑、经络、气血、表里、标本先后、虚实缓急）</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '2024-12-21T02:37:28.000Z', '1、（阴阳、寒热、脏腑、经络、气血、表里、标本先后、虚实缓急）', '2024-12-21T02:37:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'HFHOzS2lI5c');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4FcIsuX9A5j', 4, '{"title":"第400101402条・卷之一_续序例上_药性差别论","description":"<p>2、第准经文，同一苦寒也，黄芩则燥，天冬则润，芦会能消，黄檗能补，黄连止泻，大黄下通，柴胡苦寒而升，龙胆苦寒而降。同一咸也，泽泻则泻，苁容则补，海藻、昆布则消而软坚，马茎、鹿茸则补而生齿。同一酸也，硫黄味酸而热，空青味酸而寒。甘合辛而发散为阳，甘合酸而收敛为阴。人参、黄耆，阳也，甘温以除大热；地黄、五味，阴也，甘酸以敛阴精。聊采数端，引以为例。如斯之类，难可枚举。良由气味互兼，性质各异，参合多少，制用全殊。所以穷五味之变，明药物之能，厥有旨哉！顾其用纷错，其道渊微，可以意知，难以言尽。非由妙悟，则物不从心。固将拯烝民于夭枉，宜寤寐乎兹篇。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101402,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:38:57.000Z', '2024-12-21T02:38:57.000Z', '2024-12-21T02:38:57.000Z', '2、第准经文，同一苦寒也，黄芩则燥，天冬则润，芦会能消，黄檗能补，黄连止泻，大黄下通，柴胡苦寒而升，龙胆苦寒而降。同一咸也，泽泻则泻，苁容则补，海藻、昆布则消而软坚，马茎、鹿茸则补而生齿。同一酸也，硫黄味酸而热，空青味酸而寒。甘合辛而发散为阳，甘合酸而收敛为阴。人参、黄耆，阳也，甘温以除大热；地黄、五味，阴也，甘酸以敛阴精。聊采数端，引以为例。如斯之类，难可枚举。良由气味互兼，性质各异，参合多少，制用全殊。所以穷五味之变，明药物之能，厥有旨哉！顾其用纷错，其道渊微，可以意知，难以言尽。非由妙悟，则物不从心。固将拯烝民于夭枉，宜寤寐乎兹篇。', '2024-12-21T02:38:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '6LBaBNLqD3L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r4CNA1ZdUz4', 4, '{"title":"第400101401条・卷之一_续序例上_药性差别论","description":"<p>1、药有五味，中涵四气，因气味而成性。合气与味及性而论，其为差别，本自多途。其间厚薄多少，单用互兼，各各不同，良难究竟。是故《经》曰：五味之变，不可胜穷。此方剂之本也。阴阳二象，实为之纲纪焉。咸味本水，苦味本火，酸味本木，甘味本土，辛味本金，此五味之常也。及其变也，有神明之用焉。今姑陈其略以明之：　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:38:57.000Z', '2024-12-21T02:38:57.000Z', '2024-12-21T02:38:57.000Z', '1、药有五味，中涵四气，因气味而成性。合气与味及性而论，其为差别，本自多途。其间厚薄多少，单用互兼，各各不同，良难究竟。是故《经》曰：五味之变，不可胜穷。此方剂之本也。阴阳二象，实为之纲纪焉。咸味本水，苦味本火，酸味本木，甘味本土，辛味本金，此五味之常也。及其变也，有神明之用焉。今姑陈其略以明之：', '2024-12-21T02:38:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '6LBaBNLqD3L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dARquwUcLhJ', 4, '{"title":"第400101504条・ 卷之一_续序例上_脏气法时并四气所伤药随所感论","description":"<p>4、以上皆四时六气所伤致病，并证重舍时，时重舍证，用药主治之大法，万世遵守之常经，圣哲复起，不可改已。所云六气者，即风寒暑湿燥火是也。过则为淫，故曰六淫。淫则为邪，以其为天之气，从外而入，故曰外邪。邪之所中，各有其地：在表治表，在里治里，表里之间，则从和解。病有是证，证有是药，各有司存，不相越也。此古人之定法，今人之轨则也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '4、以上皆四时六气所伤致病，并证重舍时，时重舍证，用药主治之大法，万世遵守之常经，圣哲复起，不可改已。所云六气者，即风寒暑湿燥火是也。过则为淫，故曰六淫。淫则为邪，以其为天之气，从外而入，故曰外邪。邪之所中，各有其地：在表治表，在里治里，表里之间，则从和解。病有是证，证有是药，各有司存，不相越也。此古人之定法，今人之轨则也。', '2024-12-21T02:41:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'vMftSu8mf12');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vPQdiw9etW', 4, '{"title":"第400101503条・ 卷之一_续序例上_脏气法时并四气所伤药随所感论","description":"<p>3、至于四气所伤。因而致病，则各从所由。是故《经》曰：春伤于风，夏生飧泄。药宜升之、燥之，升麻、柴胡、羌活、防风之属是已。夏伤于暑，秋必痎疟。药宜清暑益气，以除寒热，石膏、知母、干葛、麦门冬、橘皮、参、苓、术之属是已。邪若内陷，必便脓血，药宜祛暑消滞，专保胃气，黄连、滑石、芍药、升麻、莲实、人参、扁豆、甘草之属是已。秋伤于湿，冬生咳嗽。药宜燥湿清热，和表降气保肺，桑白皮、石膏、薄荷、杏仁、甘草、桔梗、苏子、枇杷叶之属是已。冬伤于寒，春必病温。邪初在表，药宜辛寒、苦温、甘寒、苦寒，以解表邪，兼除内热，羌活、石膏、葛根、前胡、知母、竹叶、柴胡、麦门冬、荆芥、甘草之属是已。至夏变为热病，六经传变，药亦同前。散之贵早，治若后时，邪结于里，上则陷胸，中下承气，中病乃已，慎毋尽剂。勿僭勿忒，能事必矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '3、至于四气所伤。因而致病，则各从所由。是故《经》曰：春伤于风，夏生飧泄。药宜升之、燥之，升麻、柴胡、羌活、防风之属是已。夏伤于暑，秋必痎疟。药宜清暑益气，以除寒热，石膏、知母、干葛、麦门冬、橘皮、参、苓、术之属是已。邪若内陷，必便脓血，药宜祛暑消滞，专保胃气，黄连、滑石、芍药、升麻、莲实、人参、扁豆、甘草之属是已。秋伤于湿，冬生咳嗽。药宜燥湿清热，和表降气保肺，桑白皮、石膏、薄荷、杏仁、甘草、桔梗、苏子、枇杷叶之属是已。冬伤于寒，春必病温。邪初在表，药宜辛寒、苦温、甘寒、苦寒，以解表邪，兼除内热，羌活、石膏、葛根、前胡、知母、竹叶、柴胡、麦门冬、荆芥、甘草之属是已。至夏变为热病，六经传变，药亦同前。散之贵早，治若后时，邪结于里，上则陷胸，中下承气，中病乃已，慎毋尽剂。勿僭勿忒，能事必矣。', '2024-12-21T02:41:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'vMftSu8mf12');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fFly0RPCdD5', 4, '{"title":"第400101502条・ 卷之一_续序例上_脏气法时并四气所伤药随所感论","description":"<p>2、然而一气之中，初、中、末异；一日之内，寒燠或殊。假令大热之候，人多感暑，忽发冰雹，亦复感寒。由先而感则为暑病，由后而感则为寒病。病暑者投以暑药，病寒者投以寒药。此药之因时制宜，以合乎权，乃变中之常也。此时令不齐之所宜审也。假令阴虚之人，虽当隆冬，阴精亏竭，水既不足，不能制火，则阳无所依，外泄为热，或反汗出，药宜益阴，地黄、五味、鳖甲、枸杞之属是已。设从时令，误用辛温，势必立毙。假令阳虚之人，虽当盛夏，阳气不足，不能外卫其表，表虚不任风寒，洒淅战栗，思得热食，及御重裘，是虽天令之热，亦不足以敌其真阳之虚。病属虚寒，药宜温补，参、耆、桂、附之属是已。设从时令，误用苦寒，亦必立毙。此药之舍时从证者也。假令素病血虚之人，不利苦寒，恐其损胃伤血。一旦中暑，暴注霍乱，须用黄连、滑石以泄之；本不利升，须用葛根以散之。此药之舍证从时者也。从违之际，权其轻重耳。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '2、然而一气之中，初、中、末异；一日之内，寒燠或殊。假令大热之候，人多感暑，忽发冰雹，亦复感寒。由先而感则为暑病，由后而感则为寒病。病暑者投以暑药，病寒者投以寒药。此药之因时制宜，以合乎权，乃变中之常也。此时令不齐之所宜审也。假令阴虚之人，虽当隆冬，阴精亏竭，水既不足，不能制火，则阳无所依，外泄为热，或反汗出，药宜益阴，地黄、五味、鳖甲、枸杞之属是已。设从时令，误用辛温，势必立毙。假令阳虚之人，虽当盛夏，阳气不足，不能外卫其表，表虚不任风寒，洒淅战栗，思得热食，及御重裘，是虽天令之热，亦不足以敌其真阳之虚。病属虚寒，药宜温补，参、耆、桂、附之属是已。设从时令，误用苦寒，亦必立毙。此药之舍时从证者也。假令素病血虚之人，不利苦寒，恐其损胃伤血。一旦中暑，暴注霍乱，须用黄连、滑石以泄之；本不利升，须用葛根以散之。此药之舍证从时者也。从违之际，权其轻重耳。', '2024-12-21T02:41:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'vMftSu8mf12');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F6xKIcORKOP', 4, '{"title":"第400101501条・ 卷之一_续序例上_脏气法时并四气所伤药随所感论","description":"<p>1、夫四时之气，行乎天地之间。人处气交之中，亦必因之而感者，其常也。春气生而升，夏气长而散，长夏之气化而软，秋气收而敛，冬气藏而沉。人身之气，自然相通。是故生者顺之，长者敷之，化者坚之，收者肃之，藏者固之。此药之顺乎天者也。春温夏热，元气外泄，阴精不足，药宜养阴；秋凉冬寒，阳气潜藏，勿轻开通，药宜养阳。此药之因时制用，补不足以和其气者也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '2024-12-21T02:41:16.000Z', '1、夫四时之气，行乎天地之间。人处气交之中，亦必因之而感者，其常也。春气生而升，夏气长而散，长夏之气化而软，秋气收而敛，冬气藏而沉。人身之气，自然相通。是故生者顺之，长者敷之，化者坚之，收者肃之，藏者固之。此药之顺乎天者也。春温夏热，元气外泄，阴精不足，药宜养阴；秋凉冬寒，阳气潜藏，勿轻开通，药宜养阳。此药之因时制用，补不足以和其气者也。', '2024-12-21T02:41:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'vMftSu8mf12');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2TI2ZTz2r4a', 4, '{"title":"第400101602条・卷之一_续序例上_论制方和剂治疗大法","description":"<p>2、升降者，病机之要最也。升为春气，为风化，为木象。故升有散之之义；降为秋气，为燥化，为金象，故降有敛之之义。饮食劳倦，则阳气下陷，宜升阳益气。泻利不止，宜升阳益胃。郁火内伏，宜升阳散火。滞下不休，宜升阳解毒，开胃除热。因湿洞泄，宜升阳除湿。肝木郁于地中，以致少腹作胀、作痛，宜升阳调气。此病宜升之类也。阴虚则水不足以制火，火空则发而炎上。其为证也，为咳嗽，为多痰，为吐血，为鼻衄，为齿衄，为头痛，为齿痛，为眼痛，为头眩，为晕，为眼花，为恶心，为呕吐，为口苦舌干，为不眠，为寒热，为骨蒸，是为上盛下虚之候。宜用苏子、枇杷叶、麦门冬、白芍药、五味子之属以降气，气降则火自降，而气自归元。而又益之以滋水添精之药，以救其本，则诸证自瘳。此病宜降之类也。设宜降而妄升，当升而反降，将使轻变为重，重必毙矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101602,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:44:51.000Z', '2024-12-21T02:44:51.000Z', '2024-12-21T02:44:51.000Z', '2、升降者，病机之要最也。升为春气，为风化，为木象。故升有散之之义；降为秋气，为燥化，为金象，故降有敛之之义。饮食劳倦，则阳气下陷，宜升阳益气。泻利不止，宜升阳益胃。郁火内伏，宜升阳散火。滞下不休，宜升阳解毒，开胃除热。因湿洞泄，宜升阳除湿。肝木郁于地中，以致少腹作胀、作痛，宜升阳调气。此病宜升之类也。阴虚则水不足以制火，火空则发而炎上。其为证也，为咳嗽，为多痰，为吐血，为鼻衄，为齿衄，为头痛，为齿痛，为眼痛，为头眩，为晕，为眼花，为恶心，为呕吐，为口苦舌干，为不眠，为寒热，为骨蒸，是为上盛下虚之候。宜用苏子、枇杷叶、麦门冬、白芍药、五味子之属以降气，气降则火自降，而气自归元。而又益之以滋水添精之药，以救其本，则诸证自瘳。此病宜降之类也。设宜降而妄升，当升而反降，将使轻变为重，重必毙矣。', '2024-12-21T02:44:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DvRbae0MoD5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jJEBj6DCDM7', 4, '{"title":"第400101601条・卷之一_续序例上_论制方和剂治疗大法","description":"<p>1、夫虚实者，诸病之根本也；补泻者，治疗之纲纪也。何谓虚？五脏六腑虚所生病也。何谓实？五脏六腑实所生病也。《经》曰：真气夺则虚，邪气胜则实。虚则补之，实则泻之。此万世之常经也。以补为泻，是补中有泻也；以泻为补，是泻中有补也。譬夫参、耆、炙甘草之退劳倦气虚发热；地黄、黄檗之滋水坚肾，以除阴虚潮热，是补中之泻也。桑根白皮之泻肺火，车前子之利小便除湿，是泻中之补也。举斯为例，馀可类推矣。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:44:51.000Z', '2024-12-21T02:44:51.000Z', '2024-12-21T02:44:51.000Z', '1、夫虚实者，诸病之根本也；补泻者，治疗之纲纪也。何谓虚？五脏六腑虚所生病也。何谓实？五脏六腑实所生病也。《经》曰：真气夺则虚，邪气胜则实。虚则补之，实则泻之。此万世之常经也。以补为泻，是补中有泻也；以泻为补，是泻中有补也。譬夫参、耆、炙甘草之退劳倦气虚发热；地黄、黄檗之滋水坚肾，以除阴虚潮热，是补中之泻也。桑根白皮之泻肺火，车前子之利小便除湿，是泻中之补也。举斯为例，馀可类推矣。', '2024-12-21T02:44:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DvRbae0MoD5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y3dPEdEVdnC', 4, '{"title":"第400101704条・卷之一_续序例上_论塞因塞用、通因通用、寒因热用、热因寒用、用热远热、用寒远寒","description":"<p>4、用热远热者，是病本于寒，法应热治，所投热剂，仅使中病，毋令过焉。过则反生热病矣。用寒远寒，义亦同此。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '4、用热远热者，是病本于寒，法应热治，所投热剂，仅使中病，毋令过焉。过则反生热病矣。用寒远寒，义亦同此。', '2024-12-21T02:46:52.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'n6QwgzoTFFC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RqVKi5gWje5', 4, '{"title":"第400101703条・卷之一_续序例上_论塞因塞用、通因通用、寒因热用、热因寒用、用热远热、用寒远寒","description":"<p>3、寒因热用，是药本寒也，而反佐之以热。热因寒用，是药本热也，而反佐之以寒，则无拒格之患。故曰：必先其所主，而伏其所因也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '3、寒因热用，是药本寒也，而反佐之以热。热因寒用，是药本热也，而反佐之以寒，则无拒格之患。故曰：必先其所主，而伏其所因也。', '2024-12-21T02:46:52.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'n6QwgzoTFFC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WBpvvrxvVEI', 4, '{"title":"第400101702条・卷之一_续序例上_论塞因塞用、通因通用、寒因热用、热因寒用、用热远热、用寒远寒","description":"<p>2、通因通用者，譬夫伤寒挟热下利，或中有燥粪，必用调胃承气汤，下之乃安。滞下不休，得六一散清热除积而愈，皆其义也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '2、通因通用者，譬夫伤寒挟热下利，或中有燥粪，必用调胃承气汤，下之乃安。滞下不休，得六一散清热除积而愈，皆其义也。', '2024-12-21T02:46:52.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'n6QwgzoTFFC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tUKVwdD9Z5y', 4, '{"title":"第400101701条・卷之一_续序例上_论塞因塞用、通因通用、寒因热用、热因寒用、用热远热、用寒远寒","description":"<p>1、《经》曰：塞因塞用者，譬夫脾虚中焦作胀，肾虚气不归元，致上焦逆满，用人参之甘以补元气，五味子之酸以收虚气，则脾得补而胀自消，肾得补而气自归元，上焦清泰，而逆满自平矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '2024-12-21T02:46:52.000Z', '1、《经》曰：塞因塞用者，譬夫脾虚中焦作胀，肾虚气不归元，致上焦逆满，用人参之甘以补元气，五味子之酸以收虚气，则脾得补而胀自消，肾得补而气自归元，上焦清泰，而逆满自平矣。', '2024-12-21T02:46:52.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'n6QwgzoTFFC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Z593NNEs7G', 4, '{"title":"第400101801条・卷之一_续序例上_论天地风气渐薄，人亦因之渐弱，用药消息亦必因之而变，不可执泥古法，轻用峻利","description":"<p>1、夫人在气交之中，其强其弱，卒莫逃乎天地之气明甚。是以上古之人，度百岁乃去，今则七十称古稀矣。身形长大，常过七尺，今则世鲜六尺之躯矣。其寿数精神，既已渐减，则血气脏腑，亦应因之渐薄，乃天地之风气使然，有非人力所能挽回者。又况时丁末造，众生识昏见陋，五欲炽然，难解难遏，斫丧戕贼，日惟不足，于是疾病丛生，虚多实少。临证施治，多事调养，专防克伐，此今日治法之急务也。设使病宜用热，亦当先之以温；病宜用寒，亦当先之以清。纵有积滞宜消，必须先养胃气：纵有邪气宜祛，必须随时逐散，不得过剂，以损伤气血。气血者，人之所赖以生者也。气血一亏，则诸邪辐辏，百病横生。世人之病，十有九虚。医师之药，百无一补。宁知用药之误，则实者虚，虚者死，是死于医药，而非死于疾病也。其慎其难，属诸司命。临证之顷，宜加战兢。勉之哉！毋执己见而轻人命也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:48:29.000Z', '2024-12-21T02:48:29.000Z', '2024-12-21T02:48:29.000Z', '1、夫人在气交之中，其强其弱，卒莫逃乎天地之气明甚。是以上古之人，度百岁乃去，今则七十称古稀矣。身形长大，常过七尺，今则世鲜六尺之躯矣。其寿数精神，既已渐减，则血气脏腑，亦应因之渐薄，乃天地之风气使然，有非人力所能挽回者。又况时丁末造，众生识昏见陋，五欲炽然，难解难遏，斫丧戕贼，日惟不足，于是疾病丛生，虚多实少。临证施治，多事调养，专防克伐，此今日治法之急务也。设使病宜用热，亦当先之以温；病宜用寒，亦当先之以清。纵有积滞宜消，必须先养胃气：纵有邪气宜祛，必须随时逐散，不得过剂，以损伤气血。气血者，人之所赖以生者也。气血一亏，则诸邪辐辏，百病横生。世人之病，十有九虚。医师之药，百无一补。宁知用药之误，则实者虚，虚者死，是死于医药，而非死于疾病也。其慎其难，属诸司命。临证之顷，宜加战兢。勉之哉！毋执己见而轻人命也。', '2024-12-21T02:48:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'gMWHoxz98T3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cxm09l2vl9p', 4, '{"title":"第400101901条・卷之一_续序例上_通评虚实论","description":"<p>1、《经》曰：邪气盛则实，精气夺则虚。又曰：邪之所凑，其气必虚。凡言虚者，精气夺也；凡言实者，邪气胜也。是故虚则受邪，邪客为实，法先攻邪，邪尽治本。邪犹未尽，勿轻补益。犯之者，是谓实实。精者，阴也；气者，阳也。设被削夺，是五脏六腑之阴精、阳气皆虚也。宜从其类以补之。阴精虚者，补阴精；阳气虚者，益阳气。一切克伐攻击之药，概勿施用。犯之者，是为虚虚。《经》曰：实实虚虚，损不足而益有余，如是者，医杀之耳！戒之哉！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400101901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:49:21.000Z', '2024-12-21T02:49:21.000Z', '2024-12-21T02:49:21.000Z', '1、《经》曰：邪气盛则实，精气夺则虚。又曰：邪之所凑，其气必虚。凡言虚者，精气夺也；凡言实者，邪气胜也。是故虚则受邪，邪客为实，法先攻邪，邪尽治本。邪犹未尽，勿轻补益。犯之者，是谓实实。精者，阴也；气者，阳也。设被削夺，是五脏六腑之阴精、阳气皆虚也。宜从其类以补之。阴精虚者，补阴精；阳气虚者，益阳气。一切克伐攻击之药，概勿施用。犯之者，是为虚虚。《经》曰：实实虚虚，损不足而益有余，如是者，医杀之耳！戒之哉！', '2024-12-21T02:49:21.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'bxotugUgfvB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HDAofLF0CyN', 4, '{"title":"第400102001条・卷之一_续序例上_论治阴阳诸虚病皆当以保护胃气为急","description":"<p>夫胃气者，即后天元气也，以谷气为本。是故《经》曰：脉有胃气曰生，无胃气曰死。又曰：安谷则昌，绝谷则亡。可见先天之气，纵犹未尽，而他脏不至尽伤。独胃气偶有伤败，以至于绝，则速死矣。谷气者，譬国家之饷道也。饷道一绝，则万众立散；胃气一败，则百药难施。若阴虚，若阳虚，或中风，或中暑，乃至泻利滞下，胎前产后，丁肿痈疽，痘疮痧疹惊疳，靡不以保护胃气、补养脾气为先务，本所当急也。故益阴宜远苦寒，益阳宜防泄气，祛风勿过燥散，消暑毋轻下通，泻利勿加消导。滞下之忌芒硝、巴豆、牵牛，胎前泄泻之忌当归，产后寒热之忌芩、连、栀子，丁肿痈疽未溃之忌当归，痘疹之不可妄下。其他内外诸病，应设药之中，凡与胃气相违者，概勿施用。投药之顷，宜加三思。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:50:29.000Z', '2024-12-21T02:50:29.000Z', '2024-12-21T02:50:29.000Z', '夫胃气者，即后天元气也，以谷气为本。是故《经》曰：脉有胃气曰生，无胃气曰死。又曰：安谷则昌，绝谷则亡。可见先天之气，纵犹未尽，而他脏不至尽伤。独胃气偶有伤败，以至于绝，则速死矣。谷气者，譬国家之饷道也。饷道一绝，则万众立散；胃气一败，则百药难施。若阴虚，若阳虚，或中风，或中暑，乃至泻利滞下，胎前产后，丁肿痈疽，痘疮痧疹惊疳，靡不以保护胃气、补养脾气为先务，本所当急也。故益阴宜远苦寒，益阳宜防泄气，祛风勿过燥散，消暑毋轻下通，泻利勿加消导。滞下之忌芒硝、巴豆、牵牛，胎前泄泻之忌当归，产后寒热之忌芩、连、栀子，丁肿痈疽未溃之忌当归，痘疹之不可妄下。其他内外诸病，应设药之中，凡与胃气相违者，概勿施用。投药之顷，宜加三思。', '2024-12-21T02:50:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T6Aix9bimrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ooKQFEhU24', 4, '{"title":"第400102102条・卷之一_续序例上_论诸病惟虚与火为难治","description":"<p>2、夫火者，阳也，气也，与水为对待者也。</p>\n<p></p>\n<p>      水为阴精，火为阳气，二物匹配，名曰阴阳和平，亦名少火生气，如是则诸病不作矣。</p>\n<p> </p>\n<p>      设不善摄养，以致阴亏水涸，则火偏胜。$m{阴不足，则阳必凑}之，是谓$m{阳盛阴虚}，亦曰壮火食气。是知火即气，气即火也。故仙经谓：药即火，火即药，一而二，二而一者也。</p>\n<p></p>\n<p>      东垣亦曰：火与元气不两立。亦指此也。譬诸$m{水性本流、本寒}，$m{过极则凝而不流}，为层冰矣。解则复常，非二物也。盖平则为水火既济，当斯时也，火即真阳之气矣。及其偏也，则即阳气而为火也，始与元气不两立，而成乖否之象矣。</p>\n<p></p>\n<p>     故戴人亦曰：莫治风，莫治燥，治得火时风燥了。言苟能解此，则已达阴阳水火之原，曲畅旁通，何施不可？正指火之变态多端，其为病也非一，了此则馀皆可办。然学者非心领神会，讵足喻于斯乎？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:51:41.000Z', '2024-12-21T02:51:41.000Z', '2024-12-21T02:51:41.000Z', '2、夫火者，阳也，气也，与水为对待者也。 水为阴精，火为阳气，二物匹配，名曰阴阳和平，亦名少火生气，如是则诸病不作矣。 设不善摄养，以致阴亏水涸，则火偏胜。$m{阴不足，则阳必凑}之，是谓$m{阳盛阴虚}，亦曰壮火食气。是知火即气，气即火也。故仙经谓：药即火，火即药，一而二，二而一者也。 东垣亦曰：火与元气不两立。亦指此也。譬诸$m{水性本流、本寒}，$m{过极则凝而不流}，为层冰矣。解则复常，非二物也。盖平则为水火既济，当斯时也，火即真阳之气矣。及其偏也，则即阳气而为火也，始与元气不两立，而成乖否之象矣。 故戴人亦曰：莫治风，莫治燥，治得火时风燥了。言苟能解此，则已达阴阳水火之原，曲畅旁通，何施不可？正指火之变态多端，其为病也非一，了此则馀皆可办。然学者非心领神会，讵足喻于斯乎？', '2024-12-21T02:51:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '0JMjE4vPboJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jmjyoQ4CcJf', 4, '{"title":"第400102101条・卷之一_续序例上_论诸病惟虚与火为难治","description":"<p>1、《经》曰：精气夺则虚。又曰：邪之所凑，其气必虚。虚者，空也，无也。</p>\n<p> </p>\n<p>        譬诸国内空虚，人民离散，则百祸易起，镇抚为难。非委任贤智，安靖休养以生息之，未可保其无事也。</p>\n<p></p>\n<p>         病之虚者，亦犹是已。医非明哲，孰能镇之以静？久而弗摇，卒成收合散亡，克复故物之功哉！</p>\n<p></p>\n<p>         是故《经》曰：不能治其虚，安问其余？盖言虚为百病之本，宜其首举以冠诸证也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:51:41.000Z', '2024-12-21T02:51:41.000Z', '2024-12-21T02:51:41.000Z', '1、《经》曰：精气夺则虚。又曰：邪之所凑，其气必虚。虚者，空也，无也。 譬诸国内空虚，人民离散，则百祸易起，镇抚为难。非委任贤智，安靖休养以生息之，未可保其无事也。 病之虚者，亦犹是已。医非明哲，孰能镇之以静？久而弗摇，卒成收合散亡，克复故物之功哉！ 是故《经》曰：不能治其虚，安问其余？盖言虚为百病之本，宜其首举以冠诸证也。', '2024-12-21T02:51:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '0JMjE4vPboJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('twhPJj6bT0b', 4, '{"title":"第400102201条・卷之一_续序例上_论阳常有余，阴常不足，药必因之以为损益，误则杀人","description":"<p>1、人身之有阴阳也，水一而已，火则二焉。是秉受之始。阳常有余，阴常不足，天地且然，况于人乎？故自少至老，所生疾病，靡不由于真阴不足者，其恒也。若夫真阳不足之病，千百而一二矣。阳者气也，火也，神也：阴者血也，水也，精也。阴阳和平，气血均调，是为平人气象之常候。苟失所养，或纵恣房室，或肆情喜怒，或轻犯阴阳，或嗜好辛热，以致肾水真阴不足，不能匹配阳火，遂使阳气有余。气有余，即是火，故火愈盛而水愈涸，于是发为吐血、咳嗽、吐痰、内热、骨蒸、盗汗，种种阴虚等病。医师不察，不揆其本，凡见前证，不分阴阳，类施温补。参、耆、二术，视同食物；佐以姜、桂，若啖五辛。倘遇惫剧，辄投附子。于是轻者重，重者毙，累累相踵，死而不悟。良可悯也！然使其术得售者，不独医师之罪，亦病家不明，有以致之耳！何则？难成易亏者，阴也。益阴之药，纵医师选用无差，亦必无旦夕之效。助阳之药，能使胃气一时暂壮，饮食加增；或阳道兴举，有似神王。医师藉以要功，病者利其速效，彼此固执，莫辨厥由。故知阴虚真水不足之病，十人而九；阳虚真火不足之病，百不得一。医师之药，补助阳火者，往往概施；滋益阴精者，未尝少见。宜乎服药者之多毙，无药者之反存也。予见世医以此伤人者甚众，兹特著其误，以为世戒。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:52:32.000Z', '2024-12-21T02:52:32.000Z', '2024-12-21T02:52:32.000Z', '1、人身之有阴阳也，水一而已，火则二焉。是秉受之始。阳常有余，阴常不足，天地且然，况于人乎？故自少至老，所生疾病，靡不由于真阴不足者，其恒也。若夫真阳不足之病，千百而一二矣。阳者气也，火也，神也：阴者血也，水也，精也。阴阳和平，气血均调，是为平人气象之常候。苟失所养，或纵恣房室，或肆情喜怒，或轻犯阴阳，或嗜好辛热，以致肾水真阴不足，不能匹配阳火，遂使阳气有余。气有余，即是火，故火愈盛而水愈涸，于是发为吐血、咳嗽、吐痰、内热、骨蒸、盗汗，种种阴虚等病。医师不察，不揆其本，凡见前证，不分阴阳，类施温补。参、耆、二术，视同食物；佐以姜、桂，若啖五辛。倘遇惫剧，辄投附子。于是轻者重，重者毙，累累相踵，死而不悟。良可悯也！然使其术得售者，不独医师之罪，亦病家不明，有以致之耳！何则？难成易亏者，阴也。益阴之药，纵医师选用无差，亦必无旦夕之效。助阳之药，能使胃气一时暂壮，饮食加增；或阳道兴举，有似神王。医师藉以要功，病者利其速效，彼此固执，莫辨厥由。故知阴虚真水不足之病，十人而九；阳虚真火不足之病，百不得一。医师之药，补助阳火者，往往概施；滋益阴精者，未尝少见。宜乎服药者之多毙，无药者之反存也。予见世医以此伤人者甚众，兹特著其误，以为世戒。', '2024-12-21T02:52:32.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'SDlfV2M0h46');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('csDPm6Up9UP', 4, '{"title":"第400102301条・卷之一_续序例上_论上盛下虚本于肾水真阴不足","description":"<p>1、人身以阴阳两称为平，偏胜则病，此大较也。水不足则火有余，阴既亏则阳独盛。盖阴阳之精，互藏其宅，是阴中有阳，阳中有阴也。故心，火也，而含赤液；肾，水也，而藏白气。赤液为阴，白气为阳。循环往复，昼夜不息，此常度也。苟不知摄养，纵恣情欲，亏损真阴，阳无所附，因而发越上升，此火空则发之义，是周身之气，并于阳也。并于阳则阳盛，故上焦热而咳嗽生痰，迫血上行而为吐衄，为烦躁，为头痛，为不得眠，为胸前骨痛，为口干舌苦，此其候也。阳愈盛则阴愈虚，阴愈虚则为五心烦热，为潮热骨蒸，为遗精，为骨乏无力，为小水短赤，丹田不暖，则饮食不化，为泄泻，为卒僵仆，此其候也。治之之要，当亟降气，当益阴精。气降即阳交于阴，是火下降也。精血生即肾阴复，是水上升也。此既济之象，为坎离交也。坎离交，即是小周天。至此则阴阳二气复得其平矣，病何自而生哉？　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:54:41.000Z', '2024-12-21T02:54:41.000Z', '2024-12-21T02:54:41.000Z', '1、人身以阴阳两称为平，偏胜则病，此大较也。水不足则火有余，阴既亏则阳独盛。盖阴阳之精，互藏其宅，是阴中有阳，阳中有阴也。故心，火也，而含赤液；肾，水也，而藏白气。赤液为阴，白气为阳。循环往复，昼夜不息，此常度也。苟不知摄养，纵恣情欲，亏损真阴，阳无所附，因而发越上升，此火空则发之义，是周身之气，并于阳也。并于阳则阳盛，故上焦热而咳嗽生痰，迫血上行而为吐衄，为烦躁，为头痛，为不得眠，为胸前骨痛，为口干舌苦，此其候也。阳愈盛则阴愈虚，阴愈虚则为五心烦热，为潮热骨蒸，为遗精，为骨乏无力，为小水短赤，丹田不暖，则饮食不化，为泄泻，为卒僵仆，此其候也。治之之要，当亟降气，当益阴精。气降即阳交于阴，是火下降也。精血生即肾阴复，是水上升也。此既济之象，为坎离交也。坎离交，即是小周天。至此则阴阳二气复得其平矣，病何自而生哉？', '2024-12-21T02:54:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'aKMN48VXI8B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ml6716gUoaR', 4, '{"title":"第400102401条・卷之一_续序例上_论阴精阳气补益不同","description":"<p>1、《经》曰：形不足，温之以气。人参、羊肉、黄耆、人胞、红铅之属是已。益阳气也，乃可以却沉寒。经曰：精不足，补之以味。人乳、鳖甲、地黄、黄檗、枸杞、牛膝、天门冬之属是已。补阴精也，乃可以除伏热。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:55:15.000Z', '2024-12-21T02:55:15.000Z', '2024-12-21T02:55:15.000Z', '1、《经》曰：形不足，温之以气。人参、羊肉、黄耆、人胞、红铅之属是已。益阳气也，乃可以却沉寒。经曰：精不足，补之以味。人乳、鳖甲、地黄、黄檗、枸杞、牛膝、天门冬之属是已。补阴精也，乃可以除伏热。', '2024-12-21T02:55:15.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xWotcwQYHmY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d3TkHaNy0n6', 4, '{"title":"第400102504条・ 卷之一_续序例上_论治气三法药各不同","description":"<p>4、盖气分之病，不出三端。治之之法，及所主之药，皆不可混滥也。误则使病转剧。世多不察，故表而出之。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '4、盖气分之病，不出三端。治之之法，及所主之药，皆不可混滥也。误则使病转剧。世多不察，故表而出之。', '2024-12-21T02:57:15.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'cbU6PXzATyw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PTY46za86hG', 4, '{"title":"第400102503条・ 卷之一_续序例上_论治气三法药各不同","description":"<p>3、三、破气：破者，损也。实则宜破，如少壮人暴怒气壅之类。然亦可暂不可久。其药如枳实、青皮、枳壳、牵牛之属。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '3、三、破气：破者，损也。实则宜破，如少壮人暴怒气壅之类。然亦可暂不可久。其药如枳实、青皮、枳壳、牵牛之属。', '2024-12-21T02:57:15.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'cbU6PXzATyw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j02nqWyOmc8', 4, '{"title":"第400102502条・ 卷之一_续序例上_论治气三法药各不同","description":"<p>2、二、降气、调气：降气者，即下气也。虚则气升，故法宜降。其药之轻者，如紫苏子、橘皮、麦门冬、枇杷叶、芦根汁、甘蔗；其重者，如番降香、郁金、槟榔之属。调者，和也。逆则宜和，和则调也。其药如木香、沉水香、白豆蔻、缩砂蜜、香附、橘皮、乌药之属。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '2、二、降气、调气：降气者，即下气也。虚则气升，故法宜降。其药之轻者，如紫苏子、橘皮、麦门冬、枇杷叶、芦根汁、甘蔗；其重者，如番降香、郁金、槟榔之属。调者，和也。逆则宜和，和则调也。其药如木香、沉水香、白豆蔻、缩砂蜜、香附、橘皮、乌药之属。', '2024-12-21T02:57:15.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'cbU6PXzATyw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kh2sBOVVOMO', 4, '{"title":"第400102501条・ 卷之一_续序例上_论治气三法药各不同","description":"<p>1、一、补气：气虚宜补之，如人参、黄耆、羊肉、小麦、糯米之属是也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '2024-12-21T02:57:15.000Z', '1、一、补气：气虚宜补之，如人参、黄耆、羊肉、小麦、糯米之属是也。', '2024-12-21T02:57:15.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'cbU6PXzATyw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8U9fvHX8yUi', 4, '{"title":"第400102604条・卷之一_续序例上_论治血三法药各不同","description":"<p>4、盖血为荣，阴也，有形可见，有色可察，有证可审者也。病既不同，药亦各异。治之之法，要在合宜。倘失其宜，为厉不浅，差剧之门，可不谨乎？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102604,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '4、盖血为荣，阴也，有形可见，有色可察，有证可审者也。病既不同，药亦各异。治之之法，要在合宜。倘失其宜，为厉不浅，差剧之门，可不谨乎？', '2024-12-21T02:58:58.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uFQeZW1wNlH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t3fj3C1310J', 4, '{"title":"第400102603条・卷之一_续序例上_论治血三法药各不同","description":"<p>3、血瘀宜通之。瘀必发热发黄，作痛作肿，及作结块癖积。法宜辛温、辛热、辛平、辛寒、甘温，以入血通行。佐以咸寒，乃可软坚。其药为当归、红花、桃仁、苏木、桂、五灵脂、蒲黄、姜黄、郁金、京三棱、延胡索、花蕊石、没药、䗪虫、干漆、自然铜、韭汁、童便、牡蛎、芒硝之属。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102603,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '3、血瘀宜通之。瘀必发热发黄，作痛作肿，及作结块癖积。法宜辛温、辛热、辛平、辛寒、甘温，以入血通行。佐以咸寒，乃可软坚。其药为当归、红花、桃仁、苏木、桂、五灵脂、蒲黄、姜黄、郁金、京三棱、延胡索、花蕊石、没药、䗪虫、干漆、自然铜、韭汁、童便、牡蛎、芒硝之属。', '2024-12-21T02:58:58.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uFQeZW1wNlH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4mwJbC0obOS', 4, '{"title":"第400102602条・卷之一_续序例上_论治血三法药各不同","description":"<p>2、血热宜清之凉之。热则为痈肿疮疖，为鼻衄，为齿衄，为牙龈肿，为舌上出血，为舌肿，为血崩，为赤淋，为月事先期，为热入血室，为赤游丹，为眼暴赤痛。法宜酸寒、苦寒、咸寒、辛凉，以除实热。其药为童便、牡丹皮、赤芍药、生地黄、黄芩、犀角、地榆、大小蓟、茜草、黄连、山栀、大黄、青黛、天门冬、玄参、荆芥之属。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102602,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '2、血热宜清之凉之。热则为痈肿疮疖，为鼻衄，为齿衄，为牙龈肿，为舌上出血，为舌肿，为血崩，为赤淋，为月事先期，为热入血室，为赤游丹，为眼暴赤痛。法宜酸寒、苦寒、咸寒、辛凉，以除实热。其药为童便、牡丹皮、赤芍药、生地黄、黄芩、犀角、地榆、大小蓟、茜草、黄连、山栀、大黄、青黛、天门冬、玄参、荆芥之属。', '2024-12-21T02:58:58.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uFQeZW1wNlH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WcnQke9M2E0', 4, '{"title":"第400102601条・卷之一_续序例上_论治血三法药各不同","description":"<p>1、血虚宜补之。虚则发热。内热，法宜甘寒、甘平、酸寒、酸温，以益荣血。其药为熟地黄、白芍药、牛膝、炙甘草、酸枣仁、龙眼肉、鹿角胶、肉苁蓉、甘枸杞子、甘菊花、人乳之属。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '2024-12-21T02:58:58.000Z', '1、血虚宜补之。虚则发热。内热，法宜甘寒、甘平、酸寒、酸温，以益荣血。其药为熟地黄、白芍药、牛膝、炙甘草、酸枣仁、龙眼肉、鹿角胶、肉苁蓉、甘枸杞子、甘菊花、人乳之属。', '2024-12-21T02:58:58.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uFQeZW1wNlH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IESVwekuCpo', 4, '{"title":"第400102707条・ 卷之一_续序例上_论治吐血三要","description":"<p>7、《经》曰：五脏者，藏精气而不泻者也。肝为将军之官，主藏血。吐血者，肝失其职也。养肝则肝气平，而血有所归；伐之则肝不能藏血，血愈不止矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '7、《经》曰：五脏者，藏精气而不泻者也。肝为将军之官，主藏血。吐血者，肝失其职也。养肝则肝气平，而血有所归；伐之则肝不能藏血，血愈不止矣。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T9BjIfqD61Y', 4, '{"title":"第400102706条・ 卷之一_续序例上_论治吐血三要","description":"<p>6、【宜】补肝，不宜伐肝。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '6、【宜】补肝，不宜伐肝。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g95NnYcxhg7', 4, '{"title":"第400102705条・ 卷之一_续序例上_论治吐血三要","description":"<p>5、血不循经络者，气逆上壅也。夫血得热则行，得寒则凝，故降气行血，则血循经络，不求其止而自止矣。止之则血凝，血凝必发热、恶食，及胸胁痛，病日沉痼矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '5、血不循经络者，气逆上壅也。夫血得热则行，得寒则凝，故降气行血，则血循经络，不求其止而自止矣。止之则血凝，血凝必发热、恶食，及胸胁痛，病日沉痼矣。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gWuOxi7Py4j', 4, '{"title":"第400102704条・ 卷之一_续序例上_论治吐血三要","description":"<p>4、【宜】行血，不宜止血。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '4、【宜】行血，不宜止血。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sCzKzUNcrNl', 4, '{"title":"第400102703条・ 卷之一_续序例上_论治吐血三要","description":"<p>3、今之疗吐血者，大患有二：一则专用寒凉之味，如芩、连、山栀、青黛、柿饼灰、四物汤、黄檗、知母之类，往往伤脾作泄，以致不救。一则专用人参，肺热还伤肺，咳逆愈甚。亦有用参而愈者，此是气虚喘嗽。气属阳，不由阴虚火炽所致，然亦百不一二也。宜以白芍药、炙甘草制肝；枇杷叶、麦门冬、薄荷、橘红、贝母清肺；薏苡仁、怀山药养脾；韭菜、番降香、真苏子下气；青蒿、鳖甲、银柴胡、牡丹皮、地骨皮补阴清热；酸枣仁、白茯神养心；山茱萸、枸杞子、牛膝补肾。此累试辄验之方。然阴无骤补之法，非多服药不效。病家欲速其功，医者张皇无主。百药杂试，以致殒命，覆辙相寻而不悟，悲夫！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '3、今之疗吐血者，大患有二：一则专用寒凉之味，如芩、连、山栀、青黛、柿饼灰、四物汤、黄檗、知母之类，往往伤脾作泄，以致不救。一则专用人参，肺热还伤肺，咳逆愈甚。亦有用参而愈者，此是气虚喘嗽。气属阳，不由阴虚火炽所致，然亦百不一二也。宜以白芍药、炙甘草制肝；枇杷叶、麦门冬、薄荷、橘红、贝母清肺；薏苡仁、怀山药养脾；韭菜、番降香、真苏子下气；青蒿、鳖甲、银柴胡、牡丹皮、地骨皮补阴清热；酸枣仁、白茯神养心；山茱萸、枸杞子、牛膝补肾。此累试辄验之方。然阴无骤补之法，非多服药不效。病家欲速其功，医者张皇无主。百药杂试，以致殒命，覆辙相寻而不悟，悲夫！', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1vcS5ZX7IOZ', 4, '{"title":"第400102702条・ 卷之一_续序例上_论治吐血三要","description":"<p>2、气有余，即是火。气降则火降，火降则气不上升，血随气行，无溢出上窍之患矣。降火必用寒凉之剂，反伤胃气。胃气伤，则脾不能统血，血愈不能归经矣。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2、气有余，即是火。气降则火降，火降则气不上升，血随气行，无溢出上窍之患矣。降火必用寒凉之剂，反伤胃气。胃气伤，则脾不能统血，血愈不能归经矣。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EqkAz0iaO42', 4, '{"title":"第400102701条・ 卷之一_续序例上_论治吐血三要","description":"<p>1、【宜】降气，不宜降火。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '2024-12-21T03:01:25.000Z', '1、【宜】降气，不宜降火。', '2024-12-21T03:01:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xsyGodY30hk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bNqi3xOk1ud', 4, '{"title":"第400102801条・卷之一_续序例上_论肾泄多在黎明所由","description":"<p>1、凡人之生，二五妙合之顷，识神依托是中，即揽父精母血，以为立命之基，遂成左右两肾。肾间动气，即道家所谓先天祖气是也。藏乎两肾之中，以肾属水，故称坎宫。以平人气象言之，此气至子后一阳生，生即渐渐上升，历丑、寅、卯、辰、巳，而六阳已极，则入离宫。午后一阴生，即白气变为赤液，渐渐降下至坎宫，复为白气，昼夜循环，升降不息，此即医家所谓真阳之火，道家所谓君火，即先天祖气，医家谓为相火者是也。方此火之自下而上也，行过中焦，必经脾胃，则能腐熟水谷，蒸糟粕而化精微。脾气散精，上归于肺。通调水道，下输膀胱，气化而出，是谓清升浊降，即既济之象也。苟不慎摄生之道，不明正性之理，则必务快其心，逆于生乐，忧患以伤心，寒热以伤肺，饥饱以伤脾，多怒以伤肝，多欲以伤肾，则真气渐衰，精神日损。驯至子后，一阳不以时生，不能上升腐熟水谷，则糟粕无由而化。寅为三阳之候，阳气微则不能应候而化物，故天黎明而泄。其泄亦溏，俗名鸭溏，是为肾泄，亦名大瘕泄。昔人以四神丸治之，予加人参、莲肉，辄获奇效。盖人参补五脏之阳气故也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:02:23.000Z', '2024-12-21T03:02:23.000Z', '2024-12-21T03:02:23.000Z', '1、凡人之生，二五妙合之顷，识神依托是中，即揽父精母血，以为立命之基，遂成左右两肾。肾间动气，即道家所谓先天祖气是也。藏乎两肾之中，以肾属水，故称坎宫。以平人气象言之，此气至子后一阳生，生即渐渐上升，历丑、寅、卯、辰、巳，而六阳已极，则入离宫。午后一阴生，即白气变为赤液，渐渐降下至坎宫，复为白气，昼夜循环，升降不息，此即医家所谓真阳之火，道家所谓君火，即先天祖气，医家谓为相火者是也。方此火之自下而上也，行过中焦，必经脾胃，则能腐熟水谷，蒸糟粕而化精微。脾气散精，上归于肺。通调水道，下输膀胱，气化而出，是谓清升浊降，即既济之象也。苟不慎摄生之道，不明正性之理，则必务快其心，逆于生乐，忧患以伤心，寒热以伤肺，饥饱以伤脾，多怒以伤肝，多欲以伤肾，则真气渐衰，精神日损。驯至子后，一阳不以时生，不能上升腐熟水谷，则糟粕无由而化。寅为三阳之候，阳气微则不能应候而化物，故天黎明而泄。其泄亦溏，俗名鸭溏，是为肾泄，亦名大瘕泄。昔人以四神丸治之，予加人参、莲肉，辄获奇效。盖人参补五脏之阳气故也。', '2024-12-21T03:02:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'iyuPry1EgI7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0KyrBcEpCqN', 4, '{"title":"第400102901条・ 卷之一_续序例上_论少年人阳痿因于失志，不宜补阳","description":"<p>1、《经》曰：肾为作强之官，技巧出焉，藏精与志者也。夫志从士从心，志主决定，心主思维。思维则或迁或改，决定则一立不移，此作强之验也。苟志意不遂，则阳气不舒。阳气者，即真火也。譬夫极盛之火，置之密器之中，闭闷其气，使不得发越，则火立死而寒矣。此非真火衰也，乃闷郁之故也。宣其抑郁，通其志意，则阳气立舒，而其痿立起矣。若误谓阳精不足，过投补火之剂，多致痈疽而殁，可不戒哉！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400102901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:03:44.000Z', '2024-12-21T03:03:44.000Z', '2024-12-21T03:03:44.000Z', '1、《经》曰：肾为作强之官，技巧出焉，藏精与志者也。夫志从士从心，志主决定，心主思维。思维则或迁或改，决定则一立不移，此作强之验也。苟志意不遂，则阳气不舒。阳气者，即真火也。譬夫极盛之火，置之密器之中，闭闷其气，使不得发越，则火立死而寒矣。此非真火衰也，乃闷郁之故也。宣其抑郁，通其志意，则阳气立舒，而其痿立起矣。若误谓阳精不足，过投补火之剂，多致痈疽而殁，可不戒哉！', '2024-12-21T03:03:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xTBDXrouGLl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xhJg3bt3ZR6', 4, '{"title":"第400103007条・ 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>7、补阳则人参、黄耆、鹿茸、大枣、巴戟天之属。与时消息，则因乎证。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '7、补阳则人参、黄耆、鹿茸、大枣、巴戟天之属。与时消息，则因乎证。', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DlBjpy8umLi');
