INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cpL7h2P6hel', 4, '{"title":"第400103005条・ 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>5、开痰则贝母、白芥子、竹沥、荆沥、栝楼仁、霞天膏。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '5、开痰则贝母、白芥子、竹沥、荆沥、栝楼仁、霞天膏。', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DlBjpy8umLi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2uRi1hjbOfz', 4, '{"title":"第400103004条・ 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>4、顺气则紫苏子、枇杷叶、橘红、郁金；　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '4、顺气则紫苏子、枇杷叶、橘红、郁金；', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DlBjpy8umLi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xj1XEoXDqq7', 4, '{"title":"第400103003条・ 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>3、初清热则天门冬、麦门冬、甘菊花、白芍药、白茯苓、栝楼根、童便；　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '3、初清热则天门冬、麦门冬、甘菊花、白芍药、白茯苓、栝楼根、童便；', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DlBjpy8umLi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5NvqRL7AA2R', 4, '{"title":"第400103002条・ 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>2、若夫大江已南之东西两浙、七闽、百粤、两川、滇南、鬼方、荆、扬、梁三州之域，天地之风气既殊，人之所禀亦异。其地绝无刚猛之风，而多湿热之气，质多柔脆，往往多热多痰。真阴既亏，内热弥甚，煎熬津液，凝结为痰，壅塞气道，不得通利。热极生风，亦致猝然僵仆，类中风证。或不省人事，或语言謇涩，或口眼歪斜，或半身不遂。其将发也，外必先显内热之候，或口干舌苦，或大便秘涩，小便短赤，此其验也。刘河间所谓此证全是将息失宜，水不制火。丹溪所谓湿热相火，中痰、中气是也。此即内虚暗风，确系阴阳两虚，而阴虚者为多，与外来风邪迥别。法当清热、顺气、开痰，以救其标，次当治本。阴虚则益血，阳虚则补气，气血两虚则气血兼补，久之自瘳。设若误用治真中风药，如前辛热风燥之剂，则轻变为重，重则必死。祸福反掌，不可不察也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2、若夫大江已南之东西两浙、七闽、百粤、两川、滇南、鬼方、荆、扬、梁三州之域，天地之风气既殊，人之所禀亦异。其地绝无刚猛之风，而多湿热之气，质多柔脆，往往多热多痰。真阴既亏，内热弥甚，煎熬津液，凝结为痰，壅塞气道，不得通利。热极生风，亦致猝然僵仆，类中风证。或不省人事，或语言謇涩，或口眼歪斜，或半身不遂。其将发也，外必先显内热之候，或口干舌苦，或大便秘涩，小便短赤，此其验也。刘河间所谓此证全是将息失宜，水不制火。丹溪所谓湿热相火，中痰、中气是也。此即内虚暗风，确系阴阳两虚，而阴虚者为多，与外来风邪迥别。法当清热、顺气、开痰，以救其标，次当治本。阴虚则益血，阳虚则补气，气血两虚则气血兼补，久之自瘳。设若误用治真中风药，如前辛热风燥之剂，则轻变为重，重则必死。祸福反掌，不可不察也。', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DlBjpy8umLi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aiIqfYEMUtu', 4, '{"title":"第400103001条・ 卷之一_续序例上_论似中风与真中风治法迥别，误则杀人","description":"<p>1、凡言中风，有真假内外之别。差之毫厘，谬以千里。何者？西北土地高寒，风气刚烈。真气空虚之人，猝为所中，中脏者死，中腑者成废人，中经络者，可调理而瘳。治之之道，先以解散风邪为急，次则补养气血，此治真中外来风邪之法也。其药以小续命汤，桂枝、麻黄、生熟附子、羌独活、防风、白芷、南星、甘草之属为本。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '2024-12-21T03:06:08.000Z', '1、凡言中风，有真假内外之别。差之毫厘，谬以千里。何者？西北土地高寒，风气刚烈。真气空虚之人，猝为所中，中脏者死，中腑者成废人，中经络者，可调理而瘳。治之之道，先以解散风邪为急，次则补养气血，此治真中外来风邪之法也。其药以小续命汤，桂枝、麻黄、生熟附子、羌独活、防风、白芷、南星、甘草之属为本。', '2024-12-21T03:06:08.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'DlBjpy8umLi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G5MqrviME1m', 4, '{"title":"第400103102条・卷之一_续序例上_似中风问答","description":"<p>2、答曰：眠不竟夕而易惺者，心血不足也，故其脉弦而不洪。东垣云：胃虚者多怒，多怒者肝气必不和。《经》曰：怒则气上逆。加以久病多郁，故益易怒，故肝脉亦弦而不长。弦为血少。此非以智慧观察，以慈忍静定之力和之，未可以药石瘳也。肾属水，冬脉沉，故曰：诸浮者，肾不足也。肾主五液，又主二便，肾家有火，则真阴日亏，津液日少，不能荣养于舌络，舌络劲急，故语言不利；火性急速，故小便疾出而不能忍，且有余沥，而大便亦多燥结也。故其脉应沉实而反浮洪，失常候也。肺者，五脏之华盖，位乎上，象天而属金，喜清肃而恶烦热，热则津液干枯，无以下滴而通水道，或煎熬浓稠而成痰矣。肺热则人参反助邪热而伤肺，故往往声重多痰，壅塞气道，而升降不利也。脾为土脏，胃为之腑，乃后天元气之所自出。胃主纳，脾主消，脾阴亏则不能消，胃气弱则不能纳，饮食少则后天元气无自而生，精血坐是日益不足也。《经》曰：损其脾者，调其饮食，节其起居，适其寒温。此至论也。不如是则不足以复脾阴。然其要又在戒暴怒，使肝无不平之气，肝和则不贼脾土矣。命门者，火脏也，乃先天真阳之气之所寄，即道家所谓先天祖气，医家所谓真火是也。其壮也有三：一者元禀过厚，二者保啬精气，不妄施泄，三者志气无所怫郁，则年虽迈而犹壮也。不尔则子后一阳不生，不能上升熏蒸糟粕而化精微，以滋后天之元气，是火不生土，而脾胃因之日弱也。法当降气和肝滋肾，气降是阳交于阴也。肝和则脾胃不被贼邪所干，故能纳而能消也。脾胃无恙，则后天元气日益生长矣。肾足则真阴自生，津液自足，舌络有所荣养，则舌之伸缩自如而言语自利矣。且世无不阴虚而中风者，第须拨去烦恼，一切放下，使心火不炎，则肾亦因之而不燥，此又治之之本也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:07:28.000Z', '2024-12-21T03:07:28.000Z', '2024-12-21T03:07:28.000Z', '2、答曰：眠不竟夕而易惺者，心血不足也，故其脉弦而不洪。东垣云：胃虚者多怒，多怒者肝气必不和。《经》曰：怒则气上逆。加以久病多郁，故益易怒，故肝脉亦弦而不长。弦为血少。此非以智慧观察，以慈忍静定之力和之，未可以药石瘳也。肾属水，冬脉沉，故曰：诸浮者，肾不足也。肾主五液，又主二便，肾家有火，则真阴日亏，津液日少，不能荣养于舌络，舌络劲急，故语言不利；火性急速，故小便疾出而不能忍，且有余沥，而大便亦多燥结也。故其脉应沉实而反浮洪，失常候也。肺者，五脏之华盖，位乎上，象天而属金，喜清肃而恶烦热，热则津液干枯，无以下滴而通水道，或煎熬浓稠而成痰矣。肺热则人参反助邪热而伤肺，故往往声重多痰，壅塞气道，而升降不利也。脾为土脏，胃为之腑，乃后天元气之所自出。胃主纳，脾主消，脾阴亏则不能消，胃气弱则不能纳，饮食少则后天元气无自而生，精血坐是日益不足也。《经》曰：损其脾者，调其饮食，节其起居，适其寒温。此至论也。不如是则不足以复脾阴。然其要又在戒暴怒，使肝无不平之气，肝和则不贼脾土矣。命门者，火脏也，乃先天真阳之气之所寄，即道家所谓先天祖气，医家所谓真火是也。其壮也有三：一者元禀过厚，二者保啬精气，不妄施泄，三者志气无所怫郁，则年虽迈而犹壮也。不尔则子后一阳不生，不能上升熏蒸糟粕而化精微，以滋后天之元气，是火不生土，而脾胃因之日弱也。法当降气和肝滋肾，气降是阳交于阴也。肝和则脾胃不被贼邪所干，故能纳而能消也。脾胃无恙，则后天元气日益生长矣。肾足则真阴自生，津液自足，舌络有所荣养，则舌之伸缩自如而言语自利矣。且世无不阴虚而中风者，第须拨去烦恼，一切放下，使心火不炎，则肾亦因之而不燥，此又治之之本也。', '2024-12-21T03:07:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'CfP0L52yWOa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mi7X6by55gZ', 4, '{"title":"第400103101条・卷之一_续序例上_似中风问答","description":"<p>1、或问：有患似中风证，眠不竟夕而易惺，心脉弦而不洪，多怒，肝脉弦而不长，语言謇涩不利，多痰声重，小便疾速不能忍，且有余沥，大便燥结，左尺脉浮洪，饮食少，不易消，此何以故？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:07:28.000Z', '2024-12-21T03:07:28.000Z', '2024-12-21T03:07:28.000Z', '1、或问：有患似中风证，眠不竟夕而易惺，心脉弦而不洪，多怒，肝脉弦而不长，语言謇涩不利，多痰声重，小便疾速不能忍，且有余沥，大便燥结，左尺脉浮洪，饮食少，不易消，此何以故？', '2024-12-21T03:07:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'CfP0L52yWOa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GlzHllbJbm2', 4, '{"title":"第400103202条・卷之一_续序例上_论痰饮药宜分治","description":"<p>2、世以痰饮混称，药亦混投。殊不知痰之与饮，其由自别，其状亦殊。痰质稠粘，饮惟清水，特其色有异，或青或黄，或绿或黑，或如酸浆，或伏于肠胃，或上支胸胁，刺痛难忍，或流于经络四肢，则关节不利。支饮上攻为心痛，为中脘痛，甚则汗出，为呕吐酸水、苦黄水等，种种各异。或发寒热，不思饮食，及不得眠，皆其候也。此证皆因酒后过饮茶汤，则水浆与肠胃饮食湿热之气，凝而为饮；或因情抱抑郁，饮食停滞，不得以时消散，亦能成饮。总之必由脾胃有湿，或脾胃本虚，又感饮食之湿，则停而不消，此饮之大略也。治宜燥湿利水，行气健脾，乃为得也。其药大都以半夏、茯苓、参、术为君，佐以猪苓、泽泻以渗泄之，白豆蔻、橘皮以开散之，苏梗、旋覆花以通畅之。东垣五饮丸中有人参，其旨概可见矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103202,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:08:28.000Z', '2024-12-21T03:08:28.000Z', '2024-12-21T03:08:28.000Z', '2、世以痰饮混称，药亦混投。殊不知痰之与饮，其由自别，其状亦殊。痰质稠粘，饮惟清水，特其色有异，或青或黄，或绿或黑，或如酸浆，或伏于肠胃，或上支胸胁，刺痛难忍，或流于经络四肢，则关节不利。支饮上攻为心痛，为中脘痛，甚则汗出，为呕吐酸水、苦黄水等，种种各异。或发寒热，不思饮食，及不得眠，皆其候也。此证皆因酒后过饮茶汤，则水浆与肠胃饮食湿热之气，凝而为饮；或因情抱抑郁，饮食停滞，不得以时消散，亦能成饮。总之必由脾胃有湿，或脾胃本虚，又感饮食之湿，则停而不消，此饮之大略也。治宜燥湿利水，行气健脾，乃为得也。其药大都以半夏、茯苓、参、术为君，佐以猪苓、泽泻以渗泄之，白豆蔻、橘皮以开散之，苏梗、旋覆花以通畅之。东垣五饮丸中有人参，其旨概可见矣。', '2024-12-21T03:08:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '420lnw4jgqn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xGwu4G3i1uU', 4, '{"title":"第400103201条・卷之一_续序例上_论痰饮药宜分治","description":"<p>1、夫痰之生也，其由非一；其为治也，药亦不同。由于阴虚火炎，上迫乎肺，肺气热则煎熬津液，凝结为痰，是为阴虚痰火。痰在乎肺而本乎肾，治宜降气清热，益阴滋水。法忌辛温燥热补气等药。由于脾胃寒湿生痰，或兼饮啖过度，好食油面猪脂，以致脾气不利，壅滞为痰，浓厚胶固，甚至流于经络，及皮里膜外，或结为大块，或不思食，或彻夜不眠，或卒尔眩仆，不省人事，或发癫痫，或昔肥今瘦，或叫呼异常，或身重腹胀，不便行走，或泄泻不止，及成瘫痪。种种怪证，皆痰所为。故昔人云：怪病多属痰，暴病多属火。有以夫！此病在脾胃，无关肺肾，治宜燥脾行气，散结软坚。法忌滞泥、苦寒、湿润等药，及诸厚味。由于风寒郁闭，热气在肺，而成痰嗽齁喘，病亦在肺，治宜豁痰除肺热药中，加辛热、辛温，如麻黄、生干姜之属，以散外寒，则药无格拒之患。法忌温补、酸收等药。病因不齐，药亦宜异。利润利燥，及利发散，各有攸当，非可混施也。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:08:28.000Z', '2024-12-21T03:08:28.000Z', '2024-12-21T03:08:28.000Z', '1、夫痰之生也，其由非一；其为治也，药亦不同。由于阴虚火炎，上迫乎肺，肺气热则煎熬津液，凝结为痰，是为阴虚痰火。痰在乎肺而本乎肾，治宜降气清热，益阴滋水。法忌辛温燥热补气等药。由于脾胃寒湿生痰，或兼饮啖过度，好食油面猪脂，以致脾气不利，壅滞为痰，浓厚胶固，甚至流于经络，及皮里膜外，或结为大块，或不思食，或彻夜不眠，或卒尔眩仆，不省人事，或发癫痫，或昔肥今瘦，或叫呼异常，或身重腹胀，不便行走，或泄泻不止，及成瘫痪。种种怪证，皆痰所为。故昔人云：怪病多属痰，暴病多属火。有以夫！此病在脾胃，无关肺肾，治宜燥脾行气，散结软坚。法忌滞泥、苦寒、湿润等药，及诸厚味。由于风寒郁闭，热气在肺，而成痰嗽齁喘，病亦在肺，治宜豁痰除肺热药中，加辛热、辛温，如麻黄、生干姜之属，以散外寒，则药无格拒之患。法忌温补、酸收等药。病因不齐，药亦宜异。利润利燥，及利发散，各有攸当，非可混施也。', '2024-12-21T03:08:28.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '420lnw4jgqn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xm1hNQHQCHe', 4, '{"title":"第400103302条・卷之一_续序例上_疟痢宜从六淫例治","description":"<p>2、滞下者，俗呼为痢疾，皆缘暑湿与饮食之积滞胶固而成。其证类多里急后重，数登圊而不便，或发热，或口渴，或恶心，不思食何，莫非暑之标证也。必用六一散、黄连、芍药为主，而后随其所苦，为之增损。伤气分则调气益气；伤血分则行血和血，然未有不先治暑而可获效者矣。治病必求其本，其斯之谓欤？　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:10:38.000Z', '2024-12-21T03:10:38.000Z', '2024-12-21T03:10:38.000Z', '2、滞下者，俗呼为痢疾，皆缘暑湿与饮食之积滞胶固而成。其证类多里急后重，数登圊而不便，或发热，或口渴，或恶心，不思食何，莫非暑之标证也。必用六一散、黄连、芍药为主，而后随其所苦，为之增损。伤气分则调气益气；伤血分则行血和血，然未有不先治暑而可获效者矣。治病必求其本，其斯之谓欤？', '2024-12-21T03:10:38.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Adq9tM3QdXE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oLgOzKLW8Be', 4, '{"title":"第400103301条・卷之一_续序例上_疟痢宜从六淫例治","description":"<p>1、风寒暑湿燥火，此天之六淫。其邪自外而入，感之而病，宜随其邪之所在以攻治之。《经》曰：夏伤于暑，秋必痎疟。是疟乃暑邪为病也。虽有山岚瘴气发疟一证，治稍不同，然其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，头疼骨疼，大渴引饮，口苦舌干，呕吐不思食，或烦躁不得眠，必用白虎汤二三剂，随证增损，解表以祛暑邪。而后随经消息，以除其苦可也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:10:38.000Z', '2024-12-21T03:10:38.000Z', '2024-12-21T03:10:38.000Z', '1、风寒暑湿燥火，此天之六淫。其邪自外而入，感之而病，宜随其邪之所在以攻治之。《经》曰：夏伤于暑，秋必痎疟。是疟乃暑邪为病也。虽有山岚瘴气发疟一证，治稍不同，然其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，头疼骨疼，大渴引饮，口苦舌干，呕吐不思食，或烦躁不得眠，必用白虎汤二三剂，随证增损，解表以祛暑邪。而后随经消息，以除其苦可也。', '2024-12-21T03:10:38.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Adq9tM3QdXE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rMXqp3sxGcv', 4, '{"title":"第400103401条・卷之一_续序例上_论病由七情生者，只应养性怡神、发舒志气以解之，不宜全仗药石攻治","description":"<p>1、夫喜怒忧思悲恐惊七者，皆发于情者也。情即神识，有知不定，无迹可寻，触境乃发，滞而难通。药石无知，焉能消其妄执？纵通其已滞之气，活其已伤之血，其默默绵绵之意，物而不化者，能保无将来复结之病乎？只宜以识遣识，以理遣情，此即“心病还将心药医”之谓也。如是庶可使滞者通，结者化，情与境离，不为所转，当处寂然，心君泰定，其何七情之为累哉？</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:37:52.000Z', '2024-12-21T03:37:52.000Z', '2024-12-21T03:37:52.000Z', '1、夫喜怒忧思悲恐惊七者，皆发于情者也。情即神识，有知不定，无迹可寻，触境乃发，滞而难通。药石无知，焉能消其妄执？纵通其已滞之气，活其已伤之血，其默默绵绵之意，物而不化者，能保无将来复结之病乎？只宜以识遣识，以理遣情，此即“心病还将心药医”之谓也。如是庶可使滞者通，结者化，情与境离，不为所转，当处寂然，心君泰定，其何七情之为累哉？', '2024-12-21T03:37:52.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '17Zc7PMslmG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jf4lSTomS81', 4, '{"title":"第400103506条・卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>6、此之四证，皆须急治。要以自里达表者吉，自表陷里者凶。故药宜解散通利，最忌收涩破气，及诸温补。其关乎死生者最大，故特表而出之，俾世人知所先务也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103506,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '6、此之四证，皆须急治。要以自里达表者吉，自表陷里者凶。故药宜解散通利，最忌收涩破气，及诸温补。其关乎死生者最大，故特表而出之，俾世人知所先务也。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'EDWZU6URWOV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i68trpKKfn2', 4, '{"title":"第400103505条・卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>5、疟本暑邪，法当解肌。若元气先虚之人，脾胃薄弱，误投破气消食克伐之药，则中气愈虚，邪反内陷，必便脓血。治或失宜，多成腹胀，驯至不救，往往而是。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103505,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '5、疟本暑邪，法当解肌。若元气先虚之人，脾胃薄弱，误投破气消食克伐之药，则中气愈虚，邪反内陷，必便脓血。治或失宜，多成腹胀，驯至不救，往往而是。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'EDWZU6URWOV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nOpHotAuLQU', 4, '{"title":"第400103504条・卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>4、若夫疹家，便须速用辛寒、甘寒、苦寒之剂，清凉发散，十不失一。假令病重药轻，或治疗后期，或误投温热，则邪热内攻，烦躁闷乱，不可救药矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '4、若夫疹家，便须速用辛寒、甘寒、苦寒之剂，清凉发散，十不失一。假令病重药轻，或治疗后期，或误投温热，则邪热内攻，烦躁闷乱，不可救药矣。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'EDWZU6URWOV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NOddivXF6O8', 4, '{"title":"第400103503条・卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>3、痘疮之害，多在血热，解于一二日内者十全八九，若迟则热毒内攻，陷入于里。肠胃当之，必致大便作泄，乳食不化，或神昏闷乱，便秘腹胀，则十不救一。除是禀受虚寒，方堪补托，济以温热，可救危急。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '3、痘疮之害，多在血热，解于一二日内者十全八九，若迟则热毒内攻，陷入于里。肠胃当之，必致大便作泄，乳食不化，或神昏闷乱，便秘腹胀，则十不救一。除是禀受虚寒，方堪补托，济以温热，可救危急。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'EDWZU6URWOV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1SaHhJQM51A', 4, '{"title":"第400103502条・卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>2、痈疽皆由荣家实热气逆所结，急宜凉血活血，散结解毒，大剂连进，内外夹攻，务使消散。即势大毒盛，一时不能散尽，亦必十消七八。纵使溃脓，保无大害。若失于救治，使热毒内攻，其膜必坏。膜坏则神人不能救矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2、痈疽皆由荣家实热气逆所结，急宜凉血活血，散结解毒，大剂连进，内外夹攻，务使消散。即势大毒盛，一时不能散尽，亦必十消七八。纵使溃脓，保无大害。若失于救治，使热毒内攻，其膜必坏。膜坏则神人不能救矣。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'EDWZU6URWOV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JB79UDcOEl6', 4, '{"title":"第400103501条・卷之一_续序例上_论伤寒温疫、痈疽痘疹、疟疾诸病皆由实邪所发，自里发出于表者吉，由表陷入于里者凶","description":"<p>1、伤寒、温疫初发，邪在于表，必头疼身热，病属三阳，即于此时急表散之。冬月即病，宜用辛温、辛热以汗之；春温夏热，宜用辛凉、辛寒、甘寒以汗之。汗后身凉脉静，无所伤犯，病不复作而愈。如投药濡滞，或病重药轻，不散之于表，致邪热内结，病属三阴，须下乃愈。内虚之人，不胜下药，多致危殆。又有少阴咽痛等证，则又不宜于下，或成狐惑，虫蚀肛门，种种难治之条，皆失于不早散故也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '2024-12-21T03:40:13.000Z', '1、伤寒、温疫初发，邪在于表，必头疼身热，病属三阳，即于此时急表散之。冬月即病，宜用辛温、辛热以汗之；春温夏热，宜用辛凉、辛寒、甘寒以汗之。汗后身凉脉静，无所伤犯，病不复作而愈。如投药濡滞，或病重药轻，不散之于表，致邪热内结，病属三阴，须下乃愈。内虚之人，不胜下药，多致危殆。又有少阴咽痛等证，则又不宜于下，或成狐惑，虫蚀肛门，种种难治之条，皆失于不早散故也。', '2024-12-21T03:40:13.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'EDWZU6URWOV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e0D8IJtRu1d', 4, '{"title":"第400103602条・ 卷之一_续序例上_论五运六气之谬","description":"<p>2、予少检《素问》中载有是说。既长游于四方，见天下医师与学士大夫，在在谈说其义，于时心窃疑之。又见性理所载，元儒草庐吴氏，于天之气运之中，亦备载之。予益自信其为天运气数之法，而非医家治病之书也。后从敝邑见赵少宰家藏宋版仲景《伤寒论》，皆北宋善板，始终详检，并未尝载有是说。六经治法之中，亦并无一字及之。予乃谛信予见之不谬，而断为非治伤寒外感之说。予尝遵仲景法治一切外邪为病，靡不响应。乃信非仲景之言，不可为万世法程。杂学混滥，疑误后人，故特表而出之。俾来学知所决择云。　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103602,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:42:05.000Z', '2024-12-21T03:42:05.000Z', '2024-12-21T03:42:05.000Z', '2、予少检《素问》中载有是说。既长游于四方，见天下医师与学士大夫，在在谈说其义，于时心窃疑之。又见性理所载，元儒草庐吴氏，于天之气运之中，亦备载之。予益自信其为天运气数之法，而非医家治病之书也。后从敝邑见赵少宰家藏宋版仲景《伤寒论》，皆北宋善板，始终详检，并未尝载有是说。六经治法之中，亦并无一字及之。予乃谛信予见之不谬，而断为非治伤寒外感之说。予尝遵仲景法治一切外邪为病，靡不响应。乃信非仲景之言，不可为万世法程。杂学混滥，疑误后人，故特表而出之。俾来学知所决择云。', '2024-12-21T03:42:05.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xF3B5wJTy3y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qi0oV6tkFDR', 4, '{"title":"第400103601条・ 卷之一_续序例上_论五运六气之谬","description":"<p>1、原夫五运六气之说，其起于汉魏之后乎？何者？张仲景，汉末人也，其书不载也。华元化，三国人也，其书亦不载也。前之则越人无其文，后之则叔和鲜其说。予是以知其为后世所撰，无益于治疗，而有误乎来学，学者宜深辨之。予见今之医师，学无原本，不明所自，侈口而谈，莫不动云五运六气。将以施之治病，譬之指算法之精微，谓事物之实有，岂不误哉！殊不知五运六气者，虚位也。岁有是气至则算，无是气至则不算。既无其气，焉得有其药乎？一言可竟已。其云“必先岁气”者，譬夫此年忽多淫雨，民病多湿，药宜类用二术苦温以燥之，佐以风药，如防风、羌活、升麻、葛根之属，风能胜湿故也。此必先岁气之谓也。其云“无伐天和”者，即春夏禁用麻黄、桂枝，秋冬禁用石膏、知母、芩、连、芍药之谓。即春夏养阴、秋冬养阳之义耳！乃所以遵养天和之道也。昔人谓“不明五运六气，检遍方书何济”者，正指后人愚蒙，不明五运六气之所以，而误于方册所载，依而用之，动辄成过，则虽检遍方书，亦何益哉！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:42:05.000Z', '2024-12-21T03:42:05.000Z', '2024-12-21T03:42:05.000Z', '1、原夫五运六气之说，其起于汉魏之后乎？何者？张仲景，汉末人也，其书不载也。华元化，三国人也，其书亦不载也。前之则越人无其文，后之则叔和鲜其说。予是以知其为后世所撰，无益于治疗，而有误乎来学，学者宜深辨之。予见今之医师，学无原本，不明所自，侈口而谈，莫不动云五运六气。将以施之治病，譬之指算法之精微，谓事物之实有，岂不误哉！殊不知五运六气者，虚位也。岁有是气至则算，无是气至则不算。既无其气，焉得有其药乎？一言可竟已。其云“必先岁气”者，譬夫此年忽多淫雨，民病多湿，药宜类用二术苦温以燥之，佐以风药，如防风、羌活、升麻、葛根之属，风能胜湿故也。此必先岁气之谓也。其云“无伐天和”者，即春夏禁用麻黄、桂枝，秋冬禁用石膏、知母、芩、连、芍药之谓。即春夏养阴、秋冬养阳之义耳！乃所以遵养天和之道也。昔人谓“不明五运六气，检遍方书何济”者，正指后人愚蒙，不明五运六气之所以，而误于方册所载，依而用之，动辄成过，则虽检遍方书，亦何益哉！', '2024-12-21T03:42:05.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'xF3B5wJTy3y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pRD70CGoVzo', 4, '{"title":"第400103706条・卷之一_续序例上_祝医五则","description":"<p>6、上来所祝五条，皆关切医师才品道术，利济功过。仰愿来学，俯从吾祝，则进乎道而不囿于技矣。讵非生人之至幸，斯道之大光也哉！</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '6、上来所祝五条，皆关切医师才品道术，利济功过。仰愿来学，俯从吾祝，则进乎道而不囿于技矣。讵非生人之至幸，斯道之大光也哉！', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Scn5eB4EbzW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ejjr3W8Ucp3', 4, '{"title":"第400103705条・卷之一_续序例上_祝医五则","description":"<p>5、医师不患道术不精，而患取金不多。舍其本业，专事旁求。假宠贵人，翼其口吻，以希世重。纵得多金，无拔苦力。于当来世，岂不酬偿？作是思惟，是苦非乐。故当勤求道术，以济物命。纵有功效，任其自酬，勿责厚报。等心施治，勿轻贫贱。如此则德植厥躬，鬼神幽赞矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '5、医师不患道术不精，而患取金不多。舍其本业，专事旁求。假宠贵人，翼其口吻，以希世重。纵得多金，无拔苦力。于当来世，岂不酬偿？作是思惟，是苦非乐。故当勤求道术，以济物命。纵有功效，任其自酬，勿责厚报。等心施治，勿轻贫贱。如此则德植厥躬，鬼神幽赞矣。', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Scn5eB4EbzW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C2yN7oXM77A', 4, '{"title":"第400103704条・卷之一_续序例上_祝医五则","description":"<p>4、凡作医师，宜先虚怀。灵知空洞，本无一物。苟执我见，便与物对。我见坚固，势必轻人；我是人非，与境角立。一灵空窍，动为所塞，虽日亲至人，终不获益。白首故吾，良可悲已！执而不化，害加于人。清夜深思，宜生愧耻。况人之才识，自非生知，必假问学。问学之益，广博难量。脱不虚怀，何由纳受？不耻无学，而耻下问。师心自圣，于道何益？苟非至愚，能不儆省乎！</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '4、凡作医师，宜先虚怀。灵知空洞，本无一物。苟执我见，便与物对。我见坚固，势必轻人；我是人非，与境角立。一灵空窍，动为所塞，虽日亲至人，终不获益。白首故吾，良可悲已！执而不化，害加于人。清夜深思，宜生愧耻。况人之才识，自非生知，必假问学。问学之益，广博难量。脱不虚怀，何由纳受？不耻无学，而耻下问。师心自圣，于道何益？苟非至愚，能不儆省乎！', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Scn5eB4EbzW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SWdEjXglvuz', 4, '{"title":"第400103703条・卷之一_续序例上_祝医五则","description":"<p>3、凡为医师，先当识药。药之所产，方隅不同，则精粗顿异，收采不时，则力用全乖。又或市肆饰伪，足以混真。苟非确认形质，精尝气味，鲜有不为其误者。譬诸将不知兵，立功何自？医之于药，亦犹是耳。既识药矣，宜习修事。《雷公炮炙》，固为大法，或有未尽，可以意通。必期躬亲，勿图苟且。譬诸饮食，烹调失度，尚不益人，反能增害，何况药物关乎躯命者耶？可不慎诸！</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '3、凡为医师，先当识药。药之所产，方隅不同，则精粗顿异，收采不时，则力用全乖。又或市肆饰伪，足以混真。苟非确认形质，精尝气味，鲜有不为其误者。譬诸将不知兵，立功何自？医之于药，亦犹是耳。既识药矣，宜习修事。《雷公炮炙》，固为大法，或有未尽，可以意通。必期躬亲，勿图苟且。譬诸饮食，烹调失度，尚不益人，反能增害，何况药物关乎躯命者耶？可不慎诸！', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Scn5eB4EbzW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8tfZP4Q29lp', 4, '{"title":"第400103702条・卷之一_续序例上_祝医五则","description":"<p>2、凡为医师，当先读书。凡欲读书，当先识字。字者，文之始也。不识字义，宁解文理？文理不通，动成窒碍。虽诗书满目，于神不染，触途成滞，何由省入？譬诸面墙，亦同木偶。望其拯生民之疾苦，顾不难哉？故昔称太医，今曰儒医太医者，读书穷理，本之身心，验之事物，战战兢兢，求中于道。造次之际，罔敢或肆者也。外此则俗工耳，不可以言医矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2、凡为医师，当先读书。凡欲读书，当先识字。字者，文之始也。不识字义，宁解文理？文理不通，动成窒碍。虽诗书满目，于神不染，触途成滞，何由省入？譬诸面墙，亦同木偶。望其拯生民之疾苦，顾不难哉？故昔称太医，今曰儒医太医者，读书穷理，本之身心，验之事物，战战兢兢，求中于道。造次之际，罔敢或肆者也。外此则俗工耳，不可以言医矣。', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Scn5eB4EbzW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cYb5PLA8mgU', 4, '{"title":"第400103701条・卷之一_续序例上_祝医五则","description":"<p>1、凡人疾病，皆由前生不惜众生身命，竭用人财，好杀鸟兽昆虫，好箠楚下贱，甚则枉用毒刑，加诸无罪。种种业因，感此苦报。业作医师，为人司命，见诸苦恼，当兴悲悯。详检方书，精求药道，谛察深思，务期协中。常自思惟，药不对病，病不对机，二旨或乖，则下咽不返。人命至重，冥报难逃。勿为一时衣食，自贻莫忏之罪于千百劫。戒之哉！宜惧不宜喜也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '2024-12-21T03:44:41.000Z', '1、凡人疾病，皆由前生不惜众生身命，竭用人财，好杀鸟兽昆虫，好箠楚下贱，甚则枉用毒刑，加诸无罪。种种业因，感此苦报。业作医师，为人司命，见诸苦恼，当兴悲悯。详检方书，精求药道，谛察深思，务期协中。常自思惟，药不对病，病不对机，二旨或乖，则下咽不返。人命至重，冥报难逃。勿为一时衣食，自贻莫忏之罪于千百劫。戒之哉！宜惧不宜喜也。', '2024-12-21T03:44:41.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Scn5eB4EbzW');
