INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JliCpLMD5z5', 4, '{"title":"第400103801条・卷之二_诸病应忌药总例","description":"<p>1、补气：人参、黄耆、二术、人胞、红铅。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T04:02:20.000Z', '2024-12-21T04:02:20.000Z', '2024-12-21T04:02:20.000Z', '1、补气：人参、黄耆、二术、人胞、红铅。', '2024-12-21T04:02:20.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'U9Nk26DtJpK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gFVzEWXCR5L', 4, '{"title":"第400103909条・卷之二_续序例下_阴阳表里虚实门","description":"<p>9、上盛下虚：属阳盛阴虚。</p>\n<p></p>\n<p>【忌】升散、下、助阳、补气、复忌破气、燥热辛温。</p>\n<p></p>\n<p>      诸药俱见阴虚条下。</p>\n<p></p>\n<p>【宜】降、益阴、甘寒、酸寒、佐以咸寒、苦寒。</p>\n<p></p>\n<p>         苏子、枇杷叶、麦门冬、枸杞子、生地、沙参、白芍药、山茱萸、五味子、牛膝、童便、玄参、黄檗、天门冬。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103909,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '9、上盛下虚：属阳盛阴虚。 【忌】升散、下、助阳、补气、复忌破气、燥热辛温。 诸药俱见阴虚条下。 【宜】降、益阴、甘寒、酸寒、佐以咸寒、苦寒。 苏子、枇杷叶、麦门冬、枸杞子、生地、沙参、白芍药、山茱萸、五味子、牛膝、童便、玄参、黄檗、天门冬。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mnRm4XLphn8', 4, '{"title":"第400103908条・卷之二_续序例下_阴阳表里虚实门","description":"<p>8、阴厥：即寒厥。其证四肢厥逆，身冷，面青蜷卧，手指爪青黯，腹痛，大便溏，或完谷不化，小便自利，不渴，不省人事。</p>\n<p></p>\n<p>【忌】下、破气、苦寒、咸寒、酸寒。</p>\n<p></p>\n<p>     食盐、太阴玄精石、童便（已上咸寒）、芍药、醋（已上酸寒）。</p>\n<p></p>\n<p>     下、破气、苦寒诸药俱见前。</p>\n<p></p>\n<p>【宜】补气、温中、甘温、辛热。</p>\n<p></p>\n<p>          人参、干姜、附子、桂、吴茱萸。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '8、阴厥：即寒厥。其证四肢厥逆，身冷，面青蜷卧，手指爪青黯，腹痛，大便溏，或完谷不化，小便自利，不渴，不省人事。 【忌】下、破气、苦寒、咸寒、酸寒。 食盐、太阴玄精石、童便（已上咸寒）、芍药、醋（已上酸寒）。 下、破气、苦寒诸药俱见前。 【宜】补气、温中、甘温、辛热。 人参、干姜、附子、桂、吴茱萸。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KHfktU0DTv6', 4, '{"title":"第400103907条・卷之二_续序例下_阴阳表里虚实门","description":"<p>7、阳厥：即热厥。其证四肢厥逆，身热面赤，唇燥，大渴，口干舌苦，目闭或不闭，小便赤涩短少，大便燥结，不省人事。</p>\n<p></p>\n<p>【忌】升发、补敛、燥热、辛温。</p>\n<p></p>\n<p>          诸药俱见前。</p>\n<p></p>\n<p>【宜】下、清热、甘寒、苦寒、咸寒。</p>\n<p></p>\n<p>      大黄、芒硝、石膏、黄芩、黄连、山栀、知母、童便。</p>\n<p>如挟虚有痰者，宜麦门冬、竹沥、芦根汁、梨汁、牛黄、童便。</p>\n<p>如妇人热入血室，因而厥者，药中以童便为君，加赤芍药、生地黄、牛膝、牡丹皮、桃仁。甚者大便结燥，加芒硝、大黄下之。通即止，勿尽剂。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103907,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '7、阳厥：即热厥。其证四肢厥逆，身热面赤，唇燥，大渴，口干舌苦，目闭或不闭，小便赤涩短少，大便燥结，不省人事。 【忌】升发、补敛、燥热、辛温。 诸药俱见前。 【宜】下、清热、甘寒、苦寒、咸寒。 大黄、芒硝、石膏、黄芩、黄连、山栀、知母、童便。 如挟虚有痰者，宜麦门冬、竹沥、芦根汁、梨汁、牛黄、童便。 如妇人热入血室，因而厥者，药中以童便为君，加赤芍药、生地黄、牛膝、牡丹皮、桃仁。甚者大便结燥，加芒硝、大黄下之。通即止，勿尽剂。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BytqAynFNhi', 4, '{"title":"第400103906条・卷之二_续序例下_阴阳表里虚实门","description":"<p>6、阴实：即里实。外感证属邪热内结者，其证胸腹硬痛，手不可近，大便七八日不行，或挟热下痢。</p>\n<p></p>\n<p>【忌】辛温发散、补敛。</p>\n<p></p>\n<p>       诸药俱见前。</p>\n<p></p>\n<p>【宜】下、苦寒、咸寒、甘辛。</p>\n<p></p>\n<p>        大黄、厚朴、枳实、滑石、山栀、黄芩、黄连、蓝、茵蔯、陈、芒硝、桃仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103906,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '6、阴实：即里实。外感证属邪热内结者，其证胸腹硬痛，手不可近，大便七八日不行，或挟热下痢。 【忌】辛温发散、补敛。 诸药俱见前。 【宜】下、苦寒、咸寒、甘辛。 大黄、厚朴、枳实、滑石、山栀、黄芩、黄连、蓝、茵蔯、陈、芒硝、桃仁。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1VB8uvLBR1P', 4, '{"title":"第400103905条・卷之二_续序例下_阴阳表里虚实门","description":"<p>5、阳实：即表邪热盛，其证头痛发热，遍身骨痛，无汗。</p>\n<p></p>\n<p>【忌】补敛、下、大热。</p>\n<p></p>\n<p>         黄耆、人参、二术、桂枝、芍药、五味子、米面食、猪羊犬肉、醋（已上补敛）、附子、胡椒、干姜、肉桂、蒜、吴茱萸（已上大热）、下药见前。</p>\n<p></p>\n<p>【宜】辛寒、发散，天寒略加辛热、辛温佐之。</p>\n<p></p>\n<p>         石膏、知母、葛根、麦门冬、前胡、柴胡、黄芩、紫苏、薄荷、升麻、防风、葱白、荆芥、羌活、麻黄（冬月可用，春夏忌之）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103905,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '5、阳实：即表邪热盛，其证头痛发热，遍身骨痛，无汗。 【忌】补敛、下、大热。 黄耆、人参、二术、桂枝、芍药、五味子、米面食、猪羊犬肉、醋（已上补敛）、附子、胡椒、干姜、肉桂、蒜、吴茱萸（已上大热）、下药见前。 【宜】辛寒、发散，天寒略加辛热、辛温佐之。 石膏、知母、葛根、麦门冬、前胡、柴胡、黄芩、紫苏、薄荷、升麻、防风、葱白、荆芥、羌活、麻黄（冬月可用，春夏忌之）。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LCCJdoFY6FU', 4, '{"title":"第400103904条・卷之二_续序例下_阴阳表里虚实门","description":"<p>4、里虚：其证洞泄，或完谷不化，心腹痛，按之即止。或腹胀，或伤寒下后痞满。</p>\n<p></p>\n<p>【忌】破气、下、苦寒。</p>\n<p></p>\n<p>         大黄、芒硝、巴豆、玄明粉、牵牛（已上下）、黄芩、黄连、山栀、知母、黄檗、天门冬、茗（已上苦寒）、破气药见前。</p>\n<p></p>\n<p>【宜】温补、甘、佐以辛热。</p>\n<p></p>\n<p>           人参、炙甘草、术、大枣、糯米、肉桂、附子（有热者勿用）、干姜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103904,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '4、里虚：其证洞泄，或完谷不化，心腹痛，按之即止。或腹胀，或伤寒下后痞满。 【忌】破气、下、苦寒。 大黄、芒硝、巴豆、玄明粉、牵牛（已上下）、黄芩、黄连、山栀、知母、黄檗、天门冬、茗（已上苦寒）、破气药见前。 【宜】温补、甘、佐以辛热。 人参、炙甘草、术、大枣、糯米、肉桂、附子（有热者勿用）、干姜。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('txWjljqZuXM', 4, '{"title":"第400103903条・卷之二_续序例下_阴阳表里虚实门","description":"<p>3、表虚：其证自汗恶风，洒淅寒热，喜就温暖，脉浮无力。</p>\n<p></p>\n<p>【忌】破气、升发、辛热。</p>\n<p></p>\n<p>           麻黄、升麻、防风、柴胡、羌活、独活、前胡、干葛、紫苏、薄荷、白芷、生姜、荆芥（已上升发）、吴茱萸、桂枝（表虚而中寒者不忌）、干姜（已上辛热）、破气药见前。</p>\n<p></p>\n<p>【宜】补敛、益气实表、甘、酸。</p>\n<p></p>\n<p>        人参、黄耆、白芍药、甘草、桂枝（有热者勿用）、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103903,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '3、表虚：其证自汗恶风，洒淅寒热，喜就温暖，脉浮无力。 【忌】破气、升发、辛热。 麻黄、升麻、防风、柴胡、羌活、独活、前胡、干葛、紫苏、薄荷、白芷、生姜、荆芥（已上升发）、吴茱萸、桂枝（表虚而中寒者不忌）、干姜（已上辛热）、破气药见前。 【宜】补敛、益气实表、甘、酸。 人参、黄耆、白芍药、甘草、桂枝（有热者勿用）、五味子。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ji6MRtDTk45', 4, '{"title":"第400103902条・卷之二_续序例下_阴阳表里虚实门","description":"<p>2、阴虚：即精血虚。其证为咳嗽多痰，吐血，咯血，嗽血，鼻衄，齿衄，盗汗，自汗，发热，寒热，潮热，骨乏无力，不眠，气急，腰背痛。</p>\n<p></p>\n<p>【忌】补气，复忌破气、燥热辛温，又忌大寒大苦伤胃，并升提发散、利水。</p>\n<p></p>\n<p>         人参、黄耆、二术、人胞（已上补气）、南星、半夏、附子、官桂、桂枝、仙茅、鹿茸、干姜、硫黄、阳起石、海狗肾、丁香、胡椒、乌头、火酒、吴茱萸、乌药、生姜（已上燥热辛温）、山栀、黄芩、黄连、大黄、芒硝、玄明粉（已上大寒大苦伤胃）、麻黄、升麻、柴胡、羌活、独活、藁本、川芎、防风（已上升提发散）、破气利水药见前。</p>\n<p></p>\n<p>【宜】生精补血，兼清虚热、敛摄、酸寒、甘寒、甘平、咸寒，略兼苦寒。</p>\n<p></p>\n<p>           地黄、柏子仁、人乳、沙苑蒺藜、枸杞子、牛膝、麋角胶、阿胶、沙参、酸枣仁、白芍药、五味子、山茱萸、石斛、麦门冬、薯蓣、牡丹皮、续断、地骨皮、车前子、溺白垽、鳖甲、黄檗、知母、青蒿。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103902,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2、阴虚：即精血虚。其证为咳嗽多痰，吐血，咯血，嗽血，鼻衄，齿衄，盗汗，自汗，发热，寒热，潮热，骨乏无力，不眠，气急，腰背痛。 【忌】补气，复忌破气、燥热辛温，又忌大寒大苦伤胃，并升提发散、利水。 人参、黄耆、二术、人胞（已上补气）、南星、半夏、附子、官桂、桂枝、仙茅、鹿茸、干姜、硫黄、阳起石、海狗肾、丁香、胡椒、乌头、火酒、吴茱萸、乌药、生姜（已上燥热辛温）、山栀、黄芩、黄连、大黄、芒硝、玄明粉（已上大寒大苦伤胃）、麻黄、升麻、柴胡、羌活、独活、藁本、川芎、防风（已上升提发散）、破气利水药见前。 【宜】生精补血，兼清虚热、敛摄、酸寒、甘寒、甘平、咸寒，略兼苦寒。 地黄、柏子仁、人乳、沙苑蒺藜、枸杞子、牛膝、麋角胶、阿胶、沙参、酸枣仁、白芍药、五味子、山茱萸、石斛、麦门冬、薯蓣、牡丹皮、续断、地骨皮、车前子、溺白垽、鳖甲、黄檗、知母、青蒿。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eq6ssFs9HNI', 4, '{"title":"第400103901条・卷之二_续序例下_阴阳表里虚实门","description":"<p>1、阳虚：即真气虚。其证恶寒，或发热自汗，汗多亡阳。阳虚不发热，单恶寒者居多。</p>\n<p></p>\n<p>【忌】破气、降泄、利水、苦寒、又忌辛热发散。</p>\n<p></p>\n<p>        青皮、枳壳、厚朴、牵牛、槟榔（已上破气）、大黄、石膏、山栀、知母、天门冬、生地黄、栝楼（已上降泄）、泽泻、木通、瞿麦、木桕根皮、汉防己、葶苈、猪苓、滑石、海金沙、商陆（已上利水）、黄芩、黄连、黄檗、玄参、槐花（已上苦寒）、芍药、乌梅、醋（已上酸）、吴茱萸、麻黄、羌活、独活、前胡、防风、荆芥（已上辛热发散）。</p>\n<p></p>\n<p>【宜】补、甘、温、热。</p>\n<p></p>\n<p>       人参、黄耆、二术、炙甘草、当归、白胶、淫羊藿、人胞、红铅、补骨脂、巴戟天、桂、附子、仙茅、鹿茸、大蘹香、阳起石、羊肉、雀肉。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400103901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '2024-12-21T09:31:01.000Z', '1、阳虚：即真气虚。其证恶寒，或发热自汗，汗多亡阳。阳虚不发热，单恶寒者居多。 【忌】破气、降泄、利水、苦寒、又忌辛热发散。 青皮、枳壳、厚朴、牵牛、槟榔（已上破气）、大黄、石膏、山栀、知母、天门冬、生地黄、栝楼（已上降泄）、泽泻、木通、瞿麦、木桕根皮、汉防己、葶苈、猪苓、滑石、海金沙、商陆（已上利水）、黄芩、黄连、黄檗、玄参、槐花（已上苦寒）、芍药、乌梅、醋（已上酸）、吴茱萸、麻黄、羌活、独活、前胡、防风、荆芥（已上辛热发散）。 【宜】补、甘、温、热。 人参、黄耆、二术、炙甘草、当归、白胶、淫羊藿、人胞、红铅、补骨脂、巴戟天、桂、附子、仙茅、鹿茸、大蘹香、阳起石、羊肉、雀肉。', '2024-12-21T09:31:01.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'PJf0Q8INIUL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('atw013CInCP', 4, '{"title":"第400104002条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>2、心虚（八证）</p>\n<p>【忌】升发、破气、苦寒、辛燥、大热。诸药俱见前。</p>\n<p>【宜】补血、甘温、酸敛、佐以咸寒、镇坠。生地黄、龙眼肉、人参、炙甘草、石斛、酸枣仁、五味子、柏子仁、丹参、茯神、远志、鹿茸、炒盐、丹砂。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T02:38:53.000Z', '2024-12-23T02:38:53.000Z', '2024-12-23T02:38:53.000Z', '2、心虚（八证） 【忌】升发、破气、苦寒、辛燥、大热。诸药俱见前。 【宜】补血、甘温、酸敛、佐以咸寒、镇坠。生地黄、龙眼肉、人参、炙甘草、石斛、酸枣仁、五味子、柏子仁、丹参、茯神、远志、鹿茸、炒盐、丹砂。', '2024-12-23T02:38:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CNB4IVf4hzG', 4, '{"title":"第400104001条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>1、五脏六腑虚实门</p>\n<p>安息香、丹砂、磁石、神水</p>\n<p>五心烦热，属真阴不足。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T02:38:53.000Z', '2024-12-23T02:38:53.000Z', '2024-12-23T02:38:53.000Z', '1、五脏六腑虚实门 安息香、丹砂、磁石、神水 五心烦热，属真阴不足。', '2024-12-23T02:38:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
