INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Frvi0qDQOwz', 4, '{"title":"第400104088条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>88、腹寒，属中气虚。忌、宜俱同三焦虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104088,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '88、腹寒，属中气虚。忌、宜俱同三焦虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I9v3clz3r3b', 4, '{"title":"第400104087条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>87、三焦虚（二证）</p>\n<p>【忌】破气、降、复忌升发、苦寒。诸药俱见前。</p>\n<p>【宜】补中益气，佐以辛温。人参、黄耆、白术、益智子、沉香、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104087,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '87、三焦虚（二证） 【忌】破气、降、复忌升发、苦寒。诸药俱见前。 【宜】补中益气，佐以辛温。人参、黄耆、白术、益智子、沉香、五味子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lj40VMuKhVS', 4, '{"title":"第400104086条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>86、膀胱气。忌、宜俱同疝。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104086,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '86、膀胱气。忌、宜俱同疝。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q3bpKQ4e5Pg', 4, '{"title":"第400104085条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>85、遗尿，属本经气虚，见小肠虚条内。因膀胱虚亦能致遗尿，故复列此。忌、宜俱见小肠虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104085,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '85、遗尿，属本经气虚，见小肠虚条内。因膀胱虚亦能致遗尿，故复列此。忌、宜俱见小肠虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CrutODi2b7E', 4, '{"title":"第400104084条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>84、小便不禁，属气血虚。</p>\n<p>【忌】降下、湿润、燥热。诸药俱见前。</p>\n<p>【宜】同膀胱虚，加：牡蛎、龙骨、鹿茸、桑螵蛸、鸡䏶胵。频数不能少忍，加：麦门冬、五味子、黄檗、山茱萸、天门冬、鳖甲、牛膝、柏子仁、甘枸杞子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104084,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '84、小便不禁，属气血虚。 【忌】降下、湿润、燥热。诸药俱见前。 【宜】同膀胱虚，加：牡蛎、龙骨、鹿茸、桑螵蛸、鸡䏶胵。频数不能少忍，加：麦门冬、五味子、黄檗、山茱萸、天门冬、鳖甲、牛膝、柏子仁、甘枸杞子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4kWEnNgDjuV', 4, '{"title":"第400104083条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>83、膀胱虚（三证）</p>\n<p>【忌】破气、燥、利小便。诸药俱见前。</p>\n<p>【宜】补气、酸敛。人参、五味子、山茱萸、益智子、金樱子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104083,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '83、膀胱虚（三证） 【忌】破气、燥、利小便。诸药俱见前。 【宜】补气、酸敛。人参、五味子、山茱萸、益智子、金樱子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AuteH5IzdbJ', 4, '{"title":"第400104082条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>82、脱肛，属气虚，兼有湿热。</p>\n<p>【忌】同大肠虚。</p>\n<p>【宜】补气、升提、除湿热。人参、黄耆、炙甘草、白术、莲肉、白扁豆、升麻、干葛、柴胡、黄檗、防风、黄连、黄芩、樗根白皮、白芍药。外用五倍子傅之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104082,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '82、脱肛，属气虚，兼有湿热。 【忌】同大肠虚。 【宜】补气、升提、除湿热。人参、黄耆、炙甘草、白术、莲肉、白扁豆、升麻、干葛、柴胡、黄檗、防风、黄连、黄芩、樗根白皮、白芍药。外用五倍子傅之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q6Nr84SKtNX', 4, '{"title":"第400104081条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>81、肠鸣，属气虚。</p>\n<p>【忌】破气、下、苦寒。诸药俱见前。</p>\n<p>【宜】同大肠虚，加升麻、柴胡以佐之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104081,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '81、肠鸣，属气虚。 【忌】破气、下、苦寒。诸药俱见前。 【宜】同大肠虚，加升麻、柴胡以佐之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IQqMBJJFn9O', 4, '{"title":"第400104080条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>80、虚寒滑泄不禁，属气虚。</p>\n<p>【忌】破气、下、湿润、苦寒。诸药俱见前。</p>\n<p>【宜】补气、升、甘温、酸敛。人参、黄耆、白术、莲肉、升麻、炙甘草、吴茱萸、肉豆蔻、补骨脂、五味子、木瓜、赤石脂。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104080,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '80、虚寒滑泄不禁，属气虚。 【忌】破气、下、湿润、苦寒。诸药俱见前。 【宜】补气、升、甘温、酸敛。人参、黄耆、白术、莲肉、升麻、炙甘草、吴茱萸、肉豆蔻、补骨脂、五味子、木瓜、赤石脂。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CjcphI1exnm', 4, '{"title":"第400104079条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>79、虚热便闭不通，属血虚，津液不足。</p>\n<p>【忌】破气、下、燥热、苦温、损津液。郁李仁（损津液）。馀忌药俱见前。</p>\n<p>【宜】生津液、润燥、凉血、益血。五味子、麦门冬、芝麻、麻仁、生蜜、天门冬、肉苁蓉、生地黄、当归、芦荟、炙甘草。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104079,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '79、虚热便闭不通，属血虚，津液不足。 【忌】破气、下、燥热、苦温、损津液。郁李仁（损津液）。馀忌药俱见前。 【宜】生津液、润燥、凉血、益血。五味子、麦门冬、芝麻、麻仁、生蜜、天门冬、肉苁蓉、生地黄、当归、芦荟、炙甘草。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5GP3NaFKzr3', 4, '{"title":"第400104078条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>78、大肠虚（四证）</p>\n<p>【忌】破气、下、燥、热。诸药俱见前。</p>\n<p>【宜】补气、润燥、甘温。人参、黄耆、麦门冬、五味子、白芍药、炙甘草。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104078,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '78、大肠虚（四证） 【忌】破气、下、燥、热。诸药俱见前。 【宜】补气、润燥、甘温。人参、黄耆、麦门冬、五味子、白芍药、炙甘草。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pe0RAv8rBxT', 4, '{"title":"第400104077条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>77、中酒，属胃弱。</p>\n<p>【忌】闭气、升、甘温、燥热、收涩。诸药俱见前。</p>\n<p>【宜】养胃、酸、辛散、淡渗。人参、麦门冬、白扁豆、葛花、五味子、梅酱、橘皮、白豆蔻、黄连、缩砂蜜、白茯苓、泽泻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104077,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '77、中酒，属胃弱。 【忌】闭气、升、甘温、燥热、收涩。诸药俱见前。 【宜】养胃、酸、辛散、淡渗。人参、麦门冬、白扁豆、葛花、五味子、梅酱、橘皮、白豆蔻、黄连、缩砂蜜、白茯苓、泽泻。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g9UCMv06PdR', 4, '{"title":"第400104076条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>76、反胃，属胃气虚。</p>\n<p>【忌】破气、升、苦寒、甘、燥热。诸药俱见前。</p>\n<p>【宜】补气、降气、和胃、清热、酸敛以制肝。人参、苏子、橘皮、枇杷叶、木瓜、竹茹、麦门冬、芦根汁、石斛、白茯苓、白芍药、梅酱、蔗浆。若因虚寒而得者，加：生姜、术、白豆蔻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104076,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '76、反胃，属胃气虚。 【忌】破气、升、苦寒、甘、燥热。诸药俱见前。 【宜】补气、降气、和胃、清热、酸敛以制肝。人参、苏子、橘皮、枇杷叶、木瓜、竹茹、麦门冬、芦根汁、石斛、白茯苓、白芍药、梅酱、蔗浆。若因虚寒而得者，加：生姜、术、白豆蔻。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jj4AN52Zd4F', 4, '{"title":"第400104075条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>75、中恶腹中㽲痛，属胃气虚，恶气客之所致。</p>\n<p>【忌】补、酸敛。诸药俱见前。</p>\n<p>【宜】辟恶气、通畅胃气、辛散。龙脑香、檀香、麝香（孕妇忌用）、牛黄、乳香、苏合香、丹砂、雄黄、鬼臼、藿香、橘皮、木香、沉水香、白豆蔻、远志、石菖蒲、干姜、桂。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104075,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '75、中恶腹中㽲痛，属胃气虚，恶气客之所致。 【忌】补、酸敛。诸药俱见前。 【宜】辟恶气、通畅胃气、辛散。龙脑香、檀香、麝香（孕妇忌用）、牛黄、乳香、苏合香、丹砂、雄黄、鬼臼、藿香、橘皮、木香、沉水香、白豆蔻、远志、石菖蒲、干姜、桂。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rvY5bPtE72v', 4, '{"title":"第400104074条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>74、绞肠痧，属胃气虚，猝中天地邪恶秽污之气，郁于胸腹间，上不得吐，下不得泻，以致肠胃绞痛异常，胸腹骤胀，遍体紫黑，头顶心必有红发，急寻出拔去之，急以三棱鑱针刺委中，挤出热血，可立苏。次用新汲凉水，投入盐两许，恣饮，得吐泻即止。委中穴在两膝下湾横纹中间，两筋之中，刺入一分。</p>\n<p>【忌】温补、敛。诸药俱见前，切忌火酒、生姜、蒜及谷气、米饮、热汤，入口即死。</p>\n<p>【宜】通窍辟恶、辛散、咸寒。龙脑香、苏合香、藿香、檀香、乳香、芒硝、童便。煎药亦宜冷服。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104074,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '74、绞肠痧，属胃气虚，猝中天地邪恶秽污之气，郁于胸腹间，上不得吐，下不得泻，以致肠胃绞痛异常，胸腹骤胀，遍体紫黑，头顶心必有红发，急寻出拔去之，急以三棱鑱针刺委中，挤出热血，可立苏。次用新汲凉水，投入盐两许，恣饮，得吐泻即止。委中穴在两膝下湾横纹中间，两筋之中，刺入一分。 【忌】温补、敛。诸药俱见前，切忌火酒、生姜、蒜及谷气、米饮、热汤，入口即死。 【宜】通窍辟恶、辛散、咸寒。龙脑香、苏合香、藿香、檀香、乳香、芒硝、童便。煎药亦宜冷服。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7bh1hwCQay9', 4, '{"title":"第400104073条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>73、霍乱转筋，属胃虚，猝中邪恶气及毒气，兼有停滞所致。（转筋与肝经血虚不同。）</p>\n<p>【忌】闭气、滞腻、收敛、温补、大热。诸药俱见前。</p>\n<p>【宜】调气和中、辛散、消导。由于暑，必口渴，或口干、齿燥、口苦、小便短赤：白梅、白扁豆并叶、丝瓜叶、滑石、石膏、甘草、橘皮、香薷、木瓜、石斛、童溺、食盐、泥浆、缩砂蜜、厚朴。由于寒，则小水清白，不渴不热：缩砂蜜、丁香、橘皮、藿香。甚者加：吴茱萸、肉桂。外治用杉木、楠材，煎汤浸洗。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104073,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '73、霍乱转筋，属胃虚，猝中邪恶气及毒气，兼有停滞所致。（转筋与肝经血虚不同。） 【忌】闭气、滞腻、收敛、温补、大热。诸药俱见前。 【宜】调气和中、辛散、消导。由于暑，必口渴，或口干、齿燥、口苦、小便短赤：白梅、白扁豆并叶、丝瓜叶、滑石、石膏、甘草、橘皮、香薷、木瓜、石斛、童溺、食盐、泥浆、缩砂蜜、厚朴。由于寒，则小水清白，不渴不热：缩砂蜜、丁香、橘皮、藿香。甚者加：吴茱萸、肉桂。外治用杉木、楠材，煎汤浸洗。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mVE972ggqh7', 4, '{"title":"第400104072条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>72、胃虚呕吐，宜分寒热。忌、宜俱同胃虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104072,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '72、胃虚呕吐，宜分寒热。忌、宜俱同胃虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R0aPodwKumG', 4, '{"title":"第400104071条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>71、胃弱不纳食及不思饮食。</p>\n<p>【忌】同胃虚。</p>\n<p>【宜】同胃虚，仍分寒热治。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104071,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '71、胃弱不纳食及不思饮食。 【忌】同胃虚。 【宜】同胃虚，仍分寒热治。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7MHPugHmsYB', 4, '{"title":"第400104070条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>70、胃虚（七证）</p>\n<p>【忌】下、破气、苦寒、燥热。诸药俱见前。</p>\n<p>【宜】益气、甘平、甘淡、酸。人参、白术、白扁豆、莲肉、石斛、橘皮、白茯苓、木瓜、白芍药。兼寒加：生姜、白豆蔻、缩砂蜜。兼热加：竹茹、枇杷叶、麦门冬、芦根汁、蔗浆。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104070,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '70、胃虚（七证） 【忌】下、破气、苦寒、燥热。诸药俱见前。 【宜】益气、甘平、甘淡、酸。人参、白术、白扁豆、莲肉、石斛、橘皮、白茯苓、木瓜、白芍药。兼寒加：生姜、白豆蔻、缩砂蜜。兼热加：竹茹、枇杷叶、麦门冬、芦根汁、蔗浆。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s1FYdYB5U9A', 4, '{"title":"第400104069条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>69、病后不得眠，属胆虚。忌、宜俱同胆虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104069,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '69、病后不得眠，属胆虚。忌、宜俱同胆虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MGaPumq4fgD', 4, '{"title":"第400104068条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>68、易惊，属胆气虚。</p>\n<p>【忌】破气、升发、燥热。诸药俱见前。</p>\n<p>【宜】补胆气、甘温、辛温、酸平。人参、酸枣仁、甘草、竹叶、当归、白芍药、竹茹、橘皮。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104068,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '68、易惊，属胆气虚。 【忌】破气、升发、燥热。诸药俱见前。 【宜】补胆气、甘温、辛温、酸平。人参、酸枣仁、甘草、竹叶、当归、白芍药、竹茹、橘皮。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hH2k6pK9Rzi', 4, '{"title":"第400104067条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>67、胆虚（二证）</p>\n<p>【忌】汗、吐、下、苦寒、破气、燥。山栀、瓜蒂、藜芦、盐汤、常山（已上吐）。馀忌药俱见前。</p>\n<p>【宜】甘温、甘平、酸敛，佐以微辛。人参、当归、谷精草、决明子、木贼草、甘草、竹叶、竹茹、白芍药、酸枣仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104067,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '67、胆虚（二证） 【忌】汗、吐、下、苦寒、破气、燥。山栀、瓜蒂、藜芦、盐汤、常山（已上吐）。馀忌药俱见前。 【宜】甘温、甘平、酸敛，佐以微辛。人参、当归、谷精草、决明子、木贼草、甘草、竹叶、竹茹、白芍药、酸枣仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nMVWRXTpL7l', 4, '{"title":"第400104066条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>66、小肠虚（一证）</p>\n<p>【忌】破气、辛散、燥热。诸药俱见前。</p>\n<p>【宜】补气、甘温、酸温。人参、黄耆、麦门冬、五味子、山茱萸。</p>\n<p>遗尿，属小肠虚，兼肾气虚。</p>\n<p>【忌】同小肠虚。</p>\n<p>【宜】同小肠虚，兼固涩。牡蛎、益智子、龙骨、金樱子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104066,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '66、小肠虚（一证） 【忌】破气、辛散、燥热。诸药俱见前。 【宜】补气、甘温、酸温。人参、黄耆、麦门冬、五味子、山茱萸。 遗尿，属小肠虚，兼肾气虚。 【忌】同小肠虚。 【宜】同小肠虚，兼固涩。牡蛎、益智子、龙骨、金樱子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r3SIzqBS5No', 4, '{"title":"第400104065条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>65、畏寒足冷。忌、宜俱同命门虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104065,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '65、畏寒足冷。忌、宜俱同命门虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aQbgoCCBMth', 4, '{"title":"第400104064条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>64、肾泄，即五更及黎明泄泻者是也。亦名大瘕泄。属命门真火不足。</p>\n<p>【忌】同命门虚。</p>\n<p>【宜】益气、甘温、酸敛。人参、薯蓣、莲肉、肉豆蔻、砂仁、补骨脂、木香、吴茱萸、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104064,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '64、肾泄，即五更及黎明泄泻者是也。亦名大瘕泄。属命门真火不足。 【忌】同命门虚。 【宜】益气、甘温、酸敛。人参、薯蓣、莲肉、肉豆蔻、砂仁、补骨脂、木香、吴茱萸、五味子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C64QwGevORZ', 4, '{"title":"第400104063条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>63、精寒、精薄，属命门火衰，阳气不足。忌、宜俱同阴痿。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104063,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '63、精寒、精薄，属命门火衰，阳气不足。忌、宜俱同阴痿。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E2ogUzg6t6E', 4, '{"title":"第400104062条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>62、阴痿，属命门火衰，下焦虚寒。</p>\n<p>【忌】同命门虚。</p>\n<p>【宜】同命门虚，加：海狗肾、天雄、蛇床子、原蚕蛾、狗阴茎、雀卵、牛膝、白马阴茎。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104062,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '62、阴痿，属命门火衰，下焦虚寒。 【忌】同命门虚。 【宜】同命门虚，加：海狗肾、天雄、蛇床子、原蚕蛾、狗阴茎、雀卵、牛膝、白马阴茎。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DlJ2eC6xaVd', 4, '{"title":"第400104061条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>61、命门虚（四证）</p>\n<p>即元阳真火不足。</p>\n<p>【忌】下泄、破气、发散、辛寒、苦寒、淡渗、燥、补肾水苦寒药。黄檗、知母、生地黄、天门冬（已上补肾水苦寒药）。馀药俱见前。</p>\n<p>【宜】益真阳之气、甘温、咸温、甘热、酸敛。人参、红铅、人胞、鹿茸、白胶、肉苁蓉、菟丝子、枸杞子、覆盆子、五味子、巴戟天、山茱萸、附子、补骨脂、仙茅、阳起石。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104061,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '61、命门虚（四证） 即元阳真火不足。 【忌】下泄、破气、发散、辛寒、苦寒、淡渗、燥、补肾水苦寒药。黄檗、知母、生地黄、天门冬（已上补肾水苦寒药）。馀药俱见前。 【宜】益真阳之气、甘温、咸温、甘热、酸敛。人参、红铅、人胞、鹿茸、白胶、肉苁蓉、菟丝子、枸杞子、覆盆子、五味子、巴戟天、山茱萸、附子、补骨脂、仙茅、阳起石。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e6ihqPAlf7B', 4, '{"title":"第400104060条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>60、奔豚，属肾虚，脾家湿邪下传客肾所致。</p>\n<p>【忌】同疝，兼忌燥。诸药俱见前。</p>\n<p>【宜】补气、健脾、辛温、散结。人参、薯蓣、桂、山茱萸、牛膝、蘹香、蛇床子。参用东垣奔豚丸治之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104060,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '60、奔豚，属肾虚，脾家湿邪下传客肾所致。 【忌】同疝，兼忌燥。诸药俱见前。 【宜】补气、健脾、辛温、散结。人参、薯蓣、桂、山茱萸、牛膝、蘹香、蛇床子。参用东垣奔豚丸治之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IKynSLdGBv4', 4, '{"title":"第400104059条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>59、疝，属肾虚，寒湿邪乘虚客之所致。丹溪谓与肾经绝无相干者，误也。又有先因湿邪为病，后成湿热者，药宜分寒热、先后二途。</p>\n<p>【忌】升、破气、苦寒、湿润。诸药俱见前。</p>\n<p>【宜】补气、通肾气、除湿。又有阴虚有热之人病此，兼宜除热。人参、黄耆、橘核、合欢子、荔枝核、川楝子、牛膝、木瓜、杜仲、萆薢、巴戟天。虚寒而痛，加：桂、蘹香、补骨脂、仙茅。虚热而痛，加：黄檗、车前子。湿盛者，加：术。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104059,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '59、疝，属肾虚，寒湿邪乘虚客之所致。丹溪谓与肾经绝无相干者，误也。又有先因湿邪为病，后成湿热者，药宜分寒热、先后二途。 【忌】升、破气、苦寒、湿润。诸药俱见前。 【宜】补气、通肾气、除湿。又有阴虚有热之人病此，兼宜除热。人参、黄耆、橘核、合欢子、荔枝核、川楝子、牛膝、木瓜、杜仲、萆薢、巴戟天。虚寒而痛，加：桂、蘹香、补骨脂、仙茅。虚热而痛，加：黄檗、车前子。湿盛者，加：术。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('71TVtIRFrLF', 4, '{"title":"第400104058条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>58、阴窍漏气，属肾气虚不固。肾主纳气，虚则不能纳，故见是证。</p>\n<p>【忌】破气、降、香燥、辛热。苏子、郁金、降香、沉水香、橘皮、通草（已上降）。白豆蔻、木香、香附（已上香燥）。馀忌药俱见前。</p>\n<p>【宜】补真气、酸敛、固涩。人参、五味子、山茱萸、沙苑蒺藜、覆盆子、枸杞子、益智子、远志、龙骨、牡蛎、金樱子、莲须。参用肾虚条内诸药。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104058,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '58、阴窍漏气，属肾气虚不固。肾主纳气，虚则不能纳，故见是证。 【忌】破气、降、香燥、辛热。苏子、郁金、降香、沉水香、橘皮、通草（已上降）。白豆蔻、木香、香附（已上香燥）。馀忌药俱见前。 【宜】补真气、酸敛、固涩。人参、五味子、山茱萸、沙苑蒺藜、覆盆子、枸杞子、益智子、远志、龙骨、牡蛎、金樱子、莲须。参用肾虚条内诸药。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AaMvyNA5g1e', 4, '{"title":"第400104057条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>57、善恐，属肾气虚。肾藏志故也。</p>\n<p>【忌】破气、苦寒。诸药俱见前。</p>\n<p>【宜】补气强志、辛平、甘温、佐以辛香。人参、远志、茯苓、鹿茸、酸枣仁、柏子仁、石斛、沉水香。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104057,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '57、善恐，属肾气虚。肾藏志故也。 【忌】破气、苦寒。诸药俱见前。 【宜】补气强志、辛平、甘温、佐以辛香。人参、远志、茯苓、鹿茸、酸枣仁、柏子仁、石斛、沉水香。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('igAZD2HoFBT', 4, '{"title":"第400104056条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>56、下消，属肾阴虚，火伏下焦。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】清热，及峻补真气、润、酸敛。诸药同肾虚，宜以黄檗、五味子、生地黄、天麦门冬、人参为君；石斛、牛膝、知母、人乳、童便为臣；地骨皮、青蒿、侧柏叶为佐。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104056,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '56、下消，属肾阴虚，火伏下焦。 【忌】同肾虚。 【宜】清热，及峻补真气、润、酸敛。诸药同肾虚，宜以黄檗、五味子、生地黄、天麦门冬、人参为君；石斛、牛膝、知母、人乳、童便为臣；地骨皮、青蒿、侧柏叶为佐。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hSzLiMAe7wl', 4, '{"title":"第400104055条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>55、齿浮、真牙摇动，及下龈软或齿衄，属肾虚有热。</p>\n<p>【忌】同肾虚，又忌当归、芎。</p>\n<p>【宜】益阴、凉血、固肾。诸药略同肾虚，应以地黄、黄檗、五味子为君；桑椹、牛膝、沙苑蒺藜、鹿茸、天门冬为臣；龙骨、牡蛎为使。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104055,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '55、齿浮、真牙摇动，及下龈软或齿衄，属肾虚有热。 【忌】同肾虚，又忌当归、芎。 【宜】益阴、凉血、固肾。诸药略同肾虚，应以地黄、黄檗、五味子为君；桑椹、牛膝、沙苑蒺藜、鹿茸、天门冬为臣；龙骨、牡蛎为使。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('USSGMTme5me', 4, '{"title":"第400104054条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>54、精塞水窍不通，属房欲不竟，或思欲不遂，或惧泄忍精，或老人气不足以送精出窍。</p>\n<p>【忌】破气、下、利小便、燥热。诸药俱见前。</p>\n<p>【宜】行败精，壮实人宜兼泄火。老人宜兼补气血。外治用吮法。牛膝、生地黄、当归、桃仁、红花、车前子、鹿角霜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104054,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '54、精塞水窍不通，属房欲不竟，或思欲不遂，或惧泄忍精，或老人气不足以送精出窍。 【忌】破气、下、利小便、燥热。诸药俱见前。 【宜】行败精，壮实人宜兼泄火。老人宜兼补气血。外治用吮法。牛膝、生地黄、当归、桃仁、红花、车前子、鹿角霜。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oqOwz9UEf4V', 4, '{"title":"第400104053条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>53、五淋，属肾虚兼有湿热。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】同肾虚，加清湿热。茯苓、黄檗、车前子、石斛、萆薢、薏苡仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104053,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '53、五淋，属肾虚兼有湿热。 【忌】同肾虚。 【宜】同肾虚，加清湿热。茯苓、黄檗、车前子、石斛、萆薢、薏苡仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EJwI71FJg1C', 4, '{"title":"第400104052条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>52、伤精白浊，属房劳过度，以致精伤流出，似白浊证。</p>\n<p>【忌】利小便、燥、辛热。诸药俱见前。</p>\n<p>【宜】同肾虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104052,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '52、伤精白浊，属房劳过度，以致精伤流出，似白浊证。 【忌】利小便、燥、辛热。诸药俱见前。 【宜】同肾虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qkRpycNeUJc', 4, '{"title":"第400104051条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>51、溺血、血淋，属肾虚有火，热伤血分。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】同肾虚，加：侧柏叶、阿胶、茅根、韭白、干地黄、戎盐、蒲黄。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104051,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '51、溺血、血淋，属肾虚有火，热伤血分。 【忌】同肾虚。 【宜】同肾虚，加：侧柏叶、阿胶、茅根、韭白、干地黄、戎盐、蒲黄。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('33QbYTxsepx', 4, '{"title":"第400104050条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>50、溺有馀沥，属气虚。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】同肾虚，以五味子、黄檗、人参为君，加菟丝子、覆盆子为臣，益智为佐。如觉平日肺家有热，或咳嗽有火者，忌人参，用沙参。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104050,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '50、溺有馀沥，属气虚。 【忌】同肾虚。 【宜】同肾虚，以五味子、黄檗、人参为君，加菟丝子、覆盆子为臣，益智为佐。如觉平日肺家有热，或咳嗽有火者，忌人参，用沙参。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kUkmzaC7SsM', 4, '{"title":"第400104049条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>49、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104049,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '49、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
