INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PYdxBsshw83', 4, '{"title":"第400104047条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>47、梦遗泄精，属肾虚有火。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】滋阴、生津补血、除热、酸敛、佐以涩精。莲花蕊、生甘草、石斛、缩砂蜜、龙骨、覆盆子、鱼胶、莲肉、牡蛎、远志、韭子、桑螵蛸。馀药同肾虚条。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104047,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '47、梦遗泄精，属肾虚有火。 【忌】同肾虚。 【宜】滋阴、生津补血、除热、酸敛、佐以涩精。莲花蕊、生甘草、石斛、缩砂蜜、龙骨、覆盆子、鱼胶、莲肉、牡蛎、远志、韭子、桑螵蛸。馀药同肾虚条。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6MicfpynTei', 4, '{"title":"第400104046条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>46、传尸劳。</p>\n<p>【忌】同肾虚。</p>\n<p>【宜】除热益阴、杀劳虫，兼清镇。诸药同肾虚，加：鬼臼、干漆、漆叶、芦荟、象胆、獭肝、胡黄连。忌、宜俱同肾虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104046,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '46、传尸劳。 【忌】同肾虚。 【宜】除热益阴、杀劳虫，兼清镇。诸药同肾虚，加：鬼臼、干漆、漆叶、芦荟、象胆、獭肝、胡黄连。忌、宜俱同肾虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qdfWFKtBiZ8', 4, '{"title":"第400104045条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>45、骨蒸潮热，属精血虚极，以致阳无所附，火空上炎。忌、宜俱同肾虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104045,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '45、骨蒸潮热，属精血虚极，以致阳无所附，火空上炎。忌、宜俱同肾虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZfB3ACjmVUX', 4, '{"title":"第400104044条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>44、骨乏无力，属阴精不足，肾主骨故也。忌、宜俱同肾虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104044,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '44、骨乏无力，属阴精不足，肾主骨故也。忌、宜俱同肾虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KQeULqUcGEC', 4, '{"title":"第400104043条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>43、肾虚腰痛，属精气虚。</p>\n<p>【忌】破气、燥、热。诸药俱见前。</p>\n<p>【宜】同肾虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104043,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '43、肾虚腰痛，属精气虚。 【忌】破气、燥、热。诸药俱见前。 【宜】同肾虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pzB1BCbysCk', 4, '{"title":"第400104042条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>42、肾虚（十八证）</p>\n<p>即肾水真阴不足。</p>\n<p>【忌】升、破气、利水、温热、辛燥、补命门相火。仙茅、巴戟天、葫芦巴、人参、补骨脂、鹿茸、人胞（已上补命门相火）。馀忌药俱见前。</p>\n<p>【宜】滋阴、润、生精补血、除热、甘寒、酸寒、苦寒、咸寒。地黄、枸杞子、牛膝、人乳、肉苁蓉、柏子仁、胡麻、沙苑蒺藜、杜仲、续断、天门冬、麦门冬、五味子、山茱萸、薯蓣、牡丹皮、菟丝子、车前子、地骨皮、知母、黄柏、鳖甲、青蒿、童便。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104042,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '42、肾虚（十八证） 即肾水真阴不足。 【忌】升、破气、利水、温热、辛燥、补命门相火。仙茅、巴戟天、葫芦巴、人参、补骨脂、鹿茸、人胞（已上补命门相火）。馀忌药俱见前。 【宜】滋阴、润、生精补血、除热、甘寒、酸寒、苦寒、咸寒。地黄、枸杞子、牛膝、人乳、肉苁蓉、柏子仁、胡麻、沙苑蒺藜、杜仲、续断、天门冬、麦门冬、五味子、山茱萸、薯蓣、牡丹皮、菟丝子、车前子、地骨皮、知母、黄柏、鳖甲、青蒿、童便。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('35RgLo4bpeI', 4, '{"title":"第400104041条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>41、息贲，属肺气虚，痰热壅结所致。</p>\n<p>【忌】破气、辛热、补敛。诸药俱见前。</p>\n<p>【宜】降气、清热开痰、佐以散结。橘皮、白豆蔻、白芥子、射干、桔梗、旋覆花、桑白皮。参用东垣息贲丸治之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104041,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '41、息贲，属肺气虚，痰热壅结所致。 【忌】破气、辛热、补敛。诸药俱见前。 【宜】降气、清热开痰、佐以散结。橘皮、白豆蔻、白芥子、射干、桔梗、旋覆花、桑白皮。参用东垣息贲丸治之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bcoSRLPH7p2', 4, '{"title":"第400104040条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>40、龟胸，属肺热有痰。忌、宜俱同齁喘咳嗽。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104040,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '40、龟胸，属肺热有痰。忌、宜俱同齁喘咳嗽。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
